class SourceReadLedgerError(RuntimeError):
    """Base class for local source-read custody errors."""


class SourceReadLedgerValidationError(SourceReadLedgerError, ValueError):
    """Caller material is not an exact, bounded, offline READ record."""


class SourceReadLedgerIntegrityError(SourceReadLedgerError):
    """Schema, stored bytes, projections, or the event chain do not verify."""


class SourceReadLedgerIdempotencyConflict(SourceReadLedgerError):
    """An idempotency digest was already bound to different material."""


class SourceReadLedgerStateConflict(SourceReadLedgerError):
    """An operation cannot make the requested state transition."""


class SourceReadLedgerQuotaExceeded(SourceReadLedgerError):
    """A durable reservation would exceed an exact stored ceiling."""


class SourceReadLedgerAnchorQuarantined(SourceReadLedgerIntegrityError):
    """The injected monotonic anchor and the local append-only head diverged."""


