class SourceReadContinuationMigrationAuthority(ABC):
    """Pinned SoD authority for rights-neutral continuation migration/repair."""

    @property
    @abstractmethod
    def authority_identity_sha256(self) -> str:
        """Return the stable authority identity pinned in canonical metadata."""

    @abstractmethod
    def authorize_migration(
        self,
        *,
        store_identity_sha256: str,
        lineage_sha256: str,
        current_ledger_binding_sha256: str,
        next_ledger_binding_sha256: str,
        old_position_binding_sha256: str,
        next_position_binding_sha256: str,
        old_registry_projection_sha256: str,
        next_registry_projection_sha256: str,
        occurred_at_utc: str,
        governance_evidence_sha256: str,
    ) -> SourceReadContinuationMigrationAuthorizationReceipt:
        """Authorize one exact latest-head, rights-neutral registry revision."""

    @abstractmethod
    def authorize_stream_repair(
        self,
        *,
        store_identity_sha256: str,
        phase: str,
        incident_id: str,
        repair_id: str,
        lineage_sha256: str,
        logical_head_sha256: str,
        current_ledger_binding_sha256: str,
        next_ledger_binding_sha256: str,
        position_binding_sha256: str,
        physical_base_status: str,
        physical_base_head_sha256: str | None,
        physical_base_ledger_binding_sha256: str | None,
        repair_base_fence_sha256: str | None,
        repair_base_authorization_sha256: str | None,
        activation_evidence_sha256: str | None,
        occurred_at_utc: str,
        governance_evidence_sha256: str,
    ) -> SourceReadStreamRepairAuthorizationReceipt:
        """Authorize exact BIND/COMPLETE phases of one quarantined repair."""


