class DispatchReservationGrant:
    """Opaque, process-local authority minted only by a ledger instance.

    The public constructor is deliberately unusable.  The creating ledger also
    retains the exact object identity and its immutable expected binding; field
    lookalikes (including objects built with ``object.__new__``) have no
    dispatch authority.
    """

    __slots__ = (
        "operation_id",
        "custody_reservation_sha256",
        "writer_epoch_root_sha256",
        "factory_attested",
    )

    def __new__(cls, *_args: object, **_kwargs: object) -> "DispatchReservationGrant":
        raise SourceReadLedgerStateConflict(
            "dispatch reservation grant must be ledger-created"
        )

    def __setattr__(self, _name: str, _value: object) -> None:
        raise SourceReadLedgerStateConflict("dispatch reservation grant is immutable")

    def __repr__(self) -> str:
        return "DispatchReservationGrant(binding=<redacted>)"


