# Replaced only when the intentional sqlite_master inventory changes.  It is
# checked against the actual database on every open/read/write.
CANONICAL_SCHEMA_FINGERPRINT_SHA256 = (
    "6424b070d2018172a95dbabe6aa555640b2905de6d08d13be588cac3002f0f06"
)


def _schema_statements() -> tuple[str, ...]:
    statements: list[str] = []
    buffer = ""
    for line in _SCHEMA_SQL.splitlines():
        buffer += line + "\n"
        if sqlite3.complete_statement(buffer):
            statement = buffer.strip()
            if statement:
                statements.append(statement)
            buffer = ""
    if buffer.strip():
        raise SourceReadLedgerIntegrityError("source read schema SQL is incomplete")
    return tuple(statements)


def _normalize_sql(value: str) -> str:
    return " ".join(value.replace("\r", " ").replace("\n", " ").split())


def _schema_fingerprint(connection: sqlite3.Connection) -> str:
    rows = connection.execute(
        """SELECT type,name,tbl_name,sql FROM sqlite_master
           WHERE name NOT LIKE 'sqlite_%' AND type IN ('table','index','trigger','view')
           ORDER BY type,name,tbl_name"""
    ).fetchall()
    inventory = [
        {
            "type": str(row[0]),
            "name": str(row[1]),
            "table": str(row[2]),
            "sql": _normalize_sql(str(row[3])),
        }
        for row in rows
    ]
    return _value_sha256(inventory)


class SourceReadLedger:
    """Explicit-path SQLite custody for deterministic source READ operations."""

    def __init__(
        self,
        path: str | Path,
        *,
        external_anchor: SourceReadExternalAnchor | None = None,
        quota_epoch_authority: SourceReadQuotaEpochAuthority | None = None,
        continuation_rotation_authority: (
            SourceReadContinuationRotationAuthority | None
        ) = None,
        signed_approval_authority: (
            PinnedSignedSourceReadApprovalAuthorityV1 | None
        ) = None,
        continuation_migration_authority: (
            SourceReadContinuationMigrationAuthority | None
        ) = None,
        vault_absence_authority: SourceReadVaultAbsenceAuthority | None = None,
        vault_lifecycle_authority: SourceReadVaultLifecycleAuthority | None = None,
        key_retirement_authority: SourceReadKeyRetirementAuthority | None = None,
    ) -> None:
        if not isinstance(path, (str, Path)) or not str(path):
            raise SourceReadLedgerValidationError("ledger path must be explicit")
        self.path = Path(path)
        if self.path.exists() and self.path.is_dir():
            raise SourceReadLedgerValidationError("ledger path must be a file")
        if not self.path.parent.exists() or not self.path.parent.is_dir():
            raise SourceReadLedgerValidationError(
                "ledger parent directory must already exist"
            )
        self.path = self.path.resolve(strict=False)
        self.store_identity_sha256 = _value_sha256(
            {
                # Deliberately independent of ledger schema/protocol so an
                # upgrade at this path cannot silently obtain a new anchor
                # namespace and restart from genesis.
                "identity_namespace": "source-read-canonical-store-identity-v1",
                "record_kind": "CANONICAL_STORE_IDENTITY",
                "resolved_path_sha256": _hash_text(str(self.path)),
            }
        )
        if external_anchor is not None and not isinstance(
            external_anchor, SourceReadExternalAnchor
        ):
            raise SourceReadLedgerValidationError(
                "external anchor must implement the explicit monotonic boundary"
            )
        self._external_anchor = external_anchor
        self.external_anchor_identity_sha256 = (
            None
            if external_anchor is None
            else _sha256(
                external_anchor.anchor_identity_sha256,
                "external_anchor.anchor_identity_sha256",
            )
        )
        from .source_read_anchor_boundary import PinnedSignedSourceReadExternalAnchor

        signed_anchor = (
            external_anchor
            if type(external_anchor) is PinnedSignedSourceReadExternalAnchor
            else None
        )
        self.signed_anchor_root_policy_identity_sha256 = (
            None if signed_anchor is None else signed_anchor.root_policy_identity_sha256
        )
        self.signed_anchor_store_identity_sha256 = (
            None
            if signed_anchor is None
            else signed_anchor.authority_store_identity_sha256
        )
        self.signed_anchor_tenant_sha256 = (
            None if signed_anchor is None else signed_anchor.tenant_sha256
        )
        self.signed_anchor_trust_bundle_version = (
            None if signed_anchor is None else signed_anchor.trust_bundle_version
        )
        self.signed_anchor_trust_bundle_sha256 = (
            None if signed_anchor is None else signed_anchor.trust_bundle_sha256
        )
        self.signed_anchor_maximum_clock_skew_seconds = (
            None if signed_anchor is None else signed_anchor.maximum_clock_skew_seconds
        )
        if quota_epoch_authority is not None and not isinstance(
            quota_epoch_authority, SourceReadQuotaEpochAuthority
        ):
            raise SourceReadLedgerValidationError(
                "quota epoch authority must implement the explicit SoD boundary"
            )
        self._quota_epoch_authority = quota_epoch_authority
        self.quota_epoch_authority_identity_sha256 = (
            None
            if quota_epoch_authority is None
            else _sha256(
                quota_epoch_authority.authority_identity_sha256,
                "quota_epoch_authority.authority_identity_sha256",
            )
        )
        if continuation_rotation_authority is not None and not isinstance(
            continuation_rotation_authority,
            SourceReadContinuationRotationAuthority,
        ):
            raise SourceReadLedgerValidationError(
                "continuation rotation authority must implement the explicit SoD boundary"
            )
        self._continuation_rotation_authority = continuation_rotation_authority
        self.continuation_rotation_authority_identity_sha256 = (
            None
            if continuation_rotation_authority is None
            else _sha256(
                continuation_rotation_authority.authority_identity_sha256,
                "continuation_rotation_authority.authority_identity_sha256",
            )
        )
        if (
            signed_approval_authority is not None
            and type(signed_approval_authority)
            is not PinnedSignedSourceReadApprovalAuthorityV1
        ):
            raise SourceReadLedgerValidationError(
                "signed approval authority must use the exact pinned v1 adapter"
            )
        self._signed_rotation_authority_v1 = signed_approval_authority
        if signed_approval_authority is not None:
            signed = signed_approval_authority
            root_policy = _sha256(
                signed.root_policy_identity_sha256,
                "signed rotation root policy identity",
            )
            if (
                self.continuation_rotation_authority_identity_sha256 is not None
                and root_policy != self.continuation_rotation_authority_identity_sha256
            ):
                raise SourceReadLedgerValidationError(
                    "signed rotation root policy differs from pinned SoD identity"
                )
            self.continuation_rotation_authority_identity_sha256 = root_policy
            if type(external_anchor) is not PinnedSignedSourceReadExternalAnchor:
                raise SourceReadLedgerValidationError(
                    "signed approval authority requires the exact pinned signed anchor"
                )
            if external_anchor.tenant_sha256 != signed.tenant_sha256:
                raise SourceReadLedgerValidationError(
                    "signed approval and anchor tenant boundaries differ"
                )
            if (
                external_anchor.authority_store_identity_sha256
                == signed.authority_store_identity_sha256
                or external_anchor.root_policy_identity_sha256
                == signed.root_policy_identity_sha256
                or set(external_anchor.signer_public_key_sha256s)
                & set(signed.verifier.signer_public_key_sha256s)
                or set(external_anchor.signer_principal_sha256s)
                & set(signed.verifier.signer_principal_sha256s)
            ):
                raise SourceReadLedgerValidationError(
                    "signed approval and anchor custody must be independent"
                )
            _sha256(
                signed.authority_store_identity_sha256,
                "signed rotation authority store identity",
            )
            _sha256(signed.tenant_sha256, "signed rotation tenant")
            requester_scope = _sha256(
                signed.requester_scope_sha256,
                "signed rotation requester scope",
            )
            approver_scope = _sha256(
                signed.approver_scope_sha256,
                "signed rotation approver scope",
            )
            if requester_scope == approver_scope:
                raise SourceReadLedgerValidationError(
                    "signed rotation requester and approver scopes must differ"
                )
        self.signed_authority_root_policy_identity_sha256 = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.root_policy_identity_sha256
        )
        self.signed_authority_store_identity_sha256 = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.authority_store_identity_sha256
        )
        self.signed_authority_tenant_sha256 = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.tenant_sha256
        )
        self.signed_authority_audience = (
            None
            if signed_approval_authority is None
            else SOURCE_READ_AUTHORITY_AUDIENCE_V1
        )
        self.signed_authority_requester_scope_sha256 = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.requester_scope_sha256
        )
        self.signed_authority_approver_scope_sha256 = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.approver_scope_sha256
        )
        self.signed_authority_trust_bundle_version = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.verifier.trust_bundle_version
        )
        self.signed_authority_trust_bundle_sha256 = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.verifier.trust_bundle_sha256
        )
        self.signed_authority_maximum_clock_skew_seconds = (
            None
            if signed_approval_authority is None
            else signed_approval_authority.verifier.maximum_clock_skew_seconds
        )
        if continuation_migration_authority is not None and not isinstance(
            continuation_migration_authority,
            SourceReadContinuationMigrationAuthority,
        ):
            raise SourceReadLedgerValidationError(
                "continuation migration authority must implement the explicit SoD boundary"
            )
        self._continuation_migration_authority = continuation_migration_authority
        self.continuation_migration_authority_identity_sha256 = (
            None
            if continuation_migration_authority is None
            else _sha256(
                continuation_migration_authority.authority_identity_sha256,
                "continuation_migration_authority.authority_identity_sha256",
            )
        )
        if vault_absence_authority is not None and not isinstance(
            vault_absence_authority, SourceReadVaultAbsenceAuthority
        ):
            raise SourceReadLedgerValidationError(
                "vault absence authority must implement the non-creating boundary"
            )
        self._vault_absence_authority = vault_absence_authority
        self.vault_absence_authority_identity_sha256 = (
            None
            if vault_absence_authority is None
            else _sha256(
                vault_absence_authority.authority_identity_sha256,
                "vault_absence_authority.authority_identity_sha256",
            )
        )
        if vault_lifecycle_authority is not None and not isinstance(
            vault_lifecycle_authority, SourceReadVaultLifecycleAuthority
        ):
            raise SourceReadLedgerValidationError(
                "vault lifecycle authority must implement the factory verifier boundary"
            )
        self._vault_lifecycle_authority = vault_lifecycle_authority
        self.vault_lifecycle_authority_identity_sha256 = (
            None
            if vault_lifecycle_authority is None
            else _sha256(
                vault_lifecycle_authority.authority_identity_sha256,
                "vault_lifecycle_authority.authority_identity_sha256",
            )
        )
        if key_retirement_authority is not None and not isinstance(
            key_retirement_authority, SourceReadKeyRetirementAuthority
        ):
            raise SourceReadLedgerValidationError(
                "key retirement authority must implement the explicit SoD boundary"
            )
        self._key_retirement_authority = key_retirement_authority
        self.key_retirement_authority_identity_sha256 = (
            None
            if key_retirement_authority is None
            else _sha256(
                key_retirement_authority.authority_identity_sha256,
                "key_retirement_authority.authority_identity_sha256",
            )
        )
        self._dispatch_grants_lock = Lock()
        self._dispatch_grants: dict[
            int, tuple[DispatchReservationGrant, str, str, str, bool]
        ] = {}
        self._continuation_proofs_lock = Lock()
        self._continuation_proofs: dict[
            int, tuple[SourceReadContinuationProof, str]
        ] = {}
        self._operation_recovery_proofs_lock = Lock()
        self._operation_recovery_proofs: dict[
            int, tuple[SourceReadOperationRecoveryProof, tuple[object, ...]]
        ] = {}
        self._stream_repair_proofs_lock = Lock()
        self._stream_repair_proofs: dict[
            int, tuple[SourceReadStreamRepairActivationProof, str]
        ] = {}
        self._stream_repair_ingress_proofs_lock = Lock()
        self._stream_repair_ingress_proofs: dict[
            int, tuple[SourceReadStreamRepairIngressProof, str]
        ] = {}
        self._stream_repair_intent_proofs_lock = Lock()
        self._stream_repair_intent_proofs: dict[
            int, tuple[SourceReadStreamRepairIntentProof, str]
        ] = {}
        self._key_retirement_request_proofs_lock = Lock()
        self._key_retirement_request_proofs: dict[
            int, tuple[SourceReadKeyRetirementRequestProof, str]
        ] = {}
        self._key_retirement_proofs_lock = Lock()
        self._key_retirement_proofs: dict[
            int, tuple[SourceReadKeyRetirementProof, str]
        ] = {}
        self._key_retirement_abandonment_proofs_lock = Lock()
        self._key_retirement_abandonment_proofs: dict[
            int, tuple[SourceReadKeyRetirementAbandonmentProof, str]
        ] = {}
        self._writer_epoch_transition_proofs_lock = Lock()
        self._writer_epoch_transition_proofs: dict[
            int, tuple[SourceReadRuntimeVaultWriterEpochTransitionProof, str]
        ] = {}
        self._writer_epoch_proofs_lock = Lock()
        self._writer_epoch_proofs: dict[
            int, tuple[SourceReadRuntimeVaultWriterEpochProof, str]
        ] = {}
        self._initialize()

    def _mint_dispatch_grant(
        self,
        operation_id: str,
        custody_reservation_sha256: str,
        writer_epoch_root_sha256: str,
    ) -> DispatchReservationGrant:
        grant = object.__new__(DispatchReservationGrant)
        object.__setattr__(grant, "operation_id", operation_id)
        object.__setattr__(
            grant, "custody_reservation_sha256", custody_reservation_sha256
        )
        object.__setattr__(grant, "writer_epoch_root_sha256", writer_epoch_root_sha256)
        object.__setattr__(grant, "factory_attested", True)
        with self._dispatch_grants_lock:
            self._dispatch_grants[id(grant)] = (
                grant,
                operation_id,
                custody_reservation_sha256,
                writer_epoch_root_sha256,
                False,
            )
        return grant

    def _grant_is_known(
        self,
        grant: DispatchReservationGrant,
        operation_id: str,
        custody_reservation_sha256: str,
        writer_epoch_root_sha256: str,
    ) -> bool:
        with self._dispatch_grants_lock:
            record = self._dispatch_grants.get(id(grant))
            return (
                record is not None
                and record[0] is grant
                and record[1] == operation_id
                and record[2] == custody_reservation_sha256
                and record[3] == writer_epoch_root_sha256
            )

    def _consume_dispatch_grant(
        self,
        grant: DispatchReservationGrant,
        operation_id: str,
        custody_reservation_sha256: str,
        writer_epoch_root_sha256: str,
    ) -> None:
        with self._dispatch_grants_lock:
            record = self._dispatch_grants.get(id(grant))
            if (
                record is None
                or record[0] is not grant
                or record[1] != operation_id
                or record[2] != custody_reservation_sha256
                or record[3] != writer_epoch_root_sha256
                or record[4]
            ):
                raise SourceReadLedgerStateConflict(
                    "dispatch intent requires an unused ledger-created grant"
                )
            self._dispatch_grants[id(grant)] = (*record[:4], True)

    def _mint_continuation_proof(
        self,
        *,
        binding: SourceReadContinuationBinding,
        outcome_id: str,
        outcome_sha256: str,
        outcome_event_sha256: str,
        continuation_head_sha256: str,
        writer_epoch_head_sha256: str,
        ledger_head_event_sha256: str,
        external_anchor_status: str,
        external_anchor_generation: int,
        external_anchor_receipt_sha256: str,
    ) -> SourceReadContinuationProof:
        proof = object.__new__(SourceReadContinuationProof)
        values: dict[str, object] = {
            "binding": binding,
            "outcome_id": outcome_id,
            "outcome_sha256": outcome_sha256,
            "outcome_event_sha256": outcome_event_sha256,
            "continuation_head_sha256": continuation_head_sha256,
            "writer_epoch_head_sha256": writer_epoch_head_sha256,
            "ledger_head_event_sha256": ledger_head_event_sha256,
            "external_anchor_status": external_anchor_status,
            "external_anchor_generation": external_anchor_generation,
            "external_anchor_receipt_sha256": external_anchor_receipt_sha256,
            "factory_attested": True,
            "live_release_eligible": False,
        }
        for name, value in values.items():
            object.__setattr__(proof, name, value)
        with self._continuation_proofs_lock:
            self._continuation_proofs[id(proof)] = (
                proof,
                _value_sha256(
                    {
                        "binding_sha256": binding.ledger_binding_sha256,
                        "writer_epoch_head_sha256": writer_epoch_head_sha256,
                    }
                ),
            )
        return proof

    def continuation_proof_is_known(self, proof: SourceReadContinuationProof) -> bool:
        """Validate object identity against this exact ledger factory instance."""

        if type(proof) is not SourceReadContinuationProof:
            return False
        with self._continuation_proofs_lock:
            record = self._continuation_proofs.get(id(proof))
            try:
                return bool(
                    record is not None
                    and record[0] is proof
                    and record[1]
                    == _value_sha256(
                        {
                            "binding_sha256": proof.binding.ledger_binding_sha256,
                            "writer_epoch_head_sha256": (
                                proof.writer_epoch_head_sha256
                            ),
                        }
                    )
                )
            except AttributeError:
                return False

    def _mint_stream_repair_ingress_proof(
        self,
        *,
        binding: SourceReadContinuationBinding,
        incident: sqlite3.Row,
        source_kind: str,
        incident_authorization_sha256: str,
        parent_retirement_operation_id: str | None,
        parent_completion_sha256: str | None,
        parent_completion_event_sha256: str | None,
        incident_event_sha256: str,
        logical_continuation_head_sha256: str,
        eligible_physical_binding: SourceReadContinuationBinding,
        eligible_physical_head_sha256: str,
        eligible_physical_envelope_sha256: str,
        verification: SourceReadLedgerVerification,
    ) -> SourceReadStreamRepairIngressProof:
        proof = object.__new__(SourceReadStreamRepairIngressProof)
