    @staticmethod
    def _continuation_source_spec(operation_id: str) -> dict[str, str]:
        if _SOURCE_OPERATION_ID.fullmatch(operation_id) is not None:
            return {
                "table": "source_read_outcomes",
                "operation_column": "operation_id",
                "entity_column": "outcome_id",
                "sha_column": "outcome_sha256",
                "binding_sha_column": "continuation_binding_sha256",
                "binding_json_column": "continuation_binding_json",
                "head_column": "outcome_id",
                "entity_kind": "OUTCOME",
                "event_suffix": "",
            }
        if _ROTATION_OPERATION_ID.fullmatch(operation_id) is not None:
            return {
                "table": "source_read_continuation_rebindings",
                "operation_column": "rotation_id",
                "entity_column": "rotation_id",
                "sha_column": "rotation_sha256",
                "binding_sha_column": "next_ledger_binding_sha256",
                "binding_json_column": "next_binding_json",
                "head_column": "rotation_id",
                "entity_kind": "CONTINUATION",
                "event_suffix": "",
            }
        if _MIGRATION_OPERATION_ID.fullmatch(operation_id) is not None:
            return {
                "table": "source_read_continuation_migrations",
                "operation_column": "migration_id",
                "entity_column": "migration_id",
                "sha_column": "migration_sha256",
                "binding_sha_column": "next_ledger_binding_sha256",
                "binding_json_column": "next_binding_json",
                "head_column": "migration_id",
                "entity_kind": "CONTINUATION_MIGRATION",
                "event_suffix": "",
            }
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(operation_id) is not None:
            return {
                "table": "source_read_stream_repair_bindings",
                "operation_column": "repair_id",
                "entity_column": "repair_id",
                "sha_column": "repair_binding_sha256",
                "binding_sha_column": "next_ledger_binding_sha256",
                "binding_json_column": "next_binding_json",
                "head_column": "repair_id",
                "entity_kind": "STREAM_REPAIR",
                "event_suffix": ":BIND",
            }
        raise SourceReadLedgerValidationError("operation identity is invalid")

    @classmethod
    def _continuation_entity_rows_locked(
        cls,
        connection: sqlite3.Connection,
        operation_id: str,
        *,
        expected_binding_sha256: str | None = None,
    ) -> tuple[dict[str, str], list[sqlite3.Row]]:
        spec = cls._continuation_source_spec(operation_id)
        sql = (
            f"SELECT {spec['entity_column']} AS entity_id,"
            f" {spec['sha_column']} AS entity_sha256,"
            f" {spec['binding_sha_column']} AS binding_sha256,"
            f" {spec['binding_json_column']} AS binding_json"
            f" FROM {spec['table']} WHERE {spec['operation_column']}=?"
            f" AND {spec['binding_sha_column']} IS NOT NULL"
        )
        parameters: list[object] = [operation_id]
        if expected_binding_sha256 is not None:
            sql += f" AND {spec['binding_sha_column']}=?"
            parameters.append(expected_binding_sha256)
        sql += " ORDER BY sequence"
        return spec, connection.execute(sql, tuple(parameters)).fetchall()

    def verify_continuation_proof(self, proof: SourceReadContinuationProof) -> bool:
        """Re-read canonical ledger/anchor state before vault ACTIVATE."""

        if not self.continuation_proof_is_known(proof):
            return False
        with self._read() as connection:
            verification = self._verify_locked(connection)
            try:
                self._assert_authority_approval_fence_locked(connection)
                self._assert_no_active_key_lifecycle_locked(connection)
            except SourceReadLedgerError:
                return False
            try:
                spec, rows = self._continuation_entity_rows_locked(
                    connection,
                    proof.binding.operation_id,
                    expected_binding_sha256=proof.binding.ledger_binding_sha256,
                )
            except SourceReadLedgerError:
                return False
            row = next(
                (item for item in rows if item["entity_id"] == proof.outcome_id),
                None,
            )
            event = connection.execute(
                """SELECT * FROM source_read_events
                   WHERE entity_kind=? AND entity_id=?""",
                (
                    spec["entity_kind"],
                    proof.outcome_id + spec["event_suffix"],
                ),
            ).fetchone()
            head_was_canonical = connection.execute(
                "SELECT 1 FROM source_read_events WHERE event_sha256=?",
                (proof.ledger_head_event_sha256,),
            ).fetchone()
            if row is None or event is None or head_was_canonical is None:
                return False
            binding = _continuation_binding_from_material(
                _stored_json(row["binding_json"], "continuation binding")
            )
            latest_head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (_continuation_lineage_sha256(binding),),
            ).fetchone()
            stream_incident = self._latest_stream_incident_locked(
                connection,
                lineage_sha256=_continuation_lineage_sha256(binding),
            )
            writer_epoch = self._runtime_vault_writer_epoch_locked(
                connection,
                binding.vault_store_identity_sha256,
                replayed=True,
            )
            if (
                latest_head is None
                or latest_head[spec["head_column"]] != row["entity_id"]
                or latest_head["ledger_binding_sha256"] != binding.ledger_binding_sha256
            ):
                return False
            anchor_not_rolled_back = (
                verification.external_anchor_generation
                >= proof.external_anchor_generation
            )
            if (
                verification.external_anchor_generation
                == proof.external_anchor_generation
            ):
                anchor_not_rolled_back = anchor_not_rolled_back and (
                    verification.external_anchor_receipt_sha256
                    == proof.external_anchor_receipt_sha256
                )
            return bool(
                binding == proof.binding
                and row["entity_sha256"] == proof.outcome_sha256
                and event["event_sha256"] == proof.outcome_event_sha256
                and latest_head["head_sha256"] == proof.continuation_head_sha256
                and writer_epoch.state
                is not SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
                and proof.writer_epoch_head_sha256
                == writer_epoch.writer_epoch_head_sha256
                and proof.external_anchor_status == verification.external_anchor_status
                and (
                    stream_incident is None
                    or stream_incident[1] is SourceReadStreamRecoveryState.RESOLVED
                )
                and anchor_not_rolled_back
                and proof.live_release_eligible is False
            )

    def verify_latest_continuation_proof(
        self, proof: SourceReadContinuationProof
    ) -> bool:
        """Explicit vault-facing alias: historical lineage proofs are rejected."""

        return self.verify_continuation_proof(proof)

    @staticmethod
    def _operation_recovery_proof_commitment(
        proof: SourceReadOperationRecoveryProof,
    ) -> tuple[object, ...]:
        return (
            proof.operation_id,
            proof.request_sha256,
            proof.registry_snapshot_sha256,
            proof.registry_projection_sha256,
            proof.binding_id,
            proof.provider_id,
            proof.account_id,
            proof.capability_snapshot_sha256,
            proof.quota_epoch_sha256,
            proof.checkpoint_before_sha256,
            proof.stream_sha256,
            proof.stream_scope_sha256,
            proof.position_sha256,
            proof.command_sha256,
            proof.custody_reservation_sha256,
            proof.custody_state,
            proof.current_continuation_binding_sha256,
            proof.writer_epoch_root_sha256,
            proof.ledger_head_event_sha256,
            proof.external_anchor_generation,
            proof.external_anchor_receipt_sha256,
            proof.factory_attested,
            proof.live_release_eligible,
        )

    def _mint_operation_recovery_proof(
        self,
        *,
        operation: ReadOperationCustody,
        registry_projection_sha256: str,
        stream_sha256: str,
        current_continuation_binding_sha256: str | None,
        writer_epoch_root_sha256: str,
        verification: SourceReadLedgerVerification,
    ) -> SourceReadOperationRecoveryProof:
        proof = object.__new__(SourceReadOperationRecoveryProof)
        values: dict[str, object] = {
            "operation_id": operation.operation_id,
            "request_sha256": operation.request_sha256,
            "registry_snapshot_sha256": operation.registry_snapshot_sha256,
            "registry_projection_sha256": registry_projection_sha256,
            "binding_id": operation.binding_id,
            "provider_id": operation.provider_id,
            "account_id": operation.account_id,
            "capability_snapshot_sha256": operation.capability_snapshot_sha256,
            "quota_epoch_sha256": operation.quota_epoch_sha256,
            "checkpoint_before_sha256": operation.checkpoint_before_sha256,
            "stream_sha256": stream_sha256,
            "stream_scope_sha256": operation.stream_scope_sha256,
            "position_sha256": operation.position_sha256,
            "command_sha256": operation.command_sha256,
            "custody_reservation_sha256": operation.custody_reservation_sha256,
            "custody_state": operation.state,
            "current_continuation_binding_sha256": (
                current_continuation_binding_sha256
            ),
            "writer_epoch_root_sha256": writer_epoch_root_sha256,
            "ledger_head_event_sha256": verification.head_event_sha256,
            "external_anchor_generation": verification.external_anchor_generation,
            "external_anchor_receipt_sha256": (
                verification.external_anchor_receipt_sha256
            ),
            "factory_attested": True,
            "live_release_eligible": False,
        }
        for name, value in values.items():
            object.__setattr__(proof, name, value)
        commitment = self._operation_recovery_proof_commitment(proof)
        with self._operation_recovery_proofs_lock:
            self._operation_recovery_proofs[id(proof)] = (proof, commitment)
        return proof

    def operation_recovery_proof_is_known(
        self, proof: SourceReadOperationRecoveryProof
    ) -> bool:
        """Validate exact object identity and fields against this ledger factory."""

        if type(proof) is not SourceReadOperationRecoveryProof:
            return False
        with self._operation_recovery_proofs_lock:
            record = self._operation_recovery_proofs.get(id(proof))
            try:
                return bool(
                    record is not None
                    and record[0] is proof
                    and record[1] == self._operation_recovery_proof_commitment(proof)
                )
            except AttributeError:
                return False

    @staticmethod
    def _current_operation_continuation_locked(
        connection: sqlite3.Connection, operation_id: str
    ) -> str | None:
        row = connection.execute(
            """SELECT continuation_binding_sha256
               FROM source_read_outcomes
               WHERE operation_id=? AND continuation_binding_sha256 IS NOT NULL
               ORDER BY sequence DESC LIMIT 1""",
            (operation_id,),
        ).fetchone()
        return None if row is None else str(row["continuation_binding_sha256"])

    @staticmethod
    def _stable_stream_for_lineage_locked(
        connection: sqlite3.Connection, lineage_sha256: str
    ) -> str:
        row = connection.execute(
            """SELECT op.stable_stream_sha256
               FROM source_read_continuation_heads h
               JOIN source_read_outcomes o ON o.outcome_id=h.outcome_id
               JOIN source_read_operations op ON op.operation_id=o.operation_id
               WHERE h.lineage_sha256=? AND h.outcome_id IS NOT NULL
               ORDER BY h.sequence LIMIT 1""",
            (lineage_sha256,),
        ).fetchone()
        if row is None:
            raise SourceReadLedgerStateConflict(
                "continuation lineage has no canonical source stream origin"
            )
        return str(row["stable_stream_sha256"])

    @staticmethod
    def _continuation_position_context_locked(
        connection: sqlite3.Connection, head: sqlite3.Row
    ) -> tuple[str, dict[str, Any], SourceReadContinuationPositionBinding | None]:
        """Resolve the canonical projection/checkpoint behind one head."""

        current = head
        for _ in range(MAX_SNAPSHOT_ROWS):
            if current["migration_id"] is not None:
                row = connection.execute(
                    "SELECT * FROM source_read_continuation_migrations WHERE migration_id=?",
                    (current["migration_id"],),
                ).fetchone()
                if row is None:
                    break
                return (
                    str(row["next_registry_projection_sha256"]),
                    _stored_json(
                        row["next_checkpoint_json"], "migration checkpoint context"
                    ),
                    _continuation_position_from_material(
                        _stored_json(
                            row["next_position_binding_json"],
                            "migration position context",
                        )
                    ),
                )
            if current["repair_id"] is not None:
                row = connection.execute(
                    "SELECT * FROM source_read_stream_repair_bindings WHERE repair_id=?",
                    (current["repair_id"],),
                ).fetchone()
                if row is None:
                    break
                position = _continuation_position_from_material(
                    _stored_json(
                        row["position_binding_json"], "repair position context"
                    )
                )
                prior = connection.execute(
                    "SELECT * FROM source_read_continuation_heads WHERE head_sha256=?",
                    (current["previous_head_sha256"],),
                ).fetchone()
                if prior is None:
                    break
                projection, checkpoint, _ = (
                    SourceReadLedger._continuation_position_context_locked(
                        connection, prior
                    )
                )
                return projection, checkpoint, position
            if current["rotation_id"] is not None:
                current = connection.execute(
                    "SELECT * FROM source_read_continuation_heads WHERE head_sha256=?",
                    (current["previous_head_sha256"],),
                ).fetchone()
                if current is None:
                    break
                continue
            if current["outcome_id"] is not None:
                row = connection.execute(
                    """SELECT o.*,op.batch_id,b.registry_snapshot_sha256,
                              b.registry_projection_sha256,b.quota_epoch_sha256,
                              b.registry_material_json
                       FROM source_read_outcomes o
                       JOIN source_read_operations op ON op.operation_id=o.operation_id
                       JOIN source_read_batches b ON b.batch_id=op.batch_id
                       WHERE o.outcome_id=?""",
                    (current["outcome_id"],),
                ).fetchone()
                if row is None or row["checkpoint_after_json"] is None:
                    break
                checkpoint = _stored_json(
                    row["checkpoint_after_json"], "outcome checkpoint context"
                )
                # Historical v2 outcomes did not persist runtime content
                # binding.  All other position fields are re-derived here;
                # migration requires the injected vault verifier + SoD receipt
                # to attest the exact content commitment.
                return str(row["registry_projection_sha256"]), checkpoint, None
        raise SourceReadLedgerIntegrityError(
            "continuation position context cannot be resolved"
        )

    @staticmethod
    def _position_matches_head_locked(
        connection: sqlite3.Connection,
        head: sqlite3.Row,
        position: SourceReadContinuationPositionBinding,
    ) -> bool:
        projection, checkpoint, exact_position = (
            SourceReadLedger._continuation_position_context_locked(connection, head)
        )
        if exact_position is not None:
            return exact_position == position
        current = head
        for _ in range(MAX_SNAPSHOT_ROWS):
            if current["outcome_id"] is not None:
                row = connection.execute(
                    """SELECT op.*,b.registry_snapshot_sha256,
                              b.registry_projection_sha256,b.quota_epoch_sha256,
                              b.registry_material_json,o.checkpoint_after_json
                       FROM source_read_continuation_heads h
                       JOIN source_read_outcomes o ON o.outcome_id=h.outcome_id
                       JOIN source_read_operations op ON op.operation_id=o.operation_id
                       JOIN source_read_batches b ON b.batch_id=op.batch_id
                       WHERE h.head_sha256=?""",
                    (current["head_sha256"],),
                ).fetchone()
                if row is None:
                    return False
                registry = _stored_json(
                    row["registry_material_json"], "position origin registry"
                )
                capability = next(
                    (
                        item
                        for item in registry["capabilities"]
                        if item["capability_snapshot_sha256"]
                        == row["capability_snapshot_sha256"]
                    ),
                    None,
                )
                command = _stored_json(
                    row["command_material_json"], "position origin command"
                )
                if capability is None:
                    return False
                return bool(
                    projection == row["registry_projection_sha256"]
                    and checkpoint["checkpoint_sha256"] == position.checkpoint_sha256
                    and position.registry_snapshot_sha256
                    == row["registry_snapshot_sha256"]
                    and position.binding_id == row["binding_id"]
                    and position.provider_id == row["provider_id"]
                    and position.account_id == capability["account_id"]
                    and position.capability_snapshot_sha256
                    == row["capability_snapshot_sha256"]
                    and position.authorization_sha256 == command["authorization_sha256"]
                    and position.authorization_receipt_sha256
                    == command["authorization_receipt_sha256"]
                    and position.quota_epoch_sha256 == row["quota_epoch_sha256"]
                    and position.stream_sha256 == command["stream_id_sha256"]
                    and position.checkpoint_next_page_sequence
                    == checkpoint["next_page_sequence"]
                    and position.checkpoint_expected_cursor_sha256
                    == checkpoint["expected_cursor_sha256"]
                    and position.checkpoint_terminal == checkpoint["terminal"]
                )
            current = connection.execute(
                "SELECT * FROM source_read_continuation_heads WHERE head_sha256=?",
                (current["previous_head_sha256"],),
            ).fetchone()
            if current is None:
                return False
        return False

    @staticmethod
    def _registry_material_for_head_locked(
        connection: sqlite3.Connection, head: sqlite3.Row
    ) -> dict[str, Any]:
        current = head
        for _ in range(MAX_SNAPSHOT_ROWS):
            if current["migration_id"] is not None:
                row = connection.execute(
                    "SELECT next_registry_material_json FROM source_read_continuation_migrations WHERE migration_id=?",
                    (current["migration_id"],),
                ).fetchone()
                if row is not None:
                    return _stored_json(
                        row["next_registry_material_json"],
                        "continuation registry context",
                    )
            if current["outcome_id"] is not None:
                row = connection.execute(
                    """SELECT b.registry_material_json
                       FROM source_read_continuation_heads h
                       JOIN source_read_outcomes o ON o.outcome_id=h.outcome_id
                       JOIN source_read_operations op ON op.operation_id=o.operation_id
                       JOIN source_read_batches b ON b.batch_id=op.batch_id
                       WHERE h.head_sha256=?""",
                    (current["head_sha256"],),
                ).fetchone()
                if row is not None:
                    return _stored_json(
                        row["registry_material_json"],
                        "continuation registry context",
                    )
            current = connection.execute(
                "SELECT * FROM source_read_continuation_heads WHERE head_sha256=?",
                (current["previous_head_sha256"],),
            ).fetchone()
            if current is None:
                break
        raise SourceReadLedgerIntegrityError(
            "continuation registry context cannot be resolved"
        )

    @staticmethod
    def _request_material_for_head_locked(
        connection: sqlite3.Connection, head: sqlite3.Row
    ) -> dict[str, Any]:
        current = head
        for _ in range(MAX_SNAPSHOT_ROWS):
            if current["migration_id"] is not None:
                row = connection.execute(
                    "SELECT next_request_material_json FROM source_read_continuation_migrations WHERE migration_id=?",
                    (current["migration_id"],),
                ).fetchone()
                if row is not None:
                    return _stored_json(
                        row["next_request_material_json"],
                        "continuation request context",
                    )
            if current["outcome_id"] is not None:
                row = connection.execute(
                    """SELECT b.request_material_json
                       FROM source_read_continuation_heads h
                       JOIN source_read_outcomes o ON o.outcome_id=h.outcome_id
                       JOIN source_read_operations op ON op.operation_id=o.operation_id
                       JOIN source_read_batches b ON b.batch_id=op.batch_id
                       WHERE h.head_sha256=?""",
                    (current["head_sha256"],),
                ).fetchone()
                if row is not None:
                    return _stored_json(
                        row["request_material_json"],
                        "continuation request context",
                    )
            current = connection.execute(
                "SELECT * FROM source_read_continuation_heads WHERE head_sha256=?",
                (current["previous_head_sha256"],),
            ).fetchone()
            if current is None:
                break
        raise SourceReadLedgerIntegrityError(
            "continuation request context cannot be resolved"
        )

    @staticmethod
    def _continuation_binding_for_head_locked(
        connection: sqlite3.Connection, head: sqlite3.Row
    ) -> SourceReadContinuationBinding:
        sources = (
            (
                "outcome_id",
                "source_read_outcomes",
                "outcome_id",
                "continuation_binding_json",
            ),
            (
                "rotation_id",
                "source_read_continuation_rebindings",
                "rotation_id",
                "next_binding_json",
            ),
            (
                "migration_id",
                "source_read_continuation_migrations",
                "migration_id",
                "next_binding_json",
            ),
            (
                "repair_id",
                "source_read_stream_repair_bindings",
                "repair_id",
                "next_binding_json",
            ),
        )
        for head_column, table, key_column, json_column in sources:
            if head[head_column] is None:
                continue
            row = connection.execute(
                f"SELECT {json_column} FROM {table} WHERE {key_column}=?",
                (head[head_column],),
            ).fetchone()
            if row is None:
                break
            return _continuation_binding_from_material(
                _stored_json(row[json_column], "continuation head binding")
            )
        raise SourceReadLedgerIntegrityError(
            "continuation head binding cannot be resolved"
        )

    def _vault_alignment_heads_locked(
        self,
        connection: sqlite3.Connection,
        vault_store_identity_sha256: str,
    ) -> tuple[SourceReadVaultContinuationAlignmentHead, ...]:
        vault_store = _sha256(
            vault_store_identity_sha256, "alignment vault store identity"
        )
        latest_rows = connection.execute(
            """SELECT h.* FROM source_read_continuation_heads h
               WHERE h.sequence=(
                   SELECT MAX(other.sequence)
                   FROM source_read_continuation_heads other
                   WHERE other.lineage_sha256=h.lineage_sha256)
               ORDER BY h.lineage_sha256"""
        ).fetchall()
        heads: list[SourceReadVaultContinuationAlignmentHead] = []
        for latest_row in latest_rows:
            row = latest_row
            binding = self._continuation_binding_for_head_locked(connection, row)
            if binding.vault_store_identity_sha256 != vault_store:
                continue
            if binding.position_binding_sha256 is None:
                raise SourceReadLedgerStateConflict(
                    "key retirement alignment cannot prove a legacy continuation"
                )
            material: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "VAULT_CONTINUATION_ALIGNMENT_HEAD",
                "lineage_sha256": str(row["lineage_sha256"]),
                "slot_sha256": binding.slot_sha256,
                "generation": binding.generation,
                "expected_active_version": binding.previous_active_version + 1,
                "envelope_sha256": binding.envelope_sha256,
                "ledger_binding_sha256": binding.ledger_binding_sha256,
                "position_binding_sha256": binding.position_binding_sha256,
                "operation_id": binding.operation_id,
                "expected_outcome": binding.expected_outcome,
                "continuation_head_sha256": str(row["head_sha256"]),
            }
            heads.append(
                SourceReadVaultContinuationAlignmentHead(
                    str(material["lineage_sha256"]),
                    str(material["slot_sha256"]),
                    int(material["generation"]),
                    int(material["expected_active_version"]),
                    str(material["envelope_sha256"]),
                    str(material["ledger_binding_sha256"]),
                    str(material["position_binding_sha256"]),
                    str(material["operation_id"]),
                    str(material["expected_outcome"]),
                    str(material["continuation_head_sha256"]),
                    _value_sha256(material),
                )
            )
        result = tuple(
            sorted(heads, key=lambda item: (item.slot_sha256, item.lineage_sha256))
        )
        _vault_alignment_heads_sha256(result)
        return result

    def _key_compromise_targets_locked(
        self,
        connection: sqlite3.Connection,
        *,
        operation_id: str,
        vault_store_identity_sha256: str,
        inventory: tuple[SourceReadKeyRetirementInventoryItem, ...],
    ) -> tuple[tuple[str, sqlite3.Row, SourceReadKeyRetirementInventoryItem], ...]:
        """Resolve the sealed latest target while preserving an earlier incident."""

        targets: list[
            tuple[str, sqlite3.Row, SourceReadKeyRetirementInventoryItem]
        ] = []
        for active_item in (item for item in inventory if item.is_active_head):
            lineage = _value_sha256(
                {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "SOURCE_READ_CONTINUATION_LINEAGE",
                    "vault_store_identity_sha256": vault_store_identity_sha256,
                    "slot_sha256": active_item.slot_sha256,
                }
            )
            active_head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? AND ledger_binding_sha256=?""",
                (lineage, active_item.ledger_binding_sha256),
            ).fetchone()
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (lineage,),
            ).fetchone()
            if active_head is None or latest is None:
                raise SourceReadLedgerStateConflict(
                    "key compromise inventory has no exact ledger lineage"
                )
            if latest["ledger_binding_sha256"] != active_item.ledger_binding_sha256:
                prior_incident = connection.execute(
                    """SELECT * FROM source_read_stream_incidents
                       WHERE lineage_sha256=? AND continuation_head_sha256=?
                         AND (parent_retirement_operation_id IS NULL
                              OR parent_retirement_operation_id<>?)
                       ORDER BY sequence DESC LIMIT 1""",
                    (lineage, active_head["head_sha256"], operation_id),
                ).fetchone()
                if prior_incident is None:
                    raise SourceReadLedgerStateConflict(
                        "key compromise ledger/vault divergence has no incident"
                    )
                repair = connection.execute(
                    """SELECT * FROM source_read_stream_repair_bindings
                       WHERE incident_id=? ORDER BY sequence DESC LIMIT 1""",
                    (prior_incident["incident_id"],),
                ).fetchone()
                if repair is None:
                    raise SourceReadLedgerStateConflict(
                        "key compromise incident does not explain latest ledger head"
                    )
                abandonment = connection.execute(
                    """SELECT * FROM source_read_stream_repair_abandonments
                       WHERE repair_id=?""",
                    (repair["repair_id"],),
                ).fetchone()
                disposed = connection.execute(
                    """SELECT 1 FROM source_read_stream_repair_dispositions
                       WHERE repair_id=?""",
                    (repair["repair_id"],),
                ).fetchone()
                if disposed is not None or latest["repair_id"] != repair["repair_id"]:
                    raise SourceReadLedgerStateConflict(
                        "key compromise incident repair is already resolved"
                    )
                staged_item = next(
                    (
                        item
                        for item in inventory
                        if item.slot_sha256 == active_item.slot_sha256
                        and item.ledger_binding_sha256
                        == latest["ledger_binding_sha256"]
                    ),
                    None,
                )
                reusable_absence = abandonment is not None and abandonment[
                    "reason_code"
                ] in {
                    SourceReadPreparedAbsenceReason.PREPARED_MISSING.value,
                    SourceReadPreparedAbsenceReason.PREPARED_ROLLBACK.value,
                }
                if reusable_absence and staged_item is not None:
                    raise SourceReadLedgerStateConflict(
                        "key compromise inventory resurrects an absent repair leaf"
                    )
                if not reusable_absence and staged_item is None:
                    raise SourceReadLedgerStateConflict(
                        "key compromise sealed inventory omits a retained repair leaf"
                    )
            targets.append((lineage, active_head, active_item))
        if len({lineage for lineage, _, _ in targets}) != len(targets):
            raise SourceReadLedgerStateConflict(
                "key compromise inventory repeats a continuation lineage"
            )
        return tuple(targets)

    @staticmethod
    def _latest_stream_incident_locked(
        connection: sqlite3.Connection,
        *,
        lineage_sha256: str | None = None,
        stable_stream_sha256: str | None = None,
    ) -> tuple[sqlite3.Row, SourceReadStreamRecoveryState] | None:
        if (lineage_sha256 is None) == (stable_stream_sha256 is None):
            raise SourceReadLedgerIntegrityError(
                "stream incident lookup needs one exact identity"
            )
        column = (
            "lineage_sha256" if lineage_sha256 is not None else "stable_stream_sha256"
        )
        value = lineage_sha256 if lineage_sha256 is not None else stable_stream_sha256
        incident = connection.execute(
            f"""SELECT * FROM source_read_stream_incidents
                WHERE {column}=? ORDER BY sequence DESC LIMIT 1""",
            (value,),
        ).fetchone()
        if incident is None:
            return None
        repair = connection.execute(
            """SELECT * FROM source_read_stream_repair_bindings
               WHERE incident_id=? ORDER BY sequence DESC LIMIT 1""",
            (incident["incident_id"],),
        ).fetchone()
        if repair is None:
            return incident, SourceReadStreamRecoveryState.ACTIVE
        abandonment = connection.execute(
            "SELECT 1 FROM source_read_stream_repair_abandonments WHERE repair_id=?",
            (repair["repair_id"],),
        ).fetchone()
        if abandonment is not None:
            return incident, SourceReadStreamRecoveryState.ACTIVE
        disposition = connection.execute(
            "SELECT 1 FROM source_read_stream_repair_dispositions WHERE repair_id=?",
            (repair["repair_id"],),
        ).fetchone()
        return incident, (
            SourceReadStreamRecoveryState.RESOLVED
            if disposition is not None
            else SourceReadStreamRecoveryState.REPAIR_BOUND
        )

    @classmethod
    def _assert_no_active_stream_incident_locked(
        cls,
        connection: sqlite3.Connection,
        *,
        lineage_sha256: str | None = None,
        stable_stream_sha256: str | None = None,
    ) -> None:
        incident = cls._latest_stream_incident_locked(
            connection,
            lineage_sha256=lineage_sha256,
            stable_stream_sha256=stable_stream_sha256,
        )
        if (
            incident is not None
            and incident[1] is not SourceReadStreamRecoveryState.RESOLVED
        ):
            raise SourceReadLedgerStateConflict(
                "source stream is under durable vault reconciliation quarantine"
            )

    @classmethod
    def _assert_no_unresolved_stream_incidents_locked(
        cls,
        connection: sqlite3.Connection,
        *,
        vault_store_identity_sha256: str | None = None,
    ) -> None:
        parameters: tuple[object, ...] = ()
        where = ""
        if vault_store_identity_sha256 is not None:
            where = "WHERE vault_store_identity_sha256=?"
            parameters = (
                _sha256(
                    vault_store_identity_sha256,
                    "incident vault store identity",
                ),
            )
        rows = connection.execute(
            f"""SELECT i.* FROM source_read_stream_incidents i
                {where}
                AND i.sequence=(
                    SELECT MAX(other.sequence)
                    FROM source_read_stream_incidents other
                    WHERE other.lineage_sha256=i.lineage_sha256)
                """
            if where
            else """SELECT i.* FROM source_read_stream_incidents i
                     WHERE i.sequence=(
                         SELECT MAX(other.sequence)
                         FROM source_read_stream_incidents other
                         WHERE other.lineage_sha256=i.lineage_sha256)""",
            parameters,
        ).fetchall()
        for row in rows:
            state = cls._latest_stream_incident_locked(
                connection,
                lineage_sha256=str(row["lineage_sha256"]),
            )
            if (
                state is not None
                and state[1] is not SourceReadStreamRecoveryState.RESOLVED
            ):
                raise SourceReadLedgerStateConflict(
                    "vault-key lifecycle requires every stream incident resolved"
                )

    @staticmethod
    def _key_compromise_blocking_state_locked(
        connection: sqlite3.Connection,
        *,
        vault_store_identity_sha256: str,
        before_event_sequence: int,
    ) -> tuple[str, str]:
        """Derive the immutable local eligibility snapshot before DETECTED.

        A dirty detection is deliberately terminal for this offline slice.  The
        event-sequence cutoff lets reopen verification reproduce the decision
        even if a recovery-only outcome is appended later under the fence.
        """

        cutoff = _bounded_int(
            before_event_sequence,
            "key compromise detection event sequence",
            maximum=9_223_372_036_854_775_807,
        )
        vault_store = _sha256(
            vault_store_identity_sha256,
            "key compromise detection vault store",
        )
        unresolved = connection.execute(
            """SELECT op.operation_id,op.operation_sha256
               FROM source_read_operations op
               JOIN source_read_events reserved
                 ON reserved.entity_kind='OPERATION'
                AND reserved.entity_id=op.operation_id
               WHERE reserved.sequence<?
                 AND NOT EXISTS(
                     SELECT 1
                     FROM source_read_outcomes outcome
                     JOIN source_read_events completed
                       ON completed.entity_kind='OUTCOME'
                      AND completed.entity_id=outcome.outcome_id
                     WHERE outcome.operation_id=op.operation_id
                       AND outcome.outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')
                       AND completed.sequence<?)
               ORDER BY op.operation_id""",
            (cutoff, cutoff),
        ).fetchall()
        incidents = connection.execute(
            """SELECT incident.incident_id,incident.incident_sha256,
                      incident.lineage_sha256
               FROM source_read_stream_incidents incident
               JOIN source_read_events opened
                 ON opened.entity_kind='STREAM_INCIDENT'
                AND opened.entity_id=incident.incident_id
               WHERE incident.vault_store_identity_sha256=?
                 AND opened.sequence<?
                 AND opened.sequence=(
                     SELECT MAX(other_opened.sequence)
                     FROM source_read_stream_incidents other_incident
                     JOIN source_read_events other_opened
                       ON other_opened.entity_kind='STREAM_INCIDENT'
                      AND other_opened.entity_id=other_incident.incident_id
                     WHERE other_incident.lineage_sha256=incident.lineage_sha256
                       AND other_opened.sequence<?)
                 AND NOT EXISTS(
                     SELECT 1
                     FROM source_read_stream_repair_dispositions disposition
                     JOIN source_read_events repaired
                       ON repaired.entity_kind='STREAM_REPAIR'
                      AND repaired.entity_id=disposition.repair_id||':COMPLETE'
                     WHERE disposition.incident_id=incident.incident_id
                       AND repaired.sequence<?)
               ORDER BY incident.lineage_sha256,incident.incident_id""",
            (vault_store, cutoff, cutoff, cutoff),
        ).fetchall()
        if unresolved and incidents:
            disposition = "PERMANENT_UNRESOLVED_READ_AND_STREAM_INCIDENT"
        elif unresolved:
            disposition = "PERMANENT_UNRESOLVED_READ"
        elif incidents:
            disposition = "PERMANENT_STREAM_INCIDENT"
        else:
            disposition = "CLEAN_FINAL"
        blocking_state_sha256 = _value_sha256(
            {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "KEY_COMPROMISE_DETECTION_BLOCKING_STATE",
                "vault_store_identity_sha256": vault_store,
                "unresolved_operations": [
                    {
                        "operation_id": str(row["operation_id"]),
                        "operation_sha256": str(row["operation_sha256"]),
                    }
                    for row in unresolved
                ],
                "active_stream_incidents": [
                    {
                        "incident_id": str(row["incident_id"]),
                        "incident_sha256": str(row["incident_sha256"]),
                        "lineage_sha256": str(row["lineage_sha256"]),
                    }
                    for row in incidents
                ],
            }
        )
        return disposition, blocking_state_sha256

    @staticmethod
    def _assert_key_compromise_containment_eligible_locked(
        connection: sqlite3.Connection,
        operation_id: str,
    ) -> sqlite3.Row:
        row = connection.execute(
            """SELECT * FROM source_read_key_compromise_detections
               WHERE operation_id=?""",
            (operation_id,),
        ).fetchone()
        if row is None:
            raise SourceReadLedgerStateConflict(
                "key compromise containment has no anchored detection fence"
            )
        if row["containment_disposition"] != "CLEAN_FINAL":
            raise SourceReadLedgerStateConflict(
                "key compromise detection is a permanent global quarantine"
            )
        return row

    @staticmethod
    def _assert_no_unrelated_key_compromise_detection_locked(
        connection: sqlite3.Connection,
        *,
        allowed_operation_id: str | None,
    ) -> None:
        row = connection.execute(
            """SELECT 1
               FROM source_read_key_compromise_detections detection
               LEFT JOIN source_read_key_retirement_completions completion
                 ON completion.operation_id=detection.operation_id
               WHERE completion.operation_id IS NULL
                 AND (? IS NULL OR detection.operation_id<>?)
               LIMIT 1""",
            (allowed_operation_id, allowed_operation_id),
        ).fetchone()
        if row is not None:
            raise SourceReadLedgerStateConflict(
                "vault-key action is stale under a later compromise detection"
            )

    @staticmethod
    def _writer_epoch_transition_material(
        row: Mapping[str, object],
    ) -> dict[str, object]:
        return {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "record_kind": "RUNTIME_VAULT_WRITER_EPOCH_TRANSITION",
            "operation_id": row["operation_id"],
            "vault_store_identity_sha256": row["vault_store_identity_sha256"],
            "request_sha256": row["request_sha256"],
            "transition_mode": row["writer_epoch_transition_mode"],
            "predecessor_writer_sequence": row["predecessor_writer_sequence"],
            "predecessor_writer_key_id_sha256": row["predecessor_writer_key_id_sha256"],
            "predecessor_writer_key_epoch_sha256": row[
                "predecessor_writer_key_epoch_sha256"
            ],
            "candidate_writer_sequence": row["candidate_writer_sequence"],
            "candidate_writer_key_id_sha256": row["candidate_writer_key_id_sha256"],
            "candidate_writer_key_epoch_sha256": row[
                "candidate_writer_key_epoch_sha256"
            ],
            "candidate_key_verifier_sha256": row["candidate_key_verifier_sha256"],
            "candidate_vault_event_predecessor_sha256": row[
                "candidate_vault_event_predecessor_sha256"
            ],
            "candidate_authorization_sha256": row[
                "vault_candidate_authorization_sha256"
            ],
            "previous_writer_epoch_head_sha256": row[
                "previous_writer_epoch_head_sha256"
            ],
            "occurred_at_utc": row["occurred_at_utc"],
        }

    @classmethod
    def _writer_epoch_transition_from_row(
        cls,
        row: Mapping[str, object],
        *,
        replayed: bool,
    ) -> SourceReadRuntimeVaultWriterEpochTransition:
        return SourceReadRuntimeVaultWriterEpochTransition(
            str(row["operation_id"]),
            str(row["vault_store_identity_sha256"]),
            str(row["request_sha256"]),
            int(row["predecessor_writer_sequence"]),
            str(row["predecessor_writer_key_id_sha256"]),
            str(row["predecessor_writer_key_epoch_sha256"]),
            int(row["candidate_writer_sequence"]),
            str(row["candidate_writer_key_id_sha256"]),
            str(row["candidate_writer_key_epoch_sha256"]),
            str(row["candidate_key_verifier_sha256"]),
            str(row["candidate_vault_event_predecessor_sha256"]),
            str(row["vault_candidate_authorization_sha256"]),
            str(row["previous_writer_epoch_head_sha256"]),
            str(row["writer_epoch_transition_sha256"]),
            str(row["occurred_at_utc"]),
            replayed,
        )

    @classmethod
    def _runtime_vault_writer_epoch_locked(
        cls,
        connection: sqlite3.Connection,
        vault_store_identity_sha256: str,
        *,
        replayed: bool,
        at_event_sequence: int | None = None,
        _skip_successor_already_active_requests: bool = False,
    ) -> SourceReadRuntimeVaultWriterEpoch:
        vault_store = _sha256(
            vault_store_identity_sha256,
            "writer epoch vault_store_identity_sha256",
        )
        if at_event_sequence is None:
            request = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE vault_store_identity_sha256=?
                     AND (?=0 OR writer_epoch_transition_mode<>'SUCCESSOR_ALREADY_ACTIVE')
                   ORDER BY sequence DESC LIMIT 1""",
                (vault_store, int(_skip_successor_already_active_requests)),
            ).fetchone()
        else:
            request = connection.execute(
                """SELECT request.*
                   FROM source_read_key_retirement_requests request
                   JOIN source_read_events event
                     ON event.entity_kind='KEY_LIFECYCLE'
                    AND event.entity_id=request.operation_id || ':REQUEST'
                   WHERE request.vault_store_identity_sha256=?
                     AND event.sequence<=?
                     AND (?=0 OR request.writer_epoch_transition_mode<>'SUCCESSOR_ALREADY_ACTIVE')
                   ORDER BY event.sequence DESC LIMIT 1""",
                (
                    vault_store,
                    at_event_sequence,
                    int(_skip_successor_already_active_requests),
                ),
            ).fetchone()
        if request is None:
            material = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "RUNTIME_VAULT_WRITER_EPOCH_HEAD",
                "vault_store_identity_sha256": vault_store,
                "state": SourceReadRuntimeVaultWriterEpochState.UNMANAGED.value,
                "state_sequence": 0,
                "writer_sequence": 0,
                "writer_key_id_sha256": None,
                "writer_key_epoch_sha256": None,
                "predecessor_writer_key_id_sha256": None,
                "predecessor_writer_key_epoch_sha256": None,
                "transition_operation_id": None,
                "transition_sha256": None,
                "source_phase": "UNMANAGED",
                "source_record_sha256": ZERO_SHA256,
                "source_event_sha256": ZERO_SHA256,
                "previous_writer_epoch_head_sha256": ZERO_SHA256,
                "occurred_at_utc": None,
            }
            return SourceReadRuntimeVaultWriterEpoch(
                vault_store,
                SourceReadRuntimeVaultWriterEpochState.UNMANAGED,
                0,
                0,
                None,
                None,
                None,
                None,
                None,
                None,
                "UNMANAGED",
                ZERO_SHA256,
                ZERO_SHA256,
                ZERO_SHA256,
                _value_sha256(material),
                None,
                replayed,
            )
        ordinal = int(
            connection.execute(
                """SELECT COUNT(*) FROM source_read_key_retirement_requests
                   WHERE vault_store_identity_sha256=? AND sequence<=?""",
                (vault_store, request["sequence"]),
            ).fetchone()[0]
        )
        request_event = connection.execute(
            """SELECT * FROM source_read_events
               WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
            (str(request["operation_id"]) + ":REQUEST",),
        ).fetchone()
        activation = connection.execute(
            """SELECT * FROM source_read_runtime_vault_writer_epoch_activations
               WHERE operation_id=?""",
            (request["operation_id"],),
        ).fetchone()
        request_abandonment = connection.execute(
            """SELECT * FROM source_read_key_retirement_request_abandonments
               WHERE operation_id=?""",
            (request["operation_id"],),
        ).fetchone()
        if request_event is None:
            raise SourceReadLedgerIntegrityError(
                "writer epoch transition request event is absent"
            )
        try:
            transition_mode = SourceReadRuntimeVaultWriterEpochTransitionMode(
                str(request["writer_epoch_transition_mode"])
            )
        except ValueError as error:
            raise SourceReadLedgerIntegrityError(
                "writer epoch transition mode differs"
            ) from error
        activation_event = (
            None
            if activation is None
            else connection.execute(
                """SELECT * FROM source_read_events
                   WHERE entity_kind='RUNTIME_VAULT_WRITER_EPOCH'
                     AND entity_id=?""",
                (request["operation_id"],),
            ).fetchone()
        )
        abandonment_event = (
            None
            if request_abandonment is None
            else connection.execute(
                """SELECT * FROM source_read_events
                   WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
                (str(request["operation_id"]) + ":REQUEST_ABANDON",),
            ).fetchone()
        )
        if activation is not None and activation_event is None:
            raise SourceReadLedgerIntegrityError(
                "writer epoch activation event is absent"
            )
        if request_abandonment is not None and abandonment_event is None:
            raise SourceReadLedgerIntegrityError(
                "writer epoch abandonment event is absent"
            )
        if at_event_sequence is not None:
            if (
                activation_event is not None
                and int(activation_event["sequence"]) > at_event_sequence
            ):
                activation = None
                activation_event = None
            if (
                abandonment_event is not None
                and int(abandonment_event["sequence"]) > at_event_sequence
            ):
                request_abandonment = None
                abandonment_event = None
        if (
            transition_mode
            is SourceReadRuntimeVaultWriterEpochTransitionMode.SUCCESSOR_ALREADY_ACTIVE
        ):
            if activation is not None:
                raise SourceReadLedgerIntegrityError(
                    "already-active writer request has a registration activation"
                )
            prior = cls._runtime_vault_writer_epoch_locked(
                connection,
                vault_store,
                replayed=True,
                at_event_sequence=int(request_event["sequence"]) - 1,
                _skip_successor_already_active_requests=True,
            )
            if (
                prior.state is not SourceReadRuntimeVaultWriterEpochState.ACTIVE
                or prior.writer_epoch_head_sha256
                != request["previous_writer_epoch_head_sha256"]
                or prior.writer_sequence != int(request["candidate_writer_sequence"])
                or prior.writer_key_id_sha256
                != request["candidate_writer_key_id_sha256"]
                or prior.writer_key_epoch_sha256
                != request["candidate_writer_key_epoch_sha256"]
            ):
                raise SourceReadLedgerIntegrityError(
                    "already-active writer request differs from its predecessor"
                )
            return replace(prior, replayed=replayed)
        state = SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
        state_sequence = ordinal * 2 - 1
        writer_sequence = int(request["candidate_writer_sequence"])
        writer_key = str(request["candidate_writer_key_id_sha256"])
        writer_epoch = str(request["candidate_writer_key_epoch_sha256"])
        source_phase = "TRANSITION_PENDING"
        source_record = str(request["record_sha256"])
        source_event = str(request_event["event_sha256"])
        occurred: str | None = str(request["occurred_at_utc"])
        if activation is not None:
            assert activation_event is not None
            state = SourceReadRuntimeVaultWriterEpochState.ACTIVE
            state_sequence = ordinal * 2
            source_phase = "ACTIVE"
            source_record = str(activation["record_sha256"])
            source_event = str(activation_event["event_sha256"])
            occurred = str(activation["occurred_at_utc"])
        elif request_abandonment is not None:
            assert abandonment_event is not None
            if (
                request_abandonment["reason_code"]
                != SourceReadKeyRetirementAbandonmentReason.STALE_ALIGNMENT_NO_LOCAL_BEGIN.value
            ):
                raise SourceReadLedgerIntegrityError(
                    "unregistered writer transition abandonment differs"
                )
            state = SourceReadRuntimeVaultWriterEpochState.ACTIVE
            state_sequence = ordinal * 2
            writer_sequence = int(request["predecessor_writer_sequence"])
            writer_key = str(request["predecessor_writer_key_id_sha256"])
            writer_epoch = str(request["predecessor_writer_key_epoch_sha256"])
            source_phase = "TRANSITION_CANCELLED"
            source_record = str(request_abandonment["record_sha256"])
            source_event = str(abandonment_event["event_sha256"])
            occurred = str(request_abandonment["occurred_at_utc"])
        material = {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "record_kind": "RUNTIME_VAULT_WRITER_EPOCH_HEAD",
            "vault_store_identity_sha256": vault_store,
            "state": state.value,
            "state_sequence": state_sequence,
            "writer_sequence": writer_sequence,
            "writer_key_id_sha256": writer_key,
            "writer_key_epoch_sha256": writer_epoch,
            "predecessor_writer_key_id_sha256": request[
                "predecessor_writer_key_id_sha256"
            ],
            "predecessor_writer_key_epoch_sha256": request[
                "predecessor_writer_key_epoch_sha256"
            ],
            "transition_operation_id": request["operation_id"],
            "transition_sha256": request["writer_epoch_transition_sha256"],
            "source_phase": source_phase,
            "source_record_sha256": source_record,
            "source_event_sha256": source_event,
            "previous_writer_epoch_head_sha256": request[
                "previous_writer_epoch_head_sha256"
            ],
            "occurred_at_utc": occurred,
        }
        return SourceReadRuntimeVaultWriterEpoch(
            vault_store,
            state,
            state_sequence,
            writer_sequence,
            writer_key,
            writer_epoch,
            str(request["predecessor_writer_key_id_sha256"]),
            str(request["predecessor_writer_key_epoch_sha256"]),
            str(request["operation_id"]),
            str(request["writer_epoch_transition_sha256"]),
            source_phase,
            source_record,
            source_event,
            str(request["previous_writer_epoch_head_sha256"]),
            _value_sha256(material),
            occurred,
            replayed,
        )

    @classmethod
    def _runtime_vault_writer_epoch_ancestry_locked(
        cls,
        connection: sqlite3.Connection,
        vault_store_identity_sha256: str,
        *,
        at_event_sequence: int | None = None,
    ) -> tuple[SourceReadRuntimeVaultWriterEpochAncestryEntry, ...]:
        vault_store = _sha256(
            vault_store_identity_sha256,
            "writer epoch ancestry vault_store_identity_sha256",
        )
        requests = connection.execute(
            """SELECT request.*,
                      event.sequence AS request_event_sequence
               FROM source_read_key_retirement_requests request
               JOIN source_read_events event
                 ON event.entity_kind='KEY_LIFECYCLE'
                AND event.entity_id=request.operation_id || ':REQUEST'
               WHERE request.vault_store_identity_sha256=?
                 AND (? IS NULL OR event.sequence<=?)
               ORDER BY event.sequence""",
            (vault_store, at_event_sequence, at_event_sequence),
        ).fetchall()
        if len(requests) >= MAX_WRITER_EPOCH_ANCESTRY_ENTRIES:
            raise SourceReadLedgerIntegrityError(
                "writer epoch ancestry exceeds its safe bound"
            )
        activations = {
            str(row["operation_id"]): row
            for row in connection.execute(
                """SELECT activation.*,
                          event.sequence AS state_event_sequence,
                          event.event_sha256 AS state_event_sha256
                   FROM source_read_runtime_vault_writer_epoch_activations activation
                   JOIN source_read_key_retirement_requests request
                     ON request.operation_id=activation.operation_id
                   JOIN source_read_events event
                     ON event.entity_kind='RUNTIME_VAULT_WRITER_EPOCH'
                    AND event.entity_id=activation.operation_id
                   WHERE request.vault_store_identity_sha256=?""",
                (vault_store,),
            ).fetchall()
        }
        abandonments = {
            str(row["operation_id"]): row
            for row in connection.execute(
                """SELECT abandonment.*,
                          event.sequence AS state_event_sequence,
                          event.event_sha256 AS state_event_sha256
                   FROM source_read_key_retirement_request_abandonments abandonment
                   JOIN source_read_key_retirement_requests request
                     ON request.operation_id=abandonment.operation_id
                   JOIN source_read_events event
                     ON event.entity_kind='KEY_LIFECYCLE'
                    AND event.entity_id=abandonment.operation_id || ':REQUEST_ABANDON'
                   WHERE request.vault_store_identity_sha256=?""",
                (vault_store,),
            ).fetchall()
        }
        entries: list[SourceReadRuntimeVaultWriterEpochAncestryEntry] = []
        seen: set[tuple[int, str, str, str]] = set()

        def append_entry(
            writer_sequence: object,
            writer_key_id_sha256: object,
            writer_key_epoch_sha256: object,
            writer_epoch_head_sha256: object,
        ) -> None:
            entry = SourceReadRuntimeVaultWriterEpochAncestryEntry(
                _bounded_int(
                    writer_sequence,
                    "writer ancestry sequence",
                    minimum=1,
                    maximum=MAX_WRITER_EPOCH_ANCESTRY_ENTRIES,
                ),
                _sha256(writer_key_id_sha256, "writer ancestry key identity"),
                _sha256(writer_key_epoch_sha256, "writer ancestry key epoch"),
                _sha256(writer_epoch_head_sha256, "writer ancestry head"),
            )
            identity = (
                entry.writer_sequence,
                entry.writer_key_id_sha256,
                entry.writer_key_epoch_sha256,
                entry.writer_epoch_head_sha256,
            )
            if identity in seen:
                return
            if len(entries) >= MAX_WRITER_EPOCH_ANCESTRY_ENTRIES:
                raise SourceReadLedgerIntegrityError(
                    "writer epoch ancestry exceeds its safe bound"
                )
            entries.append(entry)
            seen.add(identity)

        for ordinal, request in enumerate(requests, 1):
            try:
                mode = SourceReadRuntimeVaultWriterEpochTransitionMode(
                    str(request["writer_epoch_transition_mode"])
                )
            except ValueError as error:
                raise SourceReadLedgerIntegrityError(
                    "writer epoch ancestry transition mode differs"
                ) from error
            if (
                mode
                is SourceReadRuntimeVaultWriterEpochTransitionMode.SUCCESSOR_ALREADY_ACTIVE
            ):
                continue
            if not entries:
                # Pre-managed continuations pin ZERO while the first candidate
                # receipt independently attests the exact predecessor key/epoch.
                append_entry(
                    request["predecessor_writer_sequence"],
                    request["predecessor_writer_key_id_sha256"],
                    request["predecessor_writer_key_epoch_sha256"],
                    ZERO_SHA256,
                )
            else:
                append_entry(
                    request["predecessor_writer_sequence"],
                    request["predecessor_writer_key_id_sha256"],
                    request["predecessor_writer_key_epoch_sha256"],
                    request["previous_writer_epoch_head_sha256"],
                )
            operation_id = str(request["operation_id"])
            activation = activations.get(operation_id)
            abandonment = abandonments.get(operation_id)
            if activation is not None and (
                at_event_sequence is None
                or int(activation["state_event_sequence"]) <= at_event_sequence
            ):
                head_material = {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "RUNTIME_VAULT_WRITER_EPOCH_HEAD",
                    "vault_store_identity_sha256": vault_store,
                    "state": SourceReadRuntimeVaultWriterEpochState.ACTIVE.value,
                    "state_sequence": ordinal * 2,
                    "writer_sequence": request["candidate_writer_sequence"],
                    "writer_key_id_sha256": request["candidate_writer_key_id_sha256"],
                    "writer_key_epoch_sha256": request[
                        "candidate_writer_key_epoch_sha256"
                    ],
                    "predecessor_writer_key_id_sha256": request[
                        "predecessor_writer_key_id_sha256"
                    ],
                    "predecessor_writer_key_epoch_sha256": request[
                        "predecessor_writer_key_epoch_sha256"
                    ],
                    "transition_operation_id": operation_id,
                    "transition_sha256": request["writer_epoch_transition_sha256"],
                    "source_phase": "ACTIVE",
                    "source_record_sha256": activation["record_sha256"],
                    "source_event_sha256": activation["state_event_sha256"],
                    "previous_writer_epoch_head_sha256": request[
                        "previous_writer_epoch_head_sha256"
                    ],
                    "occurred_at_utc": activation["occurred_at_utc"],
                }
                append_entry(
                    request["candidate_writer_sequence"],
                    request["candidate_writer_key_id_sha256"],
                    request["candidate_writer_key_epoch_sha256"],
                    _value_sha256(head_material),
                )
            elif abandonment is not None and (
                at_event_sequence is None
                or int(abandonment["state_event_sequence"]) <= at_event_sequence
            ):
                if (
                    abandonment["reason_code"]
                    != SourceReadKeyRetirementAbandonmentReason.STALE_ALIGNMENT_NO_LOCAL_BEGIN.value
                ):
                    raise SourceReadLedgerIntegrityError(
                        "writer epoch ancestry cancellation reason differs"
                    )
                head_material = {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "RUNTIME_VAULT_WRITER_EPOCH_HEAD",
                    "vault_store_identity_sha256": vault_store,
                    "state": SourceReadRuntimeVaultWriterEpochState.ACTIVE.value,
                    "state_sequence": ordinal * 2,
                    "writer_sequence": request["predecessor_writer_sequence"],
                    "writer_key_id_sha256": request["predecessor_writer_key_id_sha256"],
                    "writer_key_epoch_sha256": request[
                        "predecessor_writer_key_epoch_sha256"
                    ],
                    "predecessor_writer_key_id_sha256": request[
                        "predecessor_writer_key_id_sha256"
                    ],
                    "predecessor_writer_key_epoch_sha256": request[
                        "predecessor_writer_key_epoch_sha256"
                    ],
                    "transition_operation_id": operation_id,
                    "transition_sha256": request["writer_epoch_transition_sha256"],
                    "source_phase": "TRANSITION_CANCELLED",
                    "source_record_sha256": abandonment["record_sha256"],
                    "source_event_sha256": abandonment["state_event_sha256"],
                    "previous_writer_epoch_head_sha256": request[
                        "previous_writer_epoch_head_sha256"
                    ],
                    "occurred_at_utc": abandonment["occurred_at_utc"],
                }
                append_entry(
                    request["predecessor_writer_sequence"],
                    request["predecessor_writer_key_id_sha256"],
                    request["predecessor_writer_key_epoch_sha256"],
                    _value_sha256(head_material),
                )
        current = cls._runtime_vault_writer_epoch_locked(
            connection,
            vault_store,
            replayed=True,
            at_event_sequence=at_event_sequence,
        )
        if current.state is SourceReadRuntimeVaultWriterEpochState.ACTIVE and (
            not entries
            or entries[-1].writer_sequence != current.writer_sequence
            or entries[-1].writer_key_id_sha256 != current.writer_key_id_sha256
            or entries[-1].writer_key_epoch_sha256 != current.writer_key_epoch_sha256
            or entries[-1].writer_epoch_head_sha256 != current.writer_epoch_head_sha256
        ):
            raise SourceReadLedgerIntegrityError(
                "writer epoch ancestry does not end at the active head"
            )
        return tuple(entries)

    @classmethod
    def _runtime_vault_writer_epoch_root_locked(
        cls,
        connection: sqlite3.Connection,
        *,
        at_event_sequence: int | None = None,
    ) -> str:
        if at_event_sequence is None:
            stores = connection.execute(
                """SELECT DISTINCT vault_store_identity_sha256
                   FROM source_read_key_retirement_requests
                   ORDER BY vault_store_identity_sha256"""
            ).fetchall()
        else:
            stores = connection.execute(
                """SELECT DISTINCT request.vault_store_identity_sha256
                   FROM source_read_key_retirement_requests request
                   JOIN source_read_events event
                     ON event.entity_kind='KEY_LIFECYCLE'
                    AND event.entity_id=request.operation_id || ':REQUEST'
                   WHERE event.sequence<=?
                   ORDER BY request.vault_store_identity_sha256""",
                (at_event_sequence,),
            ).fetchall()
        if not stores:
            return ZERO_SHA256
        return _value_sha256(
            {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "RUNTIME_VAULT_WRITER_EPOCH_ROOT",
                "heads": [
                    cls._runtime_vault_writer_epoch_locked(
                        connection,
                        str(row["vault_store_identity_sha256"]),
                        replayed=True,
                        at_event_sequence=at_event_sequence,
                    ).writer_epoch_head_sha256
                    for row in stores
                ],
            }
        )

    @classmethod
    def _assert_continuation_writer_epoch_locked(
        cls,
        connection: sqlite3.Connection,
        binding: SourceReadContinuationBinding,
    ) -> SourceReadRuntimeVaultWriterEpoch:
        writer_epoch = cls._runtime_vault_writer_epoch_locked(
            connection,
            binding.vault_store_identity_sha256,
            replayed=True,
        )
        if (
            writer_epoch.state
            is SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
        ):
            raise SourceReadLedgerStateConflict(
                "continuation write is fenced by a pending writer transition"
            )
        expected = (
            ZERO_SHA256
            if writer_epoch.state is SourceReadRuntimeVaultWriterEpochState.UNMANAGED
            else writer_epoch.writer_epoch_head_sha256
        )
        if binding.writer_epoch_head_sha256 != expected:
            raise SourceReadLedgerStateConflict(
                "continuation binding writer epoch differs from the ledger head"
            )
        return writer_epoch

    @classmethod
    def _assert_writer_epoch_pending_for_request_locked(
        cls,
        connection: sqlite3.Connection,
        request_row: Mapping[str, object],
    ) -> SourceReadRuntimeVaultWriterEpoch:
        writer_epoch = cls._runtime_vault_writer_epoch_locked(
            connection,
            str(request_row["vault_store_identity_sha256"]),
            replayed=True,
        )
        if not cls._writer_epoch_pending_matches_request(writer_epoch, request_row):
            raise SourceReadLedgerStateConflict(
                "key retirement requires the exact pending successor writer transition"
            )
        return writer_epoch

    @staticmethod
    def _writer_epoch_pending_matches_request(
        writer_epoch: SourceReadRuntimeVaultWriterEpoch,
        request_row: Mapping[str, object],
    ) -> bool:
        return bool(
            request_row["writer_epoch_transition_mode"]
            == SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION.value
            and writer_epoch.state
            is SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
            and writer_epoch.transition_operation_id == request_row["operation_id"]
            and writer_epoch.transition_sha256
            == request_row["writer_epoch_transition_sha256"]
            and writer_epoch.writer_sequence
            == int(request_row["candidate_writer_sequence"])
            and writer_epoch.writer_key_id_sha256
            == request_row["candidate_writer_key_id_sha256"]
            and writer_epoch.writer_key_epoch_sha256
            == request_row["candidate_writer_key_epoch_sha256"]
            and writer_epoch.previous_writer_epoch_head_sha256
            == request_row["previous_writer_epoch_head_sha256"]
        )

    @staticmethod
    def _writer_epoch_active_matches_request(
        writer_epoch: SourceReadRuntimeVaultWriterEpoch,
        request_row: Mapping[str, object],
    ) -> bool:
        try:
            mode = SourceReadRuntimeVaultWriterEpochTransitionMode(
                str(request_row["writer_epoch_transition_mode"])
            )
        except ValueError:
            return False
        common_exact = bool(
            writer_epoch.state is SourceReadRuntimeVaultWriterEpochState.ACTIVE
            and writer_epoch.writer_sequence
            == int(request_row["candidate_writer_sequence"])
            and writer_epoch.writer_key_id_sha256
            == request_row["candidate_writer_key_id_sha256"]
            and writer_epoch.writer_key_epoch_sha256
            == request_row["candidate_writer_key_epoch_sha256"]
        )
        if not common_exact:
            return False
        if (
            mode
            is SourceReadRuntimeVaultWriterEpochTransitionMode.SUCCESSOR_ALREADY_ACTIVE
        ):
            return bool(
                writer_epoch.writer_epoch_head_sha256
                == request_row["previous_writer_epoch_head_sha256"]
            )
        return bool(
            writer_epoch.transition_operation_id == request_row["operation_id"]
            and writer_epoch.transition_sha256
            == request_row["writer_epoch_transition_sha256"]
            and writer_epoch.previous_writer_epoch_head_sha256
            == request_row["previous_writer_epoch_head_sha256"]
        )

    @classmethod
    def _assert_writer_epoch_active_for_request_locked(
        cls,
        connection: sqlite3.Connection,
        request_row: Mapping[str, object],
    ) -> SourceReadRuntimeVaultWriterEpoch:
        writer_epoch = cls._runtime_vault_writer_epoch_locked(
            connection,
            str(request_row["vault_store_identity_sha256"]),
            replayed=True,
        )
        if not cls._writer_epoch_active_matches_request(writer_epoch, request_row):
            raise SourceReadLedgerStateConflict(
                "key retirement requires the exact activated successor writer epoch"
            )
        return writer_epoch

    @classmethod
    def _assert_writer_epoch_abandonable_for_request_locked(
        cls,
        connection: sqlite3.Connection,
        request_row: Mapping[str, object],
        *,
        sealed_cancellation: bool,
    ) -> SourceReadRuntimeVaultWriterEpoch:
        mode = SourceReadRuntimeVaultWriterEpochTransitionMode(
            str(request_row["writer_epoch_transition_mode"])
        )
        writer_epoch = cls._runtime_vault_writer_epoch_locked(
            connection,
            str(request_row["vault_store_identity_sha256"]),
            replayed=True,
        )
        if cls._writer_epoch_active_matches_request(writer_epoch, request_row):
            return writer_epoch
        if (
            not sealed_cancellation
            and mode
            is SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION
            and cls._writer_epoch_pending_matches_request(writer_epoch, request_row)
        ):
            return writer_epoch
        raise SourceReadLedgerStateConflict(
            "key retirement request has no exact cancellable writer epoch"
        )

    @staticmethod
    def _writer_epoch_cancelled_matches_request(
        writer_epoch: SourceReadRuntimeVaultWriterEpoch,
        request_row: Mapping[str, object],
    ) -> bool:
        return bool(
            request_row["writer_epoch_transition_mode"]
            == SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION.value
            and writer_epoch.state is SourceReadRuntimeVaultWriterEpochState.ACTIVE
            and writer_epoch.writer_sequence
            == int(request_row["predecessor_writer_sequence"])
            and writer_epoch.writer_key_id_sha256
            == request_row["predecessor_writer_key_id_sha256"]
            and writer_epoch.writer_key_epoch_sha256
            == request_row["predecessor_writer_key_epoch_sha256"]
            and writer_epoch.transition_operation_id == request_row["operation_id"]
            and writer_epoch.transition_sha256
            == request_row["writer_epoch_transition_sha256"]
            and writer_epoch.previous_writer_epoch_head_sha256
            == request_row["previous_writer_epoch_head_sha256"]
            and writer_epoch.source_phase == "TRANSITION_CANCELLED"
        )

    @staticmethod
    def _assert_retiring_key_not_completed_locked(
        connection: sqlite3.Connection,
        request: SourceReadKeyRetirementRequest,
    ) -> None:
        rows = connection.execute(
            """SELECT r.request_json
               FROM source_read_key_retirement_requests r
               JOIN source_read_key_retirement_completions c
                 ON c.operation_id=r.operation_id
               WHERE r.vault_store_identity_sha256=?
                 AND r.retiring_key_id_sha256=?""",
            (
                request.vault_store_identity_sha256,
                _hash_text(request.retiring_key_id),
            ),
        ).fetchall()
        for row in rows:
            completed_request = _key_retirement_request_from_material(
                _stored_json(
                    row["request_json"],
                    "completed key retirement request",
                )
            )
            if (
                completed_request.retiring_key_id == request.retiring_key_id
                and completed_request.retiring_epoch_sha256
                == request.retiring_epoch_sha256
            ):
                raise SourceReadLedgerStateConflict(
                    "retiring key epoch already has a completed lifecycle"
                )

    @staticmethod
    def _assert_writer_epoch_history_capacity_locked(
        connection: sqlite3.Connection,
        vault_store_identity_sha256: str,
    ) -> None:
        request_count = int(
            connection.execute(
                """SELECT COUNT(*) FROM source_read_key_retirement_requests
                   WHERE vault_store_identity_sha256=?""",
                (vault_store_identity_sha256,),
            ).fetchone()[0]
        )
        # One final slot is reserved for the synthesized legacy predecessor
        # entry that makes pre-managed leaves explicit in writer ancestry.
        if request_count >= MAX_WRITER_EPOCH_ANCESTRY_ENTRIES - 1:
            raise SourceReadLedgerStateConflict(
                "vault writer-epoch history reached its safe bound"
            )

    @staticmethod
    def _assert_no_active_key_lifecycle_locked(
        connection: sqlite3.Connection,
        *,
        ignore_compromise_operation_id: str | None = None,
    ) -> None:
        active = connection.execute(
            """SELECT 1
               FROM source_read_key_compromise_detections d
               LEFT JOIN source_read_key_retirement_completions dc
                 ON dc.operation_id=d.operation_id
               WHERE dc.operation_id IS NULL
                 AND (? IS NULL OR d.operation_id<>?)
               UNION ALL
               SELECT 1
               FROM source_read_key_retirement_requests r
               LEFT JOIN source_read_key_retirement_completions c
                 ON c.operation_id=r.operation_id
               LEFT JOIN source_read_key_retirement_request_abandonments ra
                 ON ra.operation_id=r.operation_id
               LEFT JOIN source_read_key_retirement_intent_abandonments ia
                 ON ia.operation_id=r.operation_id
               WHERE c.operation_id IS NULL
                 AND ra.operation_id IS NULL
                 AND ia.operation_id IS NULL
                 AND (? IS NULL OR r.operation_id<>?)
               LIMIT 1""",
            (
                ignore_compromise_operation_id,
                ignore_compromise_operation_id,
                ignore_compromise_operation_id,
                ignore_compromise_operation_id,
            ),
        ).fetchone()
        if active is not None:
            raise SourceReadLedgerStateConflict(
                "source dispatch is frozen by an unresolved vault-key lifecycle"
            )

    def verify_operation_recovery_proof(
        self, proof: SourceReadOperationRecoveryProof
    ) -> bool:
        """Freshly re-read ledger and anchor before local vault recovery.

        A later final outcome, quarantine/state change, continuation bind, or
        anchor rollback invalidates the proof.  Unrelated later anchored events
        do not: the proof head must remain a canonical anchored ancestor.
        """

        if not self.operation_recovery_proof_is_known(proof):
            return False
        with self._read() as connection:
            verification = self._verify_locked(connection)
            try:
                self._assert_authority_approval_fence_locked(connection)
                self._assert_no_active_key_lifecycle_locked(connection)
            except SourceReadLedgerError:
                return False
            row = connection.execute(
                "SELECT * FROM source_read_operations WHERE operation_id=?",
                (proof.operation_id,),
            ).fetchone()
            if row is None:
                return False
            batch = connection.execute(
                "SELECT * FROM source_read_batches WHERE batch_id=?",
                (row["batch_id"],),
            ).fetchone()
            intent = connection.execute(
                "SELECT 1 FROM source_read_dispatch_intents WHERE operation_id=?",
                (proof.operation_id,),
            ).fetchone()
            head_was_canonical = connection.execute(
                "SELECT 1 FROM source_read_events WHERE event_sha256=?",
                (proof.ledger_head_event_sha256,),
            ).fetchone()
            if batch is None or intent is None or head_was_canonical is None:
                return False
            operation = self._operation_custody_locked(connection, row)
            command_material = _stored_json(
                row["command_material_json"], "operation recovery command"
            )
            current_continuation = self._current_operation_continuation_locked(
                connection, proof.operation_id
            )
            stream_incident = self._latest_stream_incident_locked(
                connection,
                stable_stream_sha256=str(row["stable_stream_sha256"]),
            )
            allowed = {
                ReadCustodyState.DISPATCH_INTENT,
                ReadCustodyState.UNCERTAIN,
                ReadCustodyState.QUARANTINED,
            }
            anchor_not_rolled_back = (
                verification.external_anchor_generation
                >= proof.external_anchor_generation
            )
            if (
                verification.external_anchor_generation
                == proof.external_anchor_generation
            ):
                anchor_not_rolled_back = anchor_not_rolled_back and (
                    verification.external_anchor_receipt_sha256
                    == proof.external_anchor_receipt_sha256
                )
            return bool(
                operation.state in allowed
                and operation.state is proof.custody_state
                and operation.operation_id == proof.operation_id
                and operation.request_sha256 == proof.request_sha256
                and operation.registry_snapshot_sha256 == proof.registry_snapshot_sha256
                and batch["registry_projection_sha256"]
                == proof.registry_projection_sha256
                and operation.binding_id == proof.binding_id
                and operation.provider_id == proof.provider_id
                and operation.account_id == proof.account_id
                and operation.capability_snapshot_sha256
                == proof.capability_snapshot_sha256
                and operation.quota_epoch_sha256 == proof.quota_epoch_sha256
                and operation.checkpoint_before_sha256 == proof.checkpoint_before_sha256
                and command_material["stream_id_sha256"] == proof.stream_sha256
                and operation.stream_scope_sha256 == proof.stream_scope_sha256
                and operation.position_sha256 == proof.position_sha256
                and operation.command_sha256 == proof.command_sha256
                and operation.custody_reservation_sha256
                == proof.custody_reservation_sha256
                and row["writer_epoch_root_sha256"] == proof.writer_epoch_root_sha256
                and self._runtime_vault_writer_epoch_root_locked(connection)
                == proof.writer_epoch_root_sha256
                and current_continuation == proof.current_continuation_binding_sha256
                and (
                    stream_incident is None
                    or stream_incident[1] is SourceReadStreamRecoveryState.RESOLVED
                )
                and verification.external_anchor_status
                == "ANCHORED_MONOTONIC_LOCAL_CUSTODY"
                and proof.external_anchor_generation >= 1
                and proof.external_anchor_receipt_sha256 != ZERO_SHA256
                and anchor_not_rolled_back
                and proof.factory_attested is True
                and proof.live_release_eligible is False
            )

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(
            str(self.path), timeout=30, isolation_level=None, check_same_thread=False
        )
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("PRAGMA trusted_schema=OFF")
        connection.execute("PRAGMA busy_timeout=30000")
        connection.execute("PRAGMA synchronous=FULL")
        journal = str(connection.execute("PRAGMA journal_mode=DELETE").fetchone()[0])
        if journal.lower() != "delete":
            connection.close()
            raise SourceReadLedgerIntegrityError(
                "source read ledger requires explicit DELETE journaling"
            )
        return connection

    def _initialize(self) -> None:
        connection = self._connect()
        try:
            connection.execute("BEGIN IMMEDIATE")
            present = connection.execute(
                """SELECT 1 FROM sqlite_master
                   WHERE name NOT LIKE 'sqlite_%' LIMIT 1"""
            ).fetchone()
            if present is None:
                connection.execute(f"PRAGMA application_id={SQLITE_APPLICATION_ID}")
                connection.execute(
                    f"PRAGMA user_version={SOURCE_READ_LEDGER_SCHEMA_VERSION}"
                )
                for statement in _schema_statements():
                    connection.execute(statement)
                fingerprint = _schema_fingerprint(connection)
                if fingerprint != CANONICAL_SCHEMA_FINGERPRINT_SHA256:
                    raise SourceReadLedgerIntegrityError(
                        "canonical source read schema fingerprint constant differs"
                    )
                connection.execute(
                    """INSERT INTO source_read_meta(
                           singleton,schema_version,schema_fingerprint_sha256,
                           protocol_version,store_identity_sha256,
                           external_anchor_identity_sha256,
                           quota_epoch_authority_identity_sha256,
                           continuation_rotation_authority_identity_sha256,
                           signed_authority_root_policy_identity_sha256,
                           signed_authority_store_identity_sha256,
                           signed_authority_tenant_sha256,
                           signed_authority_audience,
                           signed_authority_requester_scope_sha256,
                           signed_authority_approver_scope_sha256,
                           signed_authority_trust_bundle_version,
                           signed_authority_trust_bundle_sha256,
                           signed_authority_maximum_clock_skew_seconds,
                           signed_anchor_root_policy_identity_sha256,
                           signed_anchor_store_identity_sha256,
                           signed_anchor_tenant_sha256,
                           signed_anchor_trust_bundle_version,
                           signed_anchor_trust_bundle_sha256,
                           signed_anchor_maximum_clock_skew_seconds,
                           continuation_migration_authority_identity_sha256,
                           vault_absence_authority_identity_sha256,
                           vault_lifecycle_authority_identity_sha256,
                           key_retirement_authority_identity_sha256)
                       VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        SOURCE_READ_LEDGER_SCHEMA_VERSION,
                        fingerprint,
                        SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        self.store_identity_sha256,
                        self.external_anchor_identity_sha256,
                        self.quota_epoch_authority_identity_sha256,
                        self.continuation_rotation_authority_identity_sha256,
                        self.signed_authority_root_policy_identity_sha256,
                        self.signed_authority_store_identity_sha256,
                        self.signed_authority_tenant_sha256,
                        self.signed_authority_audience,
                        self.signed_authority_requester_scope_sha256,
                        self.signed_authority_approver_scope_sha256,
                        self.signed_authority_trust_bundle_version,
                        self.signed_authority_trust_bundle_sha256,
                        self.signed_authority_maximum_clock_skew_seconds,
                        self.signed_anchor_root_policy_identity_sha256,
                        self.signed_anchor_store_identity_sha256,
                        self.signed_anchor_tenant_sha256,
                        self.signed_anchor_trust_bundle_version,
                        self.signed_anchor_trust_bundle_sha256,
                        self.signed_anchor_maximum_clock_skew_seconds,
                        self.continuation_migration_authority_identity_sha256,
                        self.vault_absence_authority_identity_sha256,
                        self.vault_lifecycle_authority_identity_sha256,
                        self.key_retirement_authority_identity_sha256,
                    ),
                )
            self._verify_locked(connection, allow_pending_anchor=True)
            connection.commit()
        except Exception:
            connection.rollback()
            raise
        finally:
            connection.close()
        if self._external_anchor is not None:
            self.recover_external_anchor()

    @staticmethod
    def _pending_authority_approval_locked(
        connection: sqlite3.Connection,
    ) -> sqlite3.Row | None:
        rows = connection.execute(
            """SELECT i.*
               FROM source_read_authority_approval_intents i
               LEFT JOIN source_read_authority_approval_dispositions d
                 ON d.approval_key_sha256=i.approval_key_sha256
               WHERE d.approval_key_sha256 IS NULL OR d.decision<>'APPROVED'
               ORDER BY i.sequence"""
        ).fetchall()
        if len(rows) > 1:
            raise SourceReadLedgerIntegrityError(
                "multiple unresolved authority approvals are present"
            )
        return None if not rows else rows[0]

    @classmethod
    def _assert_authority_approval_fence_locked(
        cls,
        connection: sqlite3.Connection,
        *,
        allowed_approval_key_sha256: str | None = None,
        allow_intent_creation: bool = False,
    ) -> None:
        pending = cls._pending_authority_approval_locked(connection)
        if pending is None:
            if allowed_approval_key_sha256 is not None and not allow_intent_creation:
                approved = connection.execute(
                    """SELECT 1
                       FROM source_read_authority_approval_intents i
                       JOIN source_read_authority_approval_dispositions d
                         ON d.approval_key_sha256=i.approval_key_sha256
                       WHERE i.approval_key_sha256=? AND d.decision='APPROVED'""",
                    (allowed_approval_key_sha256,),
                ).fetchone()
                if approved is None:
                    raise SourceReadLedgerStateConflict(
                        "authority approval intent is absent"
                    )
            return
        if (
            allowed_approval_key_sha256 is None
            or pending["approval_key_sha256"] != allowed_approval_key_sha256
        ):
            raise SourceReadLedgerStateConflict(
                "source reads are frozen by an unresolved authority approval"
            )

    @staticmethod
    def _assert_no_unresolved_operations_locked(
        connection: sqlite3.Connection,
    ) -> None:
        unresolved = connection.execute(
            """SELECT 1 FROM source_read_operations op
               WHERE NOT EXISTS(
                   SELECT 1 FROM source_read_outcomes outcome
                   WHERE outcome.operation_id=op.operation_id
                     AND outcome.outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED'))
               LIMIT 1"""
        ).fetchone()
        if unresolved is not None:
            raise SourceReadLedgerStateConflict(
                "authority approval intent requires zero unresolved source reads"
            )

    @contextmanager
    def _write(
        self,
        *,
        authority_approval_key_sha256: str | None = None,
        allow_authority_intent_creation: bool = False,
    ) -> Iterator[sqlite3.Connection]:
        connection: sqlite3.Connection | None = None
        try:
            while True:
                connection = self._connect()
                connection.execute("BEGIN IMMEDIATE")
                verification = self._verify_locked(
                    connection,
                    allow_pending_anchor=self._external_anchor is not None,
                )
                if verification.external_anchor_status != "ANCHOR_ADVANCEMENT_PENDING":
                    break

                # Tx1 deliberately releases SQLite before the external CAS so
                # the durable event+intent survives a process crash.  Another
                # writer can therefore acquire the store in that narrow
                # window.  It must finish the one exact pending tail before it
                # may start a new mutation; treating that recoverable state as
                # corruption creates a false quarantine, while allowing the
                # mutation would create a second pending intent.
                connection.commit()
                connection.close()
                connection = None
                self._complete_external_anchor_pending()
            self._assert_authority_approval_fence_locked(
                connection,
                allowed_approval_key_sha256=authority_approval_key_sha256,
                allow_intent_creation=allow_authority_intent_creation,
            )
            before = connection.execute(
                "SELECT sequence,event_sha256 FROM source_read_events ORDER BY sequence DESC LIMIT 1"
            ).fetchone()
            before_sequence = 0 if before is None else int(before["sequence"])
            before_head = ZERO_SHA256 if before is None else str(before["event_sha256"])
            yield connection
            after = connection.execute(
                "SELECT sequence,event_sha256 FROM source_read_events ORDER BY sequence DESC LIMIT 1"
            ).fetchone()
            after_sequence = 0 if after is None else int(after["sequence"])
            after_head = ZERO_SHA256 if after is None else str(after["event_sha256"])
            changed = after_head != before_head
            if changed and self._external_anchor is not None:
                if after_sequence != before_sequence + 1:
                    raise SourceReadLedgerIntegrityError(
                        "state-changing transaction must append exactly one event"
                    )
                self._append_anchor_intent_locked(
                    connection,
                    previous_head_event_sha256=before_head,
                    next_head_event_sha256=after_head,
                )
                self._verify_locked(connection, allow_pending_anchor=True)
                # Tx1: the business event and exact anchor outbox intent become
                # durable together.  From this point a crash is recoverable.
                connection.commit()
                self._complete_external_anchor_pending()
                return
            self._verify_locked(connection)
            connection.commit()
        except Exception:
            if connection is not None and connection.in_transaction:
                connection.rollback()
            raise
        finally:
            if connection is not None:
                connection.close()

    @contextmanager
    def _read(self) -> Iterator[sqlite3.Connection]:
        connection: sqlite3.Connection | None = None
        try:
            while True:
                connection = self._connect()
                connection.execute("BEGIN")
                verification = self._verify_locked(
                    connection,
                    allow_pending_anchor=self._external_anchor is not None,
                )
                if verification.external_anchor_status != "ANCHOR_ADVANCEMENT_PENDING":
                    break

                # A reader may race the recoverable Tx1 -> CAS -> ACK window in
                # exactly the same way as another writer.  Never expose that
                # valid single tail as a false quarantine or a dispatch-ready
                # snapshot: finish it through the authoritative boundary and
                # restart the read from a newly verified anchored snapshot.
                connection.commit()
                connection.close()
                connection = None
                self._complete_external_anchor_pending()
            yield connection
            connection.commit()
        except Exception:
            if connection is not None and connection.in_transaction:
                connection.rollback()
            raise
        finally:
            if connection is not None:
                connection.close()

    def _authoritative_anchor_receipt(
        self,
    ) -> SourceReadExternalAnchorReceipt:
        if (
            self._external_anchor is None
            or self.external_anchor_identity_sha256 is None
        ):
            raise SourceReadLedgerAnchorQuarantined(
                "external anchor required by store metadata is unavailable"
            )
        try:
            receipt = self._external_anchor.read_receipt(
                store_identity_sha256=self.store_identity_sha256
            )
        except SourceReadLedgerAnchorQuarantined:
            raise
        except Exception as error:
            raise SourceReadLedgerAnchorQuarantined(
                "external anchor receipt is unavailable; store is quarantined"
            ) from error
        return _validated_external_anchor_receipt(
            receipt,
            anchor_identity_sha256=self.external_anchor_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
        )

    @staticmethod
    def _anchor_mutation_sha256(
        previous_head_event_sha256: str,
        next_head_event_sha256: str,
        event_sequence: int,
    ) -> str:
        return _value_sha256(
            {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "EXTERNAL_ANCHOR_ADVANCEMENT",
                "previous_head_event_sha256": previous_head_event_sha256,
                "next_head_event_sha256": next_head_event_sha256,
                "event_sequence": event_sequence,
            }
        )

    def _verify_anchor_locked(
        self,
        connection: sqlite3.Connection,
        events: list[sqlite3.Row],
        *,
        allow_pending_anchor: bool,
    ) -> tuple[str, int, str]:
        meta = connection.execute("SELECT * FROM source_read_meta").fetchone()
        intents = connection.execute(
            "SELECT * FROM source_read_anchor_intents ORDER BY sequence"
        ).fetchall()
        advancements = connection.execute(
            "SELECT * FROM source_read_anchor_advancements ORDER BY sequence"
        ).fetchall()
        pinned_identity = meta["external_anchor_identity_sha256"]
        if pinned_identity is None:
            if self._external_anchor is not None or intents or advancements:
                raise SourceReadLedgerIntegrityError(
                    "local-only store/anchor configuration differs"
                )
            return "NOT_ANCHORED_LOCAL_ONLY", 0, ZERO_SHA256
        if (
            self._external_anchor is None
            or self.external_anchor_identity_sha256 != pinned_identity
        ):
            raise SourceReadLedgerAnchorQuarantined(
                "pinned external anchor is absent or has a different identity"
            )
        if len(intents) != len(events):
            raise SourceReadLedgerIntegrityError(
                "external anchor intent/event cardinality differs"
            )
        pending = len(intents) - len(advancements)
        if pending not in ((0, 1) if allow_pending_anchor else (0,)):
            raise SourceReadLedgerAnchorQuarantined(
                "external anchor outbox is not an exact single pending tail"
            )
        genesis = _external_anchor_genesis_receipt(
            str(pinned_identity), self.store_identity_sha256
        )
        previous_receipt = genesis.receipt_sha256
        previous_head = ZERO_SHA256
        expected_receipts: list[str] = []
        for expected, intent in enumerate(intents, 1):
            event = events[expected - 1]
            mutation = self._anchor_mutation_sha256(
                previous_head, str(event["event_sha256"]), expected
            )
            material = _anchor_receipt_material(
                anchor_identity_sha256=str(pinned_identity),
                store_identity_sha256=self.store_identity_sha256,
                generation=expected,
                head_event_sha256=str(event["event_sha256"]),
                previous_receipt_sha256=previous_receipt,
                mutation_sha256=mutation,
            )
            receipt_sha = _value_sha256(material)
            if (
                int(intent["sequence"]) != expected
                or int(intent["expected_generation"]) != expected - 1
                or intent["anchor_identity_sha256"] != pinned_identity
                or intent["expected_receipt_sha256"] != previous_receipt
                or intent["previous_head_event_sha256"] != previous_head
                or intent["next_head_event_sha256"] != event["event_sha256"]
                or intent["mutation_sha256"] != mutation
                or intent["intent_sha256"]
                != _value_sha256(
                    {
                        "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        "record_kind": "EXTERNAL_ANCHOR_INTENT",
                        "sequence": expected,
                        "anchor_identity_sha256": pinned_identity,
                        "expected_generation": expected - 1,
                        "expected_receipt_sha256": previous_receipt,
                        "previous_head_event_sha256": previous_head,
                        "next_head_event_sha256": event["event_sha256"],
                        "mutation_sha256": mutation,
                    }
                )
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored external anchor intent differs"
                )
            expected_receipts.append(receipt_sha)
            previous_receipt = receipt_sha
            previous_head = str(event["event_sha256"])
        for expected, row in enumerate(advancements, 1):
            intent = intents[expected - 1]
            if (
                int(row["sequence"]) != expected
                or int(row["generation"]) != expected
                or row["anchor_identity_sha256"] != pinned_identity
                or row["previous_receipt_sha256"] != intent["expected_receipt_sha256"]
                or row["head_event_sha256"] != intent["next_head_event_sha256"]
                or row["mutation_sha256"] != intent["mutation_sha256"]
                or row["receipt_sha256"] != expected_receipts[expected - 1]
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored external anchor advancement differs"
                )
        authoritative = self._authoritative_anchor_receipt()
        ack_generation = len(advancements)
        ack_head = (
            ZERO_SHA256
            if ack_generation == 0
            else str(advancements[-1]["head_event_sha256"])
        )
        ack_receipt = (
            genesis.receipt_sha256
            if ack_generation == 0
            else str(advancements[-1]["receipt_sha256"])
        )
        authoritative_is_ack = (
            authoritative.generation == ack_generation
            and authoritative.head_event_sha256 == ack_head
            and authoritative.receipt_sha256 == ack_receipt
        )
        authoritative_is_pending_next = bool(
            pending == 1
            and authoritative.generation == ack_generation + 1
            and authoritative.head_event_sha256 == intents[-1]["next_head_event_sha256"]
            and authoritative.receipt_sha256 == expected_receipts[-1]
            and authoritative.previous_receipt_sha256 == ack_receipt
            and authoritative.mutation_sha256 == intents[-1]["mutation_sha256"]
        )
        if not authoritative_is_ack and not (
            allow_pending_anchor and authoritative_is_pending_next
        ):
            if authoritative.generation > len(intents):
                detail = "external anchor is ahead; local rollback"
            elif authoritative.generation < ack_generation:
                detail = "external anchor is stale"
            else:
                detail = "external anchor conflicts with the durable outbox"
            raise SourceReadLedgerAnchorQuarantined(
                f"{detail}; source read store is quarantined"
            )
        status = (
            "ANCHOR_ADVANCEMENT_PENDING"
            if pending
            else "ANCHORED_MONOTONIC_LOCAL_CUSTODY"
        )
        return status, authoritative.generation, authoritative.receipt_sha256

    def _append_anchor_intent_locked(
        self,
        connection: sqlite3.Connection,
        *,
        previous_head_event_sha256: str,
        next_head_event_sha256: str,
    ) -> None:
        if (
            self._external_anchor is None
            or self.external_anchor_identity_sha256 is None
        ):
            raise SourceReadLedgerAnchorQuarantined(
                "external anchor vanished during a state-changing transaction"
            )
        event = connection.execute(
            "SELECT * FROM source_read_events ORDER BY sequence DESC LIMIT 1"
        ).fetchone()
        prior = connection.execute(
            "SELECT * FROM source_read_anchor_advancements ORDER BY sequence DESC LIMIT 1"
        ).fetchone()
        event_sequence = int(event["sequence"])
        expected_generation = 0 if prior is None else int(prior["generation"])
        expected_receipt = (
            _external_anchor_genesis_receipt(
                self.external_anchor_identity_sha256, self.store_identity_sha256
            ).receipt_sha256
            if prior is None
            else str(prior["receipt_sha256"])
        )
        if (
            event_sequence != expected_generation + 1
            or event["event_sha256"] != next_head_event_sha256
        ):
            raise SourceReadLedgerIntegrityError(
                "state-changing transaction did not append exactly one event"
            )
        mutation = self._anchor_mutation_sha256(
            previous_head_event_sha256,
            next_head_event_sha256,
            event_sequence,
        )
        connection.execute(
            """INSERT INTO source_read_anchor_intents(
                   sequence,anchor_identity_sha256,expected_generation,
                   expected_receipt_sha256,previous_head_event_sha256,
                   next_head_event_sha256,mutation_sha256,intent_sha256)
               VALUES(?,?,?,?,?,?,?,?)""",
            (
                event_sequence,
                self.external_anchor_identity_sha256,
                expected_generation,
                expected_receipt,
                previous_head_event_sha256,
                next_head_event_sha256,
                mutation,
                _value_sha256(
                    {
                        "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        "record_kind": "EXTERNAL_ANCHOR_INTENT",
                        "sequence": event_sequence,
                        "anchor_identity_sha256": self.external_anchor_identity_sha256,
                        "expected_generation": expected_generation,
                        "expected_receipt_sha256": expected_receipt,
                        "previous_head_event_sha256": previous_head_event_sha256,
                        "next_head_event_sha256": next_head_event_sha256,
                        "mutation_sha256": mutation,
                    }
                ),
            ),
        )

    def _complete_external_anchor_pending(self) -> SourceReadLedgerVerification:
        if (
            self._external_anchor is None
            or self.external_anchor_identity_sha256 is None
        ):
            raise SourceReadLedgerAnchorQuarantined(
                "external anchor recovery requires the pinned boundary"
            )
        connection = self._connect()
        try:
            connection.execute("BEGIN IMMEDIATE")
            verification = self._verify_locked(connection, allow_pending_anchor=True)
            intent = connection.execute(
                """SELECT i.* FROM source_read_anchor_intents i
                   LEFT JOIN source_read_anchor_advancements a
                     ON a.sequence=i.sequence
                   WHERE a.sequence IS NULL ORDER BY i.sequence"""
            ).fetchall()
            if not intent:
                connection.commit()
                return verification
            if len(intent) != 1:
                raise SourceReadLedgerAnchorQuarantined(
                    "external anchor recovery found multiple pending intents"
                )
            pending = intent[0]
            expected_generation = int(pending["expected_generation"])
            expected_receipt = str(pending["expected_receipt_sha256"])
            expected_head = str(pending["previous_head_event_sha256"])
            next_head = str(pending["next_head_event_sha256"])
            mutation = str(pending["mutation_sha256"])
            expected_next_receipt = _value_sha256(
                _anchor_receipt_material(
                    anchor_identity_sha256=self.external_anchor_identity_sha256,
                    store_identity_sha256=self.store_identity_sha256,
                    generation=expected_generation + 1,
                    head_event_sha256=next_head,
                    previous_receipt_sha256=expected_receipt,
                    mutation_sha256=mutation,
                )
            )

            def is_prior(value: SourceReadExternalAnchorReceipt) -> bool:
                return (
                    value.generation == expected_generation
                    and value.receipt_sha256 == expected_receipt
                    and value.head_event_sha256 == expected_head
                )

            def is_next(value: SourceReadExternalAnchorReceipt) -> bool:
                return (
                    value.generation == expected_generation + 1
                    and value.receipt_sha256 == expected_next_receipt
                    and value.head_event_sha256 == next_head
                    and value.previous_receipt_sha256 == expected_receipt
                    and value.mutation_sha256 == mutation
                )

            authoritative = self._authoritative_anchor_receipt()
            if is_prior(authoritative):
                attempts = 0
                while attempts < 2 and is_prior(authoritative):
                    attempts += 1
                    try:
                        candidate = self._external_anchor.compare_and_advance(
                            store_identity_sha256=self.store_identity_sha256,
                            expected_receipt_sha256=expected_receipt,
                            expected_generation=expected_generation,
                            expected_head_event_sha256=expected_head,
                            next_head_event_sha256=next_head,
                            mutation_sha256=mutation,
                        )
                        authoritative = _validated_external_anchor_receipt(
                            candidate,
                            anchor_identity_sha256=self.external_anchor_identity_sha256,
                            store_identity_sha256=self.store_identity_sha256,
                        )
                    except Exception:
                        # A timeout is uncertain, never a proof of failure.
                        authoritative = self._authoritative_anchor_receipt()
            if not is_next(authoritative):
                raise SourceReadLedgerAnchorQuarantined(
                    "external anchor recovery cannot prove the exact next receipt"
                )
            connection.execute(
                """INSERT INTO source_read_anchor_advancements(
                       sequence,anchor_identity_sha256,generation,
                       previous_receipt_sha256,head_event_sha256,mutation_sha256,
                       receipt_sha256) VALUES(?,?,?,?,?,?,?)""",
                (
                    int(pending["sequence"]),
                    self.external_anchor_identity_sha256,
                    authoritative.generation,
                    authoritative.previous_receipt_sha256,
                    authoritative.head_event_sha256,
                    authoritative.mutation_sha256,
                    authoritative.receipt_sha256,
                ),
            )
            verification = self._verify_locked(connection)
            connection.commit()
            return verification
        except Exception:
            if connection.in_transaction:
                connection.rollback()
            raise
        finally:
            connection.close()

    def recover_external_anchor(self) -> SourceReadLedgerVerification:
        """Finish one exact durable anchor intent; no business event is added."""

        if self._external_anchor is None:
            return self.verify()
        return self._complete_external_anchor_pending()

    @staticmethod
    def _event_material(row: Mapping[str, object]) -> dict[str, object]:
        return {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "sequence": row["sequence"],
            "event_id": row["event_id"],
            "event_type": row["event_type"],
            "entity_kind": row["entity_kind"],
            "entity_id": row["entity_id"],
            "entity_sha256": row["entity_sha256"],
            "occurred_at_utc": row["occurred_at_utc"],
            "previous_event_sha256": row["previous_event_sha256"],
        }

    @staticmethod
    def _event_id(
        event_type: str, entity_kind: str, entity_id: str, entity_sha256: str
    ) -> str:
        return (
            "source-read-event-"
            + _value_sha256(
                {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "event_type": event_type,
                    "entity_kind": entity_kind,
                    "entity_id": entity_id,
                    "entity_sha256": entity_sha256,
                }
            )[:32]
        )

    def _append_event_locked(
        self,
        connection: sqlite3.Connection,
        *,
        event_type: str,
        entity_kind: str,
        entity_id: str,
        entity_sha256: str,
        occurred_at_utc: str,
    ) -> tuple[str, str]:
        row = connection.execute(
            """SELECT sequence,event_sha256,occurred_at_utc
               FROM source_read_events ORDER BY sequence DESC LIMIT 1"""
        ).fetchone()
        sequence = 1 if row is None else int(row["sequence"]) + 1
        previous = ZERO_SHA256 if row is None else str(row["event_sha256"])
        if row is not None and _utc_datetime(
            occurred_at_utc, "event occurred_at_utc"
        ) < _utc_datetime(row["occurred_at_utc"], "previous event occurred_at_utc"):
            raise SourceReadLedgerValidationError(
                "source read event time cannot move backwards"
            )
        event_id = self._event_id(event_type, entity_kind, entity_id, entity_sha256)
        material = {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "sequence": sequence,
            "event_id": event_id,
            "event_type": event_type,
            "entity_kind": entity_kind,
            "entity_id": entity_id,
            "entity_sha256": entity_sha256,
            "occurred_at_utc": occurred_at_utc,
            "previous_event_sha256": previous,
        }
        event_sha = _value_sha256(material)
        connection.execute(
            """INSERT INTO source_read_events(
                   sequence,event_id,event_type,entity_kind,entity_id,entity_sha256,
                   occurred_at_utc,previous_event_sha256,event_sha256)
               VALUES(?,?,?,?,?,?,?,?,?)""",
            (
                sequence,
                event_id,
                event_type,
                entity_kind,
                entity_id,
                entity_sha256,
                occurred_at_utc,
                previous,
                event_sha,
            ),
        )
        return event_id, event_sha

    @staticmethod
    def _find_idempotency_locked(
        connection: sqlite3.Connection, idempotency_sha256: str
    ) -> tuple[str, sqlite3.Row] | None:
        for kind, table in (
            ("BATCH", "source_read_batches"),
            ("OPERATION", "source_read_operations"),
            ("INTENT", "source_read_dispatch_intents"),
            ("OUTCOME", "source_read_outcomes"),
            ("QUARANTINE", "source_read_reconciliation_quarantines"),
            ("QUOTA_EPOCH", "source_read_quota_epoch_transitions"),
            ("CONTINUATION", "source_read_continuation_rebindings"),
            ("CONTINUATION_MIGRATION", "source_read_continuation_migrations"),
            ("STREAM_INCIDENT", "source_read_stream_incidents"),
            ("STREAM_REPAIR_INTENT", "source_read_stream_repair_intents"),
            (
                "STREAM_REPAIR_INTENT_CANCELLATION",
                "source_read_stream_repair_intent_cancellations",
            ),
            ("STREAM_REPAIR", "source_read_stream_repair_bindings"),
            ("STREAM_REPAIR_ABANDONMENT", "source_read_stream_repair_abandonments"),
            ("STREAM_REPAIR_DISPOSITION", "source_read_stream_repair_dispositions"),
            ("KEY_COMPROMISE_DETECTION", "source_read_key_compromise_detections"),
            ("KEY_RETIREMENT_REQUEST", "source_read_key_retirement_requests"),
            (
                "RUNTIME_VAULT_WRITER_EPOCH_ACTIVATION",
                "source_read_runtime_vault_writer_epoch_activations",
            ),
            (
                "KEY_RETIREMENT_REQUEST_ABANDONMENT",
                "source_read_key_retirement_request_abandonments",
            ),
            ("KEY_RETIREMENT_INTENT", "source_read_key_retirement_intents"),
            (
                "KEY_RETIREMENT_INTENT_ABANDONMENT",
                "source_read_key_retirement_intent_abandonments",
            ),
            ("KEY_RETIREMENT_COMPLETE", "source_read_key_retirement_completions"),
        ):
            row = connection.execute(
                f"SELECT * FROM {table} WHERE idempotency_sha256=?",
                (idempotency_sha256,),
            ).fetchone()
            if row is not None:
                return kind, row
        return None

    @staticmethod
    def _entity_event_locked(
        connection: sqlite3.Connection, kind: str, entity_id: str
    ) -> sqlite3.Row:
        row = connection.execute(
            "SELECT * FROM source_read_events WHERE entity_kind=? AND entity_id=?",
            (kind, entity_id),
        ).fetchone()
        if row is None:
            raise SourceReadLedgerIntegrityError("ledger entity event is absent")
        return row

    @staticmethod
    def _event_to_mutation(
        entity_id: str, entity_sha256: str, event: sqlite3.Row, *, replayed: bool
    ) -> SourceReadLedgerMutation:
        return SourceReadLedgerMutation(
            entity_id,
            entity_sha256,
            str(event["event_id"]),
            str(event["event_sha256"]),
            replayed,
        )

