            protocol=SOURCE_READ_AUTHORITY_BOUNDARY_PROTOCOL_V1,
            action=str(row["approval_kind"]),
            approval_key_sha256=str(row["approval_key_sha256"]),
            authority_namespace_sha256=str(row["authority_namespace_sha256"]),
            authority_root_policy_identity_sha256=str(row["authority_identity_sha256"]),
            authority_store_identity_sha256=str(row["authority_store_identity_sha256"]),
            audience=str(row["audience"]),
            tenant_sha256=str(row["tenant_sha256"]),
            store_identity_sha256=str(row["store_identity_sha256"]),
            vault_store_identity_sha256=str(row["vault_store_identity_sha256"]),
            operation_sha256=str(row["operation_sha256"]),
            idempotency_sha256=str(row["business_idempotency_sha256"]),
            semantic_request_sha256=str(row["semantic_request_sha256"]),
            semantic_request_json=str(row["semantic_request_json"]),
            command_sha256=str(row["command_sha256"]),
            governance_evidence_sha256=str(row["governance_evidence_sha256"]),
