    def _verify_schema_locked(self, connection: sqlite3.Connection) -> None:
        try:
            fingerprint = _schema_fingerprint(connection)
            row = connection.execute("SELECT * FROM source_read_meta").fetchall()
            application_id = int(
                connection.execute("PRAGMA application_id").fetchone()[0]
            )
            user_version = int(connection.execute("PRAGMA user_version").fetchone()[0])
            synchronous = int(connection.execute("PRAGMA synchronous").fetchone()[0])
            journal = str(connection.execute("PRAGMA journal_mode").fetchone()[0])
        except sqlite3.DatabaseError as error:
            raise SourceReadLedgerIntegrityError(
                "source read ledger schema cannot be verified"
            ) from error
        if fingerprint != CANONICAL_SCHEMA_FINGERPRINT_SHA256:
            raise SourceReadLedgerIntegrityError(
                "source read ledger schema fingerprint differs"
            )
        if (
            len(row) != 1
            or int(row[0]["singleton"]) != 1
            or int(row[0]["schema_version"]) != SOURCE_READ_LEDGER_SCHEMA_VERSION
            or str(row[0]["schema_fingerprint_sha256"]) != fingerprint
            or str(row[0]["protocol_version"]) != SOURCE_READ_LEDGER_PROTOCOL_VERSION
            or str(row[0]["store_identity_sha256"]) != self.store_identity_sha256
            or row[0]["quota_epoch_authority_identity_sha256"]
            != self.quota_epoch_authority_identity_sha256
            or row[0]["continuation_rotation_authority_identity_sha256"]
            != self.continuation_rotation_authority_identity_sha256
            or row[0]["signed_authority_root_policy_identity_sha256"]
            != self.signed_authority_root_policy_identity_sha256
            or row[0]["signed_authority_store_identity_sha256"]
            != self.signed_authority_store_identity_sha256
            or row[0]["signed_authority_tenant_sha256"]
            != self.signed_authority_tenant_sha256
            or row[0]["signed_authority_audience"] != self.signed_authority_audience
            or row[0]["signed_authority_requester_scope_sha256"]
            != self.signed_authority_requester_scope_sha256
            or row[0]["signed_authority_approver_scope_sha256"]
            != self.signed_authority_approver_scope_sha256
            or row[0]["signed_authority_trust_bundle_version"]
            != self.signed_authority_trust_bundle_version
            or row[0]["signed_authority_trust_bundle_sha256"]
            != self.signed_authority_trust_bundle_sha256
            or row[0]["signed_authority_maximum_clock_skew_seconds"]
            != self.signed_authority_maximum_clock_skew_seconds
            or row[0]["signed_anchor_root_policy_identity_sha256"]
            != self.signed_anchor_root_policy_identity_sha256
            or row[0]["signed_anchor_store_identity_sha256"]
            != self.signed_anchor_store_identity_sha256
            or row[0]["signed_anchor_tenant_sha256"] != self.signed_anchor_tenant_sha256
            or row[0]["signed_anchor_trust_bundle_version"]
            != self.signed_anchor_trust_bundle_version
            or row[0]["signed_anchor_trust_bundle_sha256"]
            != self.signed_anchor_trust_bundle_sha256
            or row[0]["signed_anchor_maximum_clock_skew_seconds"]
            != self.signed_anchor_maximum_clock_skew_seconds
            or row[0]["continuation_migration_authority_identity_sha256"]
            != self.continuation_migration_authority_identity_sha256
            or row[0]["vault_absence_authority_identity_sha256"]
            != self.vault_absence_authority_identity_sha256
            or row[0]["vault_lifecycle_authority_identity_sha256"]
            != self.vault_lifecycle_authority_identity_sha256
            or row[0]["key_retirement_authority_identity_sha256"]
            != self.key_retirement_authority_identity_sha256
            or application_id != SQLITE_APPLICATION_ID
            or user_version != SOURCE_READ_LEDGER_SCHEMA_VERSION
            or synchronous != 2
            or journal.lower() != "delete"
        ):
            raise SourceReadLedgerIntegrityError("source read ledger metadata differs")

    def _verify_locked(
        self,
        connection: sqlite3.Connection,
        *,
        allow_pending_anchor: bool = False,
    ) -> SourceReadLedgerVerification:
        self._verify_schema_locked(connection)
        try:
            batches = connection.execute(
                "SELECT * FROM source_read_batches ORDER BY sequence"
            ).fetchall()
            operations = connection.execute(
                "SELECT * FROM source_read_operations ORDER BY sequence"
            ).fetchall()
            intents = connection.execute(
                "SELECT * FROM source_read_dispatch_intents ORDER BY sequence"
            ).fetchall()
            outcomes = connection.execute(
                "SELECT * FROM source_read_outcomes ORDER BY sequence"
            ).fetchall()
            quarantines = connection.execute(
                "SELECT * FROM source_read_reconciliation_quarantines ORDER BY sequence"
            ).fetchall()
            quota_epoch_transitions = connection.execute(
                "SELECT * FROM source_read_quota_epoch_transitions ORDER BY sequence"
            ).fetchall()
            authority_approval_intents = connection.execute(
                """SELECT * FROM source_read_authority_approval_intents
                   ORDER BY sequence"""
            ).fetchall()
            authority_approval_dispositions = connection.execute(
                """SELECT * FROM source_read_authority_approval_dispositions
                   ORDER BY sequence"""
            ).fetchall()
            continuation_rebindings = connection.execute(
                "SELECT * FROM source_read_continuation_rebindings ORDER BY sequence"
            ).fetchall()
            continuation_migrations = connection.execute(
                "SELECT * FROM source_read_continuation_migrations ORDER BY sequence"
            ).fetchall()
            stream_incidents = connection.execute(
                "SELECT * FROM source_read_stream_incidents ORDER BY sequence"
            ).fetchall()
            stream_repair_intents = connection.execute(
                "SELECT * FROM source_read_stream_repair_intents ORDER BY sequence"
            ).fetchall()
            stream_repair_intent_cancellations = connection.execute(
                """SELECT * FROM source_read_stream_repair_intent_cancellations
                   ORDER BY sequence"""
            ).fetchall()
            stream_repair_bindings = connection.execute(
                "SELECT * FROM source_read_stream_repair_bindings ORDER BY sequence"
            ).fetchall()
            stream_repair_abandonments = connection.execute(
                "SELECT * FROM source_read_stream_repair_abandonments ORDER BY sequence"
            ).fetchall()
            stream_repair_dispositions = connection.execute(
                "SELECT * FROM source_read_stream_repair_dispositions ORDER BY sequence"
            ).fetchall()
            key_compromise_detections = connection.execute(
                "SELECT * FROM source_read_key_compromise_detections ORDER BY sequence"
            ).fetchall()
            key_retirement_requests = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests ORDER BY sequence"
            ).fetchall()
            writer_epoch_activations = connection.execute(
                """SELECT *
                   FROM source_read_runtime_vault_writer_epoch_activations
                   ORDER BY sequence"""
            ).fetchall()
            key_retirement_request_abandonments = connection.execute(
                """SELECT * FROM source_read_key_retirement_request_abandonments
                   ORDER BY sequence"""
            ).fetchall()
            key_retirement_intents = connection.execute(
                "SELECT * FROM source_read_key_retirement_intents ORDER BY sequence"
            ).fetchall()
            key_retirement_intent_abandonments = connection.execute(
                """SELECT * FROM source_read_key_retirement_intent_abandonments
                   ORDER BY sequence"""
            ).fetchall()
            key_retirement_inventory = connection.execute(
                "SELECT * FROM source_read_key_retirement_inventory ORDER BY sequence"
            ).fetchall()
            key_retirement_completions = connection.execute(
                "SELECT * FROM source_read_key_retirement_completions ORDER BY sequence"
            ).fetchall()
            continuation_heads = connection.execute(
                "SELECT * FROM source_read_continuation_heads ORDER BY sequence"
            ).fetchall()
            events = connection.execute(
                "SELECT * FROM source_read_events ORDER BY sequence"
            ).fetchall()
        except sqlite3.DatabaseError as error:
            raise SourceReadLedgerIntegrityError(
                "source read ledger rows cannot be verified"
            ) from error
        if len(events) != (
            len(batches)
            + len(operations)
            + len(intents)
            + len(outcomes)
            + len(quarantines)
            + len(quota_epoch_transitions)
            + len(authority_approval_intents)
            + len(
                [
                    row
                    for row in authority_approval_dispositions
                    if row["decision"] != "APPROVED"
                ]
            )
            + len(continuation_rebindings)
            + len(continuation_migrations)
            + len(
                [
                    row
                    for row in stream_incidents
                    if row["parent_retirement_operation_id"] is None
                ]
            )
            + len(stream_repair_intents)
            + len(stream_repair_intent_cancellations)
            + len(stream_repair_bindings)
            + len(stream_repair_abandonments)
            + len(stream_repair_dispositions)
            + len(key_compromise_detections)
            + len(key_retirement_requests)
            + len(writer_epoch_activations)
            + len(key_retirement_request_abandonments)
            + len(key_retirement_intents)
            + len(key_retirement_intent_abandonments)
            + len(key_retirement_completions)
        ):
            raise SourceReadLedgerIntegrityError(
                "ledger entity/event cardinality differs"
            )
        seen_idempotency: set[str] = set()
        for rows in (
            batches,
            operations,
            intents,
            outcomes,
            quarantines,
            quota_epoch_transitions,
            continuation_rebindings,
            continuation_migrations,
            stream_incidents,
            stream_repair_intents,
            stream_repair_intent_cancellations,
            stream_repair_bindings,
            stream_repair_abandonments,
            stream_repair_dispositions,
            key_compromise_detections,
            key_retirement_requests,
            writer_epoch_activations,
            key_retirement_request_abandonments,
            key_retirement_intents,
            key_retirement_intent_abandonments,
            key_retirement_completions,
        ):
            for row in rows:
                digest = _sha256(
                    row["idempotency_sha256"], "stored global idempotency digest"
                )
                if digest in seen_idempotency:
                    raise SourceReadLedgerIntegrityError(
                        "global source read idempotency digest is duplicated"
                    )
                seen_idempotency.add(digest)
        batch_by_id: dict[str, sqlite3.Row] = {}
        request_by_batch: dict[str, dict[str, Any]] = {}
        registry_by_batch: dict[str, dict[str, Any]] = {}
        expected_entities: dict[tuple[str, str], tuple[str, str, str]] = {}
        for expected, row in enumerate(batches, 1):
            if int(row["sequence"]) != expected:
                raise SourceReadLedgerIntegrityError("batch sequence is not contiguous")
            registry_material = _stored_json(
                row["registry_material_json"], "registry material"
            )
            request_material = _stored_json(
                row["request_material_json"], "request material"
            )
            material = self._batch_material(row)
            expected_id = (
                "source-read-batch-"
                + _value_sha256(
                    {
                        "request_sha256": row["request_sha256"],
                        "registry_snapshot_sha256": row["registry_snapshot_sha256"],
                        "registry_projection_sha256": row["registry_projection_sha256"],
                        "quota_epoch_sha256": row["quota_epoch_sha256"],
                    }
                )[:32]
            )
            if (
                row["batch_id"] != expected_id
                or row["batch_sha256"] != _value_sha256(material)
                or request_material.get("request_sha256") != row["request_sha256"]
                or registry_material.get("registry_snapshot_sha256")
                != row["registry_snapshot_sha256"]
                or registry_material.get("registry_projection_sha256")
                != row["registry_projection_sha256"]
                or registry_material.get("quota_epoch_sha256")
                != row["quota_epoch_sha256"]
                or request_material.get("quota_epoch_sha256")
                != row["quota_epoch_sha256"]
                or registry_material.get("boundary_sha256") != row["boundary_sha256"]
            ):
                raise SourceReadLedgerIntegrityError("stored batch material differs")
            _sha256(row["idempotency_sha256"], "stored batch idempotency")
            if (
                _ledger_utc(row["prepared_at_utc"], "stored batch time")
                != row["prepared_at_utc"]
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored batch time is not canonical"
                )
            batch_by_id[str(row["batch_id"])] = row
            request_by_batch[str(row["batch_id"])] = request_material
            registry_by_batch[str(row["batch_id"])] = registry_material
            expected_entities[("BATCH", str(row["batch_id"]))] = (
                "BATCH_PREPARED",
                str(row["batch_sha256"]),
                str(row["prepared_at_utc"]),
            )
        operation_by_id: dict[str, sqlite3.Row] = {}
        for expected, row in enumerate(operations, 1):
            if int(row["sequence"]) != expected or row["batch_id"] not in batch_by_id:
                raise SourceReadLedgerIntegrityError("operation sequence/batch differs")
            checkpoint = _stored_json(
                row["checkpoint_before_json"], "checkpoint material"
            )
            reservation = _stored_json(
                row["reservation_material_json"], "reservation material"
            )
            command = _stored_json(row["command_material_json"], "command material")
            material = self._operation_material(row)
            expected_id = (
                "source-read-op-"
                + _value_sha256(
                    {
                        "batch_id": row["batch_id"],
                        "binding_id": row["binding_id"],
                        "page_sequence": row["page_sequence"],
                        "checkpoint_before_sha256": row["checkpoint_before_sha256"],
                        "stream_scope_sha256": row["stream_scope_sha256"],
                        "position_sha256": row["position_sha256"],
                        "command_sha256": row["command_sha256"],
                    }
                )[:32]
            )
            expected_reservation = _value_sha256(
                {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "DURABLE_READ_RESERVATION",
                    **reservation,
                }
            )
            batch_registry = registry_by_batch[str(row["batch_id"])]
            capability = next(
                (
                    item
                    for item in batch_registry["capabilities"]
                    if item["capability_snapshot_sha256"]
                    == row["capability_snapshot_sha256"]
                ),
                None,
            )
            expected_stable_stream = (
                None
                if capability is None
                else _value_sha256(
                    {
                        "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        "record_kind": "STABLE_VAULT_SOURCE_STREAM",
                        "provider_id": capability["provider_id"],
                        "account_id": capability["account_id"],
                        "stream_sha256": command.get("stream_id_sha256"),
                    }
                )
            )
            operation_event = self._entity_event_locked(
                connection, "OPERATION", str(row["operation_id"])
            )
            expected_writer_epoch_root = self._runtime_vault_writer_epoch_root_locked(
                connection,
                at_event_sequence=int(operation_event["sequence"]),
            )
            if (
                row["operation_id"] != expected_id
                or row["operation_sha256"] != _value_sha256(material)
                or row["checkpoint_before_sha256"]
                != checkpoint.get("checkpoint_sha256")
                or row["command_sha256"] != command.get("command_sha256")
                or row["custody_reservation_sha256"] != expected_reservation
                or reservation.get("command_sha256") != row["command_sha256"]
                or reservation.get("checkpoint_before_sha256")
                != row["checkpoint_before_sha256"]
                or reservation.get("position_sha256") != row["position_sha256"]
                or reservation.get("stream_scope_sha256") != row["stream_scope_sha256"]
                or reservation.get("stable_stream_sha256")
                != row["stable_stream_sha256"]
                or reservation.get("writer_epoch_root_sha256")
                != row["writer_epoch_root_sha256"]
                or row["writer_epoch_root_sha256"] != expected_writer_epoch_root
                or row["stable_stream_sha256"] != expected_stable_stream
                or reservation.get("held_items") != row["held_items"]
                or reservation.get("held_bytes") != row["held_bytes"]
                or reservation.get("held_cost_minor") != 0
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored operation material differs"
                )
            if (
                _ledger_utc(row["reserved_at_utc"], "stored reservation time")
                != row["reserved_at_utc"]
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored reservation time is not canonical"
                )
            if _utc_datetime(
                row["reserved_at_utc"], "stored reservation time"
            ) < _utc_datetime(
                batch_by_id[str(row["batch_id"])]["prepared_at_utc"],
                "stored batch time",
            ):
                raise SourceReadLedgerIntegrityError("reservation predates its batch")
            operation_by_id[str(row["operation_id"])] = row
            expected_entities[("OPERATION", str(row["operation_id"]))] = (
                "READ_RESERVED",
                str(row["operation_sha256"]),
                str(row["reserved_at_utc"]),
            )
        intent_by_operation: dict[str, sqlite3.Row] = {}
        for expected, row in enumerate(intents, 1):
            if (
                int(row["sequence"]) != expected
                or row["operation_id"] not in operation_by_id
            ):
                raise SourceReadLedgerIntegrityError(
                    "dispatch intent sequence/operation differs"
                )
            material = self._intent_material(row)
            expected_id = (
                "source-read-intent-"
                + _value_sha256(
                    {
                        "operation_id": row["operation_id"],
                        "idempotency_sha256": row["idempotency_sha256"],
                    }
                )[:32]
            )
            intent_event = self._entity_event_locked(
                connection, "INTENT", str(row["intent_id"])
            )
            expected_writer_epoch_root = self._runtime_vault_writer_epoch_root_locked(
                connection,
                at_event_sequence=int(intent_event["sequence"]),
            )
            if (
                row["intent_id"] != expected_id
                or row["intent_sha256"] != _value_sha256(material)
                or row["writer_epoch_root_sha256"]
                != operation_by_id[str(row["operation_id"])]["writer_epoch_root_sha256"]
                or row["writer_epoch_root_sha256"] != expected_writer_epoch_root
                or str(row["occurred_at_utc"])
                < str(operation_by_id[str(row["operation_id"])]["reserved_at_utc"])
            ):
                raise SourceReadLedgerIntegrityError("dispatch intent material differs")
            if (
                _ledger_utc(row["occurred_at_utc"], "stored dispatch intent time")
                != row["occurred_at_utc"]
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored dispatch intent time is not canonical"
                )
            intent_by_operation[str(row["operation_id"])] = row
            expected_entities[("INTENT", str(row["intent_id"]))] = (
                "DISPATCH_INTENT",
                str(row["intent_sha256"]),
                str(row["occurred_at_utc"]),
            )
        outcomes_by_operation: dict[str, list[sqlite3.Row]] = {}
        continuation_by_outcome: dict[str, SourceReadContinuationBinding] = {}
        for expected, row in enumerate(outcomes, 1):
            if (
                int(row["sequence"]) != expected
                or row["operation_id"] not in operation_by_id
            ):
                raise SourceReadLedgerIntegrityError(
                    "outcome sequence/operation differs"
                )
            material = self._outcome_material(row)
            identity_material = {**material, "outcome_id": ""}
            expected_id = (
                "source-read-outcome-"
                + _value_sha256(
                    {
                        "operation_id": row["operation_id"],
                        "outcome_type": row["outcome_type"],
                        "payload_sha256": _value_sha256(identity_material),
                    }
                )[:32]
            )
            if row["outcome_id"] != expected_id or row[
                "outcome_sha256"
            ] != _value_sha256(material):
                raise SourceReadLedgerIntegrityError("stored outcome material differs")
            if (
                _ledger_utc(row["occurred_at_utc"], "stored outcome time")
                != row["occurred_at_utc"]
            ):
                raise SourceReadLedgerIntegrityError(
                    "stored outcome time is not canonical"
                )
            operation = operation_by_id[str(row["operation_id"])]
            operation_intent = intent_by_operation.get(str(row["operation_id"]))
            outcome_event = self._entity_event_locked(
                connection, "OUTCOME", str(row["outcome_id"])
            )
            expected_writer_epoch_root = self._runtime_vault_writer_epoch_root_locked(
                connection,
                at_event_sequence=int(outcome_event["sequence"]),
            )
            if (
                row["writer_epoch_root_sha256"] != operation["writer_epoch_root_sha256"]
                or operation_intent is None
                or row["writer_epoch_root_sha256"]
                != operation_intent["writer_epoch_root_sha256"]
                or row["writer_epoch_root_sha256"] != expected_writer_epoch_root
            ):
                raise SourceReadLedgerIntegrityError(
                    "outcome writer epoch differs from its dispatch custody"
                )
            if _utc_datetime(
                row["occurred_at_utc"], "stored outcome time"
            ) < _utc_datetime(operation["reserved_at_utc"], "stored reservation time"):
                raise SourceReadLedgerIntegrityError("outcome predates reservation")
            outcome_type = str(row["outcome_type"])
            if outcome_type == "READ_UNCERTAIN":
                factory = _stored_json(
                    row["factory_reservation_json"], "factory reservation"
                )
                if (
                    row["factory_reservation_sha256"]
                    != factory.get("reservation_sha256")
                    or any(
                        row[name] is not None
                        for name in (
                            "page_evidence_sha256",
                            "page_material_json",
                            "receipt_attestation_sha256",
                            "receipt_attestation_json",
                            "observation_sha256s_json",
                            "checkpoint_after_sha256",
                            "checkpoint_after_json",
                            "reconciliation_sha256",
                            "reconciliation_material_json",
                        )
                    )
                    or int(row["committed_items"]) != 0
                    or int(row["committed_bytes"]) != 0
                ):
                    raise SourceReadLedgerIntegrityError("uncertain outcome differs")
            else:
                page = _stored_json(row["page_material_json"], "page material")
                attestation = _stored_json(
                    row["receipt_attestation_json"], "receipt attestation"
                )
                checkpoint = _stored_json(
                    row["checkpoint_after_json"], "checkpoint after"
                )
                observations_json = row["observation_sha256s_json"]
                try:
                    observation_hashes = json.loads(observations_json)
                except (TypeError, json.JSONDecodeError) as error:
                    raise SourceReadLedgerIntegrityError(
                        "stored observation commitments are invalid"
                    ) from error
                if (
                    type(observation_hashes) is not list
                    or _canonical_json(observation_hashes) != observations_json
                    or row["page_evidence_sha256"] != page.get("evidence_sha256")
                    or row["receipt_attestation_sha256"]
                    != attestation.get("attestation_sha256")
                    or row["checkpoint_after_sha256"]
                    != checkpoint.get("checkpoint_sha256")
                    or int(row["committed_items"]) != page.get("record_count")
                    or int(row["committed_bytes"]) != page.get("byte_count")
                    or int(row["committed_items"]) > int(operation["held_items"])
                    or int(row["committed_bytes"]) > int(operation["held_bytes"])
                    or int(row["committed_cost_minor"]) != 0
                ):
                    raise SourceReadLedgerIntegrityError("final outcome differs")
                if outcome_type == "PAGE_ACCEPTED":
                    if (
                        row["factory_reservation_sha256"] is not None
                        or row["reconciliation_sha256"] is not None
                        or row["reconciliation_material_json"] is not None
                    ):
                        raise SourceReadLedgerIntegrityError("accepted outcome differs")
                elif outcome_type == "READ_RECONCILED":
                    reconciliation = _stored_json(
                        row["reconciliation_material_json"], "reconciliation material"
                    )
                    if row["factory_reservation_sha256"] is None or row[
                        "reconciliation_sha256"
                    ] != reconciliation.get("reconciliation_sha256"):
                        raise SourceReadLedgerIntegrityError(
                            "reconciled outcome differs"
                        )
                else:
                    raise SourceReadLedgerIntegrityError("unknown outcome type")
            if row["continuation_binding_sha256"] is not None:
                continuation_material = _stored_json(
                    row["continuation_binding_json"], "continuation binding"
                )
                continuation = _continuation_binding_from_material(
                    continuation_material
                )
                expected_checkpoint = (
                    str(operation["checkpoint_before_sha256"])
                    if outcome_type == "READ_UNCERTAIN"
                    else str(row["checkpoint_after_sha256"])
                )
                expected_page = (
                    None
                    if outcome_type == "READ_UNCERTAIN"
                    else str(row["page_evidence_sha256"])
                )
                if (
                    row["continuation_binding_sha256"]
                    != continuation.ledger_binding_sha256
                    or continuation.operation_id != row["operation_id"]
                    or continuation.expected_outcome != outcome_type
                    or continuation.checkpoint_after_sha256 != expected_checkpoint
                    or continuation.page_evidence_sha256 != expected_page
                ):
                    raise SourceReadLedgerIntegrityError(
                        "stored continuation/outcome binding differs"
                    )
                continuation_by_outcome[str(row["outcome_id"])] = continuation
            outcomes_by_operation.setdefault(str(row["operation_id"]), []).append(row)
            expected_entities[("OUTCOME", str(row["outcome_id"]))] = (
                outcome_type,
                str(row["outcome_sha256"]),
                str(row["occurred_at_utc"]),
            )
        authority_intent_by_key: dict[str, sqlite3.Row] = {}
        authority_disposition_by_key: dict[str, sqlite3.Row] = {}
        authority_disposition_by_ack: dict[str, sqlite3.Row] = {}
        if (
            authority_approval_intents or authority_approval_dispositions
        ) and self._signed_rotation_authority_v1 is None:
            raise SourceReadLedgerIntegrityError(
                "signed authority history has no pinned verifier boundary"
            )
        signed_authority = self._signed_rotation_authority_v1
        for expected, row in enumerate(authority_approval_intents, 1):
            if signed_authority is None:
                raise SourceReadLedgerIntegrityError(
                    "signed authority intent has no pinned verifier"
                )
            command = self._authority_command_for_intent_row(row)
            command_material = _authority_approval_command_material(command)
