    def _insert_authority_disposition_locked(
        self,
        connection: sqlite3.Connection,
        *,
        intent_row: sqlite3.Row,
        readback: SourceReadSignedApprovalReadbackV1,
        decision_verified: object,
        inclusion_verified: object,
        decision_authorized_at_utc: str,
        verification_cut_utc: str,
        business_entity_kind: str | None,
        business_entity_id: str | None,
        business_entity_sha256: str | None,
    ) -> sqlite3.Row:
        decision = readback.decision
        inclusion = readback.inclusion
        query = readback.query
        sequence = int(
            connection.execute(
                """SELECT COALESCE(MAX(sequence),0)+1
                   FROM source_read_authority_approval_dispositions"""
            ).fetchone()[0]
        )
        ack_material = _authority_approval_ack_material(
            approval_key_sha256=str(intent_row["approval_key_sha256"]),
            intent_record_sha256=str(intent_row["intent_sha256"]),
            decision=decision.decision,
            decision_envelope_sha256=decision.envelope_sha256,
            inclusion_envelope_sha256=inclusion.envelope_sha256,
            consumed_at_utc=verification_cut_utc,
            business_entity_kind=business_entity_kind,
            business_entity_id=business_entity_id,
        )
        values: dict[str, object] = {
            "sequence": sequence,
            "approval_key_sha256": str(intent_row["approval_key_sha256"]),
            "decision": decision.decision,
            "decision_payload_sha256": decision.payload_sha256,
            "decision_envelope_sha256": decision.envelope_sha256,
            "decision_envelope_json": decision.canonical_json,
            "authority_generation": decision.authority_generation,
            "authority_head_sha256": decision.authority_head_sha256,
            "authority_sequence": decision.authority_sequence,
            "authority_predecessor_sha256": (decision.authority_predecessor_sha256),
            "trust_bundle_version": decision.trust_bundle_version,
            "trust_bundle_sha256": decision.trust_bundle_sha256,
            "signer_kid": decision.signer_kid,
            "authority_signer_credential_sha256": (
                decision_verified.authority_signer_key_sha256
            ),
            "requester_principal_sha256": decision.requester_principal_sha256,
            "requester_kid": decision.requester_kid,
            "requester_credential_sha256": decision_verified.requester_key_sha256,
            "approver_principal_sha256": decision.approver_principal_sha256,
            "approver_kid": decision.approver_kid,
            "approver_credential_sha256": decision_verified.approver_key_sha256,
            "decision_authorized_at_utc": decision_authorized_at_utc,
            "inclusion_challenge_sha256": query.challenge_sha256,
            "inclusion_query_sha256": query.query_sha256,
            "inclusion_payload_sha256": inclusion.payload_sha256,
            "inclusion_envelope_sha256": inclusion.envelope_sha256,
            "inclusion_envelope_json": inclusion.canonical_json,
            "inclusion_authority_generation": inclusion.authority_generation,
            "inclusion_authority_head_sha256": inclusion.authority_head_sha256,
            "inclusion_authority_sequence": inclusion.authority_sequence,
            "inclusion_authority_predecessor_sha256": (
                inclusion.authority_predecessor_sha256
            ),
            "inclusion_trust_bundle_version": inclusion.trust_bundle_version,
            "inclusion_trust_bundle_sha256": inclusion.trust_bundle_sha256,
            "inclusion_signer_kid": inclusion.signer_kid,
            "inclusion_signer_credential_sha256": (
                inclusion_verified.authority_signer_key_sha256
            ),
            "consumed_at_utc": verification_cut_utc,
            "approval_ack_sha256": _value_sha256(ack_material),
            "business_entity_kind": business_entity_kind,
            "business_entity_id": business_entity_id,
            "business_entity_sha256": business_entity_sha256,
        }
        values["disposition_sha256"] = _value_sha256(
            self._authority_approval_disposition_material(values)
        )
        connection.execute(
            """INSERT INTO source_read_authority_approval_dispositions(
                   sequence,approval_key_sha256,decision,
                   decision_payload_sha256,decision_envelope_sha256,
                   decision_envelope_json,authority_generation,
                   authority_head_sha256,authority_sequence,
                   authority_predecessor_sha256,trust_bundle_version,
                   trust_bundle_sha256,signer_kid,
                   authority_signer_credential_sha256,
                   requester_principal_sha256,requester_kid,
                   requester_credential_sha256,approver_principal_sha256,
                   approver_kid,approver_credential_sha256,
                   decision_authorized_at_utc,inclusion_challenge_sha256,
                   inclusion_query_sha256,inclusion_payload_sha256,
                   inclusion_envelope_sha256,inclusion_envelope_json,
                   inclusion_authority_generation,
                   inclusion_authority_head_sha256,
                   inclusion_authority_sequence,
                   inclusion_authority_predecessor_sha256,
                   inclusion_trust_bundle_version,
                   inclusion_trust_bundle_sha256,inclusion_signer_kid,
                   inclusion_signer_credential_sha256,consumed_at_utc,
                   approval_ack_sha256,business_entity_kind,business_entity_id,
                   business_entity_sha256,disposition_sha256)
               VALUES(
                   :sequence,:approval_key_sha256,:decision,
                   :decision_payload_sha256,:decision_envelope_sha256,
                   :decision_envelope_json,:authority_generation,
                   :authority_head_sha256,:authority_sequence,
                   :authority_predecessor_sha256,:trust_bundle_version,
                   :trust_bundle_sha256,:signer_kid,
                   :authority_signer_credential_sha256,
                   :requester_principal_sha256,:requester_kid,
                   :requester_credential_sha256,:approver_principal_sha256,
                   :approver_kid,:approver_credential_sha256,
                   :decision_authorized_at_utc,:inclusion_challenge_sha256,
                   :inclusion_query_sha256,:inclusion_payload_sha256,
                   :inclusion_envelope_sha256,:inclusion_envelope_json,
                   :inclusion_authority_generation,
                   :inclusion_authority_head_sha256,
                   :inclusion_authority_sequence,
                   :inclusion_authority_predecessor_sha256,
                   :inclusion_trust_bundle_version,
                   :inclusion_trust_bundle_sha256,:inclusion_signer_kid,
                   :inclusion_signer_credential_sha256,:consumed_at_utc,
                   :approval_ack_sha256,:business_entity_kind,:business_entity_id,
                   :business_entity_sha256,:disposition_sha256)""",
            values,
        )
        if decision.decision != "APPROVED":
            self._append_event_locked(
                connection,
                event_type="AUTHORITY_APPROVAL_DISPOSED",
                entity_kind="AUTHORITY_APPROVAL",
                entity_id=str(intent_row["approval_id"]) + ":DISPOSITION",
                entity_sha256=str(values["disposition_sha256"]),
                occurred_at_utc=verification_cut_utc,
            )
        return connection.execute(
            """SELECT * FROM source_read_authority_approval_dispositions
               WHERE approval_key_sha256=?""",
            (intent_row["approval_key_sha256"],),
        ).fetchone()

    def _append_continuation_rotation_locked(
        self,
        connection: sqlite3.Connection,
        *,
        current_binding: SourceReadContinuationBinding,
        next_binding: SourceReadContinuationBinding,
        next_json: str,
        lineage_sha256: str,
        idempotency_sha256: str,
        governance_evidence_sha256: str,
        authorization: SourceReadContinuationRotationAuthorizationReceipt,
        authorization_json: str,
        occurred_at_utc: str,
        expected_current_head_sha256: str,
        authority_approval_ack_sha256: str | None,
    ) -> sqlite3.Row:
        prior_head = connection.execute(
            """SELECT * FROM source_read_continuation_heads
               WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
            (lineage_sha256,),
        ).fetchone()
        if prior_head is None:
            raise SourceReadLedgerStateConflict(
                "continuation rotation requires an existing latest head"
            )
        stored_current = self._continuation_binding_for_head_locked(
            connection, prior_head
        )
        if (
            stored_current != current_binding
            or prior_head["head_sha256"] != expected_current_head_sha256
            or prior_head["ledger_binding_sha256"]
            != current_binding.ledger_binding_sha256
        ):
            raise SourceReadLedgerStateConflict(
                "continuation rotation lost the latest-head comparison"
            )
        latest_event = connection.execute(
            """SELECT occurred_at_utc FROM source_read_events
               ORDER BY sequence DESC LIMIT 1"""
        ).fetchone()
        if latest_event is not None and _utc_datetime(
            occurred_at_utc, "continuation rotation time"
        ) < _utc_datetime(latest_event[0], "latest ledger event time"):
            raise SourceReadLedgerValidationError(
                "continuation rotation time predates the ledger head"
            )
        sequence = int(
            connection.execute(
                """SELECT COALESCE(MAX(sequence),0)+1
                   FROM source_read_continuation_rebindings"""
            ).fetchone()[0]
        )
        head_sequence = int(
            connection.execute(
                """SELECT COALESCE(MAX(sequence),0)+1
                   FROM source_read_continuation_heads"""
            ).fetchone()[0]
        )
        values: dict[str, object] = {
            "sequence": sequence,
            "rotation_id": next_binding.operation_id,
            "idempotency_sha256": idempotency_sha256,
            "lineage_sha256": lineage_sha256,
            "current_ledger_binding_sha256": (current_binding.ledger_binding_sha256),
            "next_ledger_binding_sha256": next_binding.ledger_binding_sha256,
            "next_binding_json": next_json,
            "previous_head_sha256": str(prior_head["head_sha256"]),
            "governance_evidence_sha256": governance_evidence_sha256,
            "governance_authorization_sha256": authorization.authorization_sha256,
            "governance_authorization_json": authorization_json,
            "authority_approval_ack_sha256": authority_approval_ack_sha256,
            "occurred_at_utc": occurred_at_utc,
        }
        values["rotation_sha256"] = _value_sha256(
            self._continuation_rotation_material(values)
        )
        connection.execute(
            """INSERT INTO source_read_continuation_rebindings(
                   sequence,rotation_id,idempotency_sha256,lineage_sha256,
                   current_ledger_binding_sha256,next_ledger_binding_sha256,
                   next_binding_json,previous_head_sha256,
                   governance_evidence_sha256,governance_authorization_sha256,
                   governance_authorization_json,authority_approval_ack_sha256,
                   occurred_at_utc,rotation_sha256)
               VALUES(
                   :sequence,:rotation_id,:idempotency_sha256,:lineage_sha256,
                   :current_ledger_binding_sha256,:next_ledger_binding_sha256,
                   :next_binding_json,:previous_head_sha256,
                   :governance_evidence_sha256,:governance_authorization_sha256,
                   :governance_authorization_json,:authority_approval_ack_sha256,
                   :occurred_at_utc,:rotation_sha256)""",
            values,
        )
        head_base: dict[str, object] = {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "record_kind": "SOURCE_READ_CONTINUATION_HEAD",
            "sequence": head_sequence,
            "lineage_sha256": lineage_sha256,
            "generation": next_binding.generation,
            "operation_id": next_binding.operation_id,
            "outcome_id": None,
            "rotation_id": next_binding.operation_id,
            "migration_id": None,
            "repair_id": None,
            "ledger_binding_sha256": next_binding.ledger_binding_sha256,
            "previous_head_sha256": str(prior_head["head_sha256"]),
        }
        connection.execute(
            """INSERT INTO source_read_continuation_heads(
                   sequence,lineage_sha256,generation,operation_id,outcome_id,
                   rotation_id,migration_id,repair_id,ledger_binding_sha256,
                   previous_head_sha256,head_sha256)
               VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
            (
                head_sequence,
                lineage_sha256,
                next_binding.generation,
                next_binding.operation_id,
                None,
                next_binding.operation_id,
                None,
                None,
                next_binding.ledger_binding_sha256,
                prior_head["head_sha256"],
                _value_sha256(head_base),
            ),
        )
        self._append_event_locked(
            connection,
            event_type="CONTINUATION_REKEYED",
            entity_kind="CONTINUATION",
            entity_id=next_binding.operation_id,
            entity_sha256=str(values["rotation_sha256"]),
            occurred_at_utc=occurred_at_utc,
        )
        return connection.execute(
            """SELECT * FROM source_read_continuation_rebindings
               WHERE rotation_id=?""",
            (next_binding.operation_id,),
        ).fetchone()

    def _signed_rotation_authorization(
        self,
        *,
        decision: SignedAuthorityEnvelopeV1,
        current_binding: SourceReadContinuationBinding,
        next_binding: SourceReadContinuationBinding,
        lineage_sha256: str,
        governance_evidence_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadContinuationRotationAuthorizationReceipt:
        material = _continuation_rotation_authorization_material(
            authority_identity_sha256=decision.issuer_sha256,
            store_identity_sha256=self.store_identity_sha256,
            lineage_sha256=lineage_sha256,
            current_ledger_binding_sha256=(current_binding.ledger_binding_sha256),
            next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
            occurred_at_utc=occurred_at_utc,
            governance_evidence_sha256=governance_evidence_sha256,
            requested_by_sha256=decision.requester_principal_sha256,
            approved_by_sha256=decision.approver_principal_sha256,
        )
        receipt = SourceReadContinuationRotationAuthorizationReceipt(
            authority_identity_sha256=decision.issuer_sha256,
            store_identity_sha256=self.store_identity_sha256,
            lineage_sha256=lineage_sha256,
            current_ledger_binding_sha256=(current_binding.ledger_binding_sha256),
            next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
            occurred_at_utc=occurred_at_utc,
            governance_evidence_sha256=governance_evidence_sha256,
            requested_by_sha256=decision.requester_principal_sha256,
            approved_by_sha256=decision.approver_principal_sha256,
            authorization_sha256=_value_sha256(material),
        )
        return _validated_continuation_rotation_authorization(
            receipt,
            authority_identity_sha256=decision.issuer_sha256,
            store_identity_sha256=self.store_identity_sha256,
            lineage_sha256=lineage_sha256,
            current_ledger_binding_sha256=(current_binding.ledger_binding_sha256),
            next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
            occurred_at_utc=occurred_at_utc,
            governance_evidence_sha256=governance_evidence_sha256,
        )

    @staticmethod
    def _authorization_json(
        authorization: SourceReadContinuationRotationAuthorizationReceipt,
    ) -> str:
        return _json_material(
            {
                "authority_identity_sha256": (authorization.authority_identity_sha256),
                "store_identity_sha256": authorization.store_identity_sha256,
                "lineage_sha256": authorization.lineage_sha256,
                "current_ledger_binding_sha256": (
                    authorization.current_ledger_binding_sha256
                ),
                "next_ledger_binding_sha256": (
                    authorization.next_ledger_binding_sha256
                ),
                "occurred_at_utc": authorization.occurred_at_utc,
                "governance_evidence_sha256": (
                    authorization.governance_evidence_sha256
                ),
                "requested_by_sha256": authorization.requested_by_sha256,
                "approved_by_sha256": authorization.approved_by_sha256,
                "authorization_sha256": authorization.authorization_sha256,
            },
            "continuation rotation authorization",
        )

    def _rotate_continuation_binding_signed(
        self,
        *,
        current_proof: SourceReadContinuationProof | None,
        current_binding: SourceReadContinuationBinding,
        expected_current_head_sha256: str,
        next_binding: SourceReadContinuationBinding,
        next_material: Mapping[str, object],
        lineage_sha256: str,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> ContinuationRotation:
        authority = self._signed_rotation_authority_v1
        if authority is None:
            raise SourceReadLedgerStateConflict(
                "signed rotation approval boundary is absent"
            )
        expected_semantic = self._signed_rotation_semantic_material(
            current_binding=current_binding,
            next_binding=next_binding,
            next_binding_material=next_material,
            lineage_sha256=lineage_sha256,
            governance_evidence_sha256=governance_evidence_sha256,
            occurred_at_utc=occurred_at_utc,
        )
        operation_sha256 = _value_sha256(
            {
                "protocol": SOURCE_READ_AUTHORITY_BOUNDARY_PROTOCOL_V1,
                "record_kind": "SOURCE_READ_AUTHORITY_BUSINESS_OPERATION",
                "action": SOURCE_READ_CONTINUATION_ROTATION_ACTION_V1,
                "operation_id": next_binding.operation_id,
            }
        )
        approval_key_sha256 = _authority_approval_key_sha256(
            store_identity_sha256=self.store_identity_sha256,
            action=SOURCE_READ_CONTINUATION_ROTATION_ACTION_V1,
            operation_sha256=operation_sha256,
            idempotency_sha256=idempotency_sha256,
        )

        with self._read() as connection:
            intent_row = connection.execute(
                """SELECT * FROM source_read_authority_approval_intents
                   WHERE approval_key_sha256=?""",
                (approval_key_sha256,),
            ).fetchone()
            pending = self._pending_authority_approval_locked(connection)
            if pending is not None and intent_row is None:
                raise SourceReadLedgerStateConflict(
                    "another authority approval already holds the ledger"
                )
            if intent_row is not None:
                occurred_at_utc = str(intent_row["frozen_occurred_at_utc"])
                expected_semantic = self._signed_rotation_semantic_material(
                    current_binding=current_binding,
                    next_binding=next_binding,
                    next_binding_material=next_material,
                    lineage_sha256=lineage_sha256,
                    governance_evidence_sha256=governance_evidence_sha256,
                    occurred_at_utc=occurred_at_utc,
                )
                command = self._authority_command_for_intent_row(intent_row)
                if (
                    not self._signed_rotation_intent_is_exact(
                        intent_row,
                        command,
                        operation_id=next_binding.operation_id,
                    )
                    or _stored_json(
                        intent_row["semantic_request_json"],
                        "signed rotation semantic request",
                    )
                    != expected_semantic
                    or command.semantic_request_sha256
                    != _value_sha256(expected_semantic)
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "signed rotation approval key is bound to different material"
                    )
            else:
                command = None

        if intent_row is None:
            if current_proof is None or not self.verify_latest_continuation_proof(
                current_proof
            ):
                raise SourceReadLedgerStateConflict(
                    "signed rotation creation requires the authoritative current proof"
                )
            with self._read() as connection:
                verification = self._verify_locked(connection)
                command = self._signed_rotation_command(
                    current_binding=current_binding,
                    next_binding=next_binding,
                    next_binding_material=next_material,
                    lineage_sha256=lineage_sha256,
                    governance_evidence_sha256=governance_evidence_sha256,
                    idempotency_sha256=idempotency_sha256,
                    occurred_at_utc=occurred_at_utc,
                    local_predecessor_event_sha256=(verification.head_event_sha256),
                )
            observation_cut = authority.trusted_now_utc()
            try:
                observed = authority.observe_request(command=command)
                observation, observation_verified = (
                    self._verify_request_observation_envelope(
                        authority,
                        command,
                        observed,
                        historical=False,
                        verification_cut_utc=observation_cut,
                    )
                )
            except (SignedAuthorityError, TypeError, ValueError) as error:
                raise SourceReadLedgerStateConflict(
                    "signed authority request observation is unavailable"
                ) from error
            with self._write(
                authority_approval_key_sha256=approval_key_sha256,
                allow_authority_intent_creation=True,
            ) as connection:
                replay_intent = connection.execute(
                    """SELECT * FROM source_read_authority_approval_intents
                       WHERE approval_key_sha256=?""",
                    (approval_key_sha256,),
                ).fetchone()
                if replay_intent is not None:
                    raced_occurred = str(replay_intent["frozen_occurred_at_utc"])
                    raced_semantic = self._signed_rotation_semantic_material(
                        current_binding=current_binding,
                        next_binding=next_binding,
                        next_binding_material=next_material,
                        lineage_sha256=lineage_sha256,
                        governance_evidence_sha256=governance_evidence_sha256,
                        occurred_at_utc=raced_occurred,
                    )
                    raced_command = self._authority_command_for_intent_row(
                        replay_intent
                    )
                    if (
                        not self._signed_rotation_intent_is_exact(
                            replay_intent,
                            raced_command,
                            operation_id=next_binding.operation_id,
                        )
                        or _stored_json(
                            replay_intent["semantic_request_json"],
                            "raced signed rotation semantic request",
                        )
                        != raced_semantic
                        or raced_command.semantic_request_sha256
                        != _value_sha256(raced_semantic)
                    ):
                        raise SourceReadLedgerIdempotencyConflict(
                            "signed rotation approval intent raced with different material"
                        )
                    intent_row = replay_intent
                    command = raced_command
                    occurred_at_utc = raced_occurred
                else:
                    self._assert_no_unresolved_operations_locked(connection)
                    self._assert_no_active_key_lifecycle_locked(connection)
                    self._assert_no_active_stream_incident_locked(
                        connection, lineage_sha256=lineage_sha256
                    )
                    self._assert_continuation_writer_epoch_locked(
                        connection, next_binding
                    )
                    latest = connection.execute(
                        """SELECT * FROM source_read_continuation_heads
                           WHERE lineage_sha256=?
                           ORDER BY sequence DESC LIMIT 1""",
                        (lineage_sha256,),
                    ).fetchone()
                    head_event = connection.execute(
                        """SELECT event_sha256,occurred_at_utc
                           FROM source_read_events
                           ORDER BY sequence DESC LIMIT 1"""
                    ).fetchone()
                    if (
                        latest is None
                        or self._continuation_binding_for_head_locked(
                            connection, latest
                        )
                        != current_binding
                        or latest["head_sha256"] != expected_current_head_sha256
                        or (
                            ZERO_SHA256
                            if head_event is None
                            else head_event["event_sha256"]
                        )
                        != command.local_predecessor_event_sha256
                    ):
                        raise SourceReadLedgerStateConflict(
                            "signed rotation lost its pre-intent ledger comparison"
                        )
                    if head_event is not None and _utc_datetime(
                        occurred_at_utc, "signed rotation frozen time"
                    ) < _utc_datetime(
                        head_event["occurred_at_utc"], "latest ledger event time"
                    ):
                        raise SourceReadLedgerValidationError(
                            "signed rotation time predates the ledger head"
                        )
                    intent_row = self._insert_authority_approval_intent_locked(
                        connection,
                        command=command,
                        operation_id=next_binding.operation_id,
                        observation=observation,
                        verified=observation_verified,
                        verification_cut_utc=observation_cut,
                    )

        with self._read() as connection:
            intent_row = connection.execute(
                """SELECT * FROM source_read_authority_approval_intents
                   WHERE approval_key_sha256=?""",
                (approval_key_sha256,),
            ).fetchone()
            if intent_row is None:
                raise SourceReadLedgerIntegrityError(
                    "signed rotation intent disappeared"
                )
            anchored_intent = self._anchored_authority_intent_locked(
                connection, intent_row
            )
            request_observation = SignedAuthorityEnvelopeV1.from_canonical_json(
                str(intent_row["request_observation_envelope_json"])
            )

        submit_error: Exception | None = None
        try:
            authority.submit_anchored_intent(intent=anchored_intent)
        except Exception as error:
            submit_error = error
        try:
            readback = authority.read_approval(intent=anchored_intent)
            consumed_at_utc = authority.trusted_now_utc()
            decision_authorized_at_utc = readback.decision.issued_at_utc
            (
                decision,
                decision_verified,
                inclusion,
                inclusion_verified,
            ) = self._verify_approval_readback(
                authority,
                anchored_intent,
                request_observation,
                readback,
                historical=False,
                decision_authorized_at_utc=decision_authorized_at_utc,
                verification_cut_utc=consumed_at_utc,
            )
        except (
            SignedAuthorityError,
            SourceReadLedgerError,
            TypeError,
            ValueError,
        ) as error:
            raise SourceReadLedgerStateConflict(
                "signed authority approval readback is unavailable"
            ) from (submit_error if submit_error is not None else error)
        exact_readback = SourceReadSignedApprovalReadbackV1(
            decision=decision,
            inclusion=inclusion,
            query=readback.query,
            live_release_eligible=False,
        )
        if decision.decision == _AUTHORITY_NOT_FOUND:
            raise SourceReadLedgerStateConflict(
                "signed authority has not durably decided the anchored intent"
            ) from submit_error

        if decision.decision != "APPROVED":
            with self._write(
                authority_approval_key_sha256=approval_key_sha256
            ) as connection:
                current_intent = connection.execute(
                    """SELECT * FROM source_read_authority_approval_intents
                       WHERE approval_key_sha256=?""",
                    (approval_key_sha256,),
                ).fetchone()
                disposition = connection.execute(
                    """SELECT * FROM source_read_authority_approval_dispositions
                       WHERE approval_key_sha256=?""",
                    (approval_key_sha256,),
                ).fetchone()
                if current_intent is None:
                    raise SourceReadLedgerIntegrityError(
                        "signed authority intent disappeared before disposition"
                    )
                if disposition is None:
                    self._insert_authority_disposition_locked(
                        connection,
                        intent_row=current_intent,
                        readback=exact_readback,
                        decision_verified=decision_verified,
                        inclusion_verified=inclusion_verified,
                        decision_authorized_at_utc=(decision_authorized_at_utc),
                        verification_cut_utc=consumed_at_utc,
                        business_entity_kind=None,
                        business_entity_id=None,
                        business_entity_sha256=None,
                    )
                elif (
                    disposition["decision"] != decision.decision
                    or disposition["decision_envelope_sha256"]
                    != decision.envelope_sha256
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "signed authority disposition differs"
                    )
            raise SourceReadLedgerStateConflict(
                f"signed authority disposition is {decision.decision}"
            )

        authorization = self._signed_rotation_authorization(
            decision=decision,
            current_binding=current_binding,
            next_binding=next_binding,
            lineage_sha256=lineage_sha256,
            governance_evidence_sha256=governance_evidence_sha256,
            occurred_at_utc=occurred_at_utc,
        )
        authorization_json = self._authorization_json(authorization)
        ack_sha256 = _value_sha256(
            _authority_approval_ack_material(
                approval_key_sha256=approval_key_sha256,
                intent_record_sha256=str(intent_row["intent_sha256"]),
                decision="APPROVED",
                decision_envelope_sha256=decision.envelope_sha256,
                inclusion_envelope_sha256=inclusion.envelope_sha256,
                consumed_at_utc=consumed_at_utc,
                business_entity_kind="CONTINUATION",
                business_entity_id=next_binding.operation_id,
            )
        )
        next_json = _json_material(next_material, "continuation rekey binding")
        with self._write(
            authority_approval_key_sha256=approval_key_sha256
        ) as connection:
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_no_active_stream_incident_locked(
                connection, lineage_sha256=lineage_sha256
            )
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
            replay = self._find_idempotency_locked(connection, idempotency_sha256)
            if replay is not None:
                kind, row = replay
                stored_disposition = connection.execute(
                    """SELECT * FROM source_read_authority_approval_dispositions
                       WHERE approval_key_sha256=?""",
                    (approval_key_sha256,),
                ).fetchone()
                if (
                    kind != "CONTINUATION"
                    or row["rotation_id"] != next_binding.operation_id
                    or row["next_ledger_binding_sha256"]
                    != next_binding.ledger_binding_sha256
                    or stored_disposition is None
                    or stored_disposition["decision"] != "APPROVED"
                    or stored_disposition["business_entity_kind"] != "CONTINUATION"
                    or stored_disposition["business_entity_id"]
                    != next_binding.operation_id
                    or row["authority_approval_ack_sha256"]
                    != stored_disposition["approval_ack_sha256"]
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "signed rotation idempotency digest is already bound"
                    )
                return self._continuation_rotation_from_row(row, replayed=True)
            current_intent = connection.execute(
                """SELECT * FROM source_read_authority_approval_intents
                   WHERE approval_key_sha256=?""",
                (approval_key_sha256,),
            ).fetchone()
            disposition = connection.execute(
                """SELECT * FROM source_read_authority_approval_dispositions
                   WHERE approval_key_sha256=?""",
                (approval_key_sha256,),
            ).fetchone()
            if current_intent is None or disposition is not None:
                raise SourceReadLedgerStateConflict(
                    "signed rotation intent is not finalizable"
                )
            row = self._append_continuation_rotation_locked(
                connection,
                current_binding=current_binding,
                next_binding=next_binding,
                next_json=next_json,
                lineage_sha256=lineage_sha256,
                idempotency_sha256=idempotency_sha256,
                governance_evidence_sha256=governance_evidence_sha256,
                authorization=authorization,
                authorization_json=authorization_json,
                occurred_at_utc=occurred_at_utc,
                expected_current_head_sha256=expected_current_head_sha256,
                authority_approval_ack_sha256=ack_sha256,
            )
            self._insert_authority_disposition_locked(
                connection,
                intent_row=current_intent,
                readback=exact_readback,
                decision_verified=decision_verified,
                inclusion_verified=inclusion_verified,
                decision_authorized_at_utc=decision_authorized_at_utc,
                verification_cut_utc=consumed_at_utc,
                business_entity_kind="CONTINUATION",
                business_entity_id=next_binding.operation_id,
                business_entity_sha256=str(row["rotation_sha256"]),
            )
            return self._continuation_rotation_from_row(row, replayed=False)

    def rotate_continuation_binding(
        self,
        current_proof: SourceReadContinuationProof | None,
        next_binding: SourceReadContinuationBinding,
        *,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> ContinuationRotation:
        """Anchor an SoD-authorized envelope rebind of the exact latest lineage."""

        if self._external_anchor is None or (
            self._continuation_rotation_authority is None
            and self._signed_rotation_authority_v1 is None
        ):
            raise SourceReadLedgerStateConflict(
                "continuation rotation requires anchor and pinned SoD authority"
            )
        next_material = _continuation_binding_material(next_binding)
        if next_binding.expected_outcome != "CONTINUATION_REKEYED":
            raise SourceReadLedgerValidationError(
                "continuation rotation requires CONTINUATION_REKEYED binding"
            )
        lineage = _continuation_lineage_sha256(next_binding)
        evidence = _sha256(
            governance_evidence_sha256,
            "continuation rotation governance_evidence_sha256",
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")

        def exact_replay(
            row: sqlite3.Row,
            current: SourceReadContinuationBinding | None,
        ) -> bool:
            return bool(
                row["rotation_id"] == next_binding.operation_id
                and row["lineage_sha256"] == lineage
                and (
                    current is None
                    or row["current_ledger_binding_sha256"]
                    == current.ledger_binding_sha256
                )
                and row["next_ledger_binding_sha256"]
                == next_binding.ledger_binding_sha256
                and row["governance_evidence_sha256"] == evidence
                and _stored_json(row["next_binding_json"], "continuation rekey binding")
                == next_material
            )

        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if kind != "CONTINUATION" or not exact_replay(
                    row,
                    None if current_proof is None else current_proof.binding,
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "continuation rotation idempotency digest is already bound"
                    )
                return self._continuation_rotation_from_row(row, replayed=True)
            if current_proof is None:
                if self._signed_rotation_authority_v1 is None:
                    raise SourceReadLedgerStateConflict(
                        "continuation rotation requires a ledger-created current proof"
                    )
                stored_intents = connection.execute(
                    """SELECT * FROM source_read_authority_approval_intents
                       WHERE business_operation_id=?
                          OR business_idempotency_sha256=?
                       ORDER BY sequence""",
                    (next_binding.operation_id, idempotency),
                ).fetchall()
                if len(stored_intents) != 1:
                    raise SourceReadLedgerStateConflict(
                        "signed rotation resume requires one exact durable intent"
                    )
                latest = connection.execute(
                    """SELECT * FROM source_read_continuation_heads
                       WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                    (lineage,),
                ).fetchone()
                if latest is None:
                    raise SourceReadLedgerStateConflict(
                        "signed rotation resume has no current continuation head"
                    )
                current_binding = self._continuation_binding_for_head_locked(
                    connection, latest
                )
                expected_current_head_sha256 = str(latest["head_sha256"])
            else:
                if not self.continuation_proof_is_known(current_proof):
                    raise SourceReadLedgerStateConflict(
                        "continuation rotation requires a ledger-created current proof"
                    )
                current_binding = current_proof.binding
                expected_current_head_sha256 = current_proof.continuation_head_sha256
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
        if lineage != _continuation_lineage_sha256(current_binding):
            raise SourceReadLedgerValidationError(
                "continuation rotation lineage differs"
            )
        if (
            next_binding.generation <= current_binding.generation
            or next_binding.previous_active_version
            != current_binding.previous_active_version + 1
            or next_binding.previous_active_envelope_sha256
            != current_binding.envelope_sha256
            or next_binding.vault_protocol != current_binding.vault_protocol
            or next_binding.vault_store_identity_sha256
            != current_binding.vault_store_identity_sha256
            or next_binding.slot_sha256 != current_binding.slot_sha256
            or next_binding.encrypted_state_sha256
            == current_binding.encrypted_state_sha256
            or next_binding.envelope_sha256 == current_binding.envelope_sha256
            or next_binding.runtime_state_sha256 != current_binding.runtime_state_sha256
            or next_binding.checkpoint_after_sha256
            != current_binding.checkpoint_after_sha256
            or next_binding.page_evidence_sha256 != current_binding.page_evidence_sha256
        ):
            raise SourceReadLedgerValidationError(
                "continuation rotation is not an exact key-only latest-head advance"
            )
        if self._signed_rotation_authority_v1 is not None:
            return self._rotate_continuation_binding_signed(
                current_proof=current_proof,
                current_binding=current_binding,
                expected_current_head_sha256=expected_current_head_sha256,
                next_binding=next_binding,
                next_material=next_material,
                lineage_sha256=lineage,
                governance_evidence_sha256=evidence,
                idempotency_sha256=idempotency,
                occurred_at_utc=occurred,
            )
        if current_proof is None or not self.verify_latest_continuation_proof(
            current_proof
        ):
            raise SourceReadLedgerStateConflict(
                "continuation rotation proof is not the authoritative latest head"
            )
        if self._continuation_rotation_authority is None:
            raise SourceReadLedgerStateConflict(
                "continuation rotation SoD authority is absent"
            )
        authority_receipt = self._continuation_rotation_authority.authorize_rotation(
            store_identity_sha256=self.store_identity_sha256,
            lineage_sha256=lineage,
            current_ledger_binding_sha256=current_binding.ledger_binding_sha256,
            next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
            occurred_at_utc=occurred,
            governance_evidence_sha256=evidence,
        )
        authorization = _validated_continuation_rotation_authorization(
            authority_receipt,
            authority_identity_sha256=(
                self.continuation_rotation_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            lineage_sha256=lineage,
            current_ledger_binding_sha256=current_binding.ledger_binding_sha256,
            next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
            occurred_at_utc=occurred,
            governance_evidence_sha256=evidence,
        )
        authorization_material = {
            "authority_identity_sha256": authorization.authority_identity_sha256,
            "store_identity_sha256": authorization.store_identity_sha256,
            "lineage_sha256": authorization.lineage_sha256,
            "current_ledger_binding_sha256": (
                authorization.current_ledger_binding_sha256
            ),
            "next_ledger_binding_sha256": authorization.next_ledger_binding_sha256,
            "occurred_at_utc": authorization.occurred_at_utc,
            "governance_evidence_sha256": (authorization.governance_evidence_sha256),
            "requested_by_sha256": authorization.requested_by_sha256,
            "approved_by_sha256": authorization.approved_by_sha256,
            "authorization_sha256": authorization.authorization_sha256,
        }
        authorization_json = _json_material(
            authorization_material,
            "continuation rotation authorization",
        )
        next_json = _json_material(next_material, "continuation rekey binding")
        with self._write() as connection:
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_no_active_stream_incident_locked(
                connection, lineage_sha256=lineage
            )
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if kind != "CONTINUATION" or not exact_replay(row, current_binding):
                    raise SourceReadLedgerIdempotencyConflict(
                        "continuation rotation idempotency digest is already bound"
                    )
                return self._continuation_rotation_from_row(row, replayed=True)
            prior_head = connection.execute(
                """SELECT h.*,COALESCE(
                           o.continuation_binding_json,r.next_binding_json
                       ) AS continuation_binding_json
                   FROM source_read_continuation_heads h
                   LEFT JOIN source_read_outcomes o ON o.outcome_id=h.outcome_id
                   LEFT JOIN source_read_continuation_rebindings r
                     ON r.rotation_id=h.rotation_id
                   WHERE h.lineage_sha256=?
                   ORDER BY h.sequence DESC LIMIT 1""",
                (lineage,),
            ).fetchone()
            if prior_head is None:
                raise SourceReadLedgerStateConflict(
                    "continuation rotation requires an existing latest head"
                )
            stored_current = _continuation_binding_from_material(
                _stored_json(
                    prior_head["continuation_binding_json"],
                    "current continuation binding",
                )
            )
            if (
                stored_current != current_binding
                or prior_head["head_sha256"] != current_proof.continuation_head_sha256
                or prior_head["ledger_binding_sha256"]
                != current_binding.ledger_binding_sha256
            ):
                raise SourceReadLedgerStateConflict(
                    "continuation rotation lost the latest-head comparison"
                )
            latest_event = connection.execute(
                "SELECT occurred_at_utc FROM source_read_events ORDER BY sequence DESC LIMIT 1"
            ).fetchone()
            if latest_event is not None and _utc_datetime(
                occurred, "continuation rotation time"
            ) < _utc_datetime(latest_event[0], "latest ledger event time"):
                raise SourceReadLedgerValidationError(
                    "continuation rotation time predates the ledger head"
                )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_continuation_rebindings"
                ).fetchone()[0]
            )
            head_sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_continuation_heads"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_CONTINUATION_REKEY",
                "rotation_id": next_binding.operation_id,
                "idempotency_sha256": idempotency,
                "lineage_sha256": lineage,
                "current_ledger_binding_sha256": (
                    current_binding.ledger_binding_sha256
                ),
                "next_ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "next_binding_json_sha256": _hash_text(next_json),
                "previous_head_sha256": str(prior_head["head_sha256"]),
                "governance_evidence_sha256": evidence,
                "governance_authorization_sha256": (authorization.authorization_sha256),
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "occurred_at_utc": occurred,
            }
            rotation_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_continuation_rebindings(
                       sequence,rotation_id,idempotency_sha256,lineage_sha256,
                       current_ledger_binding_sha256,next_ledger_binding_sha256,
                       next_binding_json,previous_head_sha256,
                       governance_evidence_sha256,governance_authorization_sha256,
                       governance_authorization_json,occurred_at_utc,rotation_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    next_binding.operation_id,
                    idempotency,
                    lineage,
                    current_binding.ledger_binding_sha256,
                    next_binding.ledger_binding_sha256,
                    next_json,
                    prior_head["head_sha256"],
                    evidence,
                    authorization.authorization_sha256,
                    authorization_json,
                    occurred,
                    rotation_sha,
                ),
            )
            head_base: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_CONTINUATION_HEAD",
                "sequence": head_sequence,
                "lineage_sha256": lineage,
                "generation": next_binding.generation,
                "operation_id": next_binding.operation_id,
                "outcome_id": None,
                "rotation_id": next_binding.operation_id,
                "migration_id": None,
                "repair_id": None,
                "ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "previous_head_sha256": str(prior_head["head_sha256"]),
            }
            connection.execute(
                """INSERT INTO source_read_continuation_heads(
                       sequence,lineage_sha256,generation,operation_id,outcome_id,
                       rotation_id,migration_id,repair_id,ledger_binding_sha256,
                       previous_head_sha256,head_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    head_sequence,
                    lineage,
                    next_binding.generation,
                    next_binding.operation_id,
                    None,
                    next_binding.operation_id,
                    None,
                    None,
                    next_binding.ledger_binding_sha256,
                    prior_head["head_sha256"],
                    _value_sha256(head_base),
                ),
            )
            self._append_event_locked(
                connection,
                event_type="CONTINUATION_REKEYED",
                entity_kind="CONTINUATION",
                entity_id=next_binding.operation_id,
                entity_sha256=rotation_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                "SELECT * FROM source_read_continuation_rebindings WHERE rotation_id=?",
                (next_binding.operation_id,),
            ).fetchone()
            return self._continuation_rotation_from_row(row, replayed=False)

    def retain_uncertain(
        self,
        operation_id: str,
        reservation: SensorReadReservation,
        *,
        idempotency_sha256: str,
        occurred_at_utc: str,
        continuation_binding: SourceReadContinuationBinding | None = None,
    ) -> SourceReadLedgerMutation:
        candidate = (
            reservation.reservation_sha256
            if type(reservation) is SensorReadReservation
            else None
        )
        self._precheck_outcome_replay(
            operation_id,
            "READ_UNCERTAIN",
            idempotency_sha256,
            factory_reservation_sha256=candidate,
            continuation_binding_sha256=_candidate_continuation_sha256(
                continuation_binding
            ),
        )
        return self._append_outcome(
            operation_id,
            outcome_type="READ_UNCERTAIN",
            idempotency_sha256=idempotency_sha256,
            occurred_at_utc=occurred_at_utc,
            reservation=reservation,
            continuation_binding=continuation_binding,
        )

    def accept_page(
        self,
        operation_id: str,
        *,
        page: SensorPageEvidence,
        observations: tuple[PrivacySafeObservation, ...],
        checkpoint: SensorCheckpoint,
        idempotency_sha256: str,
        occurred_at_utc: str,
        continuation_binding: SourceReadContinuationBinding | None = None,
    ) -> SourceReadLedgerMutation:
        self._precheck_outcome_replay(
            operation_id,
            "PAGE_ACCEPTED",
            idempotency_sha256,
            page_evidence_sha256=(
                page.evidence_sha256 if type(page) is SensorPageEvidence else None
            ),
            checkpoint_after_sha256=(
                checkpoint.checkpoint_sha256
                if type(checkpoint) is SensorCheckpoint
                else None
            ),
            observation_sha256s=(
                tuple(item.observation_sha256 for item in observations)
                if type(observations) is tuple
                and all(type(item) is PrivacySafeObservation for item in observations)
                else None
            ),
            continuation_binding_sha256=_candidate_continuation_sha256(
                continuation_binding
            ),
        )
        return self._append_outcome(
            operation_id,
            outcome_type="PAGE_ACCEPTED",
            idempotency_sha256=idempotency_sha256,
            occurred_at_utc=occurred_at_utc,
            page=page,
            observations=observations,
            checkpoint=checkpoint,
            continuation_binding=continuation_binding,
        )

    def reconcile(
        self,
        operation_id: str,
        receipt: SensorReconciliationReceipt,
        *,
        idempotency_sha256: str,
        continuation_binding: SourceReadContinuationBinding | None = None,
    ) -> SourceReadLedgerMutation:
        if type(receipt) is not SensorReconciliationReceipt:
            raise SourceReadLedgerValidationError(
                "reconciliation must be an exact sensor receipt"
            )
        self._precheck_outcome_replay(
            operation_id,
            "READ_RECONCILED",
            idempotency_sha256,
            reconciliation_sha256=receipt.reconciliation_sha256,
            continuation_binding_sha256=_candidate_continuation_sha256(
                continuation_binding
            ),
        )
        reconciliation_material = {
            "request_sha256": _sha256(receipt.request_sha256, "reconciliation.request"),
            "batch_result_sha256": _sha256(
                receipt.batch_result_sha256, "reconciliation.batch_result"
            ),
            "binding_id": _binding(receipt.binding_id),
            "reservation_sha256": _sha256(
                receipt.reservation_sha256, "reconciliation.reservation"
            ),
            "page_evidence_sha256": receipt.page.evidence_sha256,
            "observation_sha256s": [
                item.observation_sha256 for item in receipt.observations
            ],
            "checkpoint_before_sha256": _sha256(
                receipt.checkpoint_before_sha256,
                "reconciliation.checkpoint_before",
            ),
            "checkpoint_sha256": receipt.checkpoint.checkpoint_sha256,
            "released_reserved_items": _bounded_int(
                receipt.released_reserved_items,
                "reconciliation.released_reserved_items",
            ),
            "released_reserved_bytes": _bounded_int(
                receipt.released_reserved_bytes,
                "reconciliation.released_reserved_bytes",
            ),
            "committed_items": _bounded_int(
                receipt.committed_items, "reconciliation.committed_items"
            ),
            "committed_bytes": _bounded_int(
                receipt.committed_bytes, "reconciliation.committed_bytes"
            ),
            "contact_operations": receipt.contact_operations,
            "write_operations": receipt.write_operations,
            "spend_operations": receipt.spend_operations,
            "spend_minor": receipt.spend_minor,
            "reconciled_at_utc": _utc(
                receipt.reconciled_at_utc, "reconciliation.reconciled_at_utc"
            ),
        }
        expected = _value_sha256(reconciliation_material)
        if receipt.reconciliation_sha256 != expected or any(
            value != 0
            for value in (
                receipt.contact_operations,
                receipt.write_operations,
                receipt.spend_operations,
                receipt.spend_minor,
            )
        ):
            raise SourceReadLedgerValidationError(
                "reconciliation seal or zero-effect receipt differs"
            )
        return self._append_outcome(
            operation_id,
            outcome_type="READ_RECONCILED",
            idempotency_sha256=idempotency_sha256,
            occurred_at_utc=receipt.reconciled_at_utc,
            page=receipt.page,
            observations=receipt.observations,
            checkpoint=receipt.checkpoint,
            reconciliation=receipt,
            reconciliation_material=reconciliation_material,
            continuation_binding=continuation_binding,
        )

    def _precheck_outcome_replay(
        self,
        operation_id: str,
        outcome_type: str,
        idempotency_sha256: str,
        *,
        factory_reservation_sha256: str | None = None,
        page_evidence_sha256: str | None = None,
        checkpoint_after_sha256: str | None = None,
        observation_sha256s: tuple[str, ...] | None = None,
        reconciliation_sha256: str | None = None,
        continuation_binding_sha256: str | None = None,
    ) -> None:
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is None:
                return
            kind, row = replay
            if (
                kind != "OUTCOME"
                or row["operation_id"] != operation_id
                or row["outcome_type"] != outcome_type
            ):
                raise SourceReadLedgerIdempotencyConflict(
                    "outcome idempotency digest is already bound"
                )
            stored_observations = (
                None
                if row["observation_sha256s_json"] is None
                else tuple(json.loads(row["observation_sha256s_json"]))
            )
            differs = (
                (
                    outcome_type == "READ_UNCERTAIN"
                    and factory_reservation_sha256 != row["factory_reservation_sha256"]
                )
                or (
                    outcome_type == "PAGE_ACCEPTED"
                    and (
                        page_evidence_sha256 != row["page_evidence_sha256"]
                        or checkpoint_after_sha256 != row["checkpoint_after_sha256"]
                        or observation_sha256s != stored_observations
                    )
                )
                or (
                    outcome_type == "READ_RECONCILED"
                    and reconciliation_sha256 != row["reconciliation_sha256"]
                )
                or continuation_binding_sha256 != row["continuation_binding_sha256"]
            )
            if differs:
                raise SourceReadLedgerIdempotencyConflict(
                    "outcome idempotency replay material differs"
                )

    def _append_outcome(
        self,
        operation_id: str,
        *,
        outcome_type: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
        reservation: SensorReadReservation | None = None,
        page: SensorPageEvidence | None = None,
        observations: tuple[PrivacySafeObservation, ...] = (),
        checkpoint: SensorCheckpoint | None = None,
        reconciliation: SensorReconciliationReceipt | None = None,
        reconciliation_material: Mapping[str, Any] | None = None,
        continuation_binding: SourceReadContinuationBinding | None = None,
    ) -> SourceReadLedgerMutation:
        if type(operation_id) is not str or not operation_id.startswith(
            "source-read-op-"
        ):
            raise SourceReadLedgerValidationError("operation identity is invalid")
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        factory_json = page_json = attestation_json = observation_json = None
        checkpoint_json = reconciliation_json = None
        continuation_json = None
        factory_sha = page_sha = attestation_sha = checkpoint_sha = (
            reconciliation_sha
        ) = None
        continuation_sha = None
        continuation_lineage = None
        continuation_previous_head = None
        continuation_head_sequence = None
        committed_items = committed_bytes = 0
        with self._write() as connection:
            operation = connection.execute(
                "SELECT * FROM source_read_operations WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if operation is None:
                raise SourceReadLedgerStateConflict("read reservation is absent")
            replay = self._find_idempotency_locked(connection, idempotency)
            replay_row: sqlite3.Row | None = None
            if replay is not None:
                kind, row = replay
                if (
                    kind != "OUTCOME"
                    or row["operation_id"] != operation_id
                    or row["outcome_type"] != outcome_type
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "outcome idempotency digest is already bound"
                    )
                replay_row = row
            history = connection.execute(
                "SELECT * FROM source_read_outcomes WHERE operation_id=? ORDER BY sequence",
                (operation_id,),
            ).fetchall()
            quarantine = connection.execute(
                "SELECT * FROM source_read_reconciliation_quarantines WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            dispatch_intent = connection.execute(
                "SELECT * FROM source_read_dispatch_intents WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if dispatch_intent is None:
                raise SourceReadLedgerStateConflict(
                    "operation outcome requires a durable dispatch intent"
                )
            operation_writer_epoch_root = str(operation["writer_epoch_root_sha256"])
            if (
                str(dispatch_intent["writer_epoch_root_sha256"])
                != operation_writer_epoch_root
            ):
                raise SourceReadLedgerIntegrityError(
                    "dispatch intent writer epoch differs from its operation"
                )
            if (
                replay_row is None
                and self._runtime_vault_writer_epoch_root_locked(connection)
                != operation_writer_epoch_root
            ):
                raise SourceReadLedgerStateConflict(
                    "operation writer epoch is no longer current"
                )
            kinds = [str(item["outcome_type"]) for item in history]
            if replay_row is None:
                if quarantine is not None and outcome_type != "READ_RECONCILED":
                    raise SourceReadLedgerStateConflict(
                        "quarantined operation remains reconciliation-only"
                    )
                if outcome_type == "READ_UNCERTAIN" and kinds:
                    raise SourceReadLedgerStateConflict(
                        "operation outcome already exists"
                    )
                if outcome_type == "PAGE_ACCEPTED" and kinds:
                    raise SourceReadLedgerStateConflict(
                        "uncertain/final operation requires reconciliation"
                    )
                if outcome_type == "READ_RECONCILED" and any(
                    item in kinds for item in ("PAGE_ACCEPTED", "READ_RECONCILED")
                ):
                    raise SourceReadLedgerStateConflict("operation is already final")
            checkpoint_before = _stored_json(
                operation["checkpoint_before_json"], "checkpoint before"
            )
            command_material = _stored_json(
                operation["command_material_json"], "command material"
            )
            if outcome_type == "READ_UNCERTAIN":
                if reservation is None:
                    raise SourceReadLedgerValidationError(
                        "uncertain outcome requires factory reservation"
                    )
                factory_material = _factory_reservation_material(reservation)
                if (
                    factory_material["binding_id"] != operation["binding_id"]
                    or factory_material["registry_snapshot_sha256"]
                    != _stored_json(
                        operation["reservation_material_json"],
                        "reservation material",
                    )["registry_snapshot_sha256"]
                    or factory_material["capability_snapshot_sha256"]
                    != operation["capability_snapshot_sha256"]
                    or factory_material["page_sequence"] != operation["page_sequence"]
                    or factory_material["cursor_before_sha256"]
                    != checkpoint_before["expected_cursor_sha256"]
                    or factory_material["command_sha256"] != operation["command_sha256"]
                    or factory_material["operation_key_sha256"]
                    != command_material["operation_key_sha256"]
                    or factory_material["idempotency_key_sha256"]
                    != command_material["idempotency_key_sha256"]
                    or factory_material["receipt_key_sha256"]
                    != command_material["receipt_key_sha256"]
                    or factory_material["max_items"] != operation["held_items"]
                    or factory_material["max_bytes"] != operation["held_bytes"]
                    or factory_material["max_cost_minor"] != 0
                ):
                    raise SourceReadLedgerValidationError(
                        "factory reservation does not match durable custody"
                    )
                factory_sha = factory_material["reservation_sha256"]
                factory_json = _json_material(
                    factory_material, "factory reservation material"
                )
            else:
                if page is None or checkpoint is None:
                    raise SourceReadLedgerValidationError(
                        "final outcome requires page and checkpoint"
                    )
                page_material, attestation_material = _page_material(page)
                observation_hashes = _observation_hashes(observations, page)
                checkpoint_material = _checkpoint_material(checkpoint)
                expected_after = _expected_checkpoint_after(
                    checkpoint_before, page, observation_hashes
                )
                if (
                    page.binding_id != operation["binding_id"]
                    or page.capability_snapshot_sha256
                    != operation["capability_snapshot_sha256"]
                    or page.command_sha256 != operation["command_sha256"]
                    or page.page_sequence != operation["page_sequence"]
                    or page.cursor_before_sha256
                    != checkpoint_before["expected_cursor_sha256"]
                    or page.record_count > operation["held_items"]
                    or page.byte_count > operation["held_bytes"]
                    or _utc_datetime(page.received_at_utc, "page received_at_utc")
                    > _utc_datetime(occurred, "outcome occurred_at_utc")
                    or any(
                        checkpoint_material[key] != expected_after[key]
                        for key in expected_after
                    )
                ):
                    raise SourceReadLedgerValidationError(
                        "accepted page/checkpoint does not match durable reservation"
                    )
                page_sha = page.evidence_sha256
                attestation_sha = page.source_receipt_attestation.attestation_sha256
                checkpoint_sha = checkpoint.checkpoint_sha256
                page_json = _json_material(page_material, "page material")
                attestation_json = _json_material(
                    attestation_material, "receipt attestation material"
                )
                observation_json = _canonical_json(list(observation_hashes))
                checkpoint_json = _json_material(
                    checkpoint_material, "checkpoint after material"
                )
                committed_items = page.record_count
                committed_bytes = page.byte_count
                if outcome_type == "READ_RECONCILED":
                    if reconciliation is None or reconciliation_material is None:
                        raise SourceReadLedgerValidationError(
                            "reconciled outcome requires exact receipt"
                        )
                    uncertain = next(
                        (
                            item
                            for item in history
                            if item["outcome_type"] == "READ_UNCERTAIN"
                        ),
                        None,
                    )
                    stored_factory_sha = (
                        None
                        if uncertain is None
                        else uncertain["factory_reservation_sha256"]
                    )
                    if (
                        reconciliation.request_sha256
                        != _stored_json(
                            connection.execute(
                                "SELECT request_material_json FROM source_read_batches WHERE batch_id=?",
                                (operation["batch_id"],),
                            ).fetchone()[0],
                            "request material",
                        )["execution_request_sha256"]
                        or reconciliation.binding_id != operation["binding_id"]
                        or reconciliation.checkpoint_before_sha256
                        != operation["checkpoint_before_sha256"]
                        or reconciliation.released_reserved_items
                        != operation["held_items"]
                        or reconciliation.released_reserved_bytes
                        != operation["held_bytes"]
                        or reconciliation.committed_items != committed_items
                        or reconciliation.committed_bytes != committed_bytes
                        or (
                            stored_factory_sha is not None
                            and reconciliation.reservation_sha256 != stored_factory_sha
                        )
                    ):
                        raise SourceReadLedgerValidationError(
                            "reconciliation does not release exact durable custody"
                        )
                    factory_sha = reconciliation.reservation_sha256
                    reconciliation_sha = reconciliation.reconciliation_sha256
                    reconciliation_payload = {
                        **reconciliation_material,
                        "reconciliation_sha256": reconciliation_sha,
                    }
                    reconciliation_json = _json_material(
                        reconciliation_payload, "reconciliation material"
                    )
            if continuation_binding is not None:
                self._assert_continuation_writer_epoch_locked(
                    connection, continuation_binding
                )
                continuation_material = _continuation_binding_material(
                    continuation_binding
                )
                expected_checkpoint_sha = (
                    str(operation["checkpoint_before_sha256"])
                    if outcome_type == "READ_UNCERTAIN"
                    else checkpoint_sha
                )
                expected_page_sha = (
                    None if outcome_type == "READ_UNCERTAIN" else page_sha
                )
                if (
                    continuation_binding.operation_id != operation_id
                    or continuation_binding.expected_outcome != outcome_type
                    or continuation_binding.checkpoint_after_sha256
                    != expected_checkpoint_sha
                    or continuation_binding.page_evidence_sha256 != expected_page_sha
                ):
                    raise SourceReadLedgerValidationError(
                        "continuation binding does not match the exact outcome"
                    )
                continuation_sha = continuation_binding.ledger_binding_sha256
                continuation_json = _json_material(
                    continuation_material, "continuation binding"
                )
                if replay_row is None:
                    continuation_lineage = _continuation_lineage_sha256(
                        continuation_binding
                    )
                    prior_head = connection.execute(
                        """SELECT * FROM source_read_continuation_heads
                           WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                        (continuation_lineage,),
                    ).fetchone()
                    if prior_head is None:
                        if (
                            continuation_binding.previous_active_version != 0
                            or continuation_binding.previous_active_envelope_sha256
                            is not None
                        ):
                            raise SourceReadLedgerStateConflict(
                                "continuation lineage must begin from exact genesis"
                            )
                        continuation_previous_head = ZERO_SHA256
                    else:
                        prior_binding = self._continuation_binding_for_head_locked(
                            connection, prior_head
                        )
                        if (
                            continuation_binding.generation
                            <= int(prior_head["generation"])
                            or continuation_binding.previous_active_version
                            != prior_binding.previous_active_version + 1
                            or continuation_binding.previous_active_envelope_sha256
                            != prior_binding.envelope_sha256
                        ):
                            raise SourceReadLedgerStateConflict(
                                "continuation binding is not an exact latest-head advance"
                            )
                        continuation_previous_head = str(prior_head["head_sha256"])
                    continuation_head_sequence = int(
                        connection.execute(
                            "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_continuation_heads"
                        ).fetchone()[0]
                    )
            outcome_sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_outcomes"
                ).fetchone()[0]
            )
            provisional = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "outcome_id": "",
                "operation_id": operation_id,
                "idempotency_sha256": idempotency,
                "writer_epoch_root_sha256": operation_writer_epoch_root,
                "outcome_type": outcome_type,
                "factory_reservation_sha256": factory_sha,
                "page_evidence_sha256": page_sha,
                "receipt_attestation_sha256": attestation_sha,
                "checkpoint_after_sha256": checkpoint_sha,
                "reconciliation_sha256": reconciliation_sha,
                "continuation_binding_sha256": continuation_sha,
                "factory_reservation_json_sha256": (
                    None if factory_json is None else _hash_text(factory_json)
                ),
                "page_material_json_sha256": (
                    None if page_json is None else _hash_text(page_json)
                ),
                "receipt_attestation_json_sha256": (
                    None if attestation_json is None else _hash_text(attestation_json)
                ),
                "observation_sha256s_json_sha256": (
                    None if observation_json is None else _hash_text(observation_json)
                ),
                "checkpoint_after_json_sha256": (
                    None if checkpoint_json is None else _hash_text(checkpoint_json)
                ),
                "reconciliation_material_json_sha256": (
                    None
                    if reconciliation_json is None
                    else _hash_text(reconciliation_json)
                ),
                "continuation_binding_json_sha256": (
                    None if continuation_json is None else _hash_text(continuation_json)
                ),
                "committed_items": committed_items,
                "committed_bytes": committed_bytes,
                "committed_cost_minor": 0,
                "occurred_at_utc": occurred,
            }
            payload_sha = _value_sha256(provisional)
            outcome_id = (
                "source-read-outcome-"
                + _value_sha256(
                    {
                        "operation_id": operation_id,
                        "outcome_type": outcome_type,
                        "payload_sha256": payload_sha,
                    }
                )[:32]
            )
            material = {**provisional, "outcome_id": outcome_id}
            outcome_sha = _value_sha256(material)
            if replay_row is not None:
                if (
                    replay_row["outcome_id"] != outcome_id
                    or replay_row["outcome_sha256"] != outcome_sha
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "outcome idempotency replay material differs"
                    )
                event = self._entity_event_locked(
                    connection, "OUTCOME", str(replay_row["outcome_id"])
                )
                return self._event_to_mutation(
                    str(replay_row["outcome_id"]),
                    str(replay_row["outcome_sha256"]),
                    event,
                    replayed=True,
                )
            connection.execute(
                """INSERT INTO source_read_outcomes(
                       sequence,outcome_id,operation_id,idempotency_sha256,
                       writer_epoch_root_sha256,outcome_type,
                       factory_reservation_sha256,factory_reservation_json,
                       page_evidence_sha256,page_material_json,
                       receipt_attestation_sha256,receipt_attestation_json,
                       observation_sha256s_json,checkpoint_after_sha256,
                       checkpoint_after_json,reconciliation_sha256,
                       reconciliation_material_json,continuation_binding_sha256,
                       continuation_binding_json,committed_items,committed_bytes,
                       committed_cost_minor,occurred_at_utc,outcome_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    outcome_sequence,
                    outcome_id,
                    operation_id,
                    idempotency,
                    operation_writer_epoch_root,
                    outcome_type,
                    factory_sha,
                    factory_json,
                    page_sha,
                    page_json,
                    attestation_sha,
                    attestation_json,
                    observation_json,
                    checkpoint_sha,
                    checkpoint_json,
                    reconciliation_sha,
                    reconciliation_json,
                    continuation_sha,
                    continuation_json,
                    committed_items,
                    committed_bytes,
                    0,
                    occurred,
                    outcome_sha,
                ),
            )
            if continuation_binding is not None:
                if (
                    continuation_lineage is None
                    or continuation_previous_head is None
                    or continuation_head_sequence is None
                ):
                    raise SourceReadLedgerIntegrityError(
                        "continuation latest-head material is incomplete"
                    )
                head_base: dict[str, object] = {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "SOURCE_READ_CONTINUATION_HEAD",
                    "sequence": continuation_head_sequence,
                    "lineage_sha256": continuation_lineage,
                    "generation": continuation_binding.generation,
                    "operation_id": operation_id,
                    "outcome_id": outcome_id,
                    "rotation_id": None,
                    "migration_id": None,
                    "repair_id": None,
                    "ledger_binding_sha256": continuation_binding.ledger_binding_sha256,
                    "previous_head_sha256": continuation_previous_head,
                }
                connection.execute(
                    """INSERT INTO source_read_continuation_heads(
                           sequence,lineage_sha256,generation,operation_id,
                           outcome_id,rotation_id,migration_id,repair_id,
                           ledger_binding_sha256,previous_head_sha256,head_sha256)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        continuation_head_sequence,
                        continuation_lineage,
                        continuation_binding.generation,
                        operation_id,
                        outcome_id,
                        None,
                        None,
                        None,
                        continuation_binding.ledger_binding_sha256,
                        continuation_previous_head,
                        _value_sha256(head_base),
                    ),
                )
            event_id, event_sha = self._append_event_locked(
                connection,
                event_type=outcome_type,
                entity_kind="OUTCOME",
                entity_id=outcome_id,
                entity_sha256=outcome_sha,
                occurred_at_utc=occurred,
            )
            return SourceReadLedgerMutation(
                outcome_id, outcome_sha, event_id, event_sha, False
            )

    def _operation_custody_locked(
        self,
        connection: sqlite3.Connection,
        row: sqlite3.Row,
        *,
        dispatch_grant: DispatchReservationGrant | None = None,
    ) -> ReadOperationCustody:
        batch = connection.execute(
            "SELECT * FROM source_read_batches WHERE batch_id=?", (row["batch_id"],)
        ).fetchone()
        outcomes = connection.execute(
            "SELECT * FROM source_read_outcomes WHERE operation_id=? ORDER BY sequence",
            (row["operation_id"],),
        ).fetchall()
        intent = connection.execute(
            "SELECT * FROM source_read_dispatch_intents WHERE operation_id=?",
            (row["operation_id"],),
        ).fetchone()
        quarantine = connection.execute(
            "SELECT * FROM source_read_reconciliation_quarantines WHERE operation_id=?",
            (row["operation_id"],),
        ).fetchone()
        final = self._current_outcome(outcomes)
        uncertain = next(
            (item for item in outcomes if item["outcome_type"] == "READ_UNCERTAIN"),
            None,
        )
        if final is not None:
            state = (
                ReadCustodyState.COMMITTED
                if final["outcome_type"] == "PAGE_ACCEPTED"
                else ReadCustodyState.RECONCILED
            )
        elif uncertain is not None:
            state = (
                ReadCustodyState.QUARANTINED
                if quarantine is not None
                else ReadCustodyState.UNCERTAIN
            )
        elif quarantine is not None:
            state = ReadCustodyState.QUARANTINED
        elif intent is not None:
            state = ReadCustodyState.DISPATCH_INTENT
        else:
            state = ReadCustodyState.RESERVED
        registry_material = _stored_json(
            batch["registry_material_json"], "registry material"
        )
        capability_material = next(
            item
            for item in registry_material["capabilities"]
            if item["capability_snapshot_sha256"] == row["capability_snapshot_sha256"]
        )
        factory_sha = (
            str(uncertain["factory_reservation_sha256"])
            if uncertain is not None
            else (
                None
                if final is None or final["factory_reservation_sha256"] is None
                else str(final["factory_reservation_sha256"])
            )
        )
        return ReadOperationCustody(
            operation_id=str(row["operation_id"]),
            batch_id=str(row["batch_id"]),
            request_sha256=str(batch["request_sha256"]),
            registry_snapshot_sha256=str(batch["registry_snapshot_sha256"]),
            quota_epoch_sha256=str(batch["quota_epoch_sha256"]),
            binding_id=str(row["binding_id"]),
            provider_id=str(row["provider_id"]),
            account_id=str(capability_material["account_id"]),
            capability_snapshot_sha256=str(row["capability_snapshot_sha256"]),
            page_sequence=int(row["page_sequence"]),
            checkpoint_before_sha256=str(row["checkpoint_before_sha256"]),
            stream_scope_sha256=str(row["stream_scope_sha256"]),
            position_sha256=str(row["position_sha256"]),
            custody_reservation_sha256=str(row["custody_reservation_sha256"]),
            command_sha256=str(row["command_sha256"]),
            held_items=int(row["held_items"]),
            held_bytes=int(row["held_bytes"]),
            held_cost_minor=int(row["held_cost_minor"]),
            state=state,
            factory_reservation_sha256=factory_sha,
            page_evidence_sha256=(
                None if final is None else str(final["page_evidence_sha256"])
            ),
            checkpoint_after_sha256=(
                None if final is None else str(final["checkpoint_after_sha256"])
            ),
            reconciliation_quarantine_sha256=(
                None if quarantine is None else str(quarantine["disposition_sha256"])
            ),
            reconciliation_quarantine_code=(
                None
                if quarantine is None
                else ReconciliationQuarantineCode(str(quarantine["reason_code"]))
            ),
            dispatch_grant=dispatch_grant,
        )

    def quota_snapshot(
        self,
        registry_snapshot_sha256: str,
        request_sha256: str | None = None,
    ) -> QuotaCustodySnapshot:
        registry_hash = _sha256(registry_snapshot_sha256, "registry_snapshot_sha256")
        request_hash = (
            None
            if request_sha256 is None
            else _sha256(request_sha256, "request_sha256")
        )
        with self._read() as connection:
            return self._quota_snapshot_locked(connection, registry_hash, request_hash)

    def _quota_snapshot_locked(
        self,
        connection: sqlite3.Connection,
        registry_snapshot_sha256: str,
        request_sha256: str | None,
    ) -> QuotaCustodySnapshot:
        params: list[object] = [registry_snapshot_sha256]
        if (
            connection.execute(
                "SELECT 1 FROM source_read_batches WHERE registry_snapshot_sha256=? LIMIT 1",
                (registry_snapshot_sha256,),
            ).fetchone()
            is None
        ):
            raise SourceReadLedgerStateConflict(
                "quota snapshot registry context is not prepared"
            )
        sql = """SELECT o.* FROM source_read_operations o
                 JOIN source_read_batches b ON b.batch_id=o.batch_id"""
        if request_sha256 is not None:
            sql += " WHERE b.registry_snapshot_sha256=? AND b.request_sha256=?"
            params.append(request_sha256)
        else:
            # The active epoch is either genesis or the last exact governed
            # transition.  Transitions cannot occur while any prior hold is
            # pending, so no unresolved custody can be hidden here.
            sql += """ WHERE b.quota_epoch_sha256=COALESCE(
                         (SELECT next_quota_epoch_sha256
                          FROM source_read_quota_epoch_transitions
                          ORDER BY sequence DESC LIMIT 1),
                         (SELECT quota_epoch_sha256 FROM source_read_batches
                          ORDER BY sequence LIMIT 1))"""
            params = []
        operations = connection.execute(sql, params).fetchall()
        pending = committed = held_items = held_bytes = committed_items = (
            committed_bytes
        ) = 0
        for operation in operations:
            outcomes = connection.execute(
                "SELECT * FROM source_read_outcomes WHERE operation_id=? ORDER BY sequence",
                (operation["operation_id"],),
            ).fetchall()
            final = self._current_outcome(outcomes)
            if final is None:
                pending += 1
                held_items += int(operation["held_items"])
                held_bytes += int(operation["held_bytes"])
            else:
                committed += 1
                committed_items += int(final["committed_items"])
                committed_bytes += int(final["committed_bytes"])
        material = {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "record_kind": "QUOTA_CUSTODY_SNAPSHOT",
            "registry_snapshot_sha256": registry_snapshot_sha256,
            "request_sha256": request_sha256,
            "operation_count": len(operations),
            "pending_operations": pending,
            "committed_operations": committed,
            "held_items": held_items,
            "held_bytes": held_bytes,
            "held_cost_minor": 0,
            "committed_items": committed_items,
            "committed_bytes": committed_bytes,
            "committed_cost_minor": 0,
        }
        return QuotaCustodySnapshot(
            registry_snapshot_sha256,
            request_sha256,
            len(operations),
            pending,
            committed,
            held_items,
            held_bytes,
            0,
            committed_items,
            committed_bytes,
            0,
            _value_sha256(material),
        )

    def resume(self, request: SensorBatchRequest) -> SourceReadResume:
        if type(request) is not SensorBatchRequest:
            raise SourceReadLedgerValidationError("resume request must be exact")
        plans = {item.binding_id: item for item in request.plans}
        with self._read() as connection:
            batch = connection.execute(
                "SELECT * FROM source_read_batches WHERE request_sha256=?",
                (request.request_sha256,),
            ).fetchone()
            if batch is None:
                raise SourceReadLedgerStateConflict("prepared batch is absent")
            stored_request = _stored_json(
                batch["request_material_json"], "request material"
            )
            if stored_request["request_sha256"] != request.request_sha256:
                raise SourceReadLedgerIntegrityError("stored request seal differs")
            operations = connection.execute(
                "SELECT * FROM source_read_operations WHERE batch_id=? ORDER BY sequence",
                (batch["batch_id"],),
            ).fetchall()
            custody = [
                self._operation_custody_locked(connection, row) for row in operations
            ]
            latest: dict[str, Mapping[str, Any]] = {
                item["binding_id"]: item
                for item in stored_request["effective_checkpoints"]
            }
            pending: list[PendingReadCustody] = []
            for row, operation in zip(operations, custody, strict=True):
                if operation.state in {
                    ReadCustodyState.RESERVED,
                    ReadCustodyState.DISPATCH_INTENT,
                    ReadCustodyState.UNCERTAIN,
                    ReadCustodyState.QUARANTINED,
                }:
                    pending.append(PendingReadCustody(operation))
                    latest[operation.binding_id] = _stored_json(
                        row["checkpoint_before_json"], "checkpoint before"
                    )
                else:
                    outcome = connection.execute(
                        """SELECT * FROM source_read_outcomes
                           WHERE operation_id=? AND outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')""",
                        (operation.operation_id,),
                    ).fetchone()
                    latest[operation.binding_id] = _stored_json(
                        outcome["checkpoint_after_json"], "checkpoint after"
                    )
            checkpoints: list[SensorCheckpoint] = []
            for binding_id, material in sorted(latest.items()):
                plan = plans.get(binding_id)
                if (
                    plan is None
                    or _hash_text(plan.stream_id) != material["stream_id_sha256"]
                ):
                    raise SourceReadLedgerValidationError(
                        "resume request cannot rehydrate exact checkpoint"
                    )
                checkpoint = SensorCheckpoint(
                    binding_id=material["binding_id"],
                    provider_id=material["provider_id"],
                    dependency_family=material["dependency_family"],
                    registry_snapshot_sha256=material["registry_snapshot_sha256"],
                    capability_snapshot_sha256=material["capability_snapshot_sha256"],
                    stream_id=plan.stream_id,
                    next_page_sequence=material["next_page_sequence"],
                    expected_cursor_sha256=material["expected_cursor_sha256"],
                    terminal=material["terminal"],
                    last_page_evidence_sha256=material["last_page_evidence_sha256"],
                    history_sha256=material["history_sha256"],
                )
                if checkpoint.checkpoint_sha256 != material["checkpoint_sha256"]:
                    raise SourceReadLedgerIntegrityError(
                        "rehydrated checkpoint seal differs"
                    )
                checkpoints.append(checkpoint)
            quota = self._quota_snapshot_locked(
                connection,
                str(batch["registry_snapshot_sha256"]),
                str(batch["request_sha256"]),
            )
            resume_material = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_RESUME",
                "batch_id": batch["batch_id"],
                "request_sha256": batch["request_sha256"],
                "checkpoint_sha256s": [item.checkpoint_sha256 for item in checkpoints],
                "pending_operation_ids": [
                    item.operation.operation_id for item in pending
                ],
                "quota_snapshot_sha256": quota.snapshot_sha256,
            }
            return SourceReadResume(
                str(batch["batch_id"]),
                str(batch["request_sha256"]),
                tuple(checkpoints),
                tuple(pending),
                quota,
                _value_sha256(resume_material),
            )

    def verify(self) -> SourceReadLedgerVerification:
        with self._read() as connection:
            return self._verify_locked(connection)

    def operation_recovery_proof(
        self,
        registry: PlatformRegistrySnapshotBoundary,
        request: SensorBatchRequest,
        *,
        plan: SensorBindingPlan,
        checkpoint: SensorCheckpoint,
        command: SourcePageCommand,
        operation_id: str,
    ) -> SourceReadOperationRecoveryProof:
        """Mint proof for one exact anchored, unfinished dispatch position.

        No caller-supplied digest is treated as authority.  All request, plan,
        checkpoint, command, custody, intent, and anchor commitments are
        independently re-derived from canonical factory values and compared
        with the verified append-only store before a process-local proof exists.
        """

        if (
            type(operation_id) is not str
            or _SOURCE_OPERATION_ID.fullmatch(operation_id) is None
        ):
            raise SourceReadLedgerValidationError("operation identity is invalid")
        if type(plan) is not SensorBindingPlan:
            raise SourceReadLedgerValidationError("recovery plan must be exact")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            self._assert_no_active_key_lifecycle_locked(connection)
            if (
                verification.external_anchor_status
                != "ANCHORED_MONOTONIC_LOCAL_CUSTODY"
                or verification.external_anchor_generation < 1
                or verification.external_anchor_receipt_sha256 == ZERO_SHA256
            ):
                raise SourceReadLedgerStateConflict(
                    "operation recovery proof requires an exact monotonic anchor"
                )
            batch = connection.execute(
                "SELECT * FROM source_read_batches WHERE request_sha256=?",
                (
                    request.request_sha256
                    if type(request) is SensorBatchRequest
                    else ZERO_SHA256,
                ),
            ).fetchone()
            if batch is None:
                raise SourceReadLedgerStateConflict(
                    "operation recovery request is not durably prepared"
                )
            registry_material, request_material, plans = _request_and_registry_material(
                registry,
                request,
                quota_epoch_sha256=str(batch["quota_epoch_sha256"]),
            )
            exact_plan = plans.get(plan.binding_id)
            if exact_plan != plan:
                raise SourceReadLedgerValidationError(
                    "operation recovery plan is not exact"
                )
            _assert_checkpoint_plan(checkpoint, plan, request.registry_snapshot_sha256)
            checkpoint_material = _checkpoint_material(checkpoint)
            command_material = _command_material(
                command,
                registry=registry,
                request=request,
                plan=plan,
                checkpoint=checkpoint,
            )
            row = connection.execute(
                "SELECT * FROM source_read_operations WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            intent = connection.execute(
                "SELECT 1 FROM source_read_dispatch_intents WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if row is None or intent is None or row["batch_id"] != batch["batch_id"]:
                raise SourceReadLedgerStateConflict(
                    "exact dispatch-intent operation is absent"
                )
            stored_registry = _stored_json(
                batch["registry_material_json"], "operation recovery registry"
            )
            stored_request = _stored_json(
                batch["request_material_json"], "operation recovery request"
            )
            stored_checkpoint = _stored_json(
                row["checkpoint_before_json"], "operation recovery checkpoint"
            )
            stored_command = _stored_json(
                row["command_material_json"], "operation recovery command"
            )
            if (
                stored_registry != registry_material
                or stored_request != request_material
            ):
                raise SourceReadLedgerStateConflict(
                    "operation recovery registry/request binding differs"
                )
            if (
                row["binding_id"] != plan.binding_id
                or row["provider_id"] != plan.provider_id
                or row["capability_snapshot_sha256"] != plan.capability_snapshot_sha256
                or int(row["page_sequence"]) != checkpoint.next_page_sequence
                or row["checkpoint_before_sha256"] != checkpoint.checkpoint_sha256
                or stored_checkpoint != checkpoint_material
                or row["command_sha256"] != command_material["command_sha256"]
                or stored_command != command_material
            ):
                raise SourceReadLedgerStateConflict(
                    "operation recovery plan/checkpoint/command binding differs"
                )
            operation = self._operation_custody_locked(connection, row)
            self._assert_no_active_stream_incident_locked(
                connection,
                stable_stream_sha256=str(row["stable_stream_sha256"]),
            )
            if operation.state not in {
                ReadCustodyState.DISPATCH_INTENT,
                ReadCustodyState.UNCERTAIN,
                ReadCustodyState.QUARANTINED,
            }:
                raise SourceReadLedgerStateConflict(
                    "operation is not an unfinished recovery-only dispatch"
                )
            current_continuation = self._current_operation_continuation_locked(
                connection, operation_id
            )
            return self._mint_operation_recovery_proof(
                operation=operation,
                registry_projection_sha256=str(batch["registry_projection_sha256"]),
                stream_sha256=str(command_material["stream_id_sha256"]),
                current_continuation_binding_sha256=current_continuation,
                writer_epoch_root_sha256=str(row["writer_epoch_root_sha256"]),
                verification=verification,
            )

    def bind_continuation_migration(
        self,
        current_proof: SourceReadContinuationProof | None,
        old_position: SourceReadContinuationPositionBinding,
        next_binding: SourceReadContinuationBinding,
        prepared_proof: object,
        *,
        old_checkpoint: SensorCheckpoint,
        next_registry: PlatformRegistrySnapshotBoundary,
        next_request: SensorBatchRequest,
        next_plan: SensorBindingPlan,
        next_checkpoint: SensorCheckpoint,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadContinuationMigration:
        """Anchor a rights-neutral revision while preserving terminal state."""

        if (
            current_proof is not None
            and type(current_proof) is not SourceReadContinuationProof
            or current_proof is not None
            and not hasattr(current_proof, "binding")
            or type(old_checkpoint) is not SensorCheckpoint
            or type(next_plan) is not SensorBindingPlan
            or type(next_checkpoint) is not SensorCheckpoint
        ):
            raise SourceReadLedgerStateConflict(
                "continuation migration requires exact ledger/factory inputs"
            )
        old_position_material = _continuation_position_material(old_position)
        next_binding_material = _continuation_binding_material(next_binding)
        current = None if current_proof is None else current_proof.binding
        if (
            old_checkpoint.checkpoint_sha256 != old_position.checkpoint_sha256
            or next_checkpoint.terminal != old_checkpoint.terminal
            or next_binding.expected_outcome != "CONTINUATION_MIGRATED"
            or _MIGRATION_OPERATION_ID.fullmatch(next_binding.operation_id) is None
            or current is not None
            and (
                current.expected_outcome == "READ_UNCERTAIN"
                or current.position_binding_sha256 is None
                or current.position_binding_sha256
                != old_position.position_binding_sha256
            )
        ):
            raise SourceReadLedgerValidationError(
                "continuation migration source/target identity differs"
            )
        governance = _sha256(
            governance_evidence_sha256, "migration governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._continuation_migration_authority is None
            or self.continuation_migration_authority_identity_sha256 is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "continuation migration requires pinned anchor, vault verifier, and SoD authority"
            )

        try:
            projection = next_registry.resolve_exact(
                next_request.registry_snapshot_sha256
            )
        except Exception as error:
            raise SourceReadLedgerValidationError(
                "migration target registry cannot be resolved"
            ) from error
        target_capability_projection = next(
            (
                capability
                for capability in projection.capabilities
                if capability.binding_id == next_plan.binding_id
            ),
            None,
        )
        if target_capability_projection is None or next_plan not in next_request.plans:
            raise SourceReadLedgerValidationError(
                "migration target plan/capability is not factory projected"
            )
        try:
            canonical_checkpoint = migrate_sensor_checkpoint(
                old_checkpoint,
                next_binding_id=next_plan.binding_id,
                next_provider_id=next_plan.provider_id,
                next_dependency_family=next_plan.dependency_family,
                next_registry_snapshot_sha256=next_request.registry_snapshot_sha256,
                next_capability_snapshot_sha256=next_plan.capability_snapshot_sha256,
                migration_governance_evidence_sha256=governance,
                old_position_binding_sha256=old_position.position_binding_sha256,
            )
        except Exception as error:
            raise SourceReadLedgerValidationError(
                "migration target checkpoint cannot be factory derived"
            ) from error
        if canonical_checkpoint != next_checkpoint:
            raise SourceReadLedgerValidationError(
                "migration target checkpoint/history is not canonical"
            )
        next_registry_material, next_request_material, plans = (
            _request_and_registry_material(
                next_registry,
                next_request,
                quota_epoch_sha256=old_position.quota_epoch_sha256,
            )
        )
        if plans.get(next_plan.binding_id) != next_plan:
            raise SourceReadLedgerValidationError(
                "migration target request plan differs"
            )
        target_capability = next(
            item
            for item in next_registry_material["capabilities"]
            if item["capability_snapshot_sha256"]
            == next_plan.capability_snapshot_sha256
        )
        target_plan = next(
            item
            for item in next_request_material["plans"]
            if item["binding_id"] == next_plan.binding_id
        )
        next_position = source_read_continuation_position_binding(
            registry_snapshot_sha256=next_request.registry_snapshot_sha256,
            binding_id=next_plan.binding_id,
            provider_id=next_plan.provider_id,
            account_id=target_capability["account_id"],
            capability_snapshot_sha256=next_plan.capability_snapshot_sha256,
            authorization_sha256=target_capability["authorization_snapshot_sha256"],
            authorization_receipt_sha256=target_capability[
                "authorization_receipt_sha256"
            ],
            quota_epoch_sha256=old_position.quota_epoch_sha256,
            stream_sha256=target_plan["stream_id_sha256"],
            content_binding_sha256=old_position.content_binding_sha256,
            checkpoint_sha256=next_checkpoint.checkpoint_sha256,
            checkpoint_next_page_sequence=next_checkpoint.next_page_sequence,
            checkpoint_expected_cursor_sha256=(next_checkpoint.expected_cursor_sha256),
            checkpoint_terminal=next_checkpoint.terminal,
        )
        next_position_material = _continuation_position_material(next_position)
        next_rights_profile = _migration_rights_profile_sha256(
            next_registry_material,
            next_request_material,
            next_position,
        )
        if (
            next_binding.position_binding_sha256
            != next_position.position_binding_sha256
            or next_binding.checkpoint_after_sha256 != next_position.checkpoint_sha256
            or current is not None
            and (
                _continuation_lineage_sha256(next_binding)
                != _continuation_lineage_sha256(current)
                or next_binding.vault_protocol != current.vault_protocol
                or next_binding.vault_store_identity_sha256
                != current.vault_store_identity_sha256
                or next_binding.slot_sha256 != current.slot_sha256
                or next_binding.generation <= current.generation
                or next_binding.previous_active_version
                != current.previous_active_version + 1
                or next_binding.previous_active_envelope_sha256
                != current.envelope_sha256
                or next_binding.page_evidence_sha256 != current.page_evidence_sha256
            )
        ):
            raise SourceReadLedgerValidationError(
                "migration PREPARED binding is not the exact next lineage head"
            )
        rights_neutral = all(
            getattr(old_position, name) == getattr(next_position, name)
            for name in (
                "provider_id",
                "account_id",
                "authorization_sha256",
                "authorization_receipt_sha256",
                "quota_epoch_sha256",
                "stream_sha256",
                "content_binding_sha256",
                "checkpoint_next_page_sequence",
                "checkpoint_expected_cursor_sha256",
                "checkpoint_terminal",
            )
        )
        if not rights_neutral:
            raise SourceReadLedgerStateConflict(
                "migration cannot transfer authorization, content, quota, or stream rights"
            )
        old_checkpoint_material = _checkpoint_material(old_checkpoint)
        next_checkpoint_material = _checkpoint_material(next_checkpoint)
        next_registry_json = _json_material(
            next_registry_material, "migration target registry"
        )
        next_request_json = _json_material(
            next_request_material, "migration target request"
        )
        next_binding_json = _json_material(
            next_binding_material, "continuation migration binding"
        )
        old_position_json = _json_material(
            old_position_material, "migration old position"
        )
        next_position_json = _json_material(
            next_position_material, "migration next position"
        )
        old_checkpoint_json = _json_material(
            old_checkpoint_material, "migration old checkpoint"
        )
        next_checkpoint_json = _json_material(
            next_checkpoint_material, "migration next checkpoint"
        )
        lineage = _continuation_lineage_sha256(
            next_binding if current is None else current
        )

        def persisted_migration_replay_locked(
            connection: sqlite3.Connection,
        ) -> SourceReadContinuationMigration | None:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is None:
                return None
            kind, row = replay
            if (
                kind != "CONTINUATION_MIGRATION"
                or row["migration_id"] != next_binding.operation_id
                or row["lineage_sha256"] != lineage
                or (
                    current is not None
                    and row["current_ledger_binding_sha256"]
                    != current.ledger_binding_sha256
                )
                or row["next_ledger_binding_sha256"]
                != next_binding.ledger_binding_sha256
                or row["next_binding_json"] != next_binding_json
                or row["old_position_binding_json"] != old_position_json
                or row["next_position_binding_json"] != next_position_json
                or row["old_checkpoint_json"] != old_checkpoint_json
                or row["next_checkpoint_json"] != next_checkpoint_json
                or row["next_registry_projection_sha256"]
                != next_request.registry_projection_sha256
                or row["next_registry_boundary_sha256"] != next_registry.content_sha256
                or row["next_registry_material_json"] != next_registry_json
                or row["next_request_material_json"] != next_request_json
                or row["next_rights_profile_sha256"] != next_rights_profile
                or row["governance_evidence_sha256"] != governance
            ):
                raise SourceReadLedgerIdempotencyConflict(
                    "continuation migration idempotency digest is already bound"
                )
            return self._continuation_migration_from_row(row, replayed=True)

        with self._read() as connection:
            replay = persisted_migration_replay_locked(connection)
            if replay is not None:
                return replay
            if current is None or not self.continuation_proof_is_known(current_proof):
                raise SourceReadLedgerStateConflict(
                    "new continuation migration requires an exact current ledger proof"
                )
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_no_active_stream_incident_locked(
                connection, lineage_sha256=lineage
            )
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (lineage,),
            ).fetchone()
            if latest is None:
                raise SourceReadLedgerStateConflict(
                    "migration source continuation head is absent"
                )
            prior_projection, prior_checkpoint, prior_position = (
                self._continuation_position_context_locked(connection, latest)
            )
            if (
                latest["head_sha256"] != current_proof.continuation_head_sha256
                or latest["ledger_binding_sha256"] != current.ledger_binding_sha256
                or self._continuation_binding_for_head_locked(connection, latest)
                != current
                or prior_checkpoint != old_checkpoint_material
                or prior_position is not None
                and prior_position != old_position
                or not self._position_matches_head_locked(
                    connection, latest, old_position
                )
            ):
                raise SourceReadLedgerStateConflict(
                    "migration source position/head is not canonical"
                )
            old_registry_material = self._registry_material_for_head_locked(
                connection, latest
            )
            old_request_material = self._request_material_for_head_locked(
                connection, latest
            )
            old_rights_profile = _migration_rights_profile_sha256(
                old_registry_material,
                old_request_material,
                old_position,
            )
            old_capability = next(
                (
                    item
                    for item in old_registry_material["capabilities"]
                    if item["capability_snapshot_sha256"]
                    == old_position.capability_snapshot_sha256
                ),
                None,
            )
            old_plan = next(
                (
                    item
                    for item in old_request_material["plans"]
                    if item["binding_id"] == old_position.binding_id
                ),
                None,
            )
            immutable_capability_fields = (
                "provider_id",
                "account_id",
                "dependency_family",
                "capability_id",
                "authorization_snapshot_sha256",
                "authorization_receipt_sha256",
                "source_id_sha256",
                "passport_id_sha256",
                "data_contract_version_sha256",
                "mapping_version_sha256",
                "operation_limit",
                "record_limit",
                "byte_limit",
                "quota_window_seconds",
                "cost_ceiling_minor",
                "stable_provider_key_sha256",
                "stable_account_key_sha256",
                "quota_epoch_sha256",
                "quota_policy_sha256",
            )
            immutable_plan_fields = (
                "provider_id",
                "dependency_family",
                "stream_id_sha256",
                "max_pages",
                "max_items",
                "max_bytes",
                "page_max_items",
                "page_max_bytes",
            )
            unresolved = connection.execute(
                """SELECT 1 FROM source_read_operations op
                   WHERE op.stable_stream_sha256=? AND NOT EXISTS(
                       SELECT 1 FROM source_read_outcomes o
                       WHERE o.operation_id=op.operation_id
                         AND o.outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')
                   ) LIMIT 1""",
                (_stable_stream_sha256(old_position),),
            ).fetchone()
            if (
                old_capability is None
                or old_plan is None
                or prior_projection == next_request.registry_projection_sha256
                or any(
                    old_capability[name] != target_capability[name]
                    for name in immutable_capability_fields
                )
                or any(
                    old_plan[name] != target_plan[name]
                    for name in immutable_plan_fields
                )
                or old_rights_profile != next_rights_profile
                or unresolved is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "migration is not rights-neutral or stream custody is unresolved"
                )

        if not self.verify_latest_continuation_proof(current_proof):
            # A concurrent exact writer may have won after our first read.
            # Re-read only the anchored idempotency record before treating the
            # now-historical source proof as a conflict; do not re-consume the
            # vault or SoD boundary on this crash/concurrency replay path.
            with self._read() as connection:
                replay = persisted_migration_replay_locked(connection)
                if replay is not None:
                    return replay
            raise SourceReadLedgerStateConflict(
                "migration source proof is not the authoritative latest head"
            )
        prepared_authorization = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_prepared_continuation(
                prepared_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=next_binding.vault_store_identity_sha256,
                slot_sha256=next_binding.slot_sha256,
                operation_id=next_binding.operation_id,
                expected_outcome="CONTINUATION_MIGRATED",
                ledger_binding_sha256=next_binding.ledger_binding_sha256,
                position_binding_sha256=next_position.position_binding_sha256,
                generation=next_binding.generation,
                envelope_sha256=next_binding.envelope_sha256,
            ),
            receipt_type=SourceReadVaultPreparedAuthorizationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": next_binding.vault_store_identity_sha256,
                "slot_sha256": next_binding.slot_sha256,
                "operation_id": next_binding.operation_id,
                "expected_outcome": "CONTINUATION_MIGRATED",
                "ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "position_binding_sha256": next_position.position_binding_sha256,
                "generation": next_binding.generation,
                "envelope_sha256": next_binding.envelope_sha256,
            },
        )
        authorization = _validated_migration_authorization(
            self._continuation_migration_authority.authorize_migration(
                store_identity_sha256=self.store_identity_sha256,
                lineage_sha256=lineage,
                current_ledger_binding_sha256=current.ledger_binding_sha256,
                next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
                old_position_binding_sha256=old_position.position_binding_sha256,
                next_position_binding_sha256=next_position.position_binding_sha256,
                old_registry_projection_sha256=prior_projection,
                next_registry_projection_sha256=(
                    next_request.registry_projection_sha256
                ),
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=(
                self.continuation_migration_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            lineage_sha256=lineage,
            current_ledger_binding_sha256=current.ledger_binding_sha256,
            next_ledger_binding_sha256=next_binding.ledger_binding_sha256,
            old_position_binding_sha256=old_position.position_binding_sha256,
            next_position_binding_sha256=next_position.position_binding_sha256,
            old_registry_projection_sha256=prior_projection,
            next_registry_projection_sha256=next_request.registry_projection_sha256,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadContinuationMigrationAuthorizationReceipt.__dataclass_fields__
            },
            "migration governance authorization",
        )
        prepared_json = _json_material(
            {
                name: getattr(prepared_authorization, name)
                for name in SourceReadVaultPreparedAuthorizationReceipt.__dataclass_fields__
            },
            "migration vault prepared authorization",
        )
        with self._write() as connection:
            replay = persisted_migration_replay_locked(connection)
            if replay is not None:
                return replay
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_no_active_stream_incident_locked(
                connection, lineage_sha256=lineage
            )
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (lineage,),
            ).fetchone()
            if (
                latest is None
                or latest["head_sha256"] != current_proof.continuation_head_sha256
                or latest["ledger_binding_sha256"] != current.ledger_binding_sha256
                or self._continuation_binding_for_head_locked(connection, latest)
                != current
            ):
                raise SourceReadLedgerStateConflict(
                    "continuation migration lost the latest-head CAS"
                )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_continuation_migrations"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_CONTINUATION_MIGRATION",
                "migration_id": next_binding.operation_id,
                "idempotency_sha256": idempotency,
                "lineage_sha256": lineage,
                "current_ledger_binding_sha256": current.ledger_binding_sha256,
                "next_ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "next_binding_json_sha256": _hash_text(next_binding_json),
                "old_position_binding_sha256": old_position.position_binding_sha256,
                "old_position_binding_json_sha256": _hash_text(old_position_json),
                "next_position_binding_sha256": next_position.position_binding_sha256,
                "next_position_binding_json_sha256": _hash_text(next_position_json),
                "old_checkpoint_json_sha256": _hash_text(old_checkpoint_json),
                "next_checkpoint_json_sha256": _hash_text(next_checkpoint_json),
                "old_registry_projection_sha256": prior_projection,
                "next_registry_projection_sha256": (
                    next_request.registry_projection_sha256
                ),
                "next_registry_boundary_sha256": next_registry.content_sha256,
                "next_registry_material_json_sha256": _hash_text(next_registry_json),
                "next_request_material_json_sha256": _hash_text(next_request_json),
                "old_rights_profile_sha256": old_rights_profile,
                "next_rights_profile_sha256": next_rights_profile,
                "previous_head_sha256": str(latest["head_sha256"]),
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_prepared_authorization_sha256": (
                    prepared_authorization.authorization_sha256
                ),
                "vault_prepared_authorization_json_sha256": _hash_text(prepared_json),
                "occurred_at_utc": occurred,
            }
            migration_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_continuation_migrations(
                       sequence,migration_id,idempotency_sha256,lineage_sha256,
                       current_ledger_binding_sha256,next_ledger_binding_sha256,
                       next_binding_json,old_position_binding_sha256,
                       old_position_binding_json,next_position_binding_sha256,
                       next_position_binding_json,old_checkpoint_json,
                       next_checkpoint_json,old_registry_projection_sha256,
                       next_registry_projection_sha256,
                       next_registry_boundary_sha256,next_registry_material_json,
                       next_request_material_json,old_rights_profile_sha256,
                       next_rights_profile_sha256,previous_head_sha256,
                       governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_prepared_authorization_sha256,
                       vault_prepared_authorization_json,occurred_at_utc,
                       migration_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    next_binding.operation_id,
                    idempotency,
                    lineage,
                    current.ledger_binding_sha256,
                    next_binding.ledger_binding_sha256,
                    next_binding_json,
                    old_position.position_binding_sha256,
                    old_position_json,
                    next_position.position_binding_sha256,
                    next_position_json,
                    old_checkpoint_json,
                    next_checkpoint_json,
                    prior_projection,
                    next_request.registry_projection_sha256,
                    next_registry.content_sha256,
                    next_registry_json,
                    next_request_json,
                    old_rights_profile,
                    next_rights_profile,
                    latest["head_sha256"],
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    prepared_authorization.authorization_sha256,
                    prepared_json,
                    occurred,
                    migration_sha,
                ),
            )
            head_sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_continuation_heads"
                ).fetchone()[0]
            )
            head_material: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_CONTINUATION_HEAD",
                "sequence": head_sequence,
                "lineage_sha256": lineage,
                "generation": next_binding.generation,
                "operation_id": next_binding.operation_id,
                "outcome_id": None,
                "rotation_id": None,
                "migration_id": next_binding.operation_id,
                "repair_id": None,
                "ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "previous_head_sha256": str(latest["head_sha256"]),
            }
            connection.execute(
                """INSERT INTO source_read_continuation_heads(
                       sequence,lineage_sha256,generation,operation_id,outcome_id,
                       rotation_id,migration_id,repair_id,ledger_binding_sha256,
                       previous_head_sha256,head_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    head_sequence,
                    lineage,
                    next_binding.generation,
                    next_binding.operation_id,
                    None,
                    None,
                    next_binding.operation_id,
                    None,
                    next_binding.ledger_binding_sha256,
                    latest["head_sha256"],
                    _value_sha256(head_material),
                ),
            )
            self._append_event_locked(
                connection,
                event_type="CONTINUATION_MIGRATED",
                entity_kind="CONTINUATION_MIGRATION",
                entity_id=next_binding.operation_id,
                entity_sha256=migration_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                "SELECT * FROM source_read_continuation_migrations WHERE migration_id=?",
                (next_binding.operation_id,),
            ).fetchone()
            return self._continuation_migration_from_row(row, replayed=False)

    @staticmethod
    def _continuation_migration_from_row(
        row: sqlite3.Row, *, replayed: bool
    ) -> SourceReadContinuationMigration:
        return SourceReadContinuationMigration(
            str(row["migration_id"]),
            str(row["lineage_sha256"]),
            str(row["current_ledger_binding_sha256"]),
            str(row["next_ledger_binding_sha256"]),
            str(row["old_position_binding_sha256"]),
            str(row["next_position_binding_sha256"]),
            str(row["governance_evidence_sha256"]),
            str(row["governance_authorization_sha256"]),
            str(row["migration_sha256"]),
            replayed,
        )

    def continuation_migration(
        self,
        migration_id: str,
        expected_next_ledger_binding_sha256: str | None = None,
    ) -> SourceReadContinuationMigration:
        """Fresh-process readback for ledger-bound-before-vault-ACTIVATE recovery."""

        identity = _safe_id(migration_id, "continuation migration identity")
        if _MIGRATION_OPERATION_ID.fullmatch(identity) is None:
            raise SourceReadLedgerValidationError(
                "continuation migration identity is invalid"
            )
        expected = (
            None
            if expected_next_ledger_binding_sha256 is None
            else _sha256(
                expected_next_ledger_binding_sha256,
                "expected migration ledger binding",
            )
        )
        with self._read() as connection:
            self._verify_locked(connection)
            row = connection.execute(
                "SELECT * FROM source_read_continuation_migrations WHERE migration_id=?",
                (identity,),
            ).fetchone()
            if row is None or (
                expected is not None and row["next_ledger_binding_sha256"] != expected
            ):
                raise SourceReadLedgerStateConflict(
                    "continuation migration readback is absent"
                )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (row["lineage_sha256"],),
            ).fetchone()
            if (
                head is None
                or head["migration_id"] != identity
                or head["ledger_binding_sha256"] != row["next_ledger_binding_sha256"]
            ):
                raise SourceReadLedgerStateConflict(
                    "continuation migration is not the latest lineage head"
                )
            return self._continuation_migration_from_row(row, replayed=True)

    def continuation_binding_status(
        self,
        operation_id: str,
        expected_ledger_binding_sha256: str,
    ) -> ContinuationBindingStatus:
        """Distinguish exact absence from a historical/conflicting binding."""

        if type(operation_id) is not str:
            raise SourceReadLedgerValidationError("operation identity is invalid")
        self._continuation_source_spec(operation_id)
        expected = _sha256(
            expected_ledger_binding_sha256,
            "expected_ledger_binding_sha256",
        )
        with self._read() as connection:
            self._verify_locked(connection)
            spec, rows = self._continuation_entity_rows_locked(connection, operation_id)
            if not rows:
                return ContinuationBindingStatus.ABSENT
            exact_row = next(
                (row for row in rows if row["binding_sha256"] == expected),
                None,
            )
            if exact_row is None:
                return ContinuationBindingStatus.PRESENT_NOT_LATEST
            binding = _continuation_binding_from_material(
                _stored_json(exact_row["binding_json"], "continuation binding")
            )
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (_continuation_lineage_sha256(binding),),
            ).fetchone()
            if (
                latest is not None
                and latest[spec["head_column"]] == exact_row["entity_id"]
                and latest["ledger_binding_sha256"] == expected
            ):
                return ContinuationBindingStatus.LATEST_VERIFIED
            return ContinuationBindingStatus.PRESENT_NOT_LATEST

