    @staticmethod
    def _completed_vault_leaf_envelope_locked(
        connection: sqlite3.Connection,
        binding: SourceReadContinuationBinding,
    ) -> str:
        """Resolve the exact usable envelope after every completed rewrap.

        A continuation binding remains the immutable logical/origin record.
        Completed vault-key retirements append leaf rewraps without rewriting
        that record, so repair fencing must follow the completed leaf chain
        rather than reuse the origin envelope.
        """

        leaf_envelope = binding.envelope_sha256
        rows = connection.execute(
            """SELECT inventory.item_json
               FROM source_read_key_retirement_inventory inventory
               JOIN source_read_key_retirement_completions completion
                 ON completion.operation_id=inventory.operation_id
               WHERE inventory.slot_sha256=? AND inventory.generation=?
                 AND inventory.ledger_binding_sha256=?
               ORDER BY completion.sequence,inventory.sequence""",
            (
                binding.slot_sha256,
                binding.generation,
                binding.ledger_binding_sha256,
            ),
        ).fetchall()
        for row in rows:
            item = _key_retirement_item_from_material(
                _stored_json(row["item_json"], "completed retirement inventory item")
            )
            if (
                item.slot_sha256 != binding.slot_sha256
                or item.generation != binding.generation
                or item.ledger_binding_sha256 != binding.ledger_binding_sha256
                or item.original_envelope_sha256 != binding.envelope_sha256
                or item.operation_id != binding.operation_id
                or item.expected_outcome != binding.expected_outcome
                or item.runtime_state_sha256 != binding.runtime_state_sha256
                or item.position_binding_sha256 != binding.position_binding_sha256
                or item.current_leaf_envelope_sha256 != leaf_envelope
            ):
                raise SourceReadLedgerIntegrityError(
                    "completed retirement continuation leaf chain differs"
                )
            leaf_envelope = item.rewrap_envelope_sha256
        return leaf_envelope

    def stream_repair_ingress_proof(
        self,
        incident_id: str,
        expected_current_ledger_binding_sha256: str,
    ) -> SourceReadStreamRepairIngressProof:
        """Mint exact anchored authority for a vault repair-base fence."""

        incident_identity = _safe_id(incident_id, "stream incident identity")
        expected_binding = _sha256(
            expected_current_ledger_binding_sha256,
            "expected incident ledger binding",
        )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            self._assert_no_active_key_lifecycle_locked(connection)
            incident = connection.execute(
                """SELECT * FROM source_read_stream_incidents
                   WHERE incident_id=?""",
                (incident_identity,),
            ).fetchone()
            if incident is None:
                raise SourceReadLedgerStateConflict(
                    "stream repair ingress requires an exact vault incident"
                )
            source_kind = "DIRECT_ABSENCE"
            incident_authorization_sha256 = incident["absence_authorization_sha256"]
            parent_operation_id: str | None = None
            parent_completion_sha256: str | None = None
            parent_completion_event_sha256: str | None = None
            if incident_authorization_sha256 is None:
                source_kind = "KEY_COMPROMISE_PARENT"
                parent_operation_id = incident["parent_retirement_operation_id"]
                completion = connection.execute(
                    """SELECT * FROM source_read_key_retirement_completions
                       WHERE operation_id=? AND lifecycle_state='COMPROMISED'""",
                    (parent_operation_id,),
                ).fetchone()
                completion_event = (
                    None
                    if completion is None
                    else connection.execute(
                        """SELECT * FROM source_read_events
                           WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
                        (str(parent_operation_id) + ":COMPLETE",),
                    ).fetchone()
                )
                if completion is None or completion_event is None:
                    raise SourceReadLedgerStateConflict(
                        "stream repair ingress key-compromise parent is incomplete"
                    )
                incident_authorization_sha256 = completion["record_sha256"]
                parent_completion_sha256 = str(completion["record_sha256"])
                parent_completion_event_sha256 = str(completion_event["event_sha256"])
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=str(incident["lineage_sha256"])
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (incident["lineage_sha256"],),
            ).fetchone()
            event = (
                self._entity_event_locked(
                    connection, "STREAM_INCIDENT", incident_identity
                )
                if source_kind == "DIRECT_ABSENCE"
                else completion_event
            )
            if (
                state is None
                or state[0]["incident_id"] != incident_identity
                or state[1] is not SourceReadStreamRecoveryState.ACTIVE
                or head is None
                or head["ledger_binding_sha256"] != expected_binding
                or event is None
                or verification.external_anchor_generation <= 0
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair ingress is not the anchored active incident head"
                )
            binding = self._continuation_binding_for_head_locked(connection, head)
            latest_repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE incident_id=? ORDER BY sequence DESC LIMIT 1""",
                (incident_identity,),
            ).fetchone()
            eligible_head: sqlite3.Row | None
            eligible_binding: SourceReadContinuationBinding | None
            eligible_envelope: str | None
            if head["head_sha256"] == incident["continuation_head_sha256"]:
                if source_kind == "KEY_COMPROMISE_PARENT":
                    eligible_head = head
                    eligible_binding = binding
                    eligible_envelope = str(incident["expected_envelope_sha256"])
                else:
                    previous_head_sha256 = str(head["previous_head_sha256"])
                    eligible_head = (
                        None
                        if previous_head_sha256 == ZERO_SHA256
                        else connection.execute(
                            """SELECT * FROM source_read_continuation_heads
                               WHERE head_sha256=? AND lineage_sha256=?""",
                            (previous_head_sha256, incident["lineage_sha256"]),
                        ).fetchone()
                    )
                    eligible_binding = (
                        None
                        if eligible_head is None
                        else self._continuation_binding_for_head_locked(
                            connection, eligible_head
                        )
                    )
                    eligible_envelope = (
                        None
                        if eligible_binding is None
                        else self._completed_vault_leaf_envelope_locked(
                            connection, eligible_binding
                        )
                    )
            else:
                abandonment = (
                    None
                    if latest_repair is None
                    else connection.execute(
                        """SELECT * FROM source_read_stream_repair_abandonments
                           WHERE repair_id=?""",
                        (latest_repair["repair_id"],),
                    ).fetchone()
                )
                eligible_head = (
                    None
                    if latest_repair is None
                    else connection.execute(
                        """SELECT * FROM source_read_continuation_heads
                           WHERE head_sha256=? AND lineage_sha256=?""",
                        (
                            latest_repair["physical_base_head_sha256"],
                            incident["lineage_sha256"],
                        ),
                    ).fetchone()
                )
                eligible_binding = (
                    None
                    if eligible_head is None
                    else self._continuation_binding_for_head_locked(
                        connection, eligible_head
                    )
                )
                base_receipt = (
                    None
                    if latest_repair is None
                    else _vault_factory_receipt_from_material(
                        _stored_json(
                            latest_repair["vault_repair_base_authorization_json"],
                            "stream repair base authorization",
                        ),
                        SourceReadVaultStreamRepairBaseAuthorizationReceipt,
                    )
                )
                eligible_envelope = (
                    None
                    if base_receipt is None
                    else base_receipt.physical_leaf_envelope_sha256
                )
                if (
                    latest_repair is None
                    or abandonment is None
                    or latest_repair["next_ledger_binding_sha256"] != expected_binding
                ):
                    eligible_head = None
                    eligible_binding = None
                    eligible_envelope = None
            if (
                eligible_head is None
                or eligible_binding is None
                or eligible_envelope is None
                or eligible_binding.position_binding_sha256 is None
                or eligible_binding.runtime_state_sha256 != binding.runtime_state_sha256
                or eligible_binding.page_evidence_sha256 != binding.page_evidence_sha256
            ):
                raise SourceReadLedgerStateConflict(
                    "stream incident has no executable physical ACTIVE predecessor"
                )
            return self._mint_stream_repair_ingress_proof(
                binding=binding,
                incident=incident,
                source_kind=source_kind,
                incident_authorization_sha256=str(incident_authorization_sha256),
                parent_retirement_operation_id=(
                    None if parent_operation_id is None else str(parent_operation_id)
                ),
                parent_completion_sha256=parent_completion_sha256,
                parent_completion_event_sha256=(parent_completion_event_sha256),
                incident_event_sha256=str(event["event_sha256"]),
                logical_continuation_head_sha256=str(head["head_sha256"]),
                eligible_physical_binding=eligible_binding,
                eligible_physical_head_sha256=str(eligible_head["head_sha256"]),
                eligible_physical_envelope_sha256=eligible_envelope,
                verification=verification,
            )

    def verify_latest_stream_repair_ingress_proof(
        self, proof: SourceReadStreamRepairIngressProof
    ) -> bool:
        if not self._stream_repair_ingress_proof_is_known(proof):
            return False
        try:
            with self._read() as connection:
                verification = self._verify_locked(connection)
                self._assert_authority_approval_fence_locked(connection)
                self._assert_no_active_key_lifecycle_locked(connection)
                incident = connection.execute(
                    """SELECT * FROM source_read_stream_incidents
                       WHERE incident_id=?""",
                    (proof.incident_id,),
                ).fetchone()
                state = self._latest_stream_incident_locked(
                    connection, lineage_sha256=proof.lineage_sha256
                )
                head = connection.execute(
                    """SELECT * FROM source_read_continuation_heads
                       WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                    (proof.lineage_sha256,),
                ).fetchone()
                event: sqlite3.Row | None = None
                source_kind: str | None = None
                incident_authorization_sha256: str | None = None
                parent_operation_id: str | None = None
                parent_completion_sha256: str | None = None
                parent_completion_event_sha256: str | None = None
                if incident is not None:
                    if incident["absence_authorization_sha256"] is not None:
                        source_kind = "DIRECT_ABSENCE"
                        incident_authorization_sha256 = str(
                            incident["absence_authorization_sha256"]
                        )
                        event = connection.execute(
                            """SELECT * FROM source_read_events
                               WHERE entity_kind='STREAM_INCIDENT'
                                 AND entity_id=?""",
                            (proof.incident_id,),
                        ).fetchone()
                    else:
                        source_kind = "KEY_COMPROMISE_PARENT"
                        parent_operation_id = str(
                            incident["parent_retirement_operation_id"]
                        )
                        completion = connection.execute(
                            """SELECT * FROM source_read_key_retirement_completions
                               WHERE operation_id=? AND lifecycle_state='COMPROMISED'""",
                            (parent_operation_id,),
                        ).fetchone()
                        completion_event = (
                            None
                            if completion is None
                            else connection.execute(
                                """SELECT * FROM source_read_events
                                   WHERE entity_kind='KEY_LIFECYCLE'
                                     AND entity_id=?""",
                                (parent_operation_id + ":COMPLETE",),
                            ).fetchone()
                        )
                        if completion is not None and completion_event is not None:
                            event = completion_event
                            incident_authorization_sha256 = str(
                                completion["record_sha256"]
                            )
                            parent_completion_sha256 = str(completion["record_sha256"])
                            parent_completion_event_sha256 = str(
                                completion_event["event_sha256"]
                            )
                eligible_head: sqlite3.Row | None = None
                eligible_binding: SourceReadContinuationBinding | None = None
                eligible_envelope: str | None = None
                if incident is not None and head is not None:
                    logical_binding = self._continuation_binding_for_head_locked(
                        connection, head
                    )
                    if head["head_sha256"] == incident["continuation_head_sha256"]:
                        if source_kind == "KEY_COMPROMISE_PARENT":
                            eligible_head = head
                            eligible_binding = logical_binding
                            eligible_envelope = str(
                                incident["expected_envelope_sha256"]
                            )
                        else:
                            previous_head_sha256 = str(head["previous_head_sha256"])
                            if previous_head_sha256 != ZERO_SHA256:
                                eligible_head = connection.execute(
                                    """SELECT * FROM source_read_continuation_heads
                                       WHERE head_sha256=? AND lineage_sha256=?""",
                                    (
                                        previous_head_sha256,
                                        incident["lineage_sha256"],
                                    ),
                                ).fetchone()
                                if eligible_head is not None:
                                    eligible_binding = (
                                        self._continuation_binding_for_head_locked(
                                            connection, eligible_head
                                        )
                                    )
                                    eligible_envelope = (
                                        self._completed_vault_leaf_envelope_locked(
                                            connection, eligible_binding
                                        )
                                    )
                    else:
                        latest_repair = connection.execute(
                            """SELECT * FROM source_read_stream_repair_bindings
                               WHERE incident_id=? ORDER BY sequence DESC LIMIT 1""",
                            (proof.incident_id,),
                        ).fetchone()
                        abandonment = (
                            None
                            if latest_repair is None
                            else connection.execute(
                                """SELECT *
                                   FROM source_read_stream_repair_abandonments
                                   WHERE repair_id=?""",
                                (latest_repair["repair_id"],),
                            ).fetchone()
                        )
                        if (
                            latest_repair is not None
                            and abandonment is not None
                            and latest_repair["next_ledger_binding_sha256"]
                            == head["ledger_binding_sha256"]
                        ):
                            eligible_head = connection.execute(
                                """SELECT * FROM source_read_continuation_heads
                                   WHERE head_sha256=? AND lineage_sha256=?""",
                                (
                                    latest_repair["physical_base_head_sha256"],
                                    proof.lineage_sha256,
                                ),
                            ).fetchone()
                            if eligible_head is not None:
                                eligible_binding = (
                                    self._continuation_binding_for_head_locked(
                                        connection, eligible_head
                                    )
                                )
                                base_receipt = _vault_factory_receipt_from_material(
                                    _stored_json(
                                        latest_repair[
                                            "vault_repair_base_authorization_json"
                                        ],
                                        "stream repair base authorization",
                                    ),
                                    SourceReadVaultStreamRepairBaseAuthorizationReceipt,
                                )
                                eligible_envelope = (
                                    base_receipt.physical_leaf_envelope_sha256
                                )
                return bool(
                    incident is not None
                    and source_kind == proof.source_kind
                    and incident_authorization_sha256
                    == proof.incident_authorization_sha256
                    and parent_operation_id == proof.parent_retirement_operation_id
                    and parent_completion_sha256 == proof.parent_completion_sha256
                    and parent_completion_event_sha256
                    == proof.parent_completion_event_sha256
                    and state is not None
                    and state[0]["incident_id"] == proof.incident_id
                    and state[1] is SourceReadStreamRecoveryState.ACTIVE
                    and head is not None
                    and self._continuation_binding_for_head_locked(connection, head)
                    == proof.binding
                    and eligible_binding == proof.eligible_physical_binding
                    and eligible_binding is not None
                    and eligible_binding.runtime_state_sha256
                    == proof.binding.runtime_state_sha256
                    and eligible_binding.page_evidence_sha256
                    == proof.binding.page_evidence_sha256
                    and eligible_head is not None
                    and eligible_head["head_sha256"]
                    == proof.eligible_physical_head_sha256
                    and eligible_envelope == proof.eligible_physical_envelope_sha256
                    and incident["lineage_sha256"] == proof.lineage_sha256
                    and incident["stable_stream_sha256"] == proof.stable_stream_sha256
                    and incident["position_binding_sha256"]
                    == proof.position_binding_sha256
                    and incident["incident_sha256"] == proof.incident_sha256
                    and head["head_sha256"] == proof.continuation_head_sha256
                    and event is not None
                    and event["event_sha256"] == proof.incident_event_sha256
                    and verification.head_event_sha256 == proof.ledger_head_event_sha256
                    and verification.external_anchor_generation
                    == proof.external_anchor_generation
                    and verification.external_anchor_receipt_sha256
                    == proof.external_anchor_receipt_sha256
                    and proof.factory_attested is True
                    and proof.live_release_eligible is False
                )
        except SourceReadLedgerError:
            return False

    def request_continuation_stream_repair(
        self,
        incident_id: str,
        ingress_proof: SourceReadStreamRepairIngressProof,
        *,
        repair_operation_id: str,
        position: SourceReadContinuationPositionBinding,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadStreamRepairIntent:
        """Anchor SoD approval before any vault PREPARED/fence mutation."""

        incident_identity = _safe_id(incident_id, "stream incident identity")
        repair_id = _safe_id(repair_operation_id, "stream repair operation")
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(repair_id) is None:
            raise SourceReadLedgerValidationError(
                "stream repair operation identity differs"
            )
        position_material = _continuation_position_material(position)
        governance = _sha256(
            governance_evidence_sha256, "stream repair governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._continuation_migration_authority is None
            or self.continuation_migration_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "stream repair intent requires pinned anchor and SoD authority"
            )
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_INTENT"
                    or row["repair_id"] != repair_id
                    or row["incident_id"] != incident_identity
                    or row["position_binding_sha256"]
                    != position.position_binding_sha256
                    or _stored_json(
                        row["position_binding_json"], "stream repair intent position"
                    )
                    != position_material
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream repair intent idempotency digest is already bound"
                    )
                return self._stream_repair_intent_from_row(row, replayed=True)
        if (
            type(ingress_proof) is not SourceReadStreamRepairIngressProof
            or ingress_proof.incident_id != incident_identity
            or ingress_proof.position_binding_sha256 != position.position_binding_sha256
            or ingress_proof.binding.position_binding_sha256
            != position.position_binding_sha256
            or not self.verify_latest_stream_repair_ingress_proof(ingress_proof)
        ):
            raise SourceReadLedgerStateConflict(
                "stream repair intent requires the exact latest ingress proof"
            )
        authorization = _validated_stream_repair_authorization(
            self._continuation_migration_authority.authorize_stream_repair(
                store_identity_sha256=self.store_identity_sha256,
                phase="INTENT",
                incident_id=incident_identity,
                repair_id=repair_id,
                lineage_sha256=ingress_proof.lineage_sha256,
                logical_head_sha256=ingress_proof.continuation_head_sha256,
                current_ledger_binding_sha256=(
                    ingress_proof.binding.ledger_binding_sha256
                ),
                next_ledger_binding_sha256=ZERO_SHA256,
                position_binding_sha256=position.position_binding_sha256,
                physical_base_status="ACTIVE",
                physical_base_head_sha256=(ingress_proof.eligible_physical_head_sha256),
                physical_base_ledger_binding_sha256=(
                    ingress_proof.eligible_physical_binding.ledger_binding_sha256
                ),
                repair_base_fence_sha256=None,
                repair_base_authorization_sha256=None,
                activation_evidence_sha256=None,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=(
                self.continuation_migration_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            phase="INTENT",
            incident_id=incident_identity,
            repair_id=repair_id,
            lineage_sha256=ingress_proof.lineage_sha256,
            logical_head_sha256=ingress_proof.continuation_head_sha256,
            current_ledger_binding_sha256=(ingress_proof.binding.ledger_binding_sha256),
            next_ledger_binding_sha256=ZERO_SHA256,
            position_binding_sha256=position.position_binding_sha256,
            physical_base_status="ACTIVE",
            physical_base_head_sha256=(ingress_proof.eligible_physical_head_sha256),
            physical_base_ledger_binding_sha256=(
                ingress_proof.eligible_physical_binding.ledger_binding_sha256
            ),
            repair_base_fence_sha256=None,
            repair_base_authorization_sha256=None,
            activation_evidence_sha256=None,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        position_json = _json_material(
            position_material, "stream repair intent position"
        )
        eligible_json = _json_material(
            _continuation_binding_material(ingress_proof.eligible_physical_binding),
            "stream repair eligible physical binding",
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadStreamRepairAuthorizationReceipt.__dataclass_fields__
            },
            "stream repair intent authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_INTENT"
                    or row["repair_id"] != repair_id
                    or row["incident_id"] != incident_identity
                    or row["position_binding_sha256"]
                    != position.position_binding_sha256
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream repair intent idempotency digest is already bound"
                    )
                return self._stream_repair_intent_from_row(row, replayed=True)
            self._assert_no_active_key_lifecycle_locked(connection)
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=ingress_proof.lineage_sha256
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (ingress_proof.lineage_sha256,),
            ).fetchone()
            outstanding = connection.execute(
                """SELECT 1 FROM source_read_stream_repair_intents intent
                   LEFT JOIN source_read_stream_repair_bindings binding
                     ON binding.repair_id=intent.repair_id
                   LEFT JOIN source_read_stream_repair_intent_cancellations cancel
                     ON cancel.repair_id=intent.repair_id
                   WHERE intent.incident_id=? AND binding.repair_id IS NULL
                     AND cancel.repair_id IS NULL""",
                (incident_identity,),
            ).fetchone()
            if (
                state is None
                or state[0]["incident_id"] != incident_identity
                or state[1] is not SourceReadStreamRecoveryState.ACTIVE
                or head is None
                or head["head_sha256"] != ingress_proof.continuation_head_sha256
                or head["ledger_binding_sha256"]
                != ingress_proof.binding.ledger_binding_sha256
                or outstanding is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair intent lost its active incident/head comparison"
                )
            sequence = int(
                connection.execute(
                    """SELECT COALESCE(MAX(sequence),0)+1
                       FROM source_read_stream_repair_intents"""
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_STREAM_REPAIR_INTENT",
                "repair_id": repair_id,
                "incident_id": incident_identity,
                "idempotency_sha256": idempotency,
                "lineage_sha256": ingress_proof.lineage_sha256,
                "current_ledger_binding_sha256": (
                    ingress_proof.binding.ledger_binding_sha256
                ),
                "logical_head_sha256": ingress_proof.continuation_head_sha256,
                "position_binding_sha256": position.position_binding_sha256,
                "position_binding_json_sha256": _hash_text(position_json),
                "eligible_physical_head_sha256": (
                    ingress_proof.eligible_physical_head_sha256
                ),
                "eligible_physical_ledger_binding_sha256": (
                    ingress_proof.eligible_physical_binding.ledger_binding_sha256
                ),
                "eligible_physical_binding_json_sha256": _hash_text(eligible_json),
                "eligible_physical_envelope_sha256": (
                    ingress_proof.eligible_physical_envelope_sha256
                ),
                "source_kind": ingress_proof.source_kind,
                "incident_authorization_sha256": (
                    ingress_proof.incident_authorization_sha256
                ),
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": (authorization.authorization_sha256),
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "occurred_at_utc": occurred,
            }
            intent_sha256 = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_stream_repair_intents(
                       sequence,repair_id,incident_id,idempotency_sha256,
                       lineage_sha256,current_ledger_binding_sha256,
                       logical_head_sha256,position_binding_sha256,
                       position_binding_json,eligible_physical_head_sha256,
                       eligible_physical_ledger_binding_sha256,
                       eligible_physical_binding_json,
                       eligible_physical_envelope_sha256,source_kind,
                       incident_authorization_sha256,
                       governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,occurred_at_utc,intent_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    repair_id,
                    incident_identity,
                    idempotency,
                    ingress_proof.lineage_sha256,
                    ingress_proof.binding.ledger_binding_sha256,
                    ingress_proof.continuation_head_sha256,
                    position.position_binding_sha256,
                    position_json,
                    ingress_proof.eligible_physical_head_sha256,
                    ingress_proof.eligible_physical_binding.ledger_binding_sha256,
                    eligible_json,
                    ingress_proof.eligible_physical_envelope_sha256,
                    ingress_proof.source_kind,
                    ingress_proof.incident_authorization_sha256,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    occurred,
                    intent_sha256,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="STREAM_REPAIR_PREPARE_AUTHORIZED",
                entity_kind="STREAM_REPAIR_INTENT",
                entity_id=repair_id,
                entity_sha256=intent_sha256,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                """SELECT * FROM source_read_stream_repair_intents
                   WHERE repair_id=?""",
                (repair_id,),
            ).fetchone()
            return self._stream_repair_intent_from_row(row, replayed=False)

    def stream_repair_intent_proof(
        self,
        repair_id: str,
        expected_intent_sha256: str,
    ) -> SourceReadStreamRepairIntentProof:
        repair_identity = _safe_id(repair_id, "stream repair identity")
        expected = _sha256(expected_intent_sha256, "expected repair intent")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            self._assert_no_active_key_lifecycle_locked(connection)
            row = connection.execute(
                """SELECT * FROM source_read_stream_repair_intents
                   WHERE repair_id=? AND intent_sha256=?""",
                (repair_identity, expected),
            ).fetchone()
            if row is None:
                raise SourceReadLedgerStateConflict("stream repair intent is absent")
            if (
                connection.execute(
                    """SELECT 1 FROM source_read_stream_repair_bindings
                   WHERE repair_id=?""",
                    (repair_identity,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair intent is already consumed"
                )
            if (
                connection.execute(
                    """SELECT 1 FROM source_read_stream_repair_intent_cancellations
                   WHERE repair_id=?""",
                    (repair_identity,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict("stream repair intent is cancelled")
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=str(row["lineage_sha256"])
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (row["lineage_sha256"],),
            ).fetchone()
            event = self._entity_event_locked(
                connection, "STREAM_REPAIR_INTENT", repair_identity
            )
            if (
                state is None
                or state[0]["incident_id"] != row["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.ACTIVE
                or head is None
                or head["head_sha256"] != row["logical_head_sha256"]
                or head["ledger_binding_sha256"] != row["current_ledger_binding_sha256"]
                or verification.external_anchor_generation <= 0
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair intent is not the latest anchored owner"
                )
            binding = self._continuation_binding_for_head_locked(connection, head)
            eligible = _continuation_binding_from_material(
                _stored_json(
                    row["eligible_physical_binding_json"],
                    "stream repair eligible physical binding",
                )
            )
            return self._mint_stream_repair_intent_proof(
                intent=self._stream_repair_intent_from_row(row, replayed=True),
                binding=binding,
                eligible_physical_binding=eligible,
                eligible_physical_head_sha256=str(row["eligible_physical_head_sha256"]),
                eligible_physical_envelope_sha256=str(
                    row["eligible_physical_envelope_sha256"]
                ),
                logical_continuation_head_sha256=str(row["logical_head_sha256"]),
                position_binding_sha256=str(row["position_binding_sha256"]),
                intent_event_sha256=str(event["event_sha256"]),
                verification=verification,
            )

    def verify_latest_stream_repair_intent_proof(
        self, proof: SourceReadStreamRepairIntentProof
    ) -> bool:
        if not self._stream_repair_intent_proof_is_known(proof):
            return False
        try:
            fresh = self.stream_repair_intent_proof(
                proof.intent.repair_id, proof.intent.intent_sha256
            )
            return bool(
                fresh.intent == proof.intent
                and fresh.binding == proof.binding
                and fresh.eligible_physical_binding == proof.eligible_physical_binding
                and fresh.eligible_physical_head_sha256
                == proof.eligible_physical_head_sha256
                and fresh.eligible_physical_envelope_sha256
                == proof.eligible_physical_envelope_sha256
                and fresh.logical_continuation_head_sha256
                == proof.logical_continuation_head_sha256
                and fresh.position_binding_sha256 == proof.position_binding_sha256
                and fresh.intent_event_sha256 == proof.intent_event_sha256
                and fresh.ledger_head_event_sha256 == proof.ledger_head_event_sha256
                and fresh.external_anchor_generation == proof.external_anchor_generation
                and fresh.external_anchor_receipt_sha256
                == proof.external_anchor_receipt_sha256
            )
        except SourceReadLedgerError:
            return False

    def cancel_continuation_stream_repair_intent(
        self,
        repair_id: str,
        expected_intent_sha256: str,
        vault_cancellation_proof: object,
        *,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadStreamRepairIntentCancellation:
        """Cancel only after a vault-local no-PREPARED cancellation fence wins."""

        identity = _safe_id(repair_id, "stream repair identity")
        expected = _sha256(expected_intent_sha256, "expected repair intent")
        governance = _sha256(
            governance_evidence_sha256, "repair intent cancellation governance"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._continuation_migration_authority is None
            or self.continuation_migration_authority_identity_sha256 is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "repair intent cancellation requires pinned vault and SoD authorities"
            )
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_INTENT_CANCELLATION"
                    or row["repair_id"] != identity
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "repair intent cancellation idempotency is already bound"
                    )
                return self._stream_repair_intent_cancellation_from_row(
                    row, replayed=True
                )
            intent = connection.execute(
                """SELECT * FROM source_read_stream_repair_intents
                   WHERE repair_id=? AND intent_sha256=?""",
                (identity, expected),
            ).fetchone()
            if (
                intent is None
                or connection.execute(
                    """SELECT 1 FROM source_read_stream_repair_bindings
                       WHERE repair_id=?""",
                    (identity,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "repair intent cancellation requires an unconsumed intent"
                )
            eligible = _continuation_binding_from_material(
                _stored_json(
                    intent["eligible_physical_binding_json"],
                    "repair intent eligible physical binding",
                )
            )
        vault_receipt = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_stream_repair_intent_cancellation(
                vault_cancellation_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=eligible.vault_store_identity_sha256,
                slot_sha256=eligible.slot_sha256,
                repair_id=identity,
                incident_id=str(intent["incident_id"]),
                intent_sha256=expected,
                eligible_physical_head_sha256=str(
                    intent["eligible_physical_head_sha256"]
                ),
                eligible_physical_ledger_binding_sha256=(
                    eligible.ledger_binding_sha256
                ),
                eligible_physical_envelope_sha256=str(
                    intent["eligible_physical_envelope_sha256"]
                ),
            ),
            receipt_type=(SourceReadVaultStreamRepairIntentCancellationReceipt),
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": eligible.vault_store_identity_sha256,
                "slot_sha256": eligible.slot_sha256,
                "repair_id": identity,
                "incident_id": str(intent["incident_id"]),
                "intent_sha256": expected,
                "eligible_physical_head_sha256": str(
                    intent["eligible_physical_head_sha256"]
                ),
                "eligible_physical_ledger_binding_sha256": (
                    eligible.ledger_binding_sha256
                ),
                "eligible_physical_envelope_sha256": str(
                    intent["eligible_physical_envelope_sha256"]
                ),
                "observed_physical_generation": eligible.generation,
                "observed_physical_active_version": (
                    eligible.previous_active_version + 1
                ),
                "observed_physical_position_binding_sha256": (
                    eligible.position_binding_sha256
                ),
            },
        )
        observation = vault_receipt.observation_sha256
        authorization = _validated_stream_repair_authorization(
            self._continuation_migration_authority.authorize_stream_repair(
                store_identity_sha256=self.store_identity_sha256,
                phase="CANCEL_INTENT",
                incident_id=str(intent["incident_id"]),
                repair_id=identity,
                lineage_sha256=str(intent["lineage_sha256"]),
                logical_head_sha256=str(intent["logical_head_sha256"]),
                current_ledger_binding_sha256=str(
                    intent["current_ledger_binding_sha256"]
                ),
                next_ledger_binding_sha256=ZERO_SHA256,
                position_binding_sha256=str(intent["position_binding_sha256"]),
                physical_base_status="ACTIVE",
                physical_base_head_sha256=str(intent["eligible_physical_head_sha256"]),
                physical_base_ledger_binding_sha256=(eligible.ledger_binding_sha256),
                repair_base_fence_sha256=None,
                repair_base_authorization_sha256=(vault_receipt.authorization_sha256),
                activation_evidence_sha256=observation,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=(
                self.continuation_migration_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            phase="CANCEL_INTENT",
            incident_id=str(intent["incident_id"]),
            repair_id=identity,
            lineage_sha256=str(intent["lineage_sha256"]),
            logical_head_sha256=str(intent["logical_head_sha256"]),
            current_ledger_binding_sha256=str(intent["current_ledger_binding_sha256"]),
            next_ledger_binding_sha256=ZERO_SHA256,
            position_binding_sha256=str(intent["position_binding_sha256"]),
            physical_base_status="ACTIVE",
            physical_base_head_sha256=str(intent["eligible_physical_head_sha256"]),
            physical_base_ledger_binding_sha256=eligible.ledger_binding_sha256,
            repair_base_fence_sha256=None,
            repair_base_authorization_sha256=vault_receipt.authorization_sha256,
            activation_evidence_sha256=observation,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadStreamRepairAuthorizationReceipt.__dataclass_fields__
            },
            "repair intent cancellation governance authorization",
        )
        vault_json = _json_material(
            {
                name: getattr(vault_receipt, name)
                for name in SourceReadVaultStreamRepairIntentCancellationReceipt.__dataclass_fields__
            },
            "repair intent vault cancellation authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_INTENT_CANCELLATION"
                    or row["repair_id"] != identity
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "repair intent cancellation idempotency is already bound"
                    )
                return self._stream_repair_intent_cancellation_from_row(
                    row, replayed=True
                )
            current_intent = connection.execute(
                """SELECT * FROM source_read_stream_repair_intents
                   WHERE repair_id=?""",
                (identity,),
            ).fetchone()
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=str(intent["lineage_sha256"])
            )
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (intent["lineage_sha256"],),
            ).fetchone()
            if (
                current_intent is None
                or current_intent["intent_sha256"] != expected
                or connection.execute(
                    """SELECT 1 FROM source_read_stream_repair_bindings
                       WHERE repair_id=?""",
                    (identity,),
                ).fetchone()
                is not None
                or state is None
                or state[0]["incident_id"] != intent["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.ACTIVE
                or latest is None
                or latest["head_sha256"] != intent["logical_head_sha256"]
                or latest["ledger_binding_sha256"]
                != intent["current_ledger_binding_sha256"]
            ):
                raise SourceReadLedgerStateConflict(
                    "repair intent cancellation lost its CAS comparison"
                )
            sequence = int(
                connection.execute(
                    """SELECT COALESCE(MAX(sequence),0)+1
                       FROM source_read_stream_repair_intent_cancellations"""
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_STREAM_REPAIR_INTENT_CANCELLATION",
                "repair_id": identity,
                "incident_id": str(intent["incident_id"]),
                "idempotency_sha256": idempotency,
                "reason_code": (
                    SourceReadStreamRepairIntentCancellationReason.VAULT_FENCE_NOT_CREATED.value
                ),
                "observation_sha256": observation,
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": (authorization.authorization_sha256),
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_absence_authorization_sha256": (
                    vault_receipt.authorization_sha256
                ),
                "vault_absence_authorization_json_sha256": _hash_text(vault_json),
                "occurred_at_utc": occurred,
            }
            cancellation_sha256 = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_stream_repair_intent_cancellations(
                       sequence,repair_id,incident_id,idempotency_sha256,
                       reason_code,observation_sha256,governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_absence_authorization_sha256,
                       vault_absence_authorization_json,occurred_at_utc,
                       cancellation_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    identity,
                    intent["incident_id"],
                    idempotency,
                    SourceReadStreamRepairIntentCancellationReason.VAULT_FENCE_NOT_CREATED.value,
                    observation,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    vault_receipt.authorization_sha256,
                    vault_json,
                    occurred,
                    cancellation_sha256,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="STREAM_REPAIR_INTENT_CANCELLED",
                entity_kind="STREAM_REPAIR_INTENT_CANCEL",
                entity_id=identity,
                entity_sha256=cancellation_sha256,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                """SELECT * FROM source_read_stream_repair_intent_cancellations
                   WHERE repair_id=?""",
                (identity,),
            ).fetchone()
            return self._stream_repair_intent_cancellation_from_row(row, replayed=False)

    def bind_continuation_stream_repair(
        self,
        incident_id: str,
        next_binding: SourceReadContinuationBinding,
        position: SourceReadContinuationPositionBinding,
        prepared_proof: object,
        *,
        repair_intent_proof: SourceReadStreamRepairIntentProof,
        repair_base_proof: object,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadStreamRepairBinding:
        """Bind an exact vault PREPARED backup while the stream stays denied."""

        incident_identity = _safe_id(incident_id, "stream incident identity")
        next_material = _continuation_binding_material(next_binding)
        position_material = _continuation_position_material(position)
        if (
            _STREAM_REPAIR_OPERATION_ID.fullmatch(next_binding.operation_id) is None
            or next_binding.expected_outcome != "STREAM_REPAIR_BOUND"
            or next_binding.position_binding_sha256 != position.position_binding_sha256
            or next_binding.checkpoint_after_sha256 != position.checkpoint_sha256
        ):
            raise SourceReadLedgerValidationError(
                "stream repair PREPARED binding/position differs"
            )
        governance = _sha256(
            governance_evidence_sha256, "stream repair governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if repair_base_proof is None:
            raise SourceReadLedgerStateConflict(
                "stream repair requires an exact atomic repair-base fence proof"
            )
        if (
            self._external_anchor is None
            or self._continuation_migration_authority is None
            or self.continuation_migration_authority_identity_sha256 is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "stream repair requires pinned anchor, vault verifier, and SoD authority"
            )

        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR"
                    or row["incident_id"] != incident_identity
                    or row["next_ledger_binding_sha256"]
                    != next_binding.ledger_binding_sha256
                    or _stored_json(row["next_binding_json"], "stream repair binding")
                    != next_material
                    or _stored_json(
                        row["position_binding_json"], "stream repair position"
                    )
                    != position_material
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream repair idempotency digest is already bound"
                    )
                return self._stream_repair_binding_from_row(row, replayed=True)
            intent_row = connection.execute(
                """SELECT * FROM source_read_stream_repair_intents
                   WHERE repair_id=? AND incident_id=?""",
                (next_binding.operation_id, incident_identity),
            ).fetchone()
            if (
                intent_row is None
                or connection.execute(
                    """SELECT 1
                       FROM source_read_stream_repair_intent_cancellations
                       WHERE repair_id=?""",
                    (next_binding.operation_id,),
                ).fetchone()
                is not None
                or type(repair_intent_proof) is not SourceReadStreamRepairIntentProof
                or repair_intent_proof.intent.repair_id != next_binding.operation_id
                or repair_intent_proof.intent.intent_sha256
                != intent_row["intent_sha256"]
                or repair_intent_proof.position_binding_sha256
                != position.position_binding_sha256
                or repair_intent_proof.intent.governance_evidence_sha256 != governance
                or not self.verify_latest_stream_repair_intent_proof(
                    repair_intent_proof
                )
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair bind requires the exact anchored intent proof"
                )
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
            incident_state = self._latest_stream_incident_locked(
                connection,
                lineage_sha256=_continuation_lineage_sha256(next_binding),
            )
            if (
                incident_state is None
                or incident_state[0]["incident_id"] != incident_identity
                or incident_state[1] is not SourceReadStreamRecoveryState.ACTIVE
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair requires the exact active incident"
                )
            incident = incident_state[0]
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (incident["lineage_sha256"],),
            ).fetchone()
            if latest is None:
                raise SourceReadLedgerIntegrityError(
                    "stream incident continuation head is absent"
                )
            current = self._continuation_binding_for_head_locked(connection, latest)
            logical_head_exact = bool(
                latest["head_sha256"] == intent_row["logical_head_sha256"]
                and latest["ledger_binding_sha256"]
                == intent_row["current_ledger_binding_sha256"]
            )
            common_invalid = bool(
                current.position_binding_sha256 is None
                or current.position_binding_sha256 != position.position_binding_sha256
                or incident["position_binding_sha256"]
                != position.position_binding_sha256
                or (
                    incident["position_binding_json"] is not None
                    and _stored_json(
                        incident["position_binding_json"],
                        "stream incident position",
                    )
                    != position_material
                )
                or incident["stable_stream_sha256"] != _stable_stream_sha256(position)
                or current.vault_store_identity_sha256
                != next_binding.vault_store_identity_sha256
                or current.slot_sha256 != next_binding.slot_sha256
            )
            repair_base_invalid = bool(
                not logical_head_exact
                or next_binding.ledger_binding_sha256 == current.ledger_binding_sha256
                or next_binding.envelope_sha256 == current.envelope_sha256
            )
            if common_invalid or repair_base_invalid:
                raise SourceReadLedgerStateConflict(
                    "stream repair is not an exact backup advance of the quarantined head"
                )
            expected_previous_head = str(latest["head_sha256"])

        repair_base_authorization: (
            SourceReadVaultStreamRepairBaseAuthorizationReceipt | None
        ) = None
        repair_base_authorization_json: str | None = None
        physical_base_status = "LOGICAL"
        physical_base_head_sha256: str | None = None
        physical_base_ledger_binding_sha256: str | None = None
        repair_base_fence_sha256: str | None = None
        if repair_base_proof is not None:
            repair_base_authorization = _validated_vault_factory_receipt(
                self._vault_lifecycle_authority.verify_stream_repair_base(
                    repair_base_proof,
                    store_identity_sha256=self.store_identity_sha256,
                    vault_store_identity_sha256=(
                        next_binding.vault_store_identity_sha256
                    ),
                    slot_sha256=next_binding.slot_sha256,
                    incident_id=incident_identity,
                    repair_intent_sha256=repair_intent_proof.intent.intent_sha256,
                    repair_intent_event_sha256=(
                        repair_intent_proof.intent_event_sha256
                    ),
                    repair_intent_ledger_head_event_sha256=(
                        repair_intent_proof.ledger_head_event_sha256
                    ),
                    repair_intent_anchor_generation=(
                        repair_intent_proof.external_anchor_generation
                    ),
                    repair_intent_anchor_receipt_sha256=(
                        repair_intent_proof.external_anchor_receipt_sha256
                    ),
                    logical_continuation_head_sha256=expected_previous_head,
                    logical_ledger_binding_sha256=current.ledger_binding_sha256,
                    logical_generation=current.generation,
                    logical_envelope_sha256=current.envelope_sha256,
                    logical_position_binding_sha256=(position.position_binding_sha256),
                    repair_operation_id=next_binding.operation_id,
                    repair_generation=next_binding.generation,
                    repair_envelope_sha256=next_binding.envelope_sha256,
                    repair_ledger_binding_sha256=(next_binding.ledger_binding_sha256),
                    repair_position_binding_sha256=(position.position_binding_sha256),
                ),
                receipt_type=SourceReadVaultStreamRepairBaseAuthorizationReceipt,
                expected={
                    "authority_identity_sha256": (
                        self.vault_lifecycle_authority_identity_sha256
                    ),
                    "store_identity_sha256": self.store_identity_sha256,
                    "vault_store_identity_sha256": (
                        next_binding.vault_store_identity_sha256
                    ),
                    "slot_sha256": next_binding.slot_sha256,
                    "incident_id": incident_identity,
                    "repair_intent_sha256": (repair_intent_proof.intent.intent_sha256),
                    "repair_intent_event_sha256": (
                        repair_intent_proof.intent_event_sha256
                    ),
                    "repair_intent_ledger_head_event_sha256": (
                        repair_intent_proof.ledger_head_event_sha256
                    ),
                    "repair_intent_anchor_generation": (
                        repair_intent_proof.external_anchor_generation
                    ),
                    "repair_intent_anchor_receipt_sha256": (
                        repair_intent_proof.external_anchor_receipt_sha256
                    ),
                    "logical_continuation_head_sha256": expected_previous_head,
                    "logical_ledger_binding_sha256": (current.ledger_binding_sha256),
                    "logical_generation": current.generation,
                    "logical_envelope_sha256": current.envelope_sha256,
                    "logical_position_binding_sha256": (
                        position.position_binding_sha256
                    ),
                    "repair_operation_id": next_binding.operation_id,
                    "repair_generation": next_binding.generation,
                    "repair_envelope_sha256": next_binding.envelope_sha256,
                    "repair_ledger_binding_sha256": (
                        next_binding.ledger_binding_sha256
                    ),
                    "repair_position_binding_sha256": (
                        position.position_binding_sha256
                    ),
                },
            )
            physical_base_status = repair_base_authorization.physical_status
            repair_base_fence_sha256 = (
                repair_base_authorization.repair_base_fence_sha256
            )
            with self._read() as connection:
                state = self._latest_stream_incident_locked(
                    connection, lineage_sha256=str(incident["lineage_sha256"])
                )
                latest_now = connection.execute(
                    """SELECT * FROM source_read_continuation_heads
                       WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                    (incident["lineage_sha256"],),
                ).fetchone()
                if (
                    state is None
                    or state[0]["incident_id"] != incident_identity
                    or state[1] is not SourceReadStreamRecoveryState.ACTIVE
                    or latest_now is None
                    or latest_now["head_sha256"] != expected_previous_head
                    or latest_now["ledger_binding_sha256"]
                    != current.ledger_binding_sha256
                ):
                    raise SourceReadLedgerStateConflict(
                        "stream repair ingress changed during vault fencing"
                    )
                physical_base: SourceReadContinuationBinding | None = None
                physical_head: sqlite3.Row | None = None
                if physical_base_status == "ACTIVE":
                    physical_head = connection.execute(
                        """SELECT * FROM source_read_continuation_heads
                           WHERE lineage_sha256=? AND ledger_binding_sha256=?""",
                        (
                            incident["lineage_sha256"],
                            repair_base_authorization.physical_ledger_binding_sha256,
                        ),
                    ).fetchone()
                    if physical_head is not None:
                        cursor: sqlite3.Row | None = latest_now
                        ancestor = False
                        while cursor is not None:
                            if cursor["head_sha256"] == physical_head["head_sha256"]:
                                ancestor = True
                                break
                            previous = str(cursor["previous_head_sha256"])
                            if previous == ZERO_SHA256:
                                cursor = None
                            else:
                                cursor = connection.execute(
                                    """SELECT * FROM source_read_continuation_heads
                                       WHERE head_sha256=?""",
                                    (previous,),
                                ).fetchone()
                        if ancestor:
                            physical_base = self._continuation_binding_for_head_locked(
                                connection, physical_head
                            )
                    expected_physical_envelope = (
                        None if physical_base is None else physical_base.envelope_sha256
                    )
                    expected_physical_leaf_envelope = (
                        str(incident["expected_envelope_sha256"])
                        if incident["parent_retirement_operation_id"] is not None
                        else None
                        if physical_base is None
                        else self._completed_vault_leaf_envelope_locked(
                            connection, physical_base
                        )
                    )
                    if (
                        physical_head is None
                        or physical_base is None
                        or physical_head["head_sha256"]
                        != repair_intent_proof.eligible_physical_head_sha256
                        or physical_base
                        != repair_intent_proof.eligible_physical_binding
                        or physical_base.generation
                        != repair_base_authorization.physical_generation
                        or physical_base.previous_active_version + 1
                        != repair_base_authorization.physical_active_version
                        or expected_physical_envelope
                        != repair_base_authorization.physical_envelope_sha256
                        or repair_base_authorization.physical_leaf_envelope_sha256
                        != expected_physical_leaf_envelope
                        or repair_base_authorization.physical_leaf_envelope_sha256
                        != repair_intent_proof.eligible_physical_envelope_sha256
                        or physical_base.position_binding_sha256
                        != repair_base_authorization.physical_position_binding_sha256
                        or next_binding.generation <= physical_base.generation
                        or next_binding.previous_active_version
                        != repair_base_authorization.physical_active_version
                        or next_binding.previous_active_envelope_sha256
                        != expected_physical_envelope
                        or next_binding.runtime_state_sha256
                        != physical_base.runtime_state_sha256
                        or next_binding.page_evidence_sha256
                        != physical_base.page_evidence_sha256
                    ):
                        raise SourceReadLedgerStateConflict(
                            "vault repair physical ACTIVE base is not an exact ancestor"
                        )
                    physical_base_head_sha256 = str(physical_head["head_sha256"])
                    physical_base_ledger_binding_sha256 = (
                        physical_base.ledger_binding_sha256
                    )
                elif physical_base_status == "ABSENT":
                    raise SourceReadLedgerStateConflict(
                        "physical ABSENT repair requires an independent encrypted backup proof"
                    )
                else:
                    raise SourceReadLedgerStateConflict(
                        "vault repair physical status differs"
                    )
            repair_base_authorization_json = _json_material(
                {
                    name: getattr(repair_base_authorization, name)
                    for name in SourceReadVaultStreamRepairBaseAuthorizationReceipt.__dataclass_fields__
                },
                "stream repair vault base authorization",
            )

        prepared_authorization = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_prepared_continuation(
                prepared_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=next_binding.vault_store_identity_sha256,
                slot_sha256=next_binding.slot_sha256,
                operation_id=next_binding.operation_id,
                expected_outcome="STREAM_REPAIR_BOUND",
                ledger_binding_sha256=next_binding.ledger_binding_sha256,
                position_binding_sha256=position.position_binding_sha256,
                generation=next_binding.generation,
                envelope_sha256=next_binding.envelope_sha256,
            ),
            receipt_type=SourceReadVaultPreparedAuthorizationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": next_binding.vault_store_identity_sha256,
                "slot_sha256": next_binding.slot_sha256,
                "operation_id": next_binding.operation_id,
                "expected_outcome": "STREAM_REPAIR_BOUND",
                "ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "position_binding_sha256": position.position_binding_sha256,
                "generation": next_binding.generation,
                "envelope_sha256": next_binding.envelope_sha256,
            },
        )
        lineage = _continuation_lineage_sha256(next_binding)
        authorization = _stream_repair_authorization_from_material(
            _stored_json(
                intent_row["governance_authorization_json"],
                "stream repair intent authorization",
            )
        )
        authorization = _validated_stream_repair_authorization(
            authorization,
            authority_identity_sha256=(
                self.continuation_migration_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            phase="INTENT",
            incident_id=incident_identity,
            repair_id=next_binding.operation_id,
            lineage_sha256=lineage,
            logical_head_sha256=expected_previous_head,
            current_ledger_binding_sha256=current.ledger_binding_sha256,
            next_ledger_binding_sha256=ZERO_SHA256,
            position_binding_sha256=position.position_binding_sha256,
            physical_base_status="ACTIVE",
            physical_base_head_sha256=intent_row["eligible_physical_head_sha256"],
            physical_base_ledger_binding_sha256=(
                intent_row["eligible_physical_ledger_binding_sha256"]
            ),
            repair_base_fence_sha256=None,
            repair_base_authorization_sha256=None,
            activation_evidence_sha256=None,
            occurred_at_utc=str(intent_row["occurred_at_utc"]),
            governance_evidence_sha256=governance,
        )
        next_json = _json_material(next_material, "stream repair binding")
        position_json = _json_material(position_material, "stream repair position")
        authorization_json = str(intent_row["governance_authorization_json"])
        prepared_json = _json_material(
            {
                name: getattr(prepared_authorization, name)
                for name in SourceReadVaultPreparedAuthorizationReceipt.__dataclass_fields__
            },
            "stream repair vault prepared authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR"
                    or row["incident_id"] != incident_identity
                    or row["next_ledger_binding_sha256"]
                    != next_binding.ledger_binding_sha256
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream repair idempotency digest is already bound"
                    )
                return self._stream_repair_binding_from_row(row, replayed=True)
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_continuation_writer_epoch_locked(connection, next_binding)
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=lineage
            )
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (lineage,),
            ).fetchone()
            intent_now = connection.execute(
                """SELECT * FROM source_read_stream_repair_intents
                   WHERE repair_id=? AND incident_id=?""",
                (next_binding.operation_id, incident_identity),
            ).fetchone()
            intent_cancelled = connection.execute(
                """SELECT 1 FROM source_read_stream_repair_intent_cancellations
                   WHERE repair_id=?""",
                (next_binding.operation_id,),
            ).fetchone()
            if (
                intent_now is None
                or intent_cancelled is not None
                or intent_now["intent_sha256"] != intent_row["intent_sha256"]
                or intent_now["logical_head_sha256"] != expected_previous_head
                or intent_now["current_ledger_binding_sha256"]
                != current.ledger_binding_sha256
                or intent_now["eligible_physical_head_sha256"]
                != physical_base_head_sha256
                or intent_now["eligible_physical_ledger_binding_sha256"]
                != physical_base_ledger_binding_sha256
                or intent_now["position_binding_sha256"]
                != position.position_binding_sha256
                or intent_now["governance_evidence_sha256"] != governance
                or state is None
                or state[0]["incident_id"] != incident_identity
                or state[1] is not SourceReadStreamRecoveryState.ACTIVE
                or latest is None
                or latest["head_sha256"] != expected_previous_head
                or latest["ledger_binding_sha256"] != current.ledger_binding_sha256
                or self._continuation_binding_for_head_locked(connection, latest)
                != current
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair lost its incident/latest-head comparison"
                )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_stream_repair_bindings"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_STREAM_REPAIR_BINDING",
                "repair_id": next_binding.operation_id,
                "incident_id": incident_identity,
                "idempotency_sha256": idempotency,
                "lineage_sha256": lineage,
                "current_ledger_binding_sha256": current.ledger_binding_sha256,
                "next_ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "next_binding_json_sha256": _hash_text(next_json),
                "position_binding_sha256": position.position_binding_sha256,
                "position_binding_json_sha256": _hash_text(position_json),
                "previous_head_sha256": str(latest["head_sha256"]),
                "repair_intent_sha256": str(intent_row["intent_sha256"]),
                "physical_base_status": physical_base_status,
                "physical_base_head_sha256": physical_base_head_sha256,
                "physical_base_ledger_binding_sha256": (
                    physical_base_ledger_binding_sha256
                ),
                "repair_base_fence_sha256": repair_base_fence_sha256,
                "vault_repair_base_authorization_sha256": (
                    None
                    if repair_base_authorization is None
                    else repair_base_authorization.authorization_sha256
                ),
                "vault_repair_base_authorization_json_sha256": (
                    None
                    if repair_base_authorization_json is None
                    else _hash_text(repair_base_authorization_json)
                ),
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_prepared_authorization_sha256": (
                    prepared_authorization.authorization_sha256
                ),
                "vault_prepared_authorization_json_sha256": _hash_text(prepared_json),
                "occurred_at_utc": occurred,
            }
            repair_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_stream_repair_bindings(
                       sequence,repair_id,incident_id,idempotency_sha256,
                       lineage_sha256,current_ledger_binding_sha256,
                       next_ledger_binding_sha256,next_binding_json,
                       position_binding_sha256,position_binding_json,
                       previous_head_sha256,repair_intent_sha256,
                       physical_base_status,
                       physical_base_head_sha256,
                       physical_base_ledger_binding_sha256,
                       repair_base_fence_sha256,
                       vault_repair_base_authorization_sha256,
                       vault_repair_base_authorization_json,
                       governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_prepared_authorization_sha256,
                       vault_prepared_authorization_json,occurred_at_utc,
                       repair_binding_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    next_binding.operation_id,
                    incident_identity,
                    idempotency,
                    lineage,
                    current.ledger_binding_sha256,
                    next_binding.ledger_binding_sha256,
                    next_json,
                    position.position_binding_sha256,
                    position_json,
                    latest["head_sha256"],
                    intent_row["intent_sha256"],
                    physical_base_status,
                    physical_base_head_sha256,
                    physical_base_ledger_binding_sha256,
                    repair_base_fence_sha256,
                    (
                        None
                        if repair_base_authorization is None
                        else repair_base_authorization.authorization_sha256
                    ),
                    repair_base_authorization_json,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    prepared_authorization.authorization_sha256,
                    prepared_json,
                    occurred,
                    repair_sha,
                ),
            )
            head_sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_continuation_heads"
                ).fetchone()[0]
            )
            head_material: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_CONTINUATION_HEAD",
                "sequence": head_sequence,
                "lineage_sha256": lineage,
                "generation": next_binding.generation,
                "operation_id": next_binding.operation_id,
                "outcome_id": None,
                "rotation_id": None,
                "migration_id": None,
                "repair_id": next_binding.operation_id,
                "ledger_binding_sha256": next_binding.ledger_binding_sha256,
                "previous_head_sha256": str(latest["head_sha256"]),
            }
            connection.execute(
                """INSERT INTO source_read_continuation_heads(
                       sequence,lineage_sha256,generation,operation_id,outcome_id,
                       rotation_id,migration_id,repair_id,ledger_binding_sha256,
                       previous_head_sha256,head_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    head_sequence,
                    lineage,
                    next_binding.generation,
                    next_binding.operation_id,
                    None,
                    None,
                    None,
                    next_binding.operation_id,
                    next_binding.ledger_binding_sha256,
                    latest["head_sha256"],
                    _value_sha256(head_material),
                ),
            )
            self._append_event_locked(
                connection,
                event_type="STREAM_REPAIR_BOUND",
                entity_kind="STREAM_REPAIR",
                entity_id=next_binding.operation_id + ":BIND",
                entity_sha256=repair_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                "SELECT * FROM source_read_stream_repair_bindings WHERE repair_id=?",
                (next_binding.operation_id,),
            ).fetchone()
            return self._stream_repair_binding_from_row(row, replayed=False)

    def continuation_stream_repair(
        self,
        repair_id: str,
        expected_next_ledger_binding_sha256: str,
    ) -> SourceReadStreamRepairBinding:
        """Fresh readback of the exact anchored repair awaiting vault ACTIVATE."""

        identity = _safe_id(repair_id, "stream repair identity")
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(identity) is None:
            raise SourceReadLedgerValidationError("stream repair identity is invalid")
        expected = _sha256(
            expected_next_ledger_binding_sha256,
            "expected repair ledger binding",
        )
        with self._read() as connection:
            self._verify_locked(connection)
            repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE repair_id=? AND next_ledger_binding_sha256=?""",
                (identity, expected),
            ).fetchone()
            if repair is None:
                raise SourceReadLedgerStateConflict("stream repair readback is absent")
            state = self._latest_stream_incident_locked(
                connection,
                lineage_sha256=str(repair["lineage_sha256"]),
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (repair["lineage_sha256"],),
            ).fetchone()
            if (
                state is None
                or state[0]["incident_id"] != repair["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.REPAIR_BOUND
                or head is None
                or head["repair_id"] != identity
                or head["ledger_binding_sha256"] != expected
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair is not the current activation candidate"
                )
            self._assert_no_active_key_lifecycle_locked(connection)
            return self._stream_repair_binding_from_row(repair, replayed=True)

    def abandon_continuation_stream_repair(
        self,
        repair_id: str,
        expected_ledger_binding_sha256: str,
        absence_proof: object,
        *,
        reason_code: SourceReadPreparedAbsenceReason,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadStreamRepairAbandonment:
        """Anchor one failed PREPARED attempt while retaining the full stream hold."""

        identity = _safe_id(repair_id, "stream repair identity")
        if (
            _STREAM_REPAIR_OPERATION_ID.fullmatch(identity) is None
            or type(reason_code) is not SourceReadPreparedAbsenceReason
        ):
            raise SourceReadLedgerValidationError(
                "stream repair abandonment identity/reason differs"
            )
        expected = _sha256(
            expected_ledger_binding_sha256,
            "expected abandoned repair binding",
        )
        governance = _sha256(
            governance_evidence_sha256,
            "repair abandonment governance evidence",
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._continuation_migration_authority is None
            or self.continuation_migration_authority_identity_sha256 is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "repair abandonment requires pinned anchor, vault verifier, and SoD authority"
            )
        with self._read() as connection:
            repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE repair_id=? AND next_ledger_binding_sha256=?""",
                (identity, expected),
            ).fetchone()
            if repair is None:
                raise SourceReadLedgerStateConflict(
                    "repair abandonment source is absent"
                )
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_ABANDONMENT"
                    or row["repair_id"] != identity
                    or row["incident_id"] != repair["incident_id"]
                    or row["reason_code"] != reason_code.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "repair abandonment idempotency digest is already bound"
                    )
                return self._stream_repair_abandonment_from_row(
                    row, repair, replayed=True
                )
            self._assert_no_active_key_lifecycle_locked(connection)
            state = self._latest_stream_incident_locked(
                connection,
                lineage_sha256=str(repair["lineage_sha256"]),
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (repair["lineage_sha256"],),
            ).fetchone()
            if (
                state is None
                or state[0]["incident_id"] != repair["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.REPAIR_BOUND
                or head is None
                or head["repair_id"] != identity
                or head["ledger_binding_sha256"] != expected
            ):
                raise SourceReadLedgerStateConflict(
                    "repair abandonment requires the exact latest bound attempt"
                )
            binding = _continuation_binding_from_material(
                _stored_json(repair["next_binding_json"], "stream repair binding")
            )

        vault_absence = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_prepared_continuation_absence(
                absence_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=binding.vault_store_identity_sha256,
                slot_sha256=binding.slot_sha256,
                operation_id=identity,
                ledger_binding_sha256=binding.ledger_binding_sha256,
                position_binding_sha256=str(repair["position_binding_sha256"]),
                generation=binding.generation,
                envelope_sha256=binding.envelope_sha256,
                reason_code=reason_code.value,
            ),
            receipt_type=SourceReadVaultPreparedAbsenceAuthorizationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": binding.vault_store_identity_sha256,
                "slot_sha256": binding.slot_sha256,
                "operation_id": identity,
                "ledger_binding_sha256": binding.ledger_binding_sha256,
                "position_binding_sha256": str(repair["position_binding_sha256"]),
                "generation": binding.generation,
                "envelope_sha256": binding.envelope_sha256,
                "reason_code": reason_code.value,
                "occurred_at_utc": occurred,
            },
        )
        observation = vault_absence.observation_sha256
        authorization = _validated_stream_repair_authorization(
            self._continuation_migration_authority.authorize_stream_repair(
                store_identity_sha256=self.store_identity_sha256,
                phase="ABANDON",
                incident_id=str(repair["incident_id"]),
                repair_id=identity,
                lineage_sha256=str(repair["lineage_sha256"]),
                logical_head_sha256=str(repair["previous_head_sha256"]),
                current_ledger_binding_sha256=str(
                    repair["current_ledger_binding_sha256"]
                ),
                next_ledger_binding_sha256=binding.ledger_binding_sha256,
                position_binding_sha256=str(repair["position_binding_sha256"]),
                physical_base_status=str(repair["physical_base_status"]),
                physical_base_head_sha256=repair["physical_base_head_sha256"],
                physical_base_ledger_binding_sha256=repair[
                    "physical_base_ledger_binding_sha256"
                ],
                repair_base_fence_sha256=repair["repair_base_fence_sha256"],
                repair_base_authorization_sha256=repair[
                    "vault_repair_base_authorization_sha256"
                ],
                activation_evidence_sha256=observation,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=(
                self.continuation_migration_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            phase="ABANDON",
            incident_id=str(repair["incident_id"]),
            repair_id=identity,
            lineage_sha256=str(repair["lineage_sha256"]),
            logical_head_sha256=str(repair["previous_head_sha256"]),
            current_ledger_binding_sha256=str(repair["current_ledger_binding_sha256"]),
            next_ledger_binding_sha256=binding.ledger_binding_sha256,
            position_binding_sha256=str(repair["position_binding_sha256"]),
            physical_base_status=str(repair["physical_base_status"]),
            physical_base_head_sha256=repair["physical_base_head_sha256"],
            physical_base_ledger_binding_sha256=repair[
                "physical_base_ledger_binding_sha256"
            ],
            repair_base_fence_sha256=repair["repair_base_fence_sha256"],
            repair_base_authorization_sha256=repair[
                "vault_repair_base_authorization_sha256"
            ],
            activation_evidence_sha256=observation,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadStreamRepairAuthorizationReceipt.__dataclass_fields__
            },
            "repair abandonment governance authorization",
        )
        vault_json = _json_material(
            {
                name: getattr(vault_absence, name)
                for name in SourceReadVaultPreparedAbsenceAuthorizationReceipt.__dataclass_fields__
            },
            "repair PREPARED absence authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_ABANDONMENT"
                    or row["repair_id"] != identity
                    or row["reason_code"] != reason_code.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "repair abandonment idempotency digest is already bound"
                    )
                return self._stream_repair_abandonment_from_row(
                    row, repair, replayed=True
                )
            self._assert_no_active_key_lifecycle_locked(connection)
            state = self._latest_stream_incident_locked(
                connection,
                lineage_sha256=str(repair["lineage_sha256"]),
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (repair["lineage_sha256"],),
            ).fetchone()
            if (
                state is None
                or state[0]["incident_id"] != repair["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.REPAIR_BOUND
                or head is None
                or head["repair_id"] != identity
                or head["ledger_binding_sha256"] != expected
            ):
                raise SourceReadLedgerStateConflict(
                    "repair abandonment lost its latest-head comparison"
                )
            sequence = int(
                connection.execute(
                    """SELECT COALESCE(MAX(sequence),0)+1
                       FROM source_read_stream_repair_abandonments"""
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_STREAM_REPAIR_ABANDONMENT",
                "repair_id": identity,
                "incident_id": str(repair["incident_id"]),
                "idempotency_sha256": idempotency,
                "reason_code": reason_code.value,
                "observation_sha256": observation,
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": (authorization.authorization_sha256),
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_absence_authorization_sha256": (
                    vault_absence.authorization_sha256
                ),
                "vault_absence_authorization_json_sha256": _hash_text(vault_json),
                "occurred_at_utc": occurred,
            }
            abandonment_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_stream_repair_abandonments(
                       sequence,repair_id,incident_id,idempotency_sha256,
                       reason_code,observation_sha256,governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_absence_authorization_sha256,
                       vault_absence_authorization_json,occurred_at_utc,
                       abandonment_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    identity,
                    repair["incident_id"],
                    idempotency,
                    reason_code.value,
                    observation,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    vault_absence.authorization_sha256,
                    vault_json,
                    occurred,
                    abandonment_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="STREAM_REPAIR_ABANDONED",
                entity_kind="STREAM_REPAIR",
                entity_id=identity + ":ABANDON",
                entity_sha256=abandonment_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                """SELECT * FROM source_read_stream_repair_abandonments
                   WHERE repair_id=?""",
                (identity,),
            ).fetchone()
            return self._stream_repair_abandonment_from_row(row, repair, replayed=False)

    def stream_repair_activation_proof(
        self, repair_id: str, expected_ledger_binding_sha256: str
    ) -> SourceReadStreamRepairActivationProof:
        repair_identity = _safe_id(repair_id, "stream repair identity")
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(repair_identity) is None:
            raise SourceReadLedgerValidationError("stream repair identity is invalid")
        expected = _sha256(
            expected_ledger_binding_sha256,
            "expected repair ledger binding",
        )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            self._assert_no_active_key_lifecycle_locked(connection)
            repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE repair_id=? AND next_ledger_binding_sha256=?""",
                (repair_identity, expected),
            ).fetchone()
            if (
                repair is None
                or connection.execute(
                    "SELECT 1 FROM source_read_stream_repair_dispositions WHERE repair_id=?",
                    (repair_identity,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair binding is absent, completed, or stale"
                )
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=str(repair["lineage_sha256"])
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (repair["lineage_sha256"],),
            ).fetchone()
            if (
                state is None
                or state[0]["incident_id"] != repair["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.REPAIR_BOUND
                or head is None
                or head["repair_id"] != repair_identity
                or head["ledger_binding_sha256"] != expected
                or verification.external_anchor_generation <= 0
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair is not the anchored latest repair head"
                )
            binding = _continuation_binding_from_material(
                _stored_json(repair["next_binding_json"], "stream repair binding")
            )
            event = self._entity_event_locked(
                connection, "STREAM_REPAIR", repair_identity + ":BIND"
            )
            return self._mint_stream_repair_activation_proof(
                binding=binding,
                repair_id=repair_identity,
                incident_id=str(repair["incident_id"]),
                position_binding_sha256=str(repair["position_binding_sha256"]),
                repair_base_fence_sha256=(
                    None
                    if repair["repair_base_fence_sha256"] is None
                    else str(repair["repair_base_fence_sha256"])
                ),
                repair_binding_sha256=str(repair["repair_binding_sha256"]),
                repair_event_sha256=str(event["event_sha256"]),
                continuation_head_sha256=str(head["head_sha256"]),
                verification=verification,
            )

    def verify_latest_stream_repair_activation_proof(
        self, proof: SourceReadStreamRepairActivationProof
    ) -> bool:
        if not self._stream_repair_proof_is_known(proof):
            return False
        try:
            with self._read() as connection:
                verification = self._verify_locked(connection)
                self._assert_authority_approval_fence_locked(connection)
                self._assert_no_active_key_lifecycle_locked(connection)
                repair = connection.execute(
                    "SELECT * FROM source_read_stream_repair_bindings WHERE repair_id=?",
                    (proof.repair_id,),
                ).fetchone()
                head = connection.execute(
                    """SELECT * FROM source_read_continuation_heads
                       WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                    (_continuation_lineage_sha256(proof.binding),),
                ).fetchone()
                state = self._latest_stream_incident_locked(
                    connection,
                    lineage_sha256=_continuation_lineage_sha256(proof.binding),
                )
                event = connection.execute(
                    """SELECT * FROM source_read_events
                       WHERE entity_kind='STREAM_REPAIR' AND entity_id=?""",
                    (proof.repair_id + ":BIND",),
                ).fetchone()
                return bool(
                    repair is not None
                    and head is not None
                    and state is not None
                    and state[0]["incident_id"] == proof.incident_id
                    and state[1] is SourceReadStreamRecoveryState.REPAIR_BOUND
                    and connection.execute(
                        "SELECT 1 FROM source_read_stream_repair_dispositions WHERE repair_id=?",
                        (proof.repair_id,),
                    ).fetchone()
                    is None
                    and _continuation_binding_from_material(
                        _stored_json(
                            repair["next_binding_json"], "stream repair binding"
                        )
                    )
                    == proof.binding
                    and repair["position_binding_sha256"]
                    == proof.position_binding_sha256
                    and repair["repair_base_fence_sha256"]
                    == proof.repair_base_fence_sha256
                    and repair["repair_binding_sha256"] == proof.repair_binding_sha256
                    and head["head_sha256"] == proof.continuation_head_sha256
                    and head["ledger_binding_sha256"]
                    == proof.binding.ledger_binding_sha256
                    and event is not None
                    and event["event_sha256"] == proof.repair_event_sha256
                    and verification.external_anchor_generation
                    >= proof.external_anchor_generation
                    and verification.external_anchor_generation > 0
                )
        except SourceReadLedgerError:
            return False

    def complete_continuation_stream_repair(
        self,
        repair_id: str,
        expected_ledger_binding_sha256: str,
        activation_proof: object,
        *,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadStreamRepairDisposition:
        """Resolve quarantine only after exact vault ACTIVATE and SoD ACK."""

        repair_identity = _safe_id(repair_id, "stream repair identity")
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(repair_identity) is None:
            raise SourceReadLedgerValidationError("stream repair identity is invalid")
        expected_binding = _sha256(
            expected_ledger_binding_sha256,
            "expected repair ledger binding",
        )
        governance = _sha256(
            governance_evidence_sha256, "stream repair governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._continuation_migration_authority is None
            or self.continuation_migration_authority_identity_sha256 is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "stream repair completion requires pinned anchor, vault verifier, and SoD authority"
            )
        with self._read() as connection:
            self._assert_no_active_key_lifecycle_locked(connection)
            repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE repair_id=? AND next_ledger_binding_sha256=?""",
                (repair_identity, expected_binding),
            ).fetchone()
            if repair is None:
                raise SourceReadLedgerStateConflict("stream repair binding is absent")
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_DISPOSITION"
                    or row["repair_id"] != repair_identity
                    or row["incident_id"] != repair["incident_id"]
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream repair completion idempotency digest is already bound"
                    )
                return self._stream_repair_disposition_from_row(
                    row, repair, replayed=True
                )
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=str(repair["lineage_sha256"])
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (repair["lineage_sha256"],),
            ).fetchone()
            if (
                state is None
                or state[0]["incident_id"] != repair["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.REPAIR_BOUND
                or head is None
                or head["repair_id"] != repair_identity
                or head["ledger_binding_sha256"] != expected_binding
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair is not the exact active repair head"
                )
            binding = _continuation_binding_from_material(
                _stored_json(repair["next_binding_json"], "stream repair binding")
            )

        vault_activation = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_stream_repair_activation(
                activation_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=binding.vault_store_identity_sha256,
                slot_sha256=binding.slot_sha256,
                generation=binding.generation,
                envelope_sha256=binding.envelope_sha256,
                repair_id=repair_identity,
                incident_id=str(repair["incident_id"]),
                next_ledger_binding_sha256=binding.ledger_binding_sha256,
                repair_base_fence_sha256=repair["repair_base_fence_sha256"],
            ),
            receipt_type=SourceReadVaultStreamRepairActivationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": binding.vault_store_identity_sha256,
                "slot_sha256": binding.slot_sha256,
                "generation": binding.generation,
                "active_version": binding.previous_active_version + 1,
                "envelope_sha256": binding.envelope_sha256,
                "repair_id": repair_identity,
                "incident_id": str(repair["incident_id"]),
                "next_ledger_binding_sha256": binding.ledger_binding_sha256,
                "repair_base_fence_sha256": repair["repair_base_fence_sha256"],
            },
        )
        activation_evidence = vault_activation.activation_sha256
        authorization = _validated_stream_repair_authorization(
            self._continuation_migration_authority.authorize_stream_repair(
                store_identity_sha256=self.store_identity_sha256,
                phase="COMPLETE",
                incident_id=str(repair["incident_id"]),
                repair_id=repair_identity,
                lineage_sha256=str(repair["lineage_sha256"]),
                logical_head_sha256=str(repair["previous_head_sha256"]),
                current_ledger_binding_sha256=str(
                    repair["current_ledger_binding_sha256"]
                ),
                next_ledger_binding_sha256=binding.ledger_binding_sha256,
                position_binding_sha256=str(repair["position_binding_sha256"]),
                physical_base_status=str(repair["physical_base_status"]),
                physical_base_head_sha256=repair["physical_base_head_sha256"],
                physical_base_ledger_binding_sha256=repair[
                    "physical_base_ledger_binding_sha256"
                ],
                repair_base_fence_sha256=repair["repair_base_fence_sha256"],
                repair_base_authorization_sha256=repair[
                    "vault_repair_base_authorization_sha256"
                ],
                activation_evidence_sha256=activation_evidence,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=(
                self.continuation_migration_authority_identity_sha256
            ),
            store_identity_sha256=self.store_identity_sha256,
            phase="COMPLETE",
            incident_id=str(repair["incident_id"]),
            repair_id=repair_identity,
            lineage_sha256=str(repair["lineage_sha256"]),
            logical_head_sha256=str(repair["previous_head_sha256"]),
            current_ledger_binding_sha256=str(repair["current_ledger_binding_sha256"]),
            next_ledger_binding_sha256=binding.ledger_binding_sha256,
            position_binding_sha256=str(repair["position_binding_sha256"]),
            physical_base_status=str(repair["physical_base_status"]),
            physical_base_head_sha256=repair["physical_base_head_sha256"],
            physical_base_ledger_binding_sha256=repair[
                "physical_base_ledger_binding_sha256"
            ],
            repair_base_fence_sha256=repair["repair_base_fence_sha256"],
            repair_base_authorization_sha256=repair[
                "vault_repair_base_authorization_sha256"
            ],
            activation_evidence_sha256=activation_evidence,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadStreamRepairAuthorizationReceipt.__dataclass_fields__
            },
            "stream repair completion authorization",
        )
        vault_activation_json = _json_material(
            {
                name: getattr(vault_activation, name)
                for name in SourceReadVaultStreamRepairActivationReceipt.__dataclass_fields__
            },
            "stream repair vault activation authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_REPAIR_DISPOSITION"
                    or row["repair_id"] != repair_identity
                    or row["incident_id"] != repair["incident_id"]
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream repair completion idempotency digest is already bound"
                    )
                return self._stream_repair_disposition_from_row(
                    row, repair, replayed=True
                )
            self._assert_no_active_key_lifecycle_locked(connection)
            current_repair = connection.execute(
                "SELECT * FROM source_read_stream_repair_bindings WHERE repair_id=?",
                (repair_identity,),
            ).fetchone()
            state = self._latest_stream_incident_locked(
                connection, lineage_sha256=str(repair["lineage_sha256"])
            )
            head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (repair["lineage_sha256"],),
            ).fetchone()
            if (
                current_repair is None
                or current_repair["repair_binding_sha256"]
                != repair["repair_binding_sha256"]
                or state is None
                or state[0]["incident_id"] != repair["incident_id"]
                or state[1] is not SourceReadStreamRecoveryState.REPAIR_BOUND
                or head is None
                or head["repair_id"] != repair_identity
                or head["ledger_binding_sha256"] != expected_binding
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair state changed before completion"
                )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_stream_repair_dispositions"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_STREAM_REPAIR_DISPOSITION",
                "repair_id": repair_identity,
                "incident_id": repair["incident_id"],
                "idempotency_sha256": idempotency,
                "activation_evidence_sha256": activation_evidence,
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_activation_authorization_sha256": (
                    vault_activation.authorization_sha256
                ),
                "vault_activation_authorization_json_sha256": _hash_text(
                    vault_activation_json
                ),
                "occurred_at_utc": occurred,
            }
            disposition_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_stream_repair_dispositions(
                       sequence,repair_id,incident_id,idempotency_sha256,
                       activation_evidence_sha256,governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_activation_authorization_sha256,
                       vault_activation_authorization_json,occurred_at_utc,
                       disposition_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    repair_identity,
                    repair["incident_id"],
                    idempotency,
                    activation_evidence,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    vault_activation.authorization_sha256,
                    vault_activation_json,
                    occurred,
                    disposition_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="STREAM_REPAIRED",
                entity_kind="STREAM_REPAIR",
                entity_id=repair_identity + ":COMPLETE",
                entity_sha256=disposition_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                "SELECT * FROM source_read_stream_repair_dispositions WHERE repair_id=?",
                (repair_identity,),
            ).fetchone()
            return self._stream_repair_disposition_from_row(row, repair, replayed=False)

    def continuation_stream_repair_disposition(
        self,
        repair_id: str,
        expected_next_ledger_binding_sha256: str,
    ) -> SourceReadStreamRepairDisposition:
        """Read one anchored repair disposition without requiring latest head.

        This is a custody readback only.  It grants no dispatch or activation
        authority and remains usable after a later page advances the lineage.
        """

        repair_identity = _safe_id(repair_id, "stream repair identity")
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(repair_identity) is None:
            raise SourceReadLedgerValidationError("stream repair identity is invalid")
        expected_binding = _sha256(
            expected_next_ledger_binding_sha256,
            "expected repair ledger binding",
        )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE repair_id=? AND next_ledger_binding_sha256=?""",
                (repair_identity, expected_binding),
            ).fetchone()
            disposition = connection.execute(
                """SELECT * FROM source_read_stream_repair_dispositions
                   WHERE repair_id=?""",
                (repair_identity,),
            ).fetchone()
            event = connection.execute(
                """SELECT * FROM source_read_events
                   WHERE entity_kind='STREAM_REPAIR' AND entity_id=?""",
                (repair_identity + ":COMPLETE",),
            ).fetchone()
            if (
                repair is None
                or disposition is None
                or event is None
                or event["entity_sha256"] != disposition["disposition_sha256"]
                or verification.external_anchor_generation <= 0
                or not verification.external_anchor_status.startswith("ANCHORED_")
            ):
                raise SourceReadLedgerStateConflict(
                    "anchored stream repair disposition is absent"
                )
            return self._stream_repair_disposition_from_row(
                disposition,
                repair,
                replayed=True,
            )

    def continuation_stream_repair_record(
        self,
        repair_id: str,
    ) -> SourceReadStreamRepairRecord:
        """Read an anchored repair by identity without minting authority.

        Unlike activation/disposition proof APIs, this indexed readback does
        not require the repair binding to remain the latest lineage head.  It
        is therefore suitable for crash replay after a later page has already
        advanced the continuation.
        """

        identity = _safe_id(repair_id, "stream repair identity")
        if _STREAM_REPAIR_OPERATION_ID.fullmatch(identity) is None:
            raise SourceReadLedgerValidationError("stream repair identity is invalid")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            intent_row = connection.execute(
                "SELECT * FROM source_read_stream_repair_intents WHERE repair_id=?",
                (identity,),
            ).fetchone()
            if intent_row is None:
                raise SourceReadLedgerStateConflict("stream repair record is absent")
            binding_row = connection.execute(
                "SELECT * FROM source_read_stream_repair_bindings WHERE repair_id=?",
                (identity,),
            ).fetchone()
            cancellation_row = connection.execute(
                """SELECT * FROM source_read_stream_repair_intent_cancellations
                   WHERE repair_id=?""",
                (identity,),
            ).fetchone()
            abandonment_row = connection.execute(
                """SELECT * FROM source_read_stream_repair_abandonments
                   WHERE repair_id=?""",
                (identity,),
            ).fetchone()
            disposition_row = connection.execute(
                """SELECT * FROM source_read_stream_repair_dispositions
                   WHERE repair_id=?""",
                (identity,),
            ).fetchone()
            if cancellation_row is not None:
                phase = SourceReadStreamRepairRecordPhase.INTENT_CANCELLED
                event_kind = "STREAM_REPAIR_INTENT_CANCEL"
                event_id = identity
                terminal_sha256 = str(cancellation_row["cancellation_sha256"])
            elif disposition_row is not None:
                phase = SourceReadStreamRepairRecordPhase.RESOLVED
                event_kind = "STREAM_REPAIR"
                event_id = identity + ":COMPLETE"
                terminal_sha256 = str(disposition_row["disposition_sha256"])
            elif abandonment_row is not None:
                phase = SourceReadStreamRepairRecordPhase.ABANDONED
                event_kind = "STREAM_REPAIR"
                event_id = identity + ":ABANDON"
                terminal_sha256 = str(abandonment_row["abandonment_sha256"])
            elif binding_row is not None:
                phase = SourceReadStreamRepairRecordPhase.REPAIR_BOUND
                event_kind = "STREAM_REPAIR"
                event_id = identity + ":BIND"
                terminal_sha256 = str(binding_row["repair_binding_sha256"])
            else:
                phase = SourceReadStreamRepairRecordPhase.INTENT
                event_kind = "STREAM_REPAIR_INTENT"
                event_id = identity
                terminal_sha256 = str(intent_row["intent_sha256"])
            event = connection.execute(
                """SELECT * FROM source_read_events
                   WHERE entity_kind=? AND entity_id=?""",
                (event_kind, event_id),
            ).fetchone()
            if (
                event is None
                or event["entity_sha256"] != terminal_sha256
                or verification.external_anchor_generation <= 0
                or not verification.external_anchor_status.startswith("ANCHORED_")
            ):
                raise SourceReadLedgerStateConflict(
                    "stream repair record is not externally anchored"
                )
            intent = self._stream_repair_intent_from_row(intent_row, replayed=True)
            binding = (
                None
                if binding_row is None
                else self._stream_repair_binding_from_row(binding_row, replayed=True)
            )
            cancellation = (
                None
                if cancellation_row is None
                else self._stream_repair_intent_cancellation_from_row(
                    cancellation_row, replayed=True
                )
            )
            abandonment = (
                None
                if abandonment_row is None or binding_row is None
                else self._stream_repair_abandonment_from_row(
                    abandonment_row, binding_row, replayed=True
                )
            )
            disposition = (
                None
                if disposition_row is None or binding_row is None
                else self._stream_repair_disposition_from_row(
                    disposition_row, binding_row, replayed=True
                )
            )
            next_binding_sha256 = (
                None
                if binding_row is None
                else str(binding_row["next_ledger_binding_sha256"])
            )
            record_sha256 = _value_sha256(
                {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "SOURCE_READ_STREAM_REPAIR_READBACK",
                    "repair_id": identity,
                    "incident_id": str(intent_row["incident_id"]),
                    "lineage_sha256": str(intent_row["lineage_sha256"]),
                    "store_identity_sha256": self.store_identity_sha256,
                    "phase": phase.value,
                    "intent_sha256": str(intent_row["intent_sha256"]),
                    "repair_binding_sha256": (
                        None
                        if binding_row is None
                        else str(binding_row["repair_binding_sha256"])
                    ),
                    "intent_cancellation_sha256": (
                        None
                        if cancellation_row is None
                        else str(cancellation_row["cancellation_sha256"])
                    ),
                    "abandonment_sha256": (
                        None
                        if abandonment_row is None
                        else str(abandonment_row["abandonment_sha256"])
                    ),
                    "disposition_sha256": (
                        None
                        if disposition_row is None
                        else str(disposition_row["disposition_sha256"])
                    ),
                    "next_ledger_binding_sha256": next_binding_sha256,
                    "terminal_event_sha256": str(event["event_sha256"]),
                }
            )
            return SourceReadStreamRepairRecord(
                identity,
                str(intent_row["incident_id"]),
                str(intent_row["lineage_sha256"]),
                self.store_identity_sha256,
                phase,
                intent,
                binding,
                cancellation,
                abandonment,
                disposition,
                next_binding_sha256,
                str(event["event_sha256"]),
                verification.head_event_sha256,
                verification.external_anchor_generation,
                verification.external_anchor_receipt_sha256,
                record_sha256,
            )

    def verify_continuation_stream_repair_record(
        self,
        record: SourceReadStreamRepairRecord,
    ) -> bool:
        """Freshly rederive an exact historical readback for a vault consumer."""

        if type(record) is not SourceReadStreamRepairRecord:
            return False
        try:
            fresh = self.continuation_stream_repair_record(record.repair_id)
            return bool(
                fresh == record
                and record.store_identity_sha256 == self.store_identity_sha256
                and record.replayed is True
                and record.live_release_eligible is False
            )
        except SourceReadLedgerError:
            return False

    def _ensure_key_compromise_detection(
        self,
        request: SourceReadKeyRetirementRequest,
    ) -> None:
        if (
            request.reason is not SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
            or request.incident_evidence_sha256 is None
        ):
            raise SourceReadLedgerValidationError(
                "key compromise detection requires exact compromise evidence"
            )
        stable_identity = {
            "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
            "record_kind": "KEY_COMPROMISE_DETECTION_IDENTITY",
            "operation_id": request.operation_id,
            "vault_store_identity_sha256": request.vault_store_identity_sha256,
            "retiring_key_id_sha256": _hash_text(request.retiring_key_id),
            "successor_key_id_sha256": _hash_text(request.successor_key_id),
            "incident_evidence_sha256": request.incident_evidence_sha256,
            "retiring_epoch_sha256": request.retiring_epoch_sha256,
            "successor_epoch_sha256": request.successor_epoch_sha256,
            "custody_identity_sha256": request.custody_identity_sha256,
            "expected_custody_generation": request.expected_custody_generation,
            "expected_previous_custody_receipt_sha256": (
                request.expected_previous_custody_receipt_sha256
            ),
            "governance_evidence_sha256": request.governance_evidence_sha256,
        }
        stable_identity_sha256 = _value_sha256(stable_identity)
        detection_id = "source-read-key-compromise-" + stable_identity_sha256[:32]
        idempotency = _value_sha256(
            {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "KEY_COMPROMISE_DETECTION_IDEMPOTENCY",
                "stable_identity_sha256": stable_identity_sha256,
            }
        )
        with self._write() as connection:
            existing = connection.execute(
                """SELECT * FROM source_read_key_compromise_detections
                   WHERE operation_id=?""",
                (request.operation_id,),
            ).fetchone()
            if existing is not None:
                existing_identity = {
                    "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                    "record_kind": "KEY_COMPROMISE_DETECTION_IDENTITY",
                    "operation_id": existing["operation_id"],
                    "vault_store_identity_sha256": existing[
                        "vault_store_identity_sha256"
                    ],
                    "retiring_key_id_sha256": existing["retiring_key_id_sha256"],
                    "successor_key_id_sha256": existing["successor_key_id_sha256"],
                    "incident_evidence_sha256": existing["incident_evidence_sha256"],
                    "retiring_epoch_sha256": existing["retiring_epoch_sha256"],
                    "successor_epoch_sha256": existing["successor_epoch_sha256"],
                    "custody_identity_sha256": existing["custody_identity_sha256"],
                    "expected_custody_generation": existing[
                        "expected_custody_generation"
                    ],
                    "expected_previous_custody_receipt_sha256": existing[
                        "expected_previous_custody_receipt_sha256"
                    ],
                    "governance_evidence_sha256": existing[
                        "governance_evidence_sha256"
                    ],
                }
                if existing_identity != stable_identity:
                    raise SourceReadLedgerIdempotencyConflict(
                        "key compromise detection identity is already bound"
                    )
                return
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                raise SourceReadLedgerIdempotencyConflict(
                    "key compromise detection idempotency is already bound"
                )
            sequence = int(
                connection.execute(
                    """SELECT COALESCE(MAX(sequence),0)+1
                       FROM source_read_key_compromise_detections"""
                ).fetchone()[0]
            )
            detection_event_sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_events"
                ).fetchone()[0]
            )
            containment_disposition, blocking_state_sha256 = (
                self._key_compromise_blocking_state_locked(
                    connection,
                    vault_store_identity_sha256=(request.vault_store_identity_sha256),
                    before_event_sequence=detection_event_sequence,
                )
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_KEY_COMPROMISE_DETECTION",
                "detection_id": detection_id,
                "operation_id": request.operation_id,
                "idempotency_sha256": idempotency,
                "vault_store_identity_sha256": (request.vault_store_identity_sha256),
                "retiring_key_id_sha256": _hash_text(request.retiring_key_id),
                "successor_key_id_sha256": _hash_text(request.successor_key_id),
                "incident_evidence_sha256": request.incident_evidence_sha256,
                "retiring_epoch_sha256": request.retiring_epoch_sha256,
                "successor_epoch_sha256": request.successor_epoch_sha256,
                "custody_identity_sha256": request.custody_identity_sha256,
                "expected_custody_generation": (request.expected_custody_generation),
                "expected_previous_custody_receipt_sha256": (
                    request.expected_previous_custody_receipt_sha256
                ),
                "governance_evidence_sha256": (request.governance_evidence_sha256),
                "containment_disposition": containment_disposition,
                "blocking_state_sha256": blocking_state_sha256,
                "occurred_at_utc": request.occurred_at_utc,
            }
            detection_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_key_compromise_detections(
                       sequence,detection_id,operation_id,idempotency_sha256,
                       vault_store_identity_sha256,retiring_key_id_sha256,
                       successor_key_id_sha256,incident_evidence_sha256,
                       retiring_epoch_sha256,successor_epoch_sha256,
                       custody_identity_sha256,expected_custody_generation,
                       expected_previous_custody_receipt_sha256,
                       governance_evidence_sha256,containment_disposition,
                       blocking_state_sha256,occurred_at_utc,detection_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    detection_id,
                    request.operation_id,
                    idempotency,
                    request.vault_store_identity_sha256,
                    _hash_text(request.retiring_key_id),
                    _hash_text(request.successor_key_id),
                    request.incident_evidence_sha256,
                    request.retiring_epoch_sha256,
                    request.successor_epoch_sha256,
                    request.custody_identity_sha256,
                    request.expected_custody_generation,
                    request.expected_previous_custody_receipt_sha256,
                    request.governance_evidence_sha256,
                    containment_disposition,
                    blocking_state_sha256,
                    request.occurred_at_utc,
                    detection_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="KEY_COMPROMISE_DETECTED",
                entity_kind="KEY_LIFECYCLE",
                entity_id=request.operation_id + ":DETECTED",
                entity_sha256=detection_sha,
                occurred_at_utc=request.occurred_at_utc,
            )

    def request_runtime_vault_key_retirement(
        self,
        request: SourceReadKeyRetirementRequest,
        *,
        writer_epoch_candidate_proof: object,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadVaultKeyRetirement:
        """Anchor SoD authorization before the vault may fence a retiring key."""

        request_material = _key_retirement_request_dto_material(request)
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if occurred != request.occurred_at_utc:
            raise SourceReadLedgerValidationError(
                "key retirement request time must be exact"
            )
        if self._external_anchor is None:
            raise SourceReadLedgerStateConflict(
                "key compromise detection requires a pinned monotonic anchor"
            )
        if request.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT:
            # This is the first durable action.  External alignment/SoD may
            # fail or time out afterwards, but dispatch is already fenced.
            self._ensure_key_compromise_detection(request)
        if (
            self._key_retirement_authority is None
            or self.key_retirement_authority_identity_sha256 is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "key retirement requires pinned anchor, vault alignment, and SoD authority"
            )
        # An already anchored exact replay must not re-consume a one-shot SoD
        # grant.  This read path verifies the full ledger+external anchor first
        # and returns only the persisted canonical result.
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                stored_request = (
                    _key_retirement_request_from_material(
                        _stored_json(row["request_json"], "key retirement request")
                    )
                    if kind == "KEY_RETIREMENT_REQUEST"
                    else None
                )
                if kind != "KEY_RETIREMENT_REQUEST" or stored_request != request:
                    raise SourceReadLedgerIdempotencyConflict(
                        "key retirement request idempotency digest is already bound"
                    )
                return SourceReadVaultKeyRetirement(
                    request.operation_id,
                    request.request_sha256,
                    SourceReadKeyLifecycleState.ACTIVE,
                    request.governance_evidence_sha256,
                    str(row["governance_authorization_sha256"]),
                    None,
                    str(row["record_sha256"]),
                    str(row["occurred_at_utc"]),
                    True,
                )
            self._assert_no_active_key_lifecycle_locked(
                connection,
                ignore_compromise_operation_id=(
                    request.operation_id
                    if request.reason
                    is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                    else None
                ),
            )
            if request.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, request.operation_id
                )
            self._assert_no_unresolved_stream_incidents_locked(
                connection,
                vault_store_identity_sha256=request.vault_store_identity_sha256,
            )
            if (
                connection.execute(
                    """SELECT 1 FROM source_read_operations op
                   WHERE NOT EXISTS(
                       SELECT 1 FROM source_read_outcomes o
                       WHERE o.operation_id=op.operation_id
                         AND o.outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')
                   ) LIMIT 1"""
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement request requires no unresolved source reads"
                )
            self._assert_retiring_key_not_completed_locked(connection, request)
            self._assert_writer_epoch_history_capacity_locked(
                connection, request.vault_store_identity_sha256
            )
            alignment_heads = self._vault_alignment_heads_locked(
                connection,
                request.vault_store_identity_sha256,
            )
            alignment_heads_sha = _vault_alignment_heads_sha256(alignment_heads)
            previous_writer_epoch = self._runtime_vault_writer_epoch_locked(
                connection,
                request.vault_store_identity_sha256,
                replayed=True,
            )
            if previous_writer_epoch.state not in {
                SourceReadRuntimeVaultWriterEpochState.UNMANAGED,
                SourceReadRuntimeVaultWriterEpochState.ACTIVE,
            }:
                raise SourceReadLedgerStateConflict(
                    "vault writer epoch already has an unresolved transition"
                )
            retiring_key_sha = _hash_text(request.retiring_key_id)
            successor_key_sha = _hash_text(request.successor_key_id)
            successor_already_active = bool(
                previous_writer_epoch.state
                is SourceReadRuntimeVaultWriterEpochState.ACTIVE
                and previous_writer_epoch.writer_key_id_sha256 == successor_key_sha
                and previous_writer_epoch.writer_key_epoch_sha256
                == request.successor_epoch_sha256
            )
            if (
                previous_writer_epoch.state
                is SourceReadRuntimeVaultWriterEpochState.ACTIVE
                and not successor_already_active
                and (
                    previous_writer_epoch.writer_key_id_sha256 != retiring_key_sha
                    or previous_writer_epoch.writer_key_epoch_sha256
                    != request.retiring_epoch_sha256
                )
            ):
                raise SourceReadLedgerStateConflict(
                    "retirement request keys differ from the current writer epoch"
                )
        transition_mode = (
            SourceReadRuntimeVaultWriterEpochTransitionMode.SUCCESSOR_ALREADY_ACTIVE
            if successor_already_active
            else SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION
        )
        if successor_already_active:
            current_writer = _validated_vault_factory_receipt(
                self._vault_lifecycle_authority.verify_key_epoch_current_writer(
                    writer_epoch_candidate_proof,
                    store_identity_sha256=self.store_identity_sha256,
                    vault_store_identity_sha256=request.vault_store_identity_sha256,
                    operation_id=request.operation_id,
                    request_sha256=request.request_sha256,
                    writer_sequence=previous_writer_epoch.writer_sequence,
                    writer_key_id_sha256=successor_key_sha,
                    writer_key_epoch_sha256=request.successor_epoch_sha256,
                    retained_retiring_key_id_sha256=retiring_key_sha,
                    retained_retiring_key_epoch_sha256=(request.retiring_epoch_sha256),
                    expected_vault_event_head_sha256=(
                        request.expected_vault_event_head_sha256
                    ),
                    writer_epoch_head_sha256=(
                        previous_writer_epoch.writer_epoch_head_sha256
                    ),
                    governance_evidence_sha256=(request.governance_evidence_sha256),
                    occurred_at_utc=occurred,
                ),
                receipt_type=SourceReadVaultCurrentWriterAuthorizationReceipt,
                expected={
                    "authority_identity_sha256": (
                        self.vault_lifecycle_authority_identity_sha256
                    ),
                    "store_identity_sha256": self.store_identity_sha256,
                    "vault_store_identity_sha256": (
                        request.vault_store_identity_sha256
                    ),
                    "operation_id": request.operation_id,
                    "request_sha256": request.request_sha256,
                    "writer_sequence": previous_writer_epoch.writer_sequence,
                    "writer_key_id_sha256": successor_key_sha,
                    "writer_key_epoch_sha256": request.successor_epoch_sha256,
                    "retained_retiring_key_id_sha256": retiring_key_sha,
                    "retained_retiring_key_epoch_sha256": (
                        request.retiring_epoch_sha256
                    ),
                    "governance_evidence_sha256": (request.governance_evidence_sha256),
                    "expected_vault_event_head_sha256": (
                        request.expected_vault_event_head_sha256
                    ),
                    "observed_vault_event_head_sha256": (
                        request.expected_vault_event_head_sha256
                    ),
                    "writer_epoch_head_sha256": (
                        previous_writer_epoch.writer_epoch_head_sha256
                    ),
                    "occurred_at_utc": occurred,
                },
            )
            writer_authorization = current_writer
            predecessor_writer_sequence = previous_writer_epoch.writer_sequence
            predecessor_writer_key = successor_key_sha
            predecessor_writer_epoch = request.successor_epoch_sha256
            candidate_writer_sequence = previous_writer_epoch.writer_sequence
            candidate_writer_key = successor_key_sha
            candidate_writer_epoch = request.successor_epoch_sha256
            candidate_key_verifier = current_writer.writer_key_verifier_sha256
            candidate_vault_event = current_writer.observed_vault_event_head_sha256
        else:
            candidate = _validated_vault_factory_receipt(
                self._vault_lifecycle_authority.verify_key_epoch_candidate(
                    writer_epoch_candidate_proof,
                    store_identity_sha256=self.store_identity_sha256,
                    vault_store_identity_sha256=request.vault_store_identity_sha256,
                    operation_id=request.operation_id,
                    request_sha256=request.request_sha256,
                    retiring_key_id_sha256=retiring_key_sha,
                    successor_key_id_sha256=successor_key_sha,
                    retiring_epoch_sha256=request.retiring_epoch_sha256,
                    successor_epoch_sha256=request.successor_epoch_sha256,
                    expected_vault_event_head_sha256=(
                        request.expected_vault_event_head_sha256
                    ),
                    governance_evidence_sha256=(request.governance_evidence_sha256),
                    occurred_at_utc=occurred,
                ),
                receipt_type=SourceReadVaultKeyEpochCandidateAuthorizationReceipt,
                expected={
                    "authority_identity_sha256": (
                        self.vault_lifecycle_authority_identity_sha256
                    ),
                    "store_identity_sha256": self.store_identity_sha256,
                    "vault_store_identity_sha256": (
                        request.vault_store_identity_sha256
                    ),
                    "operation_id": request.operation_id,
                    "request_sha256": request.request_sha256,
                    "predecessor_key_id_sha256": retiring_key_sha,
                    "predecessor_epoch_sha256": request.retiring_epoch_sha256,
                    "successor_key_id_sha256": successor_key_sha,
                    "governance_evidence_sha256": (request.governance_evidence_sha256),
                    "registered_at_utc": occurred,
                    "candidate_epoch_sha256": request.successor_epoch_sha256,
                    "expected_vault_event_head_sha256": (
                        request.expected_vault_event_head_sha256
                    ),
                },
            )
            if (
                candidate.candidate_sequence < 2
                or previous_writer_epoch.state
                is SourceReadRuntimeVaultWriterEpochState.UNMANAGED
                and candidate.candidate_sequence != 2
                or previous_writer_epoch.state
                is SourceReadRuntimeVaultWriterEpochState.ACTIVE
                and (
                    previous_writer_epoch.writer_sequence
                    != candidate.candidate_sequence - 1
                    or previous_writer_epoch.writer_key_id_sha256
                    != candidate.predecessor_key_id_sha256
                    or previous_writer_epoch.writer_key_epoch_sha256
                    != candidate.predecessor_epoch_sha256
                )
            ):
                raise SourceReadLedgerStateConflict(
                    "vault writer-epoch candidate predecessor CAS differs"
                )
            writer_authorization = candidate
            predecessor_writer_sequence = candidate.candidate_sequence - 1
            predecessor_writer_key = candidate.predecessor_key_id_sha256
            predecessor_writer_epoch = candidate.predecessor_epoch_sha256
            candidate_writer_sequence = candidate.candidate_sequence
            candidate_writer_key = candidate.successor_key_id_sha256
            candidate_writer_epoch = candidate.candidate_epoch_sha256
            candidate_key_verifier = candidate.successor_key_verifier_sha256
            candidate_vault_event = candidate.expected_vault_event_head_sha256
        transition_provisional = {
            "operation_id": request.operation_id,
            "vault_store_identity_sha256": request.vault_store_identity_sha256,
            "request_sha256": request.request_sha256,
            "writer_epoch_transition_mode": transition_mode.value,
            "predecessor_writer_sequence": predecessor_writer_sequence,
            "predecessor_writer_key_id_sha256": predecessor_writer_key,
            "predecessor_writer_key_epoch_sha256": predecessor_writer_epoch,
            "candidate_writer_sequence": candidate_writer_sequence,
            "candidate_writer_key_id_sha256": candidate_writer_key,
            "candidate_writer_key_epoch_sha256": candidate_writer_epoch,
            "candidate_key_verifier_sha256": candidate_key_verifier,
            "candidate_vault_event_predecessor_sha256": candidate_vault_event,
            "vault_candidate_authorization_sha256": (
                writer_authorization.authorization_sha256
            ),
            "previous_writer_epoch_head_sha256": (
                previous_writer_epoch.writer_epoch_head_sha256
            ),
            "occurred_at_utc": occurred,
        }
        transition_sha = _value_sha256(
            self._writer_epoch_transition_material(transition_provisional)
        )
        alignment = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_key_retirement_alignment(
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=request.vault_store_identity_sha256,
                operation_id=request.operation_id,
                request_sha256=request.request_sha256,
                expected_vault_event_head_sha256=(
                    request.expected_vault_event_head_sha256
                ),
                continuation_heads=alignment_heads,
                continuation_heads_sha256=alignment_heads_sha,
            ),
            receipt_type=SourceReadVaultKeyRetirementAlignmentReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": (request.vault_store_identity_sha256),
                "operation_id": request.operation_id,
                "request_sha256": request.request_sha256,
                "expected_vault_event_head_sha256": (
                    request.expected_vault_event_head_sha256
                ),
                "continuation_head_count": len(alignment_heads),
                "continuation_heads_sha256": alignment_heads_sha,
                "vault_active_head_count": len(alignment_heads),
                "vault_active_heads_sha256": alignment_heads_sha,
                "observed_vault_event_head_sha256": (
                    request.expected_vault_event_head_sha256
                ),
            },
        )
        empty_inventory_sha = _value_sha256(
            {"record_kind": "VAULT_KEY_RETIREMENT_INVENTORY", "items": []}
        )
        empty_affected_sha = _value_sha256(
            {
                "record_kind": "VAULT_KEY_RETIREMENT_AFFECTED_LINEAGES",
                "lineages": [],
            }
        )
        authorization = _validated_key_retirement_authorization(
            self._key_retirement_authority.authorize_retirement(
                store_identity_sha256=self.store_identity_sha256,
                phase="REQUEST",
                operation_id=request.operation_id,
                plan_sha256=request.request_sha256,
                retiring_key_id_sha256=_hash_text(request.retiring_key_id),
                successor_key_id_sha256=_hash_text(request.successor_key_id),
                inventory_sha256=empty_inventory_sha,
                affected_lineages_sha256=empty_affected_sha,
                lifecycle_state=SourceReadKeyLifecycleState.ACTIVE.value,
                activation_evidence_sha256=None,
                occurred_at_utc=occurred,
                governance_evidence_sha256=request.governance_evidence_sha256,
            ),
            authority_identity_sha256=self.key_retirement_authority_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
            phase="REQUEST",
            operation_id=request.operation_id,
            plan_sha256=request.request_sha256,
            retiring_key_id_sha256=_hash_text(request.retiring_key_id),
            successor_key_id_sha256=_hash_text(request.successor_key_id),
            inventory_sha256=empty_inventory_sha,
            affected_lineages_sha256=empty_affected_sha,
            lifecycle_state=SourceReadKeyLifecycleState.ACTIVE.value,
            activation_evidence_sha256=None,
            occurred_at_utc=occurred,
            governance_evidence_sha256=request.governance_evidence_sha256,
        )
        request_json = _json_material(request_material, "key retirement request")
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadKeyRetirementAuthorizationReceipt.__dataclass_fields__
            },
            "key retirement request authorization",
        )
        alignment_json = _json_material(
            {
                name: getattr(alignment, name)
                for name in SourceReadVaultKeyRetirementAlignmentReceipt.__dataclass_fields__
            },
            "key retirement vault alignment authorization",
        )
        writer_authorization_json = _json_material(
            {
                name: getattr(writer_authorization, name)
                for name in type(writer_authorization).__dataclass_fields__
            },
            "runtime vault writer-epoch authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "KEY_RETIREMENT_REQUEST"
                    or row["operation_id"] != request.operation_id
                    or row["request_sha256"] != request.request_sha256
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "key retirement request idempotency digest is already bound"
                    )
                return SourceReadVaultKeyRetirement(
                    request.operation_id,
                    request.request_sha256,
                    SourceReadKeyLifecycleState.ACTIVE,
                    request.governance_evidence_sha256,
                    str(row["governance_authorization_sha256"]),
                    None,
                    str(row["record_sha256"]),
                    str(row["occurred_at_utc"]),
                    True,
                )
            if (
                connection.execute(
                    "SELECT 1 FROM source_read_key_retirement_requests WHERE operation_id=?",
                    (request.operation_id,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerIdempotencyConflict(
                    "key retirement operation already exists under another idempotency"
                )
            self._assert_no_active_key_lifecycle_locked(
                connection,
                ignore_compromise_operation_id=(
                    request.operation_id
                    if request.reason
                    is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                    else None
                ),
            )
            if request.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, request.operation_id
                )
            self._assert_no_unresolved_stream_incidents_locked(
                connection,
                vault_store_identity_sha256=request.vault_store_identity_sha256,
            )
            current_alignment_heads = self._vault_alignment_heads_locked(
                connection,
                request.vault_store_identity_sha256,
            )
            if (
                current_alignment_heads != alignment_heads
                or _vault_alignment_heads_sha256(current_alignment_heads)
                != alignment_heads_sha
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement vault/ledger alignment changed before REQUEST"
                )
            current_writer_epoch = self._runtime_vault_writer_epoch_locked(
                connection,
                request.vault_store_identity_sha256,
                replayed=True,
            )
            if (
                current_writer_epoch.writer_epoch_head_sha256
                != previous_writer_epoch.writer_epoch_head_sha256
                or current_writer_epoch.state
                not in {
                    SourceReadRuntimeVaultWriterEpochState.UNMANAGED,
                    SourceReadRuntimeVaultWriterEpochState.ACTIVE,
                }
            ):
                raise SourceReadLedgerStateConflict(
                    "vault writer-epoch predecessor changed before REQUEST"
                )
            if (
                connection.execute(
                    """SELECT 1 FROM source_read_operations op
                   WHERE NOT EXISTS(
                       SELECT 1 FROM source_read_outcomes o
                       WHERE o.operation_id=op.operation_id
                         AND o.outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')
                   ) LIMIT 1"""
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement request requires no unresolved source reads"
                )
            self._assert_retiring_key_not_completed_locked(connection, request)
            self._assert_writer_epoch_history_capacity_locked(
                connection, request.vault_store_identity_sha256
            )
            unresolved = connection.execute(
                """SELECT 1
                   FROM source_read_key_retirement_requests r
                   LEFT JOIN source_read_key_retirement_completions c
                     ON c.operation_id=r.operation_id
                   LEFT JOIN source_read_key_retirement_request_abandonments ra
                     ON ra.operation_id=r.operation_id
                   LEFT JOIN source_read_key_retirement_intent_abandonments ia
                     ON ia.operation_id=r.operation_id
                   WHERE r.vault_store_identity_sha256=?
                     AND r.retiring_key_id_sha256=?
                     AND c.operation_id IS NULL
                     AND ra.operation_id IS NULL
                     AND ia.operation_id IS NULL
                   LIMIT 1""",
                (
                    request.vault_store_identity_sha256,
                    _hash_text(request.retiring_key_id),
                ),
            ).fetchone()
            if unresolved is not None:
                raise SourceReadLedgerStateConflict(
                    "retiring key already has an unresolved lifecycle request"
                )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_key_retirement_requests"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_KEY_RETIREMENT_REQUEST_RECORD",
                "operation_id": request.operation_id,
                "idempotency_sha256": idempotency,
                "vault_store_identity_sha256": request.vault_store_identity_sha256,
                "retiring_key_id_sha256": _hash_text(request.retiring_key_id),
                "successor_key_id_sha256": _hash_text(request.successor_key_id),
                "request_sha256": request.request_sha256,
                "request_json_sha256": _hash_text(request_json),
                "alignment_head_count": len(alignment_heads),
                "alignment_heads_sha256": alignment_heads_sha,
                **transition_provisional,
                "writer_epoch_transition_sha256": transition_sha,
                "vault_candidate_authorization_json_sha256": _hash_text(
                    writer_authorization_json
                ),
                "vault_alignment_authorization_sha256": (
                    alignment.authorization_sha256
                ),
                "vault_alignment_authorization_json_sha256": _hash_text(alignment_json),
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "occurred_at_utc": occurred,
            }
            record_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_key_retirement_requests(
                       sequence,operation_id,idempotency_sha256,
                       vault_store_identity_sha256,retiring_key_id_sha256,
                       successor_key_id_sha256,request_sha256,request_json,
                       alignment_head_count,alignment_heads_sha256,
                       writer_epoch_transition_mode,
                       predecessor_writer_sequence,
                       predecessor_writer_key_id_sha256,
                       predecessor_writer_key_epoch_sha256,
                       candidate_writer_sequence,
                       candidate_writer_key_id_sha256,
                       candidate_writer_key_epoch_sha256,
                       candidate_key_verifier_sha256,
                       candidate_vault_event_predecessor_sha256,
                       previous_writer_epoch_head_sha256,
                       writer_epoch_transition_sha256,
                       vault_candidate_authorization_sha256,
                       vault_candidate_authorization_json,
                       vault_alignment_authorization_sha256,
                       vault_alignment_authorization_json,
                       governance_authorization_sha256,
                       governance_authorization_json,occurred_at_utc,record_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    request.operation_id,
                    idempotency,
                    request.vault_store_identity_sha256,
                    _hash_text(request.retiring_key_id),
                    _hash_text(request.successor_key_id),
                    request.request_sha256,
                    request_json,
                    len(alignment_heads),
                    alignment_heads_sha,
                    transition_mode.value,
                    predecessor_writer_sequence,
                    predecessor_writer_key,
                    predecessor_writer_epoch,
                    candidate_writer_sequence,
                    candidate_writer_key,
                    candidate_writer_epoch,
                    candidate_key_verifier,
                    candidate_vault_event,
                    previous_writer_epoch.writer_epoch_head_sha256,
                    transition_sha,
                    writer_authorization.authorization_sha256,
                    writer_authorization_json,
                    alignment.authorization_sha256,
                    alignment_json,
                    authorization.authorization_sha256,
                    authorization_json,
                    occurred,
                    record_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="KEY_RETIREMENT_REQUESTED",
                entity_kind="KEY_LIFECYCLE",
                entity_id=request.operation_id + ":REQUEST",
                entity_sha256=record_sha,
                occurred_at_utc=occurred,
            )
            return SourceReadVaultKeyRetirement(
                request.operation_id,
                request.request_sha256,
                SourceReadKeyLifecycleState.ACTIVE,
                request.governance_evidence_sha256,
                authorization.authorization_sha256,
                None,
                record_sha,
                occurred,
                False,
            )

    def runtime_vault_writer_epoch_transition_proof(
        self,
        operation_id: str,
        expected_request_sha256: str,
    ) -> SourceReadRuntimeVaultWriterEpochTransitionProof:
        identity = _safe_id(operation_id, "writer epoch transition operation")
        if _KEY_RETIREMENT_OPERATION_ID.fullmatch(identity) is None:
            raise SourceReadLedgerValidationError(
                "writer epoch transition operation identity is invalid"
            )
        expected = _sha256(expected_request_sha256, "expected retirement request")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            row = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=? AND request_sha256=?""",
                (identity, expected),
            ).fetchone()
            activation = connection.execute(
                """SELECT 1 FROM source_read_runtime_vault_writer_epoch_activations
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            abandonment = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            event = self._entity_event_locked(
                connection, "KEY_LIFECYCLE", identity + ":REQUEST"
            )
            if (
                row is None
                or row["writer_epoch_transition_mode"]
                != SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION.value
                or activation is not None
                or abandonment is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "writer epoch transition is absent, activated, or cancelled"
                )
            writer_epoch = self._runtime_vault_writer_epoch_locked(
                connection,
                str(row["vault_store_identity_sha256"]),
                replayed=True,
            )
            if (
                writer_epoch.state
                is not SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
                or writer_epoch.transition_operation_id != identity
                or writer_epoch.transition_sha256
                != row["writer_epoch_transition_sha256"]
                or verification.external_anchor_generation <= 0
            ):
                raise SourceReadLedgerStateConflict(
                    "writer epoch transition is not the exact latest pending head"
                )
            return self._mint_writer_epoch_transition_proof(
                transition=self._writer_epoch_transition_from_row(row, replayed=True),
                request=_key_retirement_request_from_material(
                    _stored_json(row["request_json"], "key retirement request")
                ),
                request_event_sha256=str(event["event_sha256"]),
                verification=verification,
            )

    def verify_latest_runtime_vault_writer_epoch_transition_proof(
        self,
        proof: SourceReadRuntimeVaultWriterEpochTransitionProof,
    ) -> bool:
        if not self._writer_epoch_transition_proof_is_known(proof):
            return False
        try:
            fresh = self.runtime_vault_writer_epoch_transition_proof(
                proof.transition.operation_id,
                proof.transition.request_sha256,
            )
            return bool(
                fresh.transition == proof.transition
                and fresh.request == proof.request
                and fresh.request_event_sha256 == proof.request_event_sha256
                and fresh.ledger_head_event_sha256 == proof.ledger_head_event_sha256
                and fresh.external_anchor_generation == proof.external_anchor_generation
                and fresh.external_anchor_receipt_sha256
                == proof.external_anchor_receipt_sha256
                and proof.factory_attested is True
                and proof.live_release_eligible is False
            )
        except SourceReadLedgerError:
            return False

    def activate_runtime_vault_writer_epoch(
        self,
        operation_id: str,
        expected_transition_sha256: str,
        registration_proof: object,
        *,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadRuntimeVaultWriterEpoch:
        identity = _safe_id(operation_id, "writer epoch activation operation")
        if _KEY_RETIREMENT_OPERATION_ID.fullmatch(identity) is None:
            raise SourceReadLedgerValidationError(
                "writer epoch activation operation identity is invalid"
            )
        expected = _sha256(expected_transition_sha256, "expected writer transition")
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "writer epoch activation requires pinned vault and anchor"
            )
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "RUNTIME_VAULT_WRITER_EPOCH_ACTIVATION"
                    or row["operation_id"] != identity
                    or row["transition_sha256"] != expected
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "writer epoch activation idempotency is already bound"
                    )
                request_row = connection.execute(
                    """SELECT vault_store_identity_sha256
                       FROM source_read_key_retirement_requests
                       WHERE operation_id=?""",
                    (identity,),
                ).fetchone()
                if request_row is None:
                    raise SourceReadLedgerIntegrityError(
                        "writer epoch activation request is absent"
                    )
                return self._runtime_vault_writer_epoch_locked(
                    connection,
                    str(request_row["vault_store_identity_sha256"]),
                    replayed=True,
                )
            request_row = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=? AND writer_epoch_transition_sha256=?""",
                (identity, expected),
            ).fetchone()
            abandonment = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                request_row is None
                or request_row["writer_epoch_transition_mode"]
                != SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION.value
                or abandonment is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "writer epoch transition is absent or cancelled"
                )
            current_epoch = self._runtime_vault_writer_epoch_locked(
                connection,
                str(request_row["vault_store_identity_sha256"]),
                replayed=True,
            )
            if (
                current_epoch.state
                is not SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
                or current_epoch.transition_operation_id != identity
            ):
                raise SourceReadLedgerStateConflict(
                    "writer epoch transition is not pending"
                )
        registration = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_key_epoch_registration(
                registration_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=str(
                    request_row["vault_store_identity_sha256"]
                ),
                operation_id=identity,
                request_sha256=str(request_row["request_sha256"]),
                transition_sha256=expected,
                writer_sequence=int(request_row["candidate_writer_sequence"]),
                writer_key_id_sha256=str(request_row["candidate_writer_key_id_sha256"]),
                writer_key_epoch_sha256=str(
                    request_row["candidate_writer_key_epoch_sha256"]
                ),
                predecessor_key_id_sha256=str(
                    request_row["predecessor_writer_key_id_sha256"]
                ),
                predecessor_epoch_sha256=str(
                    request_row["predecessor_writer_key_epoch_sha256"]
                ),
            ),
            receipt_type=SourceReadVaultKeyEpochRegistrationAuthorizationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": str(
                    request_row["vault_store_identity_sha256"]
                ),
                "operation_id": identity,
                "request_sha256": str(request_row["request_sha256"]),
                "transition_sha256": expected,
                "writer_sequence": int(request_row["candidate_writer_sequence"]),
                "writer_key_id_sha256": str(
                    request_row["candidate_writer_key_id_sha256"]
                ),
                "writer_key_epoch_sha256": str(
                    request_row["candidate_writer_key_epoch_sha256"]
                ),
                "predecessor_key_id_sha256": str(
                    request_row["predecessor_writer_key_id_sha256"]
                ),
                "predecessor_epoch_sha256": str(
                    request_row["predecessor_writer_key_epoch_sha256"]
                ),
                "key_verifier_sha256": str(
                    request_row["candidate_key_verifier_sha256"]
                ),
            },
        )
        registration_json = _json_material(
            {
                name: getattr(registration, name)
                for name in SourceReadVaultKeyEpochRegistrationAuthorizationReceipt.__dataclass_fields__
            },
            "runtime vault writer epoch registration authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "RUNTIME_VAULT_WRITER_EPOCH_ACTIVATION"
                    or row["operation_id"] != identity
                    or row["transition_sha256"] != expected
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "writer epoch activation idempotency is already bound"
                    )
                return self._runtime_vault_writer_epoch_locked(
                    connection,
                    str(request_row["vault_store_identity_sha256"]),
                    replayed=True,
                )
            current_request = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=? AND writer_epoch_transition_sha256=?""",
                (identity, expected),
            ).fetchone()
            current_activation = connection.execute(
                """SELECT 1 FROM source_read_runtime_vault_writer_epoch_activations
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            current_abandonment = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                current_request is None
                or current_request["writer_epoch_transition_mode"]
                != SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION.value
                or current_activation is not None
                or current_abandonment is not None
                or self._runtime_vault_writer_epoch_locked(
                    connection,
                    str(request_row["vault_store_identity_sha256"]),
                    replayed=True,
                ).state
                is not SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
            ):
                raise SourceReadLedgerStateConflict(
                    "writer epoch transition changed before activation"
                )
            sequence = int(
                connection.execute(
                    """SELECT COALESCE(MAX(sequence),0)+1
                       FROM source_read_runtime_vault_writer_epoch_activations"""
                ).fetchone()[0]
            )
            provisional = {
                "operation_id": identity,
                "idempotency_sha256": idempotency,
                "transition_sha256": expected,
                "vault_registration_authorization_sha256": (
                    registration.authorization_sha256
                ),
                "vault_registration_authorization_json": registration_json,
                "occurred_at_utc": occurred,
            }
            record_sha = _value_sha256(
                self._runtime_vault_writer_epoch_activation_material(provisional)
            )
            connection.execute(
                """INSERT INTO source_read_runtime_vault_writer_epoch_activations(
                       sequence,operation_id,idempotency_sha256,transition_sha256,
                       vault_registration_authorization_sha256,
                       vault_registration_authorization_json,
                       occurred_at_utc,record_sha256)
                   VALUES(?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    identity,
                    idempotency,
                    expected,
                    registration.authorization_sha256,
                    registration_json,
                    occurred,
                    record_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="RUNTIME_VAULT_WRITER_EPOCH_ACTIVATED",
                entity_kind="RUNTIME_VAULT_WRITER_EPOCH",
                entity_id=identity,
                entity_sha256=record_sha,
                occurred_at_utc=occurred,
            )
            return self._runtime_vault_writer_epoch_locked(
                connection,
                str(request_row["vault_store_identity_sha256"]),
                replayed=False,
            )

    def runtime_vault_writer_epoch_proof(
        self,
        vault_store_identity_sha256: str,
    ) -> SourceReadRuntimeVaultWriterEpochProof:
        vault_store = _sha256(
            vault_store_identity_sha256,
            "writer epoch vault_store_identity_sha256",
        )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            writer_epoch = self._runtime_vault_writer_epoch_locked(
                connection, vault_store, replayed=True
            )
            writer_ancestry = self._runtime_vault_writer_epoch_ancestry_locked(
                connection, vault_store
            )
            if verification.external_anchor_generation <= 0:
                raise SourceReadLedgerStateConflict(
                    "writer epoch proof requires a non-genesis anchor"
                )
            return self._mint_writer_epoch_proof(
                writer_epoch=writer_epoch,
                writer_ancestry=writer_ancestry,
                verification=verification,
            )

    def runtime_vault_writer_epoch_activation_record(
        self,
        operation_id: str,
    ) -> SourceReadRuntimeVaultWriterEpochActivationRecord:
        """Read back one anchored registration without granting new mutation."""

        identity = _safe_id(operation_id, "writer epoch activation operation")
        if _KEY_RETIREMENT_OPERATION_ID.fullmatch(identity) is None:
            raise SourceReadLedgerValidationError(
                "writer epoch activation operation identity is invalid"
            )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            request_row = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            activation = connection.execute(
                """SELECT * FROM source_read_runtime_vault_writer_epoch_activations
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                request_row is None
                or activation is None
                or request_row["writer_epoch_transition_mode"]
                != SourceReadRuntimeVaultWriterEpochTransitionMode.CANDIDATE_TRANSITION.value
            ):
                raise SourceReadLedgerStateConflict(
                    "writer epoch activation record is absent"
                )
            request_event = self._entity_event_locked(
                connection, "KEY_LIFECYCLE", identity + ":REQUEST"
            )
            activation_event = self._entity_event_locked(
                connection, "RUNTIME_VAULT_WRITER_EPOCH", identity
            )
            request_anchor = connection.execute(
                """SELECT generation,receipt_sha256
                   FROM source_read_anchor_advancements
                   WHERE head_event_sha256=?""",
                (request_event["event_sha256"],),
            ).fetchone()
            activation_anchor = connection.execute(
                """SELECT generation,receipt_sha256
                   FROM source_read_anchor_advancements
                   WHERE head_event_sha256=?""",
                (activation_event["event_sha256"],),
            ).fetchone()
            if request_anchor is None or activation_anchor is None:
                raise SourceReadLedgerStateConflict(
                    "writer epoch activation is not externally anchored"
                )
            request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            transition = self._writer_epoch_transition_from_row(
                request_row, replayed=True
            )
            registration = _vault_factory_receipt_from_material(
                _stored_json(
                    activation["vault_registration_authorization_json"],
                    "writer epoch registration authorization",
                ),
                SourceReadVaultKeyEpochRegistrationAuthorizationReceipt,
            )
            material = self._runtime_vault_writer_epoch_activation_record_material(
                store_identity_sha256=self.store_identity_sha256,
                request_sha256=request.request_sha256,
                transition_sha256=transition.transition_sha256,
                registration_authorization_sha256=(registration.authorization_sha256),
                request_event_sha256=str(request_event["event_sha256"]),
                request_anchor_generation=int(request_anchor["generation"]),
                request_anchor_receipt_sha256=str(request_anchor["receipt_sha256"]),
                activation_record_sha256=str(activation["record_sha256"]),
                activation_event_sha256=str(activation_event["event_sha256"]),
                activation_anchor_generation=int(activation_anchor["generation"]),
                activation_anchor_receipt_sha256=str(
                    activation_anchor["receipt_sha256"]
                ),
            )
            return SourceReadRuntimeVaultWriterEpochActivationRecord(
                self.store_identity_sha256,
                request,
                transition,
                registration,
                str(request_event["event_sha256"]),
                int(request_anchor["generation"]),
                str(request_anchor["receipt_sha256"]),
                str(activation["record_sha256"]),
                str(activation_event["event_sha256"]),
                int(activation_anchor["generation"]),
                str(activation_anchor["receipt_sha256"]),
                verification.head_event_sha256,
                verification.external_anchor_generation,
                verification.external_anchor_receipt_sha256,
                _value_sha256(material),
                True,
                False,
            )

    def verify_runtime_vault_writer_epoch_activation_record(
        self,
        record: SourceReadRuntimeVaultWriterEpochActivationRecord,
    ) -> bool:
        if type(record) is not SourceReadRuntimeVaultWriterEpochActivationRecord:
            return False
        try:
            fresh = self.runtime_vault_writer_epoch_activation_record(
                record.request.operation_id
            )
            return bool(fresh == record and record.live_release_eligible is False)
        except SourceReadLedgerError:
            return False

    def verify_latest_runtime_vault_writer_epoch_proof(
        self,
        proof: SourceReadRuntimeVaultWriterEpochProof,
    ) -> bool:
        if not self._writer_epoch_proof_is_known(proof):
            return False
        try:
            fresh = self.runtime_vault_writer_epoch_proof(
                proof.writer_epoch.vault_store_identity_sha256
            )
            return bool(
                fresh.writer_epoch == proof.writer_epoch
                and fresh.writer_ancestry == proof.writer_ancestry
                and fresh.ledger_head_event_sha256 == proof.ledger_head_event_sha256
                and fresh.external_anchor_generation == proof.external_anchor_generation
                and fresh.external_anchor_receipt_sha256
                == proof.external_anchor_receipt_sha256
                and proof.factory_attested is True
                and proof.live_release_eligible is False
            )
        except SourceReadLedgerError:
            return False

    def runtime_vault_key_retirement_request_proof(
        self, operation_id: str, expected_request_sha256: str
    ) -> SourceReadKeyRetirementRequestProof:
        if (
            type(operation_id) is not str
            or _KEY_RETIREMENT_OPERATION_ID.fullmatch(operation_id) is None
        ):
            raise SourceReadLedgerValidationError(
                "key retirement operation identity is invalid"
            )
        expected = _sha256(expected_request_sha256, "expected_request_sha256")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            row = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=? AND request_sha256=?""",
                (operation_id, expected),
            ).fetchone()
            later = connection.execute(
                "SELECT 1 FROM source_read_key_retirement_intents WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            abandonment = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (operation_id,),
            ).fetchone()
            if row is None or later is not None or abandonment is not None:
                raise SourceReadLedgerStateConflict(
                    "key retirement request is absent, consumed, or stale"
                )
            request = _key_retirement_request_from_material(
                _stored_json(row["request_json"], "key retirement request")
            )
            allowed_detection = (
                operation_id
                if request.reason
                is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else None
            )
            self._assert_no_unrelated_key_compromise_detection_locked(
                connection,
                allowed_operation_id=allowed_detection,
            )
            if allowed_detection is not None:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, operation_id
                )
            continuation_heads = self._vault_alignment_heads_locked(
                connection,
                request.vault_store_identity_sha256,
            )
            continuation_heads_sha = _vault_alignment_heads_sha256(continuation_heads)
            alignment = _vault_factory_receipt_from_material(
                _stored_json(
                    row["vault_alignment_authorization_json"],
                    "key retirement vault alignment authorization",
                ),
                SourceReadVaultKeyRetirementAlignmentReceipt,
            )
            if (
                len(continuation_heads) != int(row["alignment_head_count"])
                or continuation_heads_sha != row["alignment_heads_sha256"]
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement request alignment is no longer current"
                )
            event = self._entity_event_locked(
                connection, "KEY_LIFECYCLE", operation_id + ":REQUEST"
            )
            writer_epoch = self._assert_writer_epoch_active_for_request_locked(
                connection, row
            )
            if (
                verification.external_anchor_generation <= 0
                or verification.external_anchor_status
                != "ANCHORED_MONOTONIC_LOCAL_CUSTODY"
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement request is not externally anchored"
                )
            return self._mint_key_retirement_request_proof(
                request=request,
                writer_epoch_transition_mode=(
                    SourceReadRuntimeVaultWriterEpochTransitionMode(
                        str(row["writer_epoch_transition_mode"])
                    )
                ),
                writer_epoch=writer_epoch,
                continuation_heads=continuation_heads,
                continuation_heads_sha256=continuation_heads_sha,
                vault_alignment_authorization_sha256=(alignment.authorization_sha256),
                observed_vault_event_head_sha256=(
                    alignment.observed_vault_event_head_sha256
                ),
                governance_authorization_sha256=str(
                    row["governance_authorization_sha256"]
                ),
                request_event_sha256=str(event["event_sha256"]),
                verification=verification,
            )

    def verify_latest_runtime_vault_key_retirement_request_proof(
        self, proof: SourceReadKeyRetirementRequestProof
    ) -> bool:
        if not self._key_retirement_request_proof_is_known(proof):
            return False
        try:
            with self._read() as connection:
                verification = self._verify_locked(connection)
                self._assert_authority_approval_fence_locked(connection)
                row = connection.execute(
                    """SELECT * FROM source_read_key_retirement_requests
                       WHERE operation_id=? AND request_sha256=?""",
                    (proof.request.operation_id, proof.request.request_sha256),
                ).fetchone()
                consumed = connection.execute(
                    "SELECT 1 FROM source_read_key_retirement_intents WHERE operation_id=?",
                    (proof.request.operation_id,),
                ).fetchone()
                abandonment = connection.execute(
                    """SELECT 1 FROM source_read_key_retirement_request_abandonments
                       WHERE operation_id=?""",
                    (proof.request.operation_id,),
                ).fetchone()
                allowed_detection = (
                    proof.request.operation_id
                    if proof.request.reason
                    is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                    else None
                )
                self._assert_no_unrelated_key_compromise_detection_locked(
                    connection,
                    allowed_operation_id=allowed_detection,
                )
                if allowed_detection is not None:
                    self._assert_key_compromise_containment_eligible_locked(
                        connection, proof.request.operation_id
                    )
                continuation_heads = self._vault_alignment_heads_locked(
                    connection,
                    proof.request.vault_store_identity_sha256,
                )
                continuation_heads_sha = _vault_alignment_heads_sha256(
                    continuation_heads
                )
                alignment = (
                    None
                    if row is None
                    else _vault_factory_receipt_from_material(
                        _stored_json(
                            row["vault_alignment_authorization_json"],
                            "key retirement vault alignment authorization",
                        ),
                        SourceReadVaultKeyRetirementAlignmentReceipt,
                    )
                )
                event = connection.execute(
                    """SELECT * FROM source_read_events
                       WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
                    (proof.request.operation_id + ":REQUEST",),
                ).fetchone()
                writer_epoch = (
                    None
                    if row is None
                    else self._assert_writer_epoch_active_for_request_locked(
                        connection, row
                    )
                )
                anchor_valid = (
                    verification.external_anchor_generation
                    >= proof.external_anchor_generation
                    and verification.external_anchor_generation > 0
                )
                if (
                    verification.external_anchor_generation
                    == proof.external_anchor_generation
                ):
                    anchor_valid = anchor_valid and (
                        verification.external_anchor_receipt_sha256
                        == proof.external_anchor_receipt_sha256
                    )
                return bool(
                    row is not None
                    and consumed is None
                    and abandonment is None
                    and event is not None
                    and writer_epoch == proof.writer_epoch
                    and row["writer_epoch_transition_mode"]
                    == proof.writer_epoch_transition_mode.value
                    and _key_retirement_request_from_material(
                        _stored_json(row["request_json"], "key retirement request")
                    )
                    == proof.request
                    and row["governance_authorization_sha256"]
                    == proof.governance_authorization_sha256
                    and continuation_heads == proof.continuation_heads
                    and continuation_heads_sha == proof.continuation_heads_sha256
                    and len(continuation_heads) == int(row["alignment_head_count"])
                    and continuation_heads_sha == row["alignment_heads_sha256"]
                    and alignment is not None
                    and alignment.authorization_sha256
                    == proof.vault_alignment_authorization_sha256
                    and alignment.observed_vault_event_head_sha256
                    == proof.observed_vault_event_head_sha256
                    and event["event_sha256"] == proof.request_event_sha256
                    and anchor_valid
                    and proof.factory_attested is True
                    and proof.live_release_eligible is False
                )
        except SourceReadLedgerError:
            return False

    def bind_runtime_vault_key_retirement(
        self,
        plan: SourceReadKeyRetirementPlan,
        inventory: tuple[SourceReadKeyRetirementInventoryItem, ...],
        seal_proof: object,
        *,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadVaultKeyRetirement:
        """Bind the vault's complete sealed rewrap inventory as RETIRE_INTENT."""

        if (
            type(plan) is not SourceReadKeyRetirementPlan
            or type(inventory) is not tuple
        ):
            raise SourceReadLedgerValidationError(
                "key retirement plan/inventory must be exact"
            )
        governance = _sha256(
            governance_evidence_sha256, "retirement governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
            or self._key_retirement_authority is None
            or self.key_retirement_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "key retirement intent requires pinned anchor, vault verifier, and SoD authority"
            )
        with self._read() as connection:
            request_row = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
                (plan.operation_id,),
            ).fetchone()
            request_abandoned = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (plan.operation_id,),
            ).fetchone()
            if request_row is None or request_abandoned is not None:
                raise SourceReadLedgerStateConflict(
                    "anchored key retirement request is absent or abandoned"
                )
            self._assert_writer_epoch_active_for_request_locked(connection, request_row)
            request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            allowed_detection = (
                plan.operation_id
                if request.reason
                is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else None
            )
            self._assert_no_unrelated_key_compromise_detection_locked(
                connection,
                allowed_operation_id=allowed_detection,
            )
            if allowed_detection is not None:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, plan.operation_id
                )
            canonical = source_read_key_retirement_plan(
                request=request,
                vault_protocol=plan.vault_protocol,
                predecessor_vault_event_sha256=plan.predecessor_vault_event_sha256,
                inventory=inventory,
            )
            if canonical != plan or governance != request.governance_evidence_sha256:
                raise SourceReadLedgerValidationError(
                    "key retirement plan/request governance binding differs"
                )
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                stored_plan = (
                    _key_retirement_plan_from_material(
                        _stored_json(row["plan_json"], "key retirement plan"),
                        request=request,
                        inventory=tuple(
                            _key_retirement_item_from_material(
                                _stored_json(
                                    item_row["item_json"],
                                    "key retirement inventory item",
                                )
                            )
                            for item_row in connection.execute(
                                """SELECT * FROM source_read_key_retirement_inventory
                                   WHERE operation_id=? ORDER BY sequence""",
                                (plan.operation_id,),
                            ).fetchall()
                        ),
                    )
                    if kind == "KEY_RETIREMENT_INTENT"
                    else None
                )
                if (
                    kind != "KEY_RETIREMENT_INTENT"
                    or stored_plan != plan
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "key retirement intent idempotency digest is already bound"
                    )
                return SourceReadVaultKeyRetirement(
                    plan.operation_id,
                    plan.plan_sha256,
                    SourceReadKeyLifecycleState.RETIRE_INTENT,
                    governance,
                    str(row["governance_authorization_sha256"]),
                    None,
                    str(row["record_sha256"]),
                    str(row["occurred_at_utc"]),
                    True,
                )
        seal_authorization = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_key_retirement_seal(
                seal_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=plan.vault_store_identity_sha256,
                operation_id=plan.operation_id,
                plan_sha256=plan.plan_sha256,
                inventory_sha256=plan.inventory_sha256,
                rewrap_manifest_sha256=plan.rewrap_manifest_sha256,
                slot_heads_sha256=plan.slot_heads_sha256,
                affected_lineages_sha256=plan.affected_lineages_sha256,
            ),
            receipt_type=SourceReadVaultKeySealAuthorizationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": plan.vault_store_identity_sha256,
                "operation_id": plan.operation_id,
                "plan_sha256": plan.plan_sha256,
                "inventory_sha256": plan.inventory_sha256,
                "rewrap_manifest_sha256": plan.rewrap_manifest_sha256,
                "slot_heads_sha256": plan.slot_heads_sha256,
                "affected_lineages_sha256": plan.affected_lineages_sha256,
            },
        )
        authorization = _validated_key_retirement_authorization(
            self._key_retirement_authority.authorize_retirement(
                store_identity_sha256=self.store_identity_sha256,
                phase="INTENT",
                operation_id=plan.operation_id,
                plan_sha256=plan.plan_sha256,
                retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
                successor_key_id_sha256=_hash_text(plan.successor_key_id),
                inventory_sha256=plan.inventory_sha256,
                affected_lineages_sha256=plan.affected_lineages_sha256,
                lifecycle_state=SourceReadKeyLifecycleState.RETIRE_INTENT.value,
                activation_evidence_sha256=None,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=self.key_retirement_authority_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
            phase="INTENT",
            operation_id=plan.operation_id,
            plan_sha256=plan.plan_sha256,
            retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
            successor_key_id_sha256=_hash_text(plan.successor_key_id),
            inventory_sha256=plan.inventory_sha256,
            affected_lineages_sha256=plan.affected_lineages_sha256,
            lifecycle_state=SourceReadKeyLifecycleState.RETIRE_INTENT.value,
            activation_evidence_sha256=None,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        plan_json = _json_material(
            _key_retirement_plan_dto_material(plan), "key retirement plan"
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadKeyRetirementAuthorizationReceipt.__dataclass_fields__
            },
            "key retirement intent authorization",
        )
        seal_authorization_json = _json_material(
            {
                name: getattr(seal_authorization, name)
                for name in SourceReadVaultKeySealAuthorizationReceipt.__dataclass_fields__
            },
            "key retirement vault seal authorization",
        )
        item_jsons = tuple(
            _json_material(
                _key_retirement_item_material(item),
                "key retirement inventory item",
            )
            for item in inventory
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "KEY_RETIREMENT_INTENT"
                    or row["operation_id"] != plan.operation_id
                    or row["plan_sha256"] != plan.plan_sha256
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "key retirement intent idempotency digest is already bound"
                    )
                return SourceReadVaultKeyRetirement(
                    plan.operation_id,
                    plan.plan_sha256,
                    SourceReadKeyLifecycleState.RETIRE_INTENT,
                    governance,
                    str(row["governance_authorization_sha256"]),
                    None,
                    str(row["record_sha256"]),
                    str(row["occurred_at_utc"]),
                    True,
                )
            request_row = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
                (plan.operation_id,),
            ).fetchone()
            existing = connection.execute(
                "SELECT 1 FROM source_read_key_retirement_intents WHERE operation_id=?",
                (plan.operation_id,),
            ).fetchone()
            request_abandoned = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (plan.operation_id,),
            ).fetchone()
            if (
                request_row is None
                or existing is not None
                or request_abandoned is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement request is absent or already consumed"
                )
            self._assert_writer_epoch_active_for_request_locked(connection, request_row)
            stored_request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            allowed_detection = (
                plan.operation_id
                if stored_request.reason
                is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else None
            )
            self._assert_no_unrelated_key_compromise_detection_locked(
                connection,
                allowed_operation_id=allowed_detection,
            )
            if allowed_detection is not None:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, plan.operation_id
                )
            if stored_request != request or _utc_datetime(
                occurred, "retirement intent time"
            ) < _utc_datetime(request.occurred_at_utc, "retirement request time"):
                raise SourceReadLedgerStateConflict(
                    "key retirement request changed before intent"
                )
            active_lineages: set[str] = set()
            for item in inventory:
                lineage = _value_sha256(
                    {
                        "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        "record_kind": "SOURCE_READ_CONTINUATION_LINEAGE",
                        "vault_store_identity_sha256": plan.vault_store_identity_sha256,
                        "slot_sha256": item.slot_sha256,
                    }
                )
                head = connection.execute(
                    """SELECT * FROM source_read_continuation_heads
                       WHERE lineage_sha256=? AND ledger_binding_sha256=?""",
                    (lineage, item.ledger_binding_sha256),
                ).fetchone()
                latest = connection.execute(
                    """SELECT * FROM source_read_continuation_heads
                       WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                    (lineage,),
                ).fetchone()
                self._assert_no_active_stream_incident_locked(
                    connection, lineage_sha256=lineage
                )
                if item.is_active_head:
                    if head is None or latest is None:
                        raise SourceReadLedgerStateConflict(
                            "retirement active inventory has no exact ledger head"
                        )
                    if latest["ledger_binding_sha256"] != item.ledger_binding_sha256:
                        raise SourceReadLedgerStateConflict(
                            "retirement active inventory is not the latest ledger head"
                        )
                    active_lineages.add(lineage)
                elif head is None:
                    # Abandoned PREPARED generations are deliberately part of
                    # the sealed vault inventory but have no ledger head.  The
                    # injected vault factory verifier proves their exact
                    # existence; local absence is required, not rejected.
                    if (
                        connection.execute(
                            """SELECT 1 FROM source_read_continuation_heads
                           WHERE ledger_binding_sha256=? LIMIT 1""",
                            (item.ledger_binding_sha256,),
                        ).fetchone()
                        is not None
                    ):
                        raise SourceReadLedgerStateConflict(
                            "retirement unbound inventory conflicts with another lineage"
                        )
                    operation = connection.execute(
                        "SELECT 1 FROM source_read_operations WHERE operation_id=?",
                        (item.operation_id,),
                    ).fetchone()
                    final = connection.execute(
                        """SELECT 1 FROM source_read_outcomes
                           WHERE operation_id=?
                             AND outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')
                           LIMIT 1""",
                        (item.operation_id,),
                    ).fetchone()
                    if operation is not None and final is None:
                        raise SourceReadLedgerStateConflict(
                            "retirement headless PREPARED belongs to an unresolved read"
                        )
            expected_lineages = {
                _value_sha256(
                    {
                        "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        "record_kind": "SOURCE_READ_CONTINUATION_LINEAGE",
                        "vault_store_identity_sha256": plan.vault_store_identity_sha256,
                        "slot_sha256": item.slot_sha256,
                    }
                )
                for item in inventory
                if item.is_active_head
            }
            if active_lineages != expected_lineages:
                raise SourceReadLedgerStateConflict(
                    "retirement affected lineage inventory differs"
                )
            if (
                stored_request.reason
                is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
            ):
                targets = self._key_compromise_targets_locked(
                    connection,
                    operation_id=plan.operation_id,
                    vault_store_identity_sha256=plan.vault_store_identity_sha256,
                    inventory=inventory,
                )
                if {lineage for lineage, _, _ in targets} != expected_lineages:
                    raise SourceReadLedgerStateConflict(
                        "key compromise sealed lineage targets differ"
                    )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_key_retirement_intents"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_KEY_RETIREMENT_INTENT_RECORD",
                "operation_id": plan.operation_id,
                "idempotency_sha256": idempotency,
                "plan_sha256": plan.plan_sha256,
                "plan_json_sha256": _hash_text(plan_json),
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_seal_authorization_sha256": (
                    seal_authorization.authorization_sha256
                ),
                "vault_seal_authorization_json_sha256": _hash_text(
                    seal_authorization_json
                ),
                "occurred_at_utc": occurred,
            }
            record_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_key_retirement_intents(
                       sequence,operation_id,idempotency_sha256,plan_sha256,
                       plan_json,governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_seal_authorization_sha256,
                       vault_seal_authorization_json,occurred_at_utc,record_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    plan.operation_id,
                    idempotency,
                    plan.plan_sha256,
                    plan_json,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    seal_authorization.authorization_sha256,
                    seal_authorization_json,
                    occurred,
                    record_sha,
                ),
            )
            inventory_sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_key_retirement_inventory"
                ).fetchone()[0]
            )
            for offset, (item, item_json) in enumerate(
                zip(inventory, item_jsons, strict=True)
            ):
                connection.execute(
                    """INSERT INTO source_read_key_retirement_inventory(
                           sequence,operation_id,slot_sha256,generation,
                           ledger_binding_sha256,item_sha256,item_json)
                       VALUES(?,?,?,?,?,?,?)""",
                    (
                        inventory_sequence + offset,
                        plan.operation_id,
                        item.slot_sha256,
                        item.generation,
                        item.ledger_binding_sha256,
                        item.item_sha256,
                        item_json,
                    ),
                )
            self._append_event_locked(
                connection,
                event_type="KEY_RETIRE_INTENT",
                entity_kind="KEY_LIFECYCLE",
                entity_id=plan.operation_id + ":INTENT",
                entity_sha256=record_sha,
                occurred_at_utc=occurred,
            )
            return SourceReadVaultKeyRetirement(
                plan.operation_id,
                plan.plan_sha256,
                SourceReadKeyLifecycleState.RETIRE_INTENT,
                governance,
                authorization.authorization_sha256,
                None,
                record_sha,
                occurred,
                False,
            )

    @staticmethod
    def _key_retirement_abandonment_from_row(
        row: sqlite3.Row, *, phase: str, replayed: bool
    ) -> SourceReadKeyRetirementAbandonment:
        if phase == "REQUEST":
            source_sha = str(row["request_sha256"])
        elif phase == "RETIRE_INTENT":
            source_sha = str(row["plan_sha256"])
        else:
            raise SourceReadLedgerIntegrityError(
                "key retirement abandonment phase differs"
            )
        return SourceReadKeyRetirementAbandonment(
            str(row["operation_id"]),
            phase,
            "ABANDONED",
            source_sha,
            SourceReadKeyRetirementAbandonmentReason(str(row["reason_code"])),
            str(row["observation_sha256"]),
            str(row["vault_cancellation_event_sha256"]),
            str(row["governance_evidence_sha256"]),
            str(row["governance_authorization_sha256"]),
            str(row["vault_authorization_sha256"]),
            str(row["record_sha256"]),
            str(row["occurred_at_utc"]),
            replayed,
            None if row["plan_sha256"] is None else str(row["plan_sha256"]),
            None if row["seal_sha256"] is None else str(row["seal_sha256"]),
        )

    def abandon_runtime_vault_key_retirement_request(
        self,
        operation_id: str,
        expected_request_sha256: str,
        abandonment_proof: object,
        *,
        reason_code: SourceReadKeyRetirementAbandonmentReason,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadKeyRetirementAbandonment:
        """Cancel a stranded REQUEST only after a vault cancellation fence."""

        identity = _safe_id(operation_id, "key retirement operation")
        expected = _sha256(expected_request_sha256, "expected retirement request")
        governance = _sha256(
            governance_evidence_sha256, "retirement abandonment governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        sealed_cancellation = (
            reason_code
            is SourceReadKeyRetirementAbandonmentReason.SEALED_NO_LEDGER_INTENT
        )
        if _KEY_RETIREMENT_OPERATION_ID.fullmatch(
            identity
        ) is None or reason_code not in {
            SourceReadKeyRetirementAbandonmentReason.STALE_ALIGNMENT_NO_LOCAL_BEGIN,
            SourceReadKeyRetirementAbandonmentReason.SEALED_NO_LEDGER_INTENT,
        }:
            raise SourceReadLedgerValidationError(
                "retirement request abandonment identity/reason differs"
            )
        if (
            self._external_anchor is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
            or self._key_retirement_authority is None
            or self.key_retirement_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "retirement request abandonment requires pinned vault, anchor, and SoD"
            )
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                replay_phase = (
                    "REQUEST"
                    if kind == "KEY_RETIREMENT_REQUEST_ABANDONMENT"
                    else "RETIRE_INTENT"
                )
                replay_request = connection.execute(
                    """SELECT request_sha256
                       FROM source_read_key_retirement_requests
                       WHERE operation_id=?""",
                    (identity,),
                ).fetchone()
                if (
                    kind
                    not in {
                        "KEY_RETIREMENT_REQUEST_ABANDONMENT",
                        "KEY_RETIREMENT_INTENT_ABANDONMENT",
                    }
                    or kind == "KEY_RETIREMENT_INTENT_ABANDONMENT"
                    and not sealed_cancellation
                    or row["operation_id"] != identity
                    or replay_request is None
                    or replay_request["request_sha256"] != expected
                    or row["reason_code"] != reason_code.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "retirement request abandonment idempotency is already bound"
                    )
                return self._key_retirement_abandonment_from_row(
                    row, phase=replay_phase, replayed=True
                )
            request_row = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=? AND request_sha256=?""",
                (identity, expected),
            ).fetchone()
            intent = connection.execute(
                "SELECT * FROM source_read_key_retirement_intents WHERE operation_id=?",
                (identity,),
            ).fetchone()
            prior = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            prior_intent = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            completion = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_completions
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                request_row is None
                or prior is not None
                or prior_intent is not None
                or completion is not None
                or intent is not None
                and not sealed_cancellation
            ):
                raise SourceReadLedgerStateConflict(
                    "retirement request is absent, consumed, or already abandoned"
                )
            request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            allowed_detection = (
                identity
                if request.reason
                is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else None
            )
            self._assert_no_unrelated_key_compromise_detection_locked(
                connection,
                allowed_operation_id=allowed_detection,
            )
            if allowed_detection is not None:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, identity
                )
            if request.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT:
                raise SourceReadLedgerStateConflict(
                    "compromise-containment request cannot be abandoned"
                )
            self._assert_writer_epoch_abandonable_for_request_locked(
                connection,
                request_row,
                sealed_cancellation=sealed_cancellation,
            )
            if _utc_datetime(occurred, "request abandonment time") < _utc_datetime(
                request.occurred_at_utc, "retirement request time"
            ):
                raise SourceReadLedgerValidationError(
                    "retirement request abandonment precedes the request"
                )

        vault_receipt = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_key_retirement_request_abandonment(
                abandonment_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=request.vault_store_identity_sha256,
                operation_id=identity,
                request_sha256=expected,
                expected_vault_event_head_sha256=(
                    request.expected_vault_event_head_sha256
                ),
                continuation_heads_sha256=str(request_row["alignment_heads_sha256"]),
                custody_identity_sha256=request.custody_identity_sha256,
                expected_custody_generation=request.expected_custody_generation,
                expected_previous_custody_receipt_sha256=(
                    request.expected_previous_custody_receipt_sha256
                ),
                reason_code=reason_code.value,
            ),
            receipt_type=SourceReadVaultKeyRetirementRequestAbandonmentReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": request.vault_store_identity_sha256,
                "operation_id": identity,
                "request_sha256": expected,
                "expected_vault_event_head_sha256": (
                    request.expected_vault_event_head_sha256
                ),
                "continuation_heads_sha256": str(request_row["alignment_heads_sha256"]),
                "custody_identity_sha256": request.custody_identity_sha256,
                "expected_custody_generation": request.expected_custody_generation,
                "expected_previous_custody_receipt_sha256": (
                    request.expected_previous_custody_receipt_sha256
                ),
                "reason_code": reason_code.value,
            },
        )
        if (
            vault_receipt.observed_custody_generation
            != request.expected_custody_generation
            or vault_receipt.observed_custody_receipt_sha256
            != request.expected_previous_custody_receipt_sha256
        ):
            raise SourceReadLedgerStateConflict(
                "retirement request abandonment lacks exact unchanged custody"
            )
        if (
            not sealed_cancellation
            and vault_receipt.observed_vault_event_head_sha256
            == request.expected_vault_event_head_sha256
            or sealed_cancellation
            and (
                vault_receipt.plan_sha256 is None
                or vault_receipt.seal_sha256 is None
                or vault_receipt.inventory_sha256 is None
                or vault_receipt.affected_lineages_sha256 is None
                or vault_receipt.seal_event_sha256 is None
                or vault_receipt.observed_vault_event_head_sha256
                != vault_receipt.seal_event_sha256
            )
        ):
            raise SourceReadLedgerStateConflict(
                "retirement request abandonment vault phase differs"
            )
        observation = vault_receipt.observation_sha256
        empty_inventory_sha = _value_sha256(
            {"record_kind": "VAULT_KEY_RETIREMENT_INVENTORY", "items": []}
        )
        empty_affected_sha = _value_sha256(
            {
                "record_kind": "VAULT_KEY_RETIREMENT_AFFECTED_LINEAGES",
                "lineages": [],
            }
        )
        authorized_plan_sha256 = (
            vault_receipt.plan_sha256 if sealed_cancellation else expected
        )
        authorized_inventory_sha256 = (
            vault_receipt.inventory_sha256
            if sealed_cancellation
            else empty_inventory_sha
        )
        authorized_affected_sha256 = (
            vault_receipt.affected_lineages_sha256
            if sealed_cancellation
            else empty_affected_sha
        )
        if (
            authorized_plan_sha256 is None
            or authorized_inventory_sha256 is None
            or authorized_affected_sha256 is None
        ):
            raise SourceReadLedgerIntegrityError(
                "retirement request abandonment authorization material is absent"
            )
        authorization_phase = (
            "CANCEL_SEALED" if sealed_cancellation else "CANCEL_REQUEST"
        )
        authorization = _validated_key_retirement_authorization(
            self._key_retirement_authority.authorize_retirement(
                store_identity_sha256=self.store_identity_sha256,
                phase=authorization_phase,
                operation_id=identity,
                plan_sha256=authorized_plan_sha256,
                retiring_key_id_sha256=_hash_text(request.retiring_key_id),
                successor_key_id_sha256=_hash_text(request.successor_key_id),
                inventory_sha256=authorized_inventory_sha256,
                affected_lineages_sha256=authorized_affected_sha256,
                lifecycle_state=SourceReadKeyLifecycleState.ACTIVE.value,
                activation_evidence_sha256=observation,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=self.key_retirement_authority_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
            phase=authorization_phase,
            operation_id=identity,
            plan_sha256=authorized_plan_sha256,
            retiring_key_id_sha256=_hash_text(request.retiring_key_id),
            successor_key_id_sha256=_hash_text(request.successor_key_id),
            inventory_sha256=authorized_inventory_sha256,
            affected_lineages_sha256=authorized_affected_sha256,
            lifecycle_state=SourceReadKeyLifecycleState.ACTIVE.value,
            activation_evidence_sha256=observation,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        governance_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadKeyRetirementAuthorizationReceipt.__dataclass_fields__
            },
            "retirement request abandonment governance authorization",
        )
        vault_json = _json_material(
            {
                name: getattr(vault_receipt, name)
                for name in SourceReadVaultKeyRetirementRequestAbandonmentReceipt.__dataclass_fields__
            },
            "retirement request abandonment vault authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                replay_phase = (
                    "REQUEST"
                    if kind == "KEY_RETIREMENT_REQUEST_ABANDONMENT"
                    else "RETIRE_INTENT"
                )
                replay_request = connection.execute(
                    """SELECT request_sha256
                       FROM source_read_key_retirement_requests
                       WHERE operation_id=?""",
                    (identity,),
                ).fetchone()
                if (
                    kind
                    not in {
                        "KEY_RETIREMENT_REQUEST_ABANDONMENT",
                        "KEY_RETIREMENT_INTENT_ABANDONMENT",
                    }
                    or kind == "KEY_RETIREMENT_INTENT_ABANDONMENT"
                    and not sealed_cancellation
                    or row["operation_id"] != identity
                    or replay_request is None
                    or replay_request["request_sha256"] != expected
                    or row["reason_code"] != reason_code.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "retirement request abandonment idempotency is already bound"
                    )
                return self._key_retirement_abandonment_from_row(
                    row, phase=replay_phase, replayed=True
                )
            current_request = connection.execute(
                """SELECT * FROM source_read_key_retirement_requests
                   WHERE operation_id=? AND request_sha256=?""",
                (identity, expected),
            ).fetchone()
            current_intent = connection.execute(
                "SELECT * FROM source_read_key_retirement_intents WHERE operation_id=?",
                (identity,),
            ).fetchone()
            prior_request = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_request_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            prior_intent = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            completion = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_completions
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                current_request is None
                or prior_request is not None
                or prior_intent is not None
                or completion is not None
                or current_intent is not None
                and not sealed_cancellation
            ):
                raise SourceReadLedgerStateConflict(
                    "retirement request changed before abandonment"
                )
            self._assert_writer_epoch_abandonable_for_request_locked(
                connection,
                current_request,
                sealed_cancellation=sealed_cancellation,
            )
            if current_intent is not None:
                if _utc_datetime(occurred, "sealed cancellation time") < _utc_datetime(
                    str(current_intent["occurred_at_utc"]),
                    "concurrent retirement intent time",
                ):
                    raise SourceReadLedgerValidationError(
                        "sealed cancellation precedes the concurrent retirement intent"
                    )
                _, current_plan = self._key_retirement_plan_locked(connection, identity)
                current_seal = _vault_factory_receipt_from_material(
                    _stored_json(
                        current_intent["vault_seal_authorization_json"],
                        "key retirement vault seal authorization",
                    ),
                    SourceReadVaultKeySealAuthorizationReceipt,
                )
                if (
                    current_plan.plan_sha256 != vault_receipt.plan_sha256
                    or current_seal.seal_sha256 != vault_receipt.seal_sha256
                ):
                    raise SourceReadLedgerStateConflict(
                        "concurrent retirement intent differs from the sealed cancellation"
                    )
                sequence = int(
                    connection.execute(
                        """SELECT COALESCE(MAX(sequence),0)+1
                           FROM source_read_key_retirement_intent_abandonments"""
                    ).fetchone()[0]
                )
                provisional = {
                    "operation_id": identity,
                    "idempotency_sha256": idempotency,
                    "plan_sha256": vault_receipt.plan_sha256,
                    "seal_sha256": vault_receipt.seal_sha256,
                    "reason_code": reason_code.value,
                    "observation_sha256": observation,
                    "vault_cancellation_event_sha256": (
                        vault_receipt.cancellation_event_sha256
                    ),
                    "governance_evidence_sha256": governance,
                    "governance_authorization_sha256": (
                        authorization.authorization_sha256
                    ),
                    "governance_authorization_json": governance_json,
                    "vault_authorization_sha256": (vault_receipt.authorization_sha256),
                    "vault_authorization_json": vault_json,
                    "occurred_at_utc": occurred,
                }
                record_sha = _value_sha256(
                    self._key_retirement_intent_abandonment_material(provisional)
                )
                connection.execute(
                    """INSERT INTO source_read_key_retirement_intent_abandonments(
                           sequence,operation_id,idempotency_sha256,plan_sha256,
                           seal_sha256,reason_code,observation_sha256,
                           vault_cancellation_event_sha256,
                           governance_evidence_sha256,
                           governance_authorization_sha256,
                           governance_authorization_json,
                           vault_authorization_sha256,vault_authorization_json,
                           occurred_at_utc,record_sha256)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        sequence,
                        identity,
                        idempotency,
                        vault_receipt.plan_sha256,
                        vault_receipt.seal_sha256,
                        reason_code.value,
                        observation,
                        vault_receipt.cancellation_event_sha256,
                        governance,
                        authorization.authorization_sha256,
                        governance_json,
                        vault_receipt.authorization_sha256,
                        vault_json,
                        occurred,
                        record_sha,
                    ),
                )
                event_type = "KEY_RETIREMENT_INTENT_ABANDONED"
                entity_id = identity + ":INTENT_ABANDON"
                phase = "RETIRE_INTENT"
                table = "source_read_key_retirement_intent_abandonments"
            else:
                sequence = int(
                    connection.execute(
                        """SELECT COALESCE(MAX(sequence),0)+1
                           FROM source_read_key_retirement_request_abandonments"""
                    ).fetchone()[0]
                )
                provisional = {
                    "operation_id": identity,
                    "idempotency_sha256": idempotency,
                    "request_sha256": expected,
                    "plan_sha256": vault_receipt.plan_sha256,
                    "seal_sha256": vault_receipt.seal_sha256,
                    "reason_code": reason_code.value,
                    "observation_sha256": observation,
                    "vault_cancellation_event_sha256": (
                        vault_receipt.cancellation_event_sha256
                    ),
                    "governance_evidence_sha256": governance,
                    "governance_authorization_sha256": (
                        authorization.authorization_sha256
                    ),
                    "governance_authorization_json": governance_json,
                    "vault_authorization_sha256": (vault_receipt.authorization_sha256),
                    "vault_authorization_json": vault_json,
                    "occurred_at_utc": occurred,
                }
                record_sha = _value_sha256(
                    self._key_retirement_request_abandonment_material(provisional)
                )
                connection.execute(
                    """INSERT INTO source_read_key_retirement_request_abandonments(
                           sequence,operation_id,idempotency_sha256,request_sha256,
                           plan_sha256,seal_sha256,reason_code,observation_sha256,
                           vault_cancellation_event_sha256,
                           governance_evidence_sha256,
                           governance_authorization_sha256,
                           governance_authorization_json,
                           vault_authorization_sha256,vault_authorization_json,
                           occurred_at_utc,record_sha256)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        sequence,
                        identity,
                        idempotency,
                        expected,
                        vault_receipt.plan_sha256,
                        vault_receipt.seal_sha256,
                        reason_code.value,
                        observation,
                        vault_receipt.cancellation_event_sha256,
                        governance,
                        authorization.authorization_sha256,
                        governance_json,
                        vault_receipt.authorization_sha256,
                        vault_json,
                        occurred,
                        record_sha,
                    ),
                )
                event_type = "KEY_RETIREMENT_REQUEST_ABANDONED"
                entity_id = identity + ":REQUEST_ABANDON"
                phase = "REQUEST"
                table = "source_read_key_retirement_request_abandonments"
            self._append_event_locked(
                connection,
                event_type=event_type,
                entity_kind="KEY_LIFECYCLE",
                entity_id=entity_id,
                entity_sha256=record_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                f"SELECT * FROM {table} WHERE operation_id=?",
                (identity,),
            ).fetchone()
            return self._key_retirement_abandonment_from_row(
                row, phase=phase, replayed=False
            )

    def abandon_runtime_vault_key_retirement_intent(
        self,
        operation_id: str,
        expected_plan_sha256: str,
        rollback_proof: object,
        *,
        reason_code: SourceReadKeyRetirementAbandonmentReason,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadKeyRetirementAbandonment:
        """Cancel RETIRE_INTENT only when local SEAL/custody effects are absent."""

        identity = _safe_id(operation_id, "key retirement operation")
        expected = _sha256(expected_plan_sha256, "expected retirement plan")
        governance = _sha256(
            governance_evidence_sha256, "retirement abandonment governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if _KEY_RETIREMENT_OPERATION_ID.fullmatch(
            identity
        ) is None or reason_code not in {
            SourceReadKeyRetirementAbandonmentReason.LOCAL_SEAL_MISSING,
            SourceReadKeyRetirementAbandonmentReason.LOCAL_SEAL_ROLLBACK,
        }:
            raise SourceReadLedgerValidationError(
                "retirement intent abandonment identity/reason differs"
            )
        if (
            self._external_anchor is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
            or self._key_retirement_authority is None
            or self.key_retirement_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "retirement intent abandonment requires pinned vault, anchor, and SoD"
            )
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "KEY_RETIREMENT_INTENT_ABANDONMENT"
                    or row["operation_id"] != identity
                    or row["plan_sha256"] != expected
                    or row["reason_code"] != reason_code.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "retirement intent abandonment idempotency is already bound"
                    )
                return self._key_retirement_abandonment_from_row(
                    row, phase="RETIRE_INTENT", replayed=True
                )
            intent, plan = self._key_retirement_plan_locked(connection, identity)
            request_row = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
                (identity,),
            ).fetchone()
            completion = connection.execute(
                "SELECT 1 FROM source_read_key_retirement_completions WHERE operation_id=?",
                (identity,),
            ).fetchone()
            prior = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                plan.plan_sha256 != expected
                or request_row is None
                or completion is not None
                or prior is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "retirement intent is absent, completed, or already abandoned"
                )
            request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            seal = _vault_factory_receipt_from_material(
                _stored_json(
                    intent["vault_seal_authorization_json"],
                    "key retirement vault seal authorization",
                ),
                SourceReadVaultKeySealAuthorizationReceipt,
            )
            if plan.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT:
                raise SourceReadLedgerStateConflict(
                    "compromise-containment intent cannot be abandoned"
                )
            if _utc_datetime(occurred, "intent abandonment time") < _utc_datetime(
                str(intent["occurred_at_utc"]), "retirement intent time"
            ):
                raise SourceReadLedgerValidationError(
                    "retirement intent abandonment precedes the intent"
                )

        vault_receipt = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_key_retirement_rollback(
                rollback_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=plan.vault_store_identity_sha256,
                operation_id=identity,
                plan_sha256=expected,
                seal_sha256=seal.seal_sha256,
                ledger_intent_record_sha256=str(intent["record_sha256"]),
                custody_identity_sha256=request.custody_identity_sha256,
                expected_custody_generation=request.expected_custody_generation,
                expected_previous_custody_receipt_sha256=(
                    request.expected_previous_custody_receipt_sha256
                ),
                reason_code=reason_code.value,
            ),
            receipt_type=SourceReadVaultKeyRetirementRollbackReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": plan.vault_store_identity_sha256,
                "operation_id": identity,
                "plan_sha256": expected,
                "seal_sha256": seal.seal_sha256,
                "ledger_intent_record_sha256": str(intent["record_sha256"]),
                "custody_identity_sha256": request.custody_identity_sha256,
                "expected_custody_generation": request.expected_custody_generation,
                "expected_previous_custody_receipt_sha256": (
                    request.expected_previous_custody_receipt_sha256
                ),
                "reason_code": reason_code.value,
                "occurred_at_utc": occurred,
            },
        )
        if (
            vault_receipt.observed_custody_generation
            != request.expected_custody_generation
            or vault_receipt.observed_custody_receipt_sha256
            != request.expected_previous_custody_receipt_sha256
        ):
            raise SourceReadLedgerStateConflict(
                "retirement intent abandonment lacks exact unchanged custody"
            )
        observation = vault_receipt.observation_sha256
        authorization = _validated_key_retirement_authorization(
            self._key_retirement_authority.authorize_retirement(
                store_identity_sha256=self.store_identity_sha256,
                phase="CANCEL_INTENT",
                operation_id=identity,
                plan_sha256=expected,
                retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
                successor_key_id_sha256=_hash_text(plan.successor_key_id),
                inventory_sha256=plan.inventory_sha256,
                affected_lineages_sha256=plan.affected_lineages_sha256,
                lifecycle_state=SourceReadKeyLifecycleState.ACTIVE.value,
                activation_evidence_sha256=observation,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=self.key_retirement_authority_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
            phase="CANCEL_INTENT",
            operation_id=identity,
            plan_sha256=expected,
            retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
            successor_key_id_sha256=_hash_text(plan.successor_key_id),
            inventory_sha256=plan.inventory_sha256,
            affected_lineages_sha256=plan.affected_lineages_sha256,
            lifecycle_state=SourceReadKeyLifecycleState.ACTIVE.value,
            activation_evidence_sha256=observation,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        governance_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadKeyRetirementAuthorizationReceipt.__dataclass_fields__
            },
            "retirement intent abandonment governance authorization",
        )
        vault_json = _json_material(
            {
                name: getattr(vault_receipt, name)
                for name in SourceReadVaultKeyRetirementRollbackReceipt.__dataclass_fields__
            },
            "retirement intent rollback authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "KEY_RETIREMENT_INTENT_ABANDONMENT"
                    or row["operation_id"] != identity
                    or row["plan_sha256"] != expected
                    or row["reason_code"] != reason_code.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "retirement intent abandonment idempotency is already bound"
                    )
                return self._key_retirement_abandonment_from_row(
                    row, phase="RETIRE_INTENT", replayed=True
                )
            current_intent, current_plan = self._key_retirement_plan_locked(
                connection, identity
            )
            completion = connection.execute(
                "SELECT 1 FROM source_read_key_retirement_completions WHERE operation_id=?",
                (identity,),
            ).fetchone()
            prior = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            if (
                current_plan != plan
                or current_intent["record_sha256"] != intent["record_sha256"]
                or completion is not None
                or prior is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "retirement intent changed before abandonment"
                )
            sequence = int(
                connection.execute(
                    """SELECT COALESCE(MAX(sequence),0)+1
                       FROM source_read_key_retirement_intent_abandonments"""
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "operation_id": identity,
                "idempotency_sha256": idempotency,
                "plan_sha256": expected,
                "seal_sha256": seal.seal_sha256,
                "reason_code": reason_code.value,
                "observation_sha256": observation,
                "vault_cancellation_event_sha256": (
                    vault_receipt.cancellation_event_sha256
                ),
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json": governance_json,
                "vault_authorization_sha256": vault_receipt.authorization_sha256,
                "vault_authorization_json": vault_json,
                "occurred_at_utc": occurred,
            }
            record_sha = _value_sha256(
                self._key_retirement_intent_abandonment_material(provisional)
            )
            connection.execute(
                """INSERT INTO source_read_key_retirement_intent_abandonments(
                       sequence,operation_id,idempotency_sha256,plan_sha256,
                       seal_sha256,reason_code,observation_sha256,
                       vault_cancellation_event_sha256,
                       governance_evidence_sha256,governance_authorization_sha256,
                       governance_authorization_json,vault_authorization_sha256,
                       vault_authorization_json,occurred_at_utc,record_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    identity,
                    idempotency,
                    expected,
                    seal.seal_sha256,
                    reason_code.value,
                    observation,
                    vault_receipt.cancellation_event_sha256,
                    governance,
                    authorization.authorization_sha256,
                    governance_json,
                    vault_receipt.authorization_sha256,
                    vault_json,
                    occurred,
                    record_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="KEY_RETIREMENT_INTENT_ABANDONED",
                entity_kind="KEY_LIFECYCLE",
                entity_id=identity + ":INTENT_ABANDON",
                entity_sha256=record_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                """SELECT * FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                (identity,),
            ).fetchone()
            return self._key_retirement_abandonment_from_row(
                row, phase="RETIRE_INTENT", replayed=False
            )

    def _key_retirement_plan_locked(
        self, connection: sqlite3.Connection, operation_id: str
    ) -> tuple[sqlite3.Row, SourceReadKeyRetirementPlan]:
        intent = connection.execute(
            "SELECT * FROM source_read_key_retirement_intents WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        request_row = connection.execute(
            "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
            (operation_id,),
        ).fetchone()
        if intent is None or request_row is None:
            raise SourceReadLedgerStateConflict("key retirement intent is absent")
        request = _key_retirement_request_from_material(
            _stored_json(request_row["request_json"], "key retirement request")
        )
        inventory = tuple(
            _key_retirement_item_from_material(
                _stored_json(row["item_json"], "key retirement inventory item")
            )
            for row in connection.execute(
                """SELECT * FROM source_read_key_retirement_inventory
                   WHERE operation_id=? ORDER BY sequence""",
                (operation_id,),
            ).fetchall()
        )
        plan = _key_retirement_plan_from_material(
            _stored_json(intent["plan_json"], "key retirement plan"),
            request=request,
            inventory=inventory,
        )
        return intent, plan

    def runtime_vault_key_retirement_proof(
        self, operation_id: str, expected_plan_sha256: str
    ) -> SourceReadKeyRetirementProof:
        if (
            type(operation_id) is not str
            or _KEY_RETIREMENT_OPERATION_ID.fullmatch(operation_id) is None
        ):
            raise SourceReadLedgerValidationError(
                "key retirement operation identity is invalid"
            )
        expected = _sha256(expected_plan_sha256, "expected_plan_sha256")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            intent, plan = self._key_retirement_plan_locked(connection, operation_id)
            completion = connection.execute(
                "SELECT 1 FROM source_read_key_retirement_completions WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            abandonment = connection.execute(
                """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                (operation_id,),
            ).fetchone()
            request_row = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if (
                plan.plan_sha256 != expected
                or completion is not None
                or abandonment is not None
                or request_row is None
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement intent is absent, completed, abandoned, or stale"
                )
            self._assert_writer_epoch_active_for_request_locked(connection, request_row)
            request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            inventory = tuple(
                _key_retirement_item_from_material(
                    _stored_json(row["item_json"], "key retirement inventory item")
                )
                for row in connection.execute(
                    """SELECT * FROM source_read_key_retirement_inventory
                       WHERE operation_id=? ORDER BY sequence""",
                    (operation_id,),
                ).fetchall()
            )
            event = self._entity_event_locked(
                connection, "KEY_LIFECYCLE", operation_id + ":INTENT"
            )
            if verification.external_anchor_generation <= 0:
                raise SourceReadLedgerStateConflict(
                    "key retirement intent is not externally anchored"
                )
            retirement = SourceReadVaultKeyRetirement(
                operation_id,
                plan.plan_sha256,
                SourceReadKeyLifecycleState.RETIRE_INTENT,
                str(intent["governance_evidence_sha256"]),
                str(intent["governance_authorization_sha256"]),
                None,
                str(intent["record_sha256"]),
                str(intent["occurred_at_utc"]),
                False,
            )
            return self._mint_key_retirement_proof(
                retirement=retirement,
                request=request,
                plan=plan,
                inventory=inventory,
                seal_sha256=str(
                    _vault_factory_receipt_from_material(
                        _stored_json(
                            intent["vault_seal_authorization_json"],
                            "key retirement vault seal authorization",
                        ),
                        SourceReadVaultKeySealAuthorizationReceipt,
                    ).seal_sha256
                ),
                lifecycle_event_sha256=str(event["event_sha256"]),
                verification=verification,
            )

    def verify_latest_runtime_vault_key_retirement_proof(
        self, proof: SourceReadKeyRetirementProof
    ) -> bool:
        if not self._key_retirement_proof_is_known(proof):
            return False
        try:
            with self._read() as connection:
                verification = self._verify_locked(connection)
                self._assert_authority_approval_fence_locked(connection)
                intent, plan = self._key_retirement_plan_locked(
                    connection, proof.retirement.operation_id
                )
                completion = connection.execute(
                    "SELECT 1 FROM source_read_key_retirement_completions WHERE operation_id=?",
                    (proof.retirement.operation_id,),
                ).fetchone()
                abandonment = connection.execute(
                    """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                       WHERE operation_id=?""",
                    (proof.retirement.operation_id,),
                ).fetchone()
                request_row = connection.execute(
                    """SELECT * FROM source_read_key_retirement_requests
                       WHERE operation_id=?""",
                    (proof.retirement.operation_id,),
                ).fetchone()
                writer_epoch = (
                    None
                    if request_row is None
                    else self._assert_writer_epoch_active_for_request_locked(
                        connection, request_row
                    )
                )
                inventory = tuple(
                    _key_retirement_item_from_material(
                        _stored_json(row["item_json"], "key retirement inventory item")
                    )
                    for row in connection.execute(
                        """SELECT * FROM source_read_key_retirement_inventory
                           WHERE operation_id=? ORDER BY sequence""",
                        (proof.retirement.operation_id,),
                    ).fetchall()
                )
                event = connection.execute(
                    """SELECT * FROM source_read_events
                       WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
                    (proof.retirement.operation_id + ":INTENT",),
                ).fetchone()
                anchor_valid = (
                    verification.external_anchor_generation
                    >= proof.external_anchor_generation
                    and verification.external_anchor_generation > 0
                )
                if (
                    verification.external_anchor_generation
                    == proof.external_anchor_generation
                ):
                    anchor_valid = anchor_valid and (
                        verification.external_anchor_receipt_sha256
                        == proof.external_anchor_receipt_sha256
                    )
                expected_retirement = SourceReadVaultKeyRetirement(
                    plan.operation_id,
                    plan.plan_sha256,
                    SourceReadKeyLifecycleState.RETIRE_INTENT,
                    str(intent["governance_evidence_sha256"]),
                    str(intent["governance_authorization_sha256"]),
                    None,
                    str(intent["record_sha256"]),
                    str(intent["occurred_at_utc"]),
                    False,
                )
                return bool(
                    completion is None
                    and abandonment is None
                    and request_row is not None
                    and writer_epoch is not None
                    and event is not None
                    and _key_retirement_request_from_material(
                        _stored_json(
                            request_row["request_json"], "key retirement request"
                        )
                    )
                    == proof.request
                    and plan == proof.plan
                    and inventory == proof.inventory
                    and proof.seal_sha256
                    == _vault_factory_receipt_from_material(
                        _stored_json(
                            intent["vault_seal_authorization_json"],
                            "key retirement vault seal authorization",
                        ),
                        SourceReadVaultKeySealAuthorizationReceipt,
                    ).seal_sha256
                    and expected_retirement == proof.retirement
                    and proof.inventory_sha256 == plan.inventory_sha256
                    and proof.affected_lineages_sha256 == plan.affected_lineages_sha256
                    and event["event_sha256"] == proof.lifecycle_event_sha256
                    and anchor_valid
                    and proof.factory_attested is True
                    and proof.live_release_eligible is False
                )
        except SourceReadLedgerError:
            return False

    def runtime_vault_key_retirement_abandonment_proof(
        self,
        operation_id: str,
        phase: str,
        expected_record_sha256: str,
    ) -> SourceReadKeyRetirementAbandonmentProof:
        identity = _safe_id(operation_id, "key retirement operation")
        expected = _sha256(expected_record_sha256, "expected abandonment record")
        if _KEY_RETIREMENT_OPERATION_ID.fullmatch(identity) is None or phase not in {
            "REQUEST",
            "RETIRE_INTENT",
        }:
            raise SourceReadLedgerValidationError(
                "key retirement abandonment proof identity/phase differs"
            )
        table = (
            "source_read_key_retirement_request_abandonments"
            if phase == "REQUEST"
            else "source_read_key_retirement_intent_abandonments"
        )
        entity_suffix = "REQUEST_ABANDON" if phase == "REQUEST" else "INTENT_ABANDON"
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            row = connection.execute(
                f"SELECT * FROM {table} WHERE operation_id=? AND record_sha256=?",
                (identity, expected),
            ).fetchone()
            if row is None or verification.external_anchor_generation <= 0:
                raise SourceReadLedgerStateConflict(
                    "key retirement abandonment is absent or not externally anchored"
                )
            event = self._entity_event_locked(
                connection, "KEY_LIFECYCLE", identity + ":" + entity_suffix
            )
            abandonment = self._key_retirement_abandonment_from_row(
                row, phase=phase, replayed=False
            )
            return self._mint_key_retirement_abandonment_proof(
                abandonment=abandonment,
                abandonment_event_sha256=str(event["event_sha256"]),
                verification=verification,
            )

    def verify_latest_runtime_vault_key_retirement_abandonment_proof(
        self, proof: SourceReadKeyRetirementAbandonmentProof
    ) -> bool:
        if not self._key_retirement_abandonment_proof_is_known(proof):
            return False
        phase = proof.abandonment.phase
        if phase not in {"REQUEST", "RETIRE_INTENT"}:
            return False
        table = (
            "source_read_key_retirement_request_abandonments"
            if phase == "REQUEST"
            else "source_read_key_retirement_intent_abandonments"
        )
        entity_suffix = "REQUEST_ABANDON" if phase == "REQUEST" else "INTENT_ABANDON"
        try:
            with self._read() as connection:
                verification = self._verify_locked(connection)
                self._assert_authority_approval_fence_locked(connection)
                row = connection.execute(
                    f"SELECT * FROM {table} WHERE operation_id=? AND record_sha256=?",
                    (
                        proof.abandonment.operation_id,
                        proof.abandonment.record_sha256,
                    ),
                ).fetchone()
                event = connection.execute(
                    """SELECT * FROM source_read_events
                       WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
                    (proof.abandonment.operation_id + ":" + entity_suffix,),
                ).fetchone()
                anchor_valid = (
                    verification.external_anchor_generation
                    >= proof.external_anchor_generation
                    and verification.external_anchor_generation > 0
                )
                if (
                    verification.external_anchor_generation
                    == proof.external_anchor_generation
                ):
                    anchor_valid = anchor_valid and (
                        verification.external_anchor_receipt_sha256
                        == proof.external_anchor_receipt_sha256
                    )
                return bool(
                    row is not None
                    and event is not None
                    and self._key_retirement_abandonment_from_row(
                        row, phase=phase, replayed=False
                    )
                    == proof.abandonment
                    and event["event_sha256"] == proof.abandonment_event_sha256
                    and anchor_valid
                    and proof.factory_attested is True
                    and proof.live_release_eligible is False
                )
        except SourceReadLedgerError:
            return False

    def complete_runtime_vault_key_retirement(
        self,
        operation_id: str,
        expected_plan_sha256: str,
        activation_proof: object,
        *,
        lifecycle_state: SourceReadKeyLifecycleState,
        governance_evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadVaultKeyRetirement:
        """Anchor exact vault/KMS ACTIVATE readback and finish key lifecycle.

        The operation/plan identity, rather than a process-local intent proof,
        is accepted so a crash after this ledger commit can be replayed after a
        fresh-process restart without re-consuming either external authority.
        """

        if (
            type(operation_id) is not str
            or _KEY_RETIREMENT_OPERATION_ID.fullmatch(operation_id) is None
            or type(lifecycle_state) is not SourceReadKeyLifecycleState
            or lifecycle_state
            not in {
                SourceReadKeyLifecycleState.RETIRED,
                SourceReadKeyLifecycleState.COMPROMISED,
            }
        ):
            raise SourceReadLedgerValidationError(
                "key retirement completion identity/state is invalid"
            )
        expected_plan = _sha256(expected_plan_sha256, "expected_plan_sha256")
        governance = _sha256(
            governance_evidence_sha256, "retirement governance evidence"
        )
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._vault_lifecycle_authority is None
            or self.vault_lifecycle_authority_identity_sha256 is None
            or self._key_retirement_authority is None
            or self.key_retirement_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "key retirement completion requires pinned anchor, vault verifier, and SoD authority"
            )

        with self._read() as connection:
            intent, plan = self._key_retirement_plan_locked(connection, operation_id)
            request_row = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if request_row is None:
                raise SourceReadLedgerStateConflict("key retirement request is absent")
            self._assert_writer_epoch_active_for_request_locked(connection, request_row)
            request = _key_retirement_request_from_material(
                _stored_json(request_row["request_json"], "key retirement request")
            )
            allowed_detection = (
                operation_id
                if request.reason
                is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else None
            )
            self._assert_no_unrelated_key_compromise_detection_locked(
                connection,
                allowed_operation_id=allowed_detection,
            )
            if allowed_detection is not None:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, operation_id
                )
            expected_state = (
                SourceReadKeyLifecycleState.COMPROMISED
                if plan.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else SourceReadKeyLifecycleState.RETIRED
            )
            if (
                plan.plan_sha256 != expected_plan
                or lifecycle_state is not expected_state
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement completion plan/state differs"
                )
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "KEY_RETIREMENT_COMPLETE"
                    or row["operation_id"] != operation_id
                    or row["lifecycle_state"] != lifecycle_state.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "key retirement completion idempotency digest is already bound"
                    )
                return SourceReadVaultKeyRetirement(
                    operation_id,
                    expected_plan,
                    lifecycle_state,
                    governance,
                    str(row["governance_authorization_sha256"]),
                    str(row["activation_evidence_sha256"]),
                    str(row["record_sha256"]),
                    str(row["occurred_at_utc"]),
                    True,
                )
            if (
                connection.execute(
                    "SELECT 1 FROM source_read_key_retirement_completions WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerIdempotencyConflict(
                    "key retirement completion exists under another idempotency"
                )
            if (
                connection.execute(
                    """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                   WHERE operation_id=?""",
                    (operation_id,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "abandoned key retirement intent cannot complete"
                )
            seal = _vault_factory_receipt_from_material(
                _stored_json(
                    intent["vault_seal_authorization_json"],
                    "key retirement vault seal authorization",
                ),
                SourceReadVaultKeySealAuthorizationReceipt,
            )

        vault_activation = _validated_vault_factory_receipt(
            self._vault_lifecycle_authority.verify_key_retirement_activation(
                activation_proof,
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=plan.vault_store_identity_sha256,
                operation_id=operation_id,
                plan_sha256=plan.plan_sha256,
                retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
                successor_key_id_sha256=_hash_text(plan.successor_key_id),
                lifecycle_state=lifecycle_state.value,
                ledger_intent_record_sha256=str(intent["record_sha256"]),
                custody_identity_sha256=request.custody_identity_sha256,
                expected_custody_generation=request.expected_custody_generation + 1,
                expected_previous_custody_receipt_sha256=(
                    request.expected_previous_custody_receipt_sha256
                ),
            ),
            receipt_type=SourceReadVaultKeyRetirementActivationReceipt,
            expected={
                "authority_identity_sha256": (
                    self.vault_lifecycle_authority_identity_sha256
                ),
                "store_identity_sha256": self.store_identity_sha256,
                "vault_store_identity_sha256": plan.vault_store_identity_sha256,
                "operation_id": operation_id,
                "plan_sha256": plan.plan_sha256,
                "seal_sha256": seal.seal_sha256,
                "retiring_key_id_sha256": _hash_text(plan.retiring_key_id),
                "successor_key_id_sha256": _hash_text(plan.successor_key_id),
                "lifecycle_state": lifecycle_state.value,
                "custody_identity_sha256": request.custody_identity_sha256,
                "custody_generation": request.expected_custody_generation + 1,
                "previous_custody_receipt_sha256": (
                    request.expected_previous_custody_receipt_sha256
                ),
                "ledger_intent_record_sha256": str(intent["record_sha256"]),
            },
        )
        activation_evidence = vault_activation.activation_evidence_sha256
        authorization = _validated_key_retirement_authorization(
            self._key_retirement_authority.authorize_retirement(
                store_identity_sha256=self.store_identity_sha256,
                phase="COMPLETE",
                operation_id=operation_id,
                plan_sha256=plan.plan_sha256,
                retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
                successor_key_id_sha256=_hash_text(plan.successor_key_id),
                inventory_sha256=plan.inventory_sha256,
                affected_lineages_sha256=plan.affected_lineages_sha256,
                lifecycle_state=lifecycle_state.value,
                activation_evidence_sha256=activation_evidence,
                occurred_at_utc=occurred,
                governance_evidence_sha256=governance,
            ),
            authority_identity_sha256=self.key_retirement_authority_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
            phase="COMPLETE",
            operation_id=operation_id,
            plan_sha256=plan.plan_sha256,
            retiring_key_id_sha256=_hash_text(plan.retiring_key_id),
            successor_key_id_sha256=_hash_text(plan.successor_key_id),
            inventory_sha256=plan.inventory_sha256,
            affected_lineages_sha256=plan.affected_lineages_sha256,
            lifecycle_state=lifecycle_state.value,
            activation_evidence_sha256=activation_evidence,
            occurred_at_utc=occurred,
            governance_evidence_sha256=governance,
        )
        authorization_json = _json_material(
            {
                name: getattr(authorization, name)
                for name in SourceReadKeyRetirementAuthorizationReceipt.__dataclass_fields__
            },
            "key retirement completion authorization",
        )
        vault_activation_json = _json_material(
            {
                name: getattr(vault_activation, name)
                for name in SourceReadVaultKeyRetirementActivationReceipt.__dataclass_fields__
            },
            "key retirement vault activation authorization",
        )

        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "KEY_RETIREMENT_COMPLETE"
                    or row["operation_id"] != operation_id
                    or row["lifecycle_state"] != lifecycle_state.value
                    or row["governance_evidence_sha256"] != governance
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "key retirement completion idempotency digest is already bound"
                    )
                return SourceReadVaultKeyRetirement(
                    operation_id,
                    expected_plan,
                    lifecycle_state,
                    governance,
                    str(row["governance_authorization_sha256"]),
                    str(row["activation_evidence_sha256"]),
                    str(row["record_sha256"]),
                    str(row["occurred_at_utc"]),
                    True,
                )
            allowed_detection = (
                operation_id
                if plan.reason is SourceReadKeyRetirementReason.COMPROMISE_CONTAINMENT
                else None
            )
            self._assert_no_unrelated_key_compromise_detection_locked(
                connection,
                allowed_operation_id=allowed_detection,
            )
            if allowed_detection is not None:
                self._assert_key_compromise_containment_eligible_locked(
                    connection, operation_id
                )
            current_intent, current_plan = self._key_retirement_plan_locked(
                connection, operation_id
            )
            current_request_row = connection.execute(
                "SELECT * FROM source_read_key_retirement_requests WHERE operation_id=?",
                (operation_id,),
            ).fetchone()
            if current_request_row is not None:
                self._assert_writer_epoch_active_for_request_locked(
                    connection, current_request_row
                )
            if (
                current_request_row is None
                or current_plan != plan
                or current_intent["record_sha256"] != intent["record_sha256"]
                or connection.execute(
                    "SELECT 1 FROM source_read_key_retirement_completions WHERE operation_id=?",
                    (operation_id,),
                ).fetchone()
                is not None
                or connection.execute(
                    """SELECT 1 FROM source_read_key_retirement_intent_abandonments
                       WHERE operation_id=?""",
                    (operation_id,),
                ).fetchone()
                is not None
            ):
                raise SourceReadLedgerStateConflict(
                    "key retirement intent changed before completion"
                )
            inventory = tuple(
                _key_retirement_item_from_material(
                    _stored_json(row["item_json"], "key retirement inventory item")
                )
                for row in connection.execute(
                    """SELECT * FROM source_read_key_retirement_inventory
                       WHERE operation_id=? ORDER BY sequence""",
                    (operation_id,),
                ).fetchall()
            )
            child_rows: list[dict[str, object]] = []
            if lifecycle_state is SourceReadKeyLifecycleState.COMPROMISED:
                if plan.incident_evidence_sha256 is None:
                    raise SourceReadLedgerIntegrityError(
                        "compromise retirement has no incident evidence"
                    )
                next_incident_sequence = int(
                    connection.execute(
                        "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_stream_incidents"
                    ).fetchone()[0]
                )
                targets = self._key_compromise_targets_locked(
                    connection,
                    operation_id=operation_id,
                    vault_store_identity_sha256=plan.vault_store_identity_sha256,
                    inventory=inventory,
                )
                for lineage, head, item in targets:
                    stable_stream = self._stable_stream_for_lineage_locked(
                        connection, lineage
                    )
                    incident_id = (
                        "source-read-stream-incident-"
                        + _value_sha256(
                            {
                                "lineage_sha256": lineage,
                                "continuation_head_sha256": head["head_sha256"],
                                "reason_code": SourceReadStreamQuarantineCode.KEY_COMPROMISE_CONTAINMENT.value,
                                "evidence_sha256": plan.incident_evidence_sha256,
                                "parent_retirement_operation_id": operation_id,
                            }
                        )[:32]
                    )
                    incident: dict[str, object] = {
                        "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                        "record_kind": "SOURCE_READ_STREAM_INCIDENT",
                        "incident_id": incident_id,
                        "idempotency_sha256": _value_sha256(
                            {
                                "operation_id": operation_id,
                                "lineage_sha256": lineage,
                                "record_kind": "KEY_COMPROMISE_STREAM_INCIDENT",
                            }
                        ),
                        "lineage_sha256": lineage,
                        "stable_stream_sha256": stable_stream,
                        "vault_store_identity_sha256": plan.vault_store_identity_sha256,
                        "slot_sha256": item.slot_sha256,
                        "current_ledger_binding_sha256": item.ledger_binding_sha256,
                        "continuation_head_sha256": head["head_sha256"],
                        "expected_envelope_sha256": item.rewrap_envelope_sha256,
                        "position_binding_sha256": item.position_binding_sha256,
                        "position_binding_json_sha256": None,
                        "reason_code": SourceReadStreamQuarantineCode.KEY_COMPROMISE_CONTAINMENT.value,
                        "evidence_sha256": plan.incident_evidence_sha256,
                        "absence_authorization_sha256": None,
                        "absence_authorization_json_sha256": None,
                        "parent_retirement_operation_id": operation_id,
                        "occurred_at_utc": occurred,
                    }
                    incident["incident_sha256"] = _value_sha256(incident)
                    incident["sequence"] = next_incident_sequence + len(child_rows)
                    child_rows.append(incident)
            compromise_sha256s = tuple(
                str(row["incident_sha256"]) for row in child_rows
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_KEY_RETIREMENT_COMPLETION_RECORD",
                "operation_id": operation_id,
                "plan_sha256": plan.plan_sha256,
                "inventory_sha256": plan.inventory_sha256,
                "affected_lineages_sha256": plan.affected_lineages_sha256,
                "compromise_incident_sha256s": list(compromise_sha256s),
                "idempotency_sha256": idempotency,
                "lifecycle_state": lifecycle_state.value,
                "activation_evidence_sha256": activation_evidence,
                "governance_evidence_sha256": governance,
                "governance_authorization_sha256": authorization.authorization_sha256,
                "governance_authorization_json_sha256": _hash_text(authorization_json),
                "vault_activation_authorization_sha256": (
                    vault_activation.authorization_sha256
                ),
                "vault_activation_authorization_json_sha256": _hash_text(
                    vault_activation_json
                ),
                "occurred_at_utc": occurred,
            }
            record_sha = _value_sha256(provisional)
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_key_retirement_completions"
                ).fetchone()[0]
            )
            connection.execute(
                """INSERT INTO source_read_key_retirement_completions(
                       sequence,operation_id,idempotency_sha256,lifecycle_state,
                       activation_evidence_sha256,governance_evidence_sha256,
                       governance_authorization_sha256,
                       governance_authorization_json,
                       vault_activation_authorization_sha256,
                       vault_activation_authorization_json,occurred_at_utc,
                       record_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    operation_id,
                    idempotency,
                    lifecycle_state.value,
                    activation_evidence,
                    governance,
                    authorization.authorization_sha256,
                    authorization_json,
                    vault_activation.authorization_sha256,
                    vault_activation_json,
                    occurred,
                    record_sha,
                ),
            )
            for row in child_rows:
                connection.execute(
                    """INSERT INTO source_read_stream_incidents(
                           sequence,incident_id,idempotency_sha256,lineage_sha256,
                           stable_stream_sha256,vault_store_identity_sha256,
                           slot_sha256,current_ledger_binding_sha256,
                           continuation_head_sha256,expected_envelope_sha256,
                           position_binding_sha256,position_binding_json,
                           reason_code,evidence_sha256,
                           absence_authorization_sha256,
                           absence_authorization_json,
                           parent_retirement_operation_id,occurred_at_utc,
                           incident_sha256)
                       VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (
                        row["sequence"],
                        row["incident_id"],
                        row["idempotency_sha256"],
                        row["lineage_sha256"],
                        row["stable_stream_sha256"],
                        row["vault_store_identity_sha256"],
                        row["slot_sha256"],
                        row["current_ledger_binding_sha256"],
                        row["continuation_head_sha256"],
                        row["expected_envelope_sha256"],
                        row["position_binding_sha256"],
                        None,
                        row["reason_code"],
                        row["evidence_sha256"],
                        None,
                        None,
                        operation_id,
                        occurred,
                        row["incident_sha256"],
                    ),
                )
            self._append_event_locked(
                connection,
                event_type=(
                    "KEY_COMPROMISED"
                    if lifecycle_state is SourceReadKeyLifecycleState.COMPROMISED
                    else "KEY_RETIRED"
                ),
                entity_kind="KEY_LIFECYCLE",
                entity_id=operation_id + ":COMPLETE",
                entity_sha256=record_sha,
                occurred_at_utc=occurred,
            )
            return SourceReadVaultKeyRetirement(
                operation_id,
                plan.plan_sha256,
                lifecycle_state,
                governance,
                authorization.authorization_sha256,
                activation_evidence,
                record_sha,
                occurred,
                False,
            )

    @staticmethod
    def _stream_quarantine_from_row(
        row: sqlite3.Row, *, replayed: bool
    ) -> SourceReadStreamQuarantineDisposition:
        return SourceReadStreamQuarantineDisposition(
            str(row["incident_id"]),
            str(row["lineage_sha256"]),
            str(row["stable_stream_sha256"]),
            str(row["current_ledger_binding_sha256"]),
            str(row["expected_envelope_sha256"]),
            SourceReadStreamQuarantineCode(str(row["reason_code"])),
            str(row["evidence_sha256"]),
            str(row["incident_sha256"]),
            str(row["occurred_at_utc"]),
            SourceReadStreamRecoveryState.ACTIVE,
            replayed,
        )

    def continuation_stream_incident(
        self,
        incident_id: str,
    ) -> SourceReadStreamQuarantineDisposition:
        """Read one durable incident without requiring a current proof object."""

        identity = _safe_id(incident_id, "stream incident identity")
        with self._read() as connection:
            verification = self._verify_locked(connection)
            incident = connection.execute(
                "SELECT * FROM source_read_stream_incidents WHERE incident_id=?",
                (identity,),
            ).fetchone()
            if incident is None:
                raise SourceReadLedgerStateConflict("stream incident is absent")
            if incident["parent_retirement_operation_id"] is None:
                event = connection.execute(
                    """SELECT * FROM source_read_events
                       WHERE entity_kind='STREAM_INCIDENT' AND entity_id=?""",
                    (identity,),
                ).fetchone()
                event_entity_sha256 = str(incident["incident_sha256"])
            else:
                parent = str(incident["parent_retirement_operation_id"])
                completion = connection.execute(
                    """SELECT * FROM source_read_key_retirement_completions
                       WHERE operation_id=? AND lifecycle_state='COMPROMISED'""",
                    (parent,),
                ).fetchone()
                event = connection.execute(
                    """SELECT * FROM source_read_events
                       WHERE entity_kind='KEY_LIFECYCLE' AND entity_id=?""",
                    (parent + ":COMPLETE",),
                ).fetchone()
                event_entity_sha256 = (
                    ZERO_SHA256
                    if completion is None
                    else str(completion["record_sha256"])
                )
            disposition = connection.execute(
                """SELECT 1 FROM source_read_stream_repair_dispositions
                   WHERE incident_id=?""",
                (identity,),
            ).fetchone()
            latest_repair = connection.execute(
                """SELECT * FROM source_read_stream_repair_bindings
                   WHERE incident_id=? ORDER BY sequence DESC LIMIT 1""",
                (identity,),
            ).fetchone()
            abandonment = (
                None
                if latest_repair is None
                else connection.execute(
                    """SELECT 1 FROM source_read_stream_repair_abandonments
                       WHERE repair_id=?""",
                    (latest_repair["repair_id"],),
                ).fetchone()
            )
            state = (
                SourceReadStreamRecoveryState.RESOLVED
                if disposition is not None
                else SourceReadStreamRecoveryState.REPAIR_BOUND
                if latest_repair is not None and abandonment is None
                else SourceReadStreamRecoveryState.ACTIVE
            )
            if (
                event is None
                or event["entity_sha256"] != event_entity_sha256
                or verification.external_anchor_generation <= 0
                or not verification.external_anchor_status.startswith("ANCHORED_")
            ):
                raise SourceReadLedgerStateConflict(
                    "stream incident is not externally anchored"
                )
            return SourceReadStreamQuarantineDisposition(
                str(incident["incident_id"]),
                str(incident["lineage_sha256"]),
                str(incident["stable_stream_sha256"]),
                str(incident["current_ledger_binding_sha256"]),
                str(incident["expected_envelope_sha256"]),
                SourceReadStreamQuarantineCode(str(incident["reason_code"])),
                str(incident["evidence_sha256"]),
                str(incident["incident_sha256"]),
                str(incident["occurred_at_utc"]),
                state,
                True,
            )

    def quarantine_continuation_stream(
        self,
        current_proof: SourceReadContinuationProof | None,
        position: SourceReadContinuationPositionBinding,
        *,
        reason_code: SourceReadStreamQuarantineCode,
        evidence_sha256: str,
        idempotency_sha256: str,
        occurred_at_utc: str,
    ) -> SourceReadStreamQuarantineDisposition:
        """Durably quarantine a final stream after trusted non-creating observation."""

        if (
            current_proof is not None
            and type(current_proof) is not SourceReadContinuationProof
            or type(reason_code) is not SourceReadStreamQuarantineCode
            or reason_code is SourceReadStreamQuarantineCode.KEY_COMPROMISE_CONTAINMENT
        ):
            raise SourceReadLedgerStateConflict(
                "stream quarantine requires the exact latest final continuation proof"
            )
        position_material = _continuation_position_material(position)
        evidence = _sha256(evidence_sha256, "stream incident evidence")
        idempotency = _sha256(idempotency_sha256, "idempotency_sha256")
        occurred = _ledger_utc(occurred_at_utc, "occurred_at_utc")
        if (
            self._external_anchor is None
            or self._vault_absence_authority is None
            or self.vault_absence_authority_identity_sha256 is None
        ):
            raise SourceReadLedgerStateConflict(
                "stream quarantine requires pinned anchor and absence authority"
            )
        position_json = _json_material(position_material, "stream incident position")
        # Exact anchored replay precedes both the now-stale continuation proof
        # check and the one-shot absence observation boundary.
        with self._read() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_INCIDENT"
                    or row["position_binding_sha256"]
                    != position.position_binding_sha256
                    or row["position_binding_json"] != position_json
                    or row["reason_code"] != reason_code.value
                    or row["evidence_sha256"] != evidence
                    or row["parent_retirement_operation_id"] is not None
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream incident idempotency digest is already bound"
                    )
                return self._stream_quarantine_from_row(row, replayed=True)
            self._assert_no_active_key_lifecycle_locked(connection)
        if (
            current_proof is None
            or not self.continuation_proof_is_known(current_proof)
            or current_proof.binding.expected_outcome == "READ_UNCERTAIN"
        ):
            raise SourceReadLedgerStateConflict(
                "new stream quarantine requires the exact latest final continuation proof"
            )
        binding = current_proof.binding
        if (
            binding.position_binding_sha256 is None
            or binding.position_binding_sha256 != position.position_binding_sha256
        ):
            raise SourceReadLedgerStateConflict(
                "stream quarantine requires the exact vault-bound continuation position"
            )
        lineage = _continuation_lineage_sha256(binding)
        stable_stream = _stable_stream_sha256(position)
        if position.checkpoint_sha256 != binding.checkpoint_after_sha256:
            raise SourceReadLedgerValidationError(
                "stream quarantine checkpoint/continuation differs"
            )
        incident_id = (
            "source-read-stream-incident-"
            + _value_sha256(
                {
                    "lineage_sha256": lineage,
                    "continuation_head_sha256": current_proof.continuation_head_sha256,
                    "reason_code": reason_code.value,
                    "evidence_sha256": evidence,
                    "parent_retirement_operation_id": None,
                }
            )[:32]
        )
        if not self.verify_continuation_proof(current_proof):
            raise SourceReadLedgerStateConflict(
                "stream quarantine requires the authoritative latest continuation proof"
            )
        absence = _validated_vault_absence_authorization(
            self._vault_absence_authority.attest_absence(
                store_identity_sha256=self.store_identity_sha256,
                vault_store_identity_sha256=binding.vault_store_identity_sha256,
                slot_sha256=binding.slot_sha256,
                lineage_sha256=lineage,
                current_ledger_binding_sha256=binding.ledger_binding_sha256,
                position_binding_sha256=position.position_binding_sha256,
                expected_envelope_sha256=binding.envelope_sha256,
                reason_code=reason_code.value,
                evidence_sha256=evidence,
                occurred_at_utc=occurred,
            ),
            authority_identity_sha256=self.vault_absence_authority_identity_sha256,
            store_identity_sha256=self.store_identity_sha256,
            vault_store_identity_sha256=binding.vault_store_identity_sha256,
            slot_sha256=binding.slot_sha256,
            lineage_sha256=lineage,
            current_ledger_binding_sha256=binding.ledger_binding_sha256,
            position_binding_sha256=position.position_binding_sha256,
            expected_envelope_sha256=binding.envelope_sha256,
            reason_code=reason_code.value,
            evidence_sha256=evidence,
            occurred_at_utc=occurred,
        )
        absence_json = _json_material(
            {
                name: getattr(absence, name)
                for name in SourceReadVaultAbsenceAuthorizationReceipt.__dataclass_fields__
            },
            "stream incident absence authorization",
        )
        with self._write() as connection:
            replay = self._find_idempotency_locked(connection, idempotency)
            if replay is not None:
                kind, row = replay
                if (
                    kind != "STREAM_INCIDENT"
                    or row["incident_id"] != incident_id
                    or row["lineage_sha256"] != lineage
                    or row["current_ledger_binding_sha256"]
                    != binding.ledger_binding_sha256
                ):
                    raise SourceReadLedgerIdempotencyConflict(
                        "stream incident idempotency digest is already bound"
                    )
                return self._stream_quarantine_from_row(row, replayed=True)
            self._assert_no_active_key_lifecycle_locked(connection)
            self._assert_no_active_stream_incident_locked(
                connection, lineage_sha256=lineage
            )
            latest = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (lineage,),
            ).fetchone()
            unresolved = connection.execute(
                """SELECT 1 FROM source_read_operations op
                   WHERE op.stable_stream_sha256=? AND NOT EXISTS(
                       SELECT 1 FROM source_read_outcomes o
                       WHERE o.operation_id=op.operation_id
                         AND o.outcome_type IN ('PAGE_ACCEPTED','READ_RECONCILED')
                   ) LIMIT 1""",
                (stable_stream,),
            ).fetchone()
            canonical_stable = self._stable_stream_for_lineage_locked(
                connection, lineage
            )
            if (
                latest is None
                or latest["head_sha256"] != current_proof.continuation_head_sha256
                or latest["ledger_binding_sha256"] != binding.ledger_binding_sha256
                or not self._position_matches_head_locked(connection, latest, position)
                or unresolved is not None
                or canonical_stable != stable_stream
            ):
                raise SourceReadLedgerStateConflict(
                    "stream incident lost latest-head or final-custody comparison"
                )
            sequence = int(
                connection.execute(
                    "SELECT COALESCE(MAX(sequence),0)+1 FROM source_read_stream_incidents"
                ).fetchone()[0]
            )
            provisional: dict[str, object] = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "SOURCE_READ_STREAM_INCIDENT",
                "incident_id": incident_id,
                "idempotency_sha256": idempotency,
                "lineage_sha256": lineage,
                "stable_stream_sha256": stable_stream,
                "vault_store_identity_sha256": binding.vault_store_identity_sha256,
                "slot_sha256": binding.slot_sha256,
                "current_ledger_binding_sha256": binding.ledger_binding_sha256,
                "continuation_head_sha256": current_proof.continuation_head_sha256,
                "expected_envelope_sha256": binding.envelope_sha256,
                "position_binding_sha256": position.position_binding_sha256,
                "position_binding_json_sha256": _hash_text(position_json),
                "reason_code": reason_code.value,
                "evidence_sha256": evidence,
                "absence_authorization_sha256": absence.authorization_sha256,
                "absence_authorization_json_sha256": _hash_text(absence_json),
                "parent_retirement_operation_id": None,
                "occurred_at_utc": occurred,
            }
            incident_sha = _value_sha256(provisional)
            connection.execute(
                """INSERT INTO source_read_stream_incidents(
                       sequence,incident_id,idempotency_sha256,lineage_sha256,
                       stable_stream_sha256,vault_store_identity_sha256,slot_sha256,
                       current_ledger_binding_sha256,continuation_head_sha256,
                       expected_envelope_sha256,position_binding_sha256,
                       position_binding_json,reason_code,evidence_sha256,
                       absence_authorization_sha256,absence_authorization_json,
                       parent_retirement_operation_id,occurred_at_utc,incident_sha256)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sequence,
                    incident_id,
                    idempotency,
                    lineage,
                    stable_stream,
                    binding.vault_store_identity_sha256,
                    binding.slot_sha256,
                    binding.ledger_binding_sha256,
                    current_proof.continuation_head_sha256,
                    binding.envelope_sha256,
                    position.position_binding_sha256,
                    position_json,
                    reason_code.value,
                    evidence,
                    absence.authorization_sha256,
                    absence_json,
                    None,
                    occurred,
                    incident_sha,
                ),
            )
            self._append_event_locked(
                connection,
                event_type="STREAM_QUARANTINED",
                entity_kind="STREAM_INCIDENT",
                entity_id=incident_id,
                entity_sha256=incident_sha,
                occurred_at_utc=occurred,
            )
            row = connection.execute(
                "SELECT * FROM source_read_stream_incidents WHERE incident_id=?",
                (incident_id,),
            ).fetchone()
            return self._stream_quarantine_from_row(row, replayed=False)

    def continuation_proof(
        self,
        operation_id: str,
        expected_ledger_binding_sha256: str,
    ) -> SourceReadContinuationProof:
        """Mint an exact verified vault activation proof for the latest binding."""

        if type(operation_id) is not str:
            raise SourceReadLedgerValidationError("operation identity is invalid")
        self._continuation_source_spec(operation_id)
        expected = _sha256(
            expected_ledger_binding_sha256,
            "expected_ledger_binding_sha256",
        )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            self._assert_authority_approval_fence_locked(connection)
            self._assert_no_active_key_lifecycle_locked(connection)
            spec, rows = self._continuation_entity_rows_locked(
                connection,
                operation_id,
                expected_binding_sha256=expected,
            )
            row = rows[-1] if rows else None
            if row is None:
                raise SourceReadLedgerStateConflict(
                    "expected continuation-bound outcome differs or is absent"
                )
            binding = _continuation_binding_from_material(
                _stored_json(row["binding_json"], "continuation binding")
            )
            latest_head = connection.execute(
                """SELECT * FROM source_read_continuation_heads
                   WHERE lineage_sha256=? ORDER BY sequence DESC LIMIT 1""",
                (_continuation_lineage_sha256(binding),),
            ).fetchone()
            if (
                latest_head is None
                or latest_head[spec["head_column"]] != row["entity_id"]
                or latest_head["ledger_binding_sha256"] != expected
            ):
                raise SourceReadLedgerStateConflict(
                    "continuation binding is not the authoritative latest lineage head"
                )
            self._assert_no_active_stream_incident_locked(
                connection,
                lineage_sha256=_continuation_lineage_sha256(binding),
            )
            writer_epoch = self._runtime_vault_writer_epoch_locked(
                connection,
                binding.vault_store_identity_sha256,
                replayed=True,
            )
            if (
                writer_epoch.state
                is SourceReadRuntimeVaultWriterEpochState.TRANSITION_PENDING
            ):
                raise SourceReadLedgerStateConflict(
                    "continuation proof is fenced by a pending writer transition"
                )
            if spec["head_column"] == "repair_id":
                repair_state = self._latest_stream_incident_locked(
                    connection,
                    lineage_sha256=_continuation_lineage_sha256(binding),
                )
                if (
                    repair_state is None
                    or repair_state[1] is not SourceReadStreamRecoveryState.RESOLVED
                ):
                    raise SourceReadLedgerStateConflict(
                        "ordinary continuation proof requires completed stream repair"
                    )
            event = self._entity_event_locked(
                connection,
                spec["entity_kind"],
                str(row["entity_id"]) + spec["event_suffix"],
            )
            return self._mint_continuation_proof(
                binding=binding,
                outcome_id=str(row["entity_id"]),
                outcome_sha256=str(row["entity_sha256"]),
                outcome_event_sha256=str(event["event_sha256"]),
                continuation_head_sha256=str(latest_head["head_sha256"]),
                writer_epoch_head_sha256=(writer_epoch.writer_epoch_head_sha256),
                ledger_head_event_sha256=verification.head_event_sha256,
                external_anchor_status=verification.external_anchor_status,
                external_anchor_generation=verification.external_anchor_generation,
                external_anchor_receipt_sha256=(
                    verification.external_anchor_receipt_sha256
                ),
            )

    def events(self, *, limit: int = 200) -> tuple[SourceReadLedgerEvent, ...]:
        bound = _bounded_int(limit, "event limit", minimum=1, maximum=MAX_SNAPSHOT_ROWS)
        with self._read() as connection:
            rows = connection.execute(
                "SELECT * FROM source_read_events ORDER BY sequence DESC LIMIT ?",
                (bound,),
            ).fetchall()
            return tuple(
                SourceReadLedgerEvent(
                    int(row["sequence"]),
                    str(row["event_id"]),
                    str(row["event_type"]),
                    str(row["entity_kind"]),
                    str(row["entity_id"]),
                    str(row["entity_sha256"]),
                    str(row["occurred_at_utc"]),
                    str(row["previous_event_sha256"]),
                    str(row["event_sha256"]),
                )
                for row in reversed(rows)
            )

    def snapshot(
        self, *, event_limit: int = 200, operation_limit: int = 200
    ) -> SourceReadLedgerSnapshot:
        event_bound = _bounded_int(
            event_limit, "event limit", minimum=1, maximum=MAX_SNAPSHOT_ROWS
        )
        operation_bound = _bounded_int(
            operation_limit, "operation limit", minimum=1, maximum=MAX_SNAPSHOT_ROWS
        )
        with self._read() as connection:
            verification = self._verify_locked(connection)
            operation_rows = connection.execute(
                "SELECT * FROM source_read_operations ORDER BY sequence DESC LIMIT ?",
                (operation_bound,),
            ).fetchall()
            event_rows = connection.execute(
                "SELECT * FROM source_read_events ORDER BY sequence DESC LIMIT ?",
                (event_bound,),
            ).fetchall()
            operations = tuple(
                self._operation_custody_locked(connection, row)
                for row in reversed(operation_rows)
            )
            events = tuple(
                SourceReadLedgerEvent(
                    int(row["sequence"]),
                    str(row["event_id"]),
                    str(row["event_type"]),
                    str(row["entity_kind"]),
                    str(row["entity_id"]),
                    str(row["entity_sha256"]),
                    str(row["occurred_at_utc"]),
                    str(row["previous_event_sha256"]),
                    str(row["event_sha256"]),
                )
                for row in reversed(event_rows)
            )
            material = {
                "protocol": SOURCE_READ_LEDGER_PROTOCOL_VERSION,
                "record_kind": "BOUNDED_LEDGER_SNAPSHOT",
                "verification": {
                    "schema_fingerprint_sha256": verification.schema_fingerprint_sha256,
                    "store_identity_sha256": verification.store_identity_sha256,
                    "batch_count": verification.batch_count,
                    "operation_count": verification.operation_count,
                    "outcome_count": verification.outcome_count,
                    "event_count": verification.event_count,
                    "pending_operation_count": verification.pending_operation_count,
                    "head_event_sha256": verification.head_event_sha256,
                    "external_anchor_status": verification.external_anchor_status,
                    "external_anchor_generation": (
                        verification.external_anchor_generation
                    ),
                    "external_anchor_receipt_sha256": (
                        verification.external_anchor_receipt_sha256
                    ),
                    "reconciliation_quarantine_count": (
                        verification.reconciliation_quarantine_count
                    ),
                    "quota_epoch_transition_count": (
                        verification.quota_epoch_transition_count
                    ),
                },
                "operation_sha256s": [
                    item.custody_reservation_sha256 for item in operations
                ],
                "event_sha256s": [item.event_sha256 for item in events],
                "operations_truncated": verification.operation_count > len(operations),
                "events_truncated": verification.event_count > len(events),
            }
            return SourceReadLedgerSnapshot(
                verification,
                operations,
                events,
                verification.operation_count > len(operations),
                verification.event_count > len(events),
                _value_sha256(material),
            )


